// Content for Consent, For Real (node g44, ages 18-22, Chapter 6): NEW v2 build to GDD 44 (mechanic-embodying),
// the FIRST node of Chapter 6 (College) and the adult completion of the consent thread (Thread B · Safety,
// Consent & Boundaries). Reworks the old ModesEngine build onto the shared v2 engine. "Consent isn't a box you
// tick; it's an enthusiastic, ongoing, freely-given, revocable, sober-enough yes between equals: in the messier
// realities of adult life: parties and alcohol, hook-ups and relationships, apps and hostel rooms." 84 researched,
// India-grounded, trauma-aware, strictly NON-GRAPHIC scenarios across real-situations → drinks-and-capacity →
// spot-the-pressure → after-harm-support → consent-culture → tools-and-help, each encoded as one of the shared v2
// play actions (branch / strike-rewrite / sort / reflect / role-play / spot / match): no binary "tap the right
// card". Lead: branch (your move), strike-rewrite (bust the myth), role-play (say the line). SURVIVOR-CENTRED
// throughout: believe, never blame, ask what they need, respect their choices about reporting, signpost help;
// responsibility lies ONLY with the person who ignored consent. Even-handed across genders (anyone can be harmed
// or harm; male and LGBTQ+ survivors are especially silenced). India: hostel/PG/campus reality, parties families
// don't know about, acquaintance assault and stigma; helplines 181, 1091, 112, campus Internal Committee
// (POSH/UGC). Routes any disclosure to support. Builds on g31 (Mutual); opens the adult journey before g45/g46/g47.
// gameId trap: library/GDD aspirational id is "consent-for-real" but the engine-host registry id is "consent-real"
// config uses "consent-real".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"cr-001","cat":"real-situations","type":"branch","persona":"Ananya","source":"real situations","hook":"At a party, Nikhil keeps moving things along after you've told him you're not sure.","steps":[{"prompt":"He murmurs that you'll like it once you relax. What do you do?","options":[{"text":"Tell yourself 'not sure' probably wasn't clear enough","then":"You start doubting your own words, and Nikhil pauses, reading your face."},{"text":"Tell yourself it's too late to stop once you've started","then":"The thought makes stopping feel unfair. Nikhil pauses: \"What now?\""},{"text":"Say clearly that you want to stop","then":"Nikhil pulls back, annoyed: \"Seriously? Now?\"","best":true},{"text":"Feel you owe him an apology for being awkward","then":"Guilt creeps in, and Nikhil pauses, waiting for you to explain."}],"why":"'Not sure' already means stop. Saying it plainly leaves no room for doubt."},{"prompt":"Nikhil says you led him on by kissing him first. What do you do?","options":[{"text":"Wonder if he's right, since you did kiss first","then":"The doubt stings. Nikhil shrugs and goes off to get a drink."},{"text":"Argue with him till he admits he's wrong","then":"Nikhil argues back, louder, until his friend calls him away."},{"text":"Apologise for sending mixed signals","then":"Nikhil softens: \"It's okay.\" Then his phone rings and he wanders off."},{"text":"Say a kiss was a kiss, and go find your friends","then":"Nikhil mutters something, but you're already back with Zara and the others.","best":true}],"why":"A kiss is never a yes to more, and your friends are where you're safe."},{"prompt":"Later that night, you feel shaky and can't stop thinking about it. What do you do?","options":[{"text":"Tell a friend you trust what happened","then":"Zara listens, then says: \"Not sure means stop. This is on him, not you.\"","best":true},{"text":"Keep it to yourself so it's not a big deal","then":"You smile through the rest of the night, carrying it alone."},{"text":"Post a vague story about 'creeps' online","then":"People react with emojis, but no one is actually with you."},{"text":"Decide it was your fault for kissing him","then":"You go home replaying the night, looking for your mistake."}],"why":"It's never your fault. Telling someone you trust means you're not carrying it alone."},{"prompt":"A week later, Nikhil's friend says you should give him another chance. What do you do?","options":[{"text":"Tell yourself one chat is only fair to him","then":"You start to feel you owe Nikhil a hearing you never wanted to give."},{"text":"Explain every detail of that night to prove your point","then":"The friend argues each detail, and you end up defending yourself."},{"text":"Wonder if you were too harsh on Nikhil","then":"The friend senses it and pushes harder for 'just one chat'."},{"text":"Say no, and that you don't owe anyone a reason","then":"The friend shrugs and drops it. Your no stands on its own.","best":true}],"why":"You never owe a yes, or a second chance, to avoid awkwardness."}],"debrief":"Consent is an enthusiastic yes; anything less is a stop, and it's never your fault when someone ignores it.","relearn":"'Not sure' means stop; you never owe a yes to avoid awkwardness."},
  {"id":"cr-002","cat":"real-situations","type":"role-play","persona":"any","source":"voicing a boundary","hook":"You're seeing Advait, and you want to slow things down physically.","setup":"He's walking you back to your hostel after dinner.","steps":[{"prompt":"Advait asks: \"Want to come to mine instead? My flatmate's away.\"","options":[{"text":"\"Um, maybe? I don't know.\"","then":"Advait pauses: \"Maybe? Then let's not tonight.\""},{"text":"\"Sorry, sorry. I'm just really old-fashioned.\"","then":"Advait laughs: \"No need to be sorry. Just for a bit?\""},{"text":"\"I'm into you, and I want to slow down. That okay?\"","then":"Advait smiles: \"Totally okay. Thanks for telling me.\"","best":true},{"text":"\"Is that all you want from me?\"","then":"Advait looks stung: \"What? No. I just asked.\""}],"why":"Naming it plainly, with warmth, lets a good partner welcome it."},{"prompt":"A few steps on, Advait asks: \"Was I moving too fast? I thought we were on the same page.\"","options":[{"text":"\"You should have just known.\"","then":"Advait frowns: \"How? You never said.\""},{"text":"\"We are. I just want to go slower physically.\"","then":"Advait nods: \"Got it. Slow is good. I'd rather you enjoy it.\"","best":true},{"text":"\"Let's talk about it some other day, maybe.\"","then":"Advait shrugs: \"Okay...\" The question hangs between you."},{"text":"\"I guess I'm just not that fun a person.\"","then":"Advait sighs: \"That's not what I said.\""}],"why":"Plain words and reassurance keep you both on the same page."},{"prompt":"A week later, Advait says: \"Tell me if I ever go too fast, okay?\"","options":[{"text":"\"I will. And you tell me too.\"","then":"Advait grins: \"Deal. This feels easy.\"","best":true},{"text":"\"You won't. Don't worry about it.\"","then":"Advait smiles, unsure: \"Okay, if you say so.\""},{"text":"\"I'll try, but I hate saying things like that.\"","then":"Advait nods: \"Hmm. Then how will I know?\""},{"text":"\"Just read my face. You'll know.\"","then":"Advait laughs: \"I'm not that good at faces.\""}],"why":"Making it a two-way deal keeps both of you comfortable saying things."}],"relearn":"You can name a boundary plainly; a good partner welcomes it."},
  {"id":"cr-003","cat":"real-situations","type":"branch","persona":"any","source":"enthusiasm vs politeness","hook":"Things are warming up with Meher. She says yes, but it sounds more polite than keen.","steps":[{"prompt":"She glances away as she says it. What do you do?","options":[{"text":"Take the yes and carry on","then":"Meher smiles tightly and goes quieter. Something feels off."},{"text":"Ask \"You sure?\" in a light, teasing voice","then":"Meher laughs and says \"yeah, yeah\". You still can't tell."},{"text":"Stop and ask her what you did wrong","then":"Meher rushes to reassure you, and now she's managing your feelings."},{"text":"Check in: \"Only if you actually want to\"","then":"Meher pauses, then says she'd rather slow down tonight.","best":true}],"why":"A polite yes isn't an eager one. Checking in makes space for the real answer."},{"prompt":"A little later, Meher says she likes you but isn't ready for more yet. What do you do?","options":[{"text":"Say you understand, then ask when she will be","then":"Meher shifts: \"I don't know.\" She goes quiet."},{"text":"Go quiet so she knows you're disappointed","then":"Meher apologises, and the evening sours."},{"text":"Say that's fine, and suggest just one more kiss","then":"Meher hesitates, and the ease between you slips away."},{"text":"Thank her for saying so, and slow right down","then":"Meher relaxes and leans into your shoulder. The evening feels easy.","best":true}],"why":"Thanking her makes her no easy to say, and that makes her yes mean more."},{"prompt":"Next week, a friend says checking in mid-moment kills the mood. What do you say?","options":[{"text":"Agree it's awkward, but safer","then":"Your friend nods, and checking in stays a chore in both your heads."},{"text":"Say an eager yes is what makes it good anyway","then":"Your friend thinks, then admits they've taken a polite yes at face value before.","best":true},{"text":"Joke that you got lucky she said anything","then":"The joke lands, and the point about asking gets lost."},{"text":"Say you'll just read body language next time","then":"Your friend agrees, though Meher's words told you more than her face."}],"why":"Enthusiasm is the bar, and checking in is how you know you've got it."}],"debrief":"Enthusiasm is the bar; a polite, going-along yes isn't it.","relearn":"A yes to please isn't enthusiastic consent; check in for the real one."},
  {"id":"cr-004","cat":"real-situations","type":"spot","persona":"any","source":"reading the yes","relearn":"Only a clear, willing yes is consent; 'I guess' or 'fine' is not.","hook":"Spot the enthusiastic yes.","scene":[{"id":"a","text":"\"Yes, I really want to\"","trick":false},{"id":"b","text":"A quiet, unsure \"...I guess\"","trick":true},{"id":"c","text":"\"Yes, let's\" with a real grin","trick":false},{"id":"d","text":"\"Fine, whatever, if you want\"","trick":true},{"id":"e","text":"\"Definitely, I'm into this\"","trick":false}],"why":"Only a clear, willing yes is consent; an unsure 'I guess' or a worn-down 'fine' is not."},
  {"id":"cr-005","cat":"real-situations","type":"branch","persona":"any","source":"consent in relationships","hook":"You've been with Arnav for a year. Tonight he isn't in the mood, though usually he is.","steps":[{"prompt":"He says \"not tonight, sorry\". What do you do?","options":[{"text":"Remind him you're together, so it's expected","then":"Arnav goes stiff and says quietly: \"That's not how it works.\""},{"text":"Say okay, then turn away and go quiet","then":"Arnav notices, and apologises for something he doesn't owe."},{"text":"Ask if he's gone off you","then":"Arnav sighs and spends the evening reassuring you."},{"text":"Say \"no worries\" and pick a film together","then":"Arnav smiles, relieved, and picks a film you both like.","best":true}],"why":"A warm, no-pressure reply shows consent is needed every time, partner or not."},{"prompt":"A few days later, it happens again. What do you do?","options":[{"text":"Say okay, and that he can talk to you anytime","then":"Arnav squeezes your hand. Later, he mentions work has been draining him.","best":true},{"text":"Keep a count so you can raise it later","then":"The count grows, and so does a quiet resentment."},{"text":"Ask him what's changed lately, so you can fix it","then":"Arnav hesitates, then lists reasons, as if a no needed one."},{"text":"Try harder to get him in the mood","then":"Arnav pulls away, tired, and says he just wants to sleep."}],"why":"A no needs no reason. Leaving the door open, without digging, is real care."},{"prompt":"Arnav asks if you're upset with him about it. What do you say?","options":[{"text":"Say 'a bit', so he knows it matters to you","then":"Arnav looks guilty, and the next no gets harder for him to say."},{"text":"Say it's fine, but hint you're keeping score","then":"He laughs uneasily, unsure if you're joking."},{"text":"Say it's fine, as long as it's not every week","then":"Arnav nods, but now every no feels counted."},{"text":"Say no, and that his no is always welcome","then":"Arnav hugs you: \"Thanks. That makes it easier to be honest.\"","best":true}],"why":"Knowing his no is safe makes his yes mean more."}],"debrief":"A relationship doesn't bank consent; it's freely given each time.","relearn":"Being in a relationship never means an automatic yes; consent is each time."},
  {"id":"cr-006","cat":"real-situations","type":"role-play","persona":"any","source":"checking in","hook":"Things are getting close with Kabir, and you want checking in to feel natural.","setup":"You're both on his sofa after a film.","steps":[{"prompt":"Kabir leans in and says: \"This is nice.\"","options":[{"text":"\"You'd tell me if you weren't into it, right?\"","then":"He nods. \"Sure,\" he says, and doesn't add anything."},{"text":"\"Is this good for you? Tell me what you want.\"","then":"He grins. \"Honestly? Slower. I like this.\"","best":true},{"text":"\"Good. I'll take that as a yes to everything.\"","then":"He laughs, a little unsure. \"Everything? Let's see.\""},{"text":"\"You're smiling, so I know you're into this.\"","then":"He smiles, but doesn't say whether he is."}],"why":"An open, warm question invites his real answer instead of waiting for an objection."},{"prompt":"A little later Kabir pauses and asks: \"What do you like? I want to know.\"","options":[{"text":"\"Whatever you want is fine with me.\"","then":"He hesitates. \"I'd rather know what you actually want.\""},{"text":"\"You don't need to ask. I'll say if something's off.\"","then":"\"Okay,\" he says, and stops asking for the rest of the night."},{"text":"\"I like this pace. And I like that you asked.\"","then":"He smiles. \"Me too. This feels easy now.\"","best":true},{"text":"\"Ha, let's not make this a whole discussion.\"","then":"He goes a bit quiet. \"Right. Sorry I asked.\""}],"why":"Answering honestly and welcoming his question makes checking in a two-way habit."},{"prompt":"The next week your friend Nisha asks: \"Doesn't asking kill the mood?\"","options":[{"text":"\"Sometimes. You just read their body language.\"","then":"\"But what if I read it wrong?\" Nisha asks."},{"text":"\"Only if they seem unsure. Otherwise, why bother?\"","then":"Nisha nods. \"So if they seem fine, just go ahead?\""},{"text":"\"Yeah, a bit. I only did it because I was nervous.\"","then":"\"See? It is awkward,\" Nisha says, and shrugs it off."},{"text":"\"Not at all. Asking 'is this good?' builds trust.\"","then":"Nisha looks surprised. \"Huh. Maybe I should try that.\"","best":true}],"why":"Checking in warmly builds trust. A calm face or silence isn't the same as a yes."}],"relearn":"Checking in warmly is part of good intimacy, not a mood-killer."},
  {"id":"cr-007","cat":"real-situations","type":"branch","persona":"any","source":"digital consent","hook":"Harsh, who you've been chatting with, asks for an intimate photo. You're not comfortable.","steps":[{"prompt":"He says everyone sends them these days. What do you do?","options":[{"text":"Say no. Your comfort decides, not his asking","then":"Harsh sends a sulky \"ok fine\". You feel lighter for saying it.","best":true},{"text":"Tell yourself one photo is harmless if he's nice","then":"The thought makes his ask feel smaller, and your unease feel silly."},{"text":"Wonder if you're being old-fashioned about it","then":"The doubt nags at you, and you start to feel like the problem."},{"text":"Ask a friend, who says one photo won't hurt","then":"Your friend shrugs it off, and your no starts to feel like overthinking."}],"why":"Your comfort is the whole answer. Consent covers photos too."},{"prompt":"Next day, Harsh says you'd send it if you really trusted him. What do you do?","options":[{"text":"Wonder if he's right and you don't trust him enough","then":"The question turns your no into a test of you, not him."},{"text":"Say trust isn't a photo, and your no stands","then":"Harsh goes quiet for a day, then sends a short \"sorry\".","best":true},{"text":"Explain all your reasons, one by one","then":"Harsh argues each reason back, and the chat drags on for an hour."},{"text":"Ask him to send one first, to test him","then":"Harsh sends one straight away, and now you feel you owe him."}],"why":"Trust never requires a photo. Pressure isn't consent online either."},{"prompt":"By the weekend, Harsh has asked four more times. What do you do?","options":[{"text":"Keep it to yourself so no one judges you","then":"The messages keep coming, and you carry them alone."},{"text":"Tell a friend you trust and mute his chat","then":"Your friend Sana helps you mute him: \"Your no was enough the first time.\"","best":true},{"text":"Blame yourself for flirting back at first","then":"You scroll old chats, looking for your mistake instead of his."},{"text":"Reply \"stop\" to every single message he sends","then":"You spend the weekend answering him, and he keeps asking."}],"why":"Repeated asking is pressure, and never your fault. A trusted friend helps you hold your no."},{"prompt":"A week later, a friend says in your group chat that face-cropped pics are 'totally safe'. What do you say?","options":[{"text":"Agree that cropping makes it okay","then":"Your friend sends a thumbs up, and a workaround starts to look like a plan."},{"text":"Say not wanting to is reason enough","then":"Your friend replies: \"Fair. No one should send what they don't want to.\"","best":true},{"text":"Tell the whole group about Harsh's asks","then":"The chat explodes with opinions, and now everyone is in your business."},{"text":"Send a laughing emoji and scroll on","then":"Someone else agrees, and the idea goes unanswered."}],"why":"Not wanting to is reason enough. No workaround changes that."}],"debrief":"Consent applies to sexting and photos; pressure doesn't override your no.","relearn":"Consent applies online too; pressure to send doesn't override your no."},
  {"id":"cr-008","cat":"real-situations","type":"sort","persona":"any","source":"reading the yes","relearn":"A clear, willing yes is consent; silence or a pressured 'I suppose' is not.","hook":"Sort: a true yes, or not really?","items":[{"id":"a","text":"\"Yes, I want to\""},{"id":"b","text":"Silence and stillness"},{"id":"c","text":"An eager, clear yes"},{"id":"d","text":"\"I suppose, if you'll be upset otherwise\""},{"id":"e","text":"\"Yes, definitely\""},{"id":"f","text":"A shrug and looking away"}],"bins":[{"id":"yes","label":"A true yes","valence":"pos"},{"id":"no","label":"Not really","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"}},
  {"id":"cr-009","cat":"real-situations","type":"branch","persona":"any","source":"ongoing consent","hook":"Mid-moment with Ishaan, he goes quiet and still, and the energy shifts.","steps":[{"prompt":"He hasn't said anything. What do you do?","options":[{"text":"Keep going since he hasn't said stop","then":"Ishaan stays still, eyes on the ceiling, then quietly moves your hand away."},{"text":"Pause and ask if he's okay","then":"Ishaan lets out a breath: \"Can we stop? I'm not feeling it.\"","best":true},{"text":"Slow down but keep going gently","then":"Ishaan doesn't respond, then turns onto his side."},{"text":"Ask: \"Is something wrong with me?\"","then":"Ishaan shakes his head quickly, now worried about you instead."}],"why":"Going quiet and still is a reason to pause and check, not a green light."},{"prompt":"Ishaan says he's not sure why he went so still. What do you do?","options":[{"text":"Ask him to explain, so you can avoid it next time","then":"Ishaan struggles for words and ends up apologising."},{"text":"Say it happens to everyone and move on","then":"Ishaan nods, but he still looks shaken, and you don't know why."},{"text":"Tell him he should've just said stop","then":"Ishaan goes quiet again: \"I know. Sorry.\""},{"text":"Say he doesn't have to explain, and ask what he needs","then":"Ishaan says he needs sleep and a hug, nothing more. You give him both.","best":true}],"why":"Freezing is a common response. He owes no explanation, just care."},{"prompt":"Next time things heat up, you want to know he's really with you. What do you do?","options":[{"text":"Wait for him to say stop if he wants to","then":"He goes quiet again at one point, and you're left guessing."},{"text":"Ask once at the start, then relax","then":"He says yes at the start. Midway, you notice his hands go still."},{"text":"Check in as you go: \"Still good?\"","then":"Ishaan laughs softly: \"Still good. Very good.\"","best":true},{"text":"Keep things short so there's less to go wrong","then":"It's quick and a bit tense, and neither of you really enjoys it."}],"why":"Consent is ongoing. A quick check keeps you both in it."}],"debrief":"Consent is ongoing; a shift in someone's energy means pause and check.","relearn":"If someone goes quiet or still, pause and check; it isn't a green light."},
  {"id":"cr-010","cat":"real-situations","type":"spot","persona":"any","source":"freely given","relearn":"Consent needs real freedom; a worn-down or pressured yes isn't free.","hook":"Spot the freely-given yes.","scene":[{"id":"a","text":"Yes, with no pressure in the room","trick":false},{"id":"b","text":"Yes, after being worn down for an hour","trick":true},{"id":"c","text":"Yes, relaxed and unhurried","trick":false},{"id":"d","text":"Yes, because a senior asked","trick":true},{"id":"e","text":"Yes, said warmly and freely","trick":false}],"why":"Consent needs real freedom; a worn-down or power-pressured yes isn't free."},
  {"id":"cr-011","cat":"real-situations","type":"branch","persona":"Ananya","source":"revocable consent","hook":"You said yes to Rahul earlier tonight, but now you've changed your mind.","steps":[{"prompt":"He's still keen and hasn't noticed. What do you do?","options":[{"text":"Say it plainly: \"I've changed my mind\"","then":"Rahul pauses: \"Oh. Okay. Did I do something?\"","best":true},{"text":"Tell yourself a yes can't be taken back","then":"The thought keeps you quiet, but Rahul notices you've gone stiff and stops."},{"text":"Recall a friend saying backing out is cruel","then":"You go quiet and tense, and Rahul stops, puzzled."},{"text":"Hint by checking your phone a lot","then":"Rahul stops and asks if you're bored. He hasn't understood."}],"why":"A yes is revocable, always. Saying so plainly is enough."},{"prompt":"Rahul says, a little hurt, that you seemed so keen earlier. What do you do?","options":[{"text":"Say you were, and now you're not","then":"Rahul nods slowly: \"Okay. Fair enough.\"","best":true},{"text":"Apologise and explain every reason","then":"Rahul picks at each reason, and you feel on trial."},{"text":"Say sorry and offer to make it up to him","then":"Rahul brightens, and now it feels like you owe him."},{"text":"Wonder if changing your mind makes you a tease","then":"The word stings, and you start to feel you owe him more."}],"why":"Changing your mind needs no defence. You owe no reason."},{"prompt":"Walking home, you wonder if changing your mind was unfair. What do you tell yourself?","options":[{"text":"That next time you shouldn't say yes so fast","then":"You decide to hold back your yeses, just in case."},{"text":"That Rahul was probably upset and you should text sorry","then":"You draft three apologies and send none."},{"text":"That a yes can change at any point, no reason owed","then":"You reach home feeling steady. Your mind was yours to change.","best":true},{"text":"That it was only okay because nothing much had started","then":"The idea stays that later on, stopping wouldn't have been allowed."}],"why":"Consent is revocable at every point. Changing your mind is never unfair or your fault."}],"debrief":"Consent is revocable; you can stop at any time, no matter what you said before.","relearn":"You can withdraw consent at any time; an earlier yes doesn't bind you."},
  {"id":"cr-012","cat":"real-situations","type":"role-play","persona":"any","source":"changing your mind","hook":"You and Aryan are making out in his room, and you realise you want to stop.","setup":"The room is quiet except for his music.","steps":[{"prompt":"Aryan pulls back and asks: \"Hey, you okay?\"","options":[{"text":"\"Sorry, I'm being weird. Is it okay if we stop?\"","then":"\"You're not being weird,\" he says. \"Of course we can stop.\""},{"text":"\"I'm just tired. Maybe another night?\"","then":"\"Sure,\" he says. \"Tomorrow, then?\" He sounds hopeful."},{"text":"\"I want to stop here.\"","then":"He nods and sits back. \"Okay. Want some water?\"","best":true},{"text":"\"It's not you. My parents would kill me if they knew.\"","then":"He nods, confused. \"Okay. So is it them, or you?\""}],"why":"A plain \"I want to stop\" is enough. You don't owe an apology or a reason."},{"prompt":"A bit later Aryan asks: \"Can I ask what changed?\"","options":[{"text":"\"Nothing you did. I just don't want to right now.\"","then":"\"Okay,\" he says. \"Thanks for telling me. No pressure.\"","best":true},{"text":"\"I'll explain properly once I've figured it out.\"","then":"\"Okay. Let me know when you know,\" he says."},{"text":"\"Does it matter? Why are you making it a big deal?\"","then":"He blinks. \"I wasn't. I just wanted to check you're okay.\""},{"text":"\"I'm sorry. I know I led you on.\"","then":"He frowns. \"You didn't lead me on. You can stop.\""}],"why":"You never owe a reason for stopping, and stopping never means you led anyone on."},{"prompt":"The next day Aryan texts: \"Last night was still nice. We good?\"","options":[{"text":"\"Yes! Next time I'll make it up to you.\"","then":"\"Oh? Can't wait,\" he replies, with a wink emoji."},{"text":"\"Sorry again for ruining the mood last night.\"","then":"\"You didn't ruin anything,\" he replies. You still feel guilty."},{"text":"\"Let's just not talk about last night.\"","then":"\"Okay,\" he replies. The next few chats feel oddly careful."},{"text":"\"We're good. I liked it, stop and all.\"","then":"\"Same,\" he replies. \"Dinner on Friday?\"","best":true}],"why":"Stopping isn't a debt. You can like someone and still keep every future choice."}],"relearn":"You can stop at any time and you don't owe a reason."},
  {"id":"cr-013","cat":"real-situations","type":"branch","persona":"Deepak","source":"equals / power","hook":"At your internship, your manager Ms. Kapoor, who'll write your reference, makes a pass at you.","steps":[{"prompt":"She says interns who are 'friendly' go far. What do you do?","options":[{"text":"Assume it's fine, since she's the senior one","then":"You start rethinking everything she's said, unsure where the line is."},{"text":"Recognise it as pressure, not a free choice","then":"The knot in your stomach makes sense now. This isn't about you.","best":true},{"text":"Wonder if you gave her the wrong idea","then":"You replay every smile and email, looking for your mistake."},{"text":"Take it as a compliment on your work","then":"You feel flattered for a moment, then uneasy about Monday."}],"why":"A power gap means her ask isn't a free choice for you. That's coercion, not consent."},{"prompt":"Next day, she asks you to stay late to 'go over your work'. What do you do?","options":[{"text":"Confront her in front of the whole team","then":"The room goes silent, and she calls it a misunderstanding in front of everyone."},{"text":"Offer to go over it in the day, with the team","then":"She pauses, then says: \"Fine. Tomorrow at eleven.\" You breathe out.","best":true},{"text":"Tell yourself staying late is part of interning","then":"The thought makes her ask feel normal, and your unease feel like the problem."},{"text":"Ask a friend, who says just keep her happy","then":"The advice makes her pressure sound like your job to manage."}],"why":"Keeping work in daylight, with others around, protects you without a fight."},{"prompt":"That night, the worry won't let you sleep. What do you do?","options":[{"text":"Keep quiet till the internship ends","then":"Weeks drag by, and every meeting with her feels heavy."},{"text":"Post a vague rant about bosses online","then":"Friends like it, but no one knows what's wrong or how to help."},{"text":"Tell a mentor or teacher you trust what happened","then":"Your mentor listens: \"This is not on you. Let's work out your options.\"","best":true},{"text":"Decide it's your fault for being too friendly","then":"You go quiet at work, blaming yourself for her choices."}],"why":"It's never your fault. Someone you trust can help you weigh your options."},{"prompt":"Over chai, a friend says interns should play along with bosses to get a good reference. What do you say?","options":[{"text":"Say a yes under pressure isn't a free yes","then":"Your friend pauses: \"True. I wouldn't want that either.\"","best":true},{"text":"Agree that the reference is worth it","then":"The idea sits heavy, as if your comfort had a price."},{"text":"Say it's different when the boss is a woman","then":"Your friend nods, and the pressure gets waved away."},{"text":"Change the subject so you don't have to think","then":"The idea hangs around in your head all week."}],"why":"Consent needs equals. A yes bought with a reference isn't freely given."}],"debrief":"Consent needs equals; a power dynamic can make a 'yes' unfree.","relearn":"A power gap can remove real freedom, making a yes coercion, not consent."},
  {"id":"cr-014","cat":"real-situations","type":"reflect","hook":"Lensy: enthusiasm is the bar, an ongoing, freely-given yes. Does that feel like the standard?","prompt":"What do you think?","options":["Yes","The bar","Enthusiasm"],"affirm":"Enthusiasm as the bar protects everyone and makes intimacy better, not less.","relearn":"Enthusiasm is the bar: an ongoing, freely-given yes.","persona":"any","source":"the standard"},
  {"id":"cr-015","cat":"real-situations","type":"sort","persona":"any","source":"consent-first","relearn":"Checking in and stopping at hesitation is consent-first; assuming and silence aren't.","hook":"Sort: consent-first, or not?","items":[{"id":"a","text":"Checking in as things go"},{"id":"b","text":"Assuming a yes carries all night"},{"id":"c","text":"Stopping the moment they hesitate"},{"id":"d","text":"Treating silence as agreement"},{"id":"e","text":"Pausing to ask \"still good?\""},{"id":"f","text":"Pushing past a quiet \"wait\""}],"bins":[{"id":"first","label":"Consent-first","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"first","b":"not","c":"first","d":"not","e":"first","f":"not"}},
  {"id":"cr-016","cat":"drinks-and-capacity","type":"strike-rewrite","hook":"\"They didn't resist, so it was fine.\"","myth":{"un":"They didn't resist, so it was fine.","re":"Not resisting is never consent, especially if someone is drunk or frozen.","why":"Consent is an active yes, not the absence of a fight."},"relearn":"Not resisting is never consent; consent is an active yes.","persona":"any","source":"capacity / not resisting"},
  {"id":"cr-017","cat":"drinks-and-capacity","type":"branch","persona":"Ananya","source":"incapacitation","hook":"Neha, who you've liked for weeks, is very drunk at a party and starts coming onto you.","steps":[{"prompt":"She's slurring and pulling you towards a quiet room. What do you do?","options":[{"text":"Go with it. She's the one who started it","then":"Neha stumbles on the stairs and grabs the rail to stay upright."},{"text":"Kiss her back for a minute, then pull away","then":"Neha doesn't seem to notice when you pull away. She's barely steady."},{"text":"Stop, and help her find water and her friends","then":"Neha pouts but sits down. Her friend Kriti comes over, relieved to find her.","best":true},{"text":"Ask her: \"Are you sure you want this?\"","then":"Neha slurs \"totally\" and nearly falls over."}],"why":"Someone that drunk can't consent, no matter who started it. Getting her safe comes first."},{"prompt":"Neha insists she knows exactly what she wants. What do you say?","options":[{"text":"\"Okay. If you're really, really sure about it\"","then":"Neha nods, eyes half closed. She can't finish her sentence."},{"text":"\"Not tonight. If you still want this sober, let's talk\"","then":"Neha rolls her eyes, then sits down heavily on the stairs.","best":true},{"text":"\"You're way too drunk. It's embarrassing\"","then":"Neha's face crumples and she turns away from you."},{"text":"\"Maybe just a little, then. Just for a bit\"","then":"Neha sways and grabs your arm to stay up."}],"why":"A kind, clear \"not tonight\" keeps the door open for a real, sober yes."},{"prompt":"Soon, Neha's friend Kriti asks you to help get Neha home. What do you do?","options":[{"text":"Help Kriti get her into a cab, and check she got home","then":"Kriti texts later: \"She's in bed with water. Thank you.\"","best":true},{"text":"Say she'll be fine sleeping it off on the sofa here","then":"Kriti looks worried. Strangers keep walking past Neha all night."},{"text":"Offer to take Neha home on your own","then":"Kriti hesitates. She doesn't know you well enough to agree."},{"text":"Leave it to Kriti. It's not your job","then":"Kriti struggles to hold Neha up on the way to the gate."}],"why":"Getting her home with a friend she trusts is looking out, not taking over."},{"prompt":"Next day, Neha texts, embarrassed, asking what happened between you two. What do you reply?","options":[{"text":"\"Don't worry about it. Let's just forget it\"","then":"Neha sends \"ok\". She still has no idea what happened."},{"text":"\"You were a mess last night. Be more careful next time\"","then":"Neha feels judged and leaves you on read."},{"text":"\"Honestly? You owe me one for last night\"","then":"Neha sends a nervous laugh and goes quiet."},{"text":"\"I'll tell you all of it. You were too drunk to decide\"","then":"You explain. After a while Neha replies: \"Thank you for telling me straight.\"","best":true}],"why":"Plain facts, with no judgement, answer her worry and keep it about capacity, not shame."}],"debrief":"If someone is incapacitated, there's no consent to be had, whoever started it.","relearn":"An incapacitated person can't consent, no matter who started it."},
  {"id":"cr-018","type":"sort","hook":"Sort: can give consent right now, or cannot?","items":[{"id":"a","text":"Sober and clearly willing"},{"id":"b","text":"Slurring, can barely stand"},{"id":"c","text":"Passed out / asleep"},{"id":"d","text":"Had one drink, fully with it"},{"id":"e","text":"Blackout drunk, not making sense"},{"id":"f","text":"A glass of wine, sharp and keen"}],"bins":[{"id":"can","label":"Can consent","valence":"pos"},{"id":"cant","label":"Cannot","valence":"neg"}],"key":{"a":"can","b":"cant","c":"cant","d":"can","e":"cant","f":"can"},"relearn":"Incapacitated, blackout or asleep means no capacity to consent; mildly tipsy-but-with-it can.","persona":"any","source":"capacity line","cat":"drinks-and-capacity"},
  {"id":"cr-019","cat":"drinks-and-capacity","type":"strike-rewrite","hook":"\"If they're drinking at all, anything goes.\"","myth":{"un":"If they're drinking at all, anything goes.","re":"It's about incapacity, not any drink; if there's any doubt they're too far gone, you wait.","why":"The safe rule is simple: unsure means stop."},"relearn":"It's incapacity that removes consent, not any drink; if in doubt, wait.","persona":"any","source":"capacity nuance"},
  {"id":"cr-020","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"looking out","hook":"At a house party, you see a guy steering Simi, a girl you vaguely know, towards a bedroom. She's clearly wasted.","steps":[{"prompt":"She's leaning on him and can barely walk. What do you do?","options":[{"text":"Step in: check on her, and get a friend or the host","then":"The guy stops. Simi squints at you and mumbles that she feels sick.","best":true},{"text":"Assume it's none of your business, and look away","then":"Moments later, Simi stumbles into you. The guy is right behind her."},{"text":"Film it on your phone, just in case you need it","then":"The guy notices your phone and walks over, annoyed."},{"text":"Wait a few minutes, then knock on the door to check","then":"The guy opens the door a crack. You can't see Simi behind him."}],"why":"Someone that drunk can't look out for herself. Stepping in now is what counts."},{"prompt":"The guy says he's her friend and is just helping her lie down. What do you do?","options":[{"text":"Believe him, and head back to the party","then":"Simi looks back at you as they go. Minutes later, the host brings her out, sick and shaking."},{"text":"Shove him away from her and pull her back","then":"He shoves back. A crowd gathers, and Simi slumps to the floor in the middle of it."},{"text":"Ask Simi if she wants to go with him","then":"Simi mumbles something. \"See? She's fine,\" he says, just as she doubles over."},{"text":"Say you'll stay with her, and get the host","then":"The host comes over. The guy mutters something and walks away.","best":true}],"why":"Staying with her and getting the host keeps her safe without a fight."},{"prompt":"The guy has slipped away. Simi feels sick, and her friends aren't answering. What do you do?","options":[{"text":"Put her in a cab alone so she gets home quickly","then":"The driver asks Simi for an address. She can't give one."},{"text":"Leave her on the sofa to sleep it off in peace","then":"You come back later. Simi is alone, and people keep wandering past."},{"text":"Stay with her, get water, keep trying her friends","then":"Her friend Lavanya finally calls back and says she's on her way.","best":true},{"text":"Post in the party group asking who knows her","then":"A few people reply \"no idea\". Simi's name gets passed around."}],"why":"Staying with her until a trusted friend arrives means she's never alone and exposed."},{"prompt":"Next week, people gossip that Simi \"got herself into that state\". What do you say?","options":[{"text":"\"She did drink a lot, though, to be fair\"","then":"The group nods. Simi becomes the story, not him."},{"text":"\"Drinking isn't a crime. He was the problem\"","then":"The gossip stalls. Someone mutters that they hadn't thought of it that way.","best":true},{"text":"Nothing. It's not your story to tell","then":"The gossip keeps going. It reaches Simi by Friday."},{"text":"Tell them exactly what you saw that night","then":"The group leans in for details. Simi's night becomes everyone's gossip."}],"why":"Blame belongs with the person who ignored her state. It was never her fault."}],"debrief":"Looking out for friends and strangers alike is what a consent culture does.","relearn":"Look out for someone too drunk to look out for themselves; step in."},
  {"id":"cr-021","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"bystander","hook":"Your friend Aman is very drunk, and a stranger at the bar is getting handsy with him.","setup":"You reach them just as Aman sways against the stranger.","steps":[{"prompt":"The stranger smirks: \"Relax, he's having fun with me.\"","options":[{"text":"\"Hey, he's with me. Come on, Aman, let's get water.\"","then":"The stranger rolls their eyes: \"Whatever. Take him.\" Aman leans on you.","best":true},{"text":"\"Aman, are you okay with this?\"","then":"Aman mumbles: \"Huh? Yeah, 's fine.\" The stranger's grin widens."},{"text":"\"Get your hands off him, or you'll regret it, mate.\"","then":"The stranger squares up: \"Or what?\" People turn to stare."},{"text":"\"Sorry to interrupt. Just checking in.\"","then":"The stranger waves you off: \"All good here, thanks.\" Aman sways."}],"why":"A light, firm line gets your friend out without a fight."},{"prompt":"A bouncer walks over and asks: \"What's going on here?\"","options":[{"text":"\"My friend's very drunk. Can you help me get him out?\"","then":"The bouncer nods, steps between Aman and the stranger, and clears a path.","best":true},{"text":"\"Nothing, sorry. We're fine.\"","then":"The bouncer shrugs: \"Keep it calm, then.\" He walks off."},{"text":"\"This creep is all over him. Throw them out, now!\"","then":"The bouncer frowns: \"Calm down. Who's harassing who?\""},{"text":"\"Ask him yourself. He'll tell you.\"","then":"Aman mumbles something no one can follow, and the bouncer looks unsure."}],"why":"Asking staff for help gets your friend out safely, without a fight."},{"prompt":"Next day, Aman texts: \"Sorry about last night. Was I embarrassing?\"","options":[{"text":"\"Honestly, a bit. You were all over them all night.\"","then":"Aman replies: \"Oh god. Never drinking again.\" Then he goes quiet."},{"text":"\"Let's just never talk about it.\"","then":"Aman sends \"ok\" and nothing else all day."},{"text":"\"Not at all. That person crossed a line, not you.\"","then":"Aman replies: \"Thanks. I don't remember much, but I'm glad you were there.\"","best":true},{"text":"\"You were fine. It was all a laugh.\"","then":"Aman replies: \"Was it? I don't remember much.\" He sounds uneasy."}],"why":"Putting it on the person who crossed the line takes the shame off him."}],"relearn":"A simple, firm intervention can keep a drunk friend safe."},
  {"id":"cr-022","cat":"drinks-and-capacity","type":"strike-rewrite","hook":"\"We were both drunk, so it cancels out.\"","myth":{"un":"We were both drunk, so it cancels out.","re":"Both drinking doesn't erase the need for consent or the harm if someone couldn't agree.","why":"Two people drinking isn't a free pass."},"relearn":"Both drinking doesn't cancel the need for consent or the harm done.","persona":"any","source":"mutual intoxication"},
  {"id":"cr-023","type":"sort","hook":"Sort: looking out for each other, or not?","items":[{"id":"a","text":"Walking a wasted friend home"},{"id":"b","text":"Leaving them alone with a stranger"},{"id":"c","text":"Checking they got back okay"},{"id":"d","text":"Filming them for a laugh"},{"id":"e","text":"Getting them water and a safe ride"},{"id":"f","text":"Slipping out and ghosting them"}],"bins":[{"id":"out","label":"Looking out","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"out","b":"not","c":"out","d":"not","e":"out","f":"not"},"relearn":"Walking a friend home and checking in is looking out; abandoning or filming them isn't.","persona":"any","source":"consent culture","cat":"drinks-and-capacity"},
  {"id":"cr-024","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"when in doubt","hook":"You and Aarav have both been drinking at his place, and you can't tell if he's really into it.","steps":[{"prompt":"Things are heating up, but his answers are fuzzy. What do you do?","options":[{"text":"Wait. Sober up, and check in tomorrow","then":"Aarav mumbles \"okay\" and is asleep on the sofa within minutes.","best":true},{"text":"Carry on and hope it's fine","then":"Aarav's eyes keep closing. You're guessing, and you know it."},{"text":"Ask if he wants to, and go with the answer","then":"Aarav slurs \"sure, whatever\" and gazes past you."},{"text":"Have some water together, then carry on","then":"Ten minutes later, Aarav is still fuzzy, and you're no clearer."}],"why":"When capacity is unclear, waiting is the only safe call. There's no prize for not waiting."},{"prompt":"Soon Aarav is fast asleep on the sofa. What do you do?","options":[{"text":"Leave quietly without checking on him","then":"You're halfway home before you wonder if he's okay."},{"text":"Nudge him awake to see if he still wants to","then":"Aarav groans, confused, and can't keep his eyes open."},{"text":"Cover him with a blanket and head home","then":"He's warm, but flat on his back, and nobody checks on him."},{"text":"Turn him on his side and leave water nearby","then":"Aarav snores lightly. You text a friend that you're crashing here.","best":true}],"why":"Someone asleep can't consent. Keeping him safe is the only job left tonight."},{"prompt":"Next morning, Aarav asks, a bit embarrassed, why nothing happened. What do you say?","options":[{"text":"\"You passed out. Kind of a letdown, honestly\"","then":"Aarav goes red and apologises for ruining the night."},{"text":"\"Nothing to talk about. Let's just forget it\"","then":"Aarav looks unsure whether he did something wrong."},{"text":"\"We'd both had too much. I'd rather we remember it\"","then":"Aarav grins. \"Fair. Dinner this week, sober?\"","best":true},{"text":"\"I wasn't sure you were even into me\"","then":"Aarav looks surprised. \"I was. I was just very drunk.\""}],"why":"Naming capacity plainly, without blame, shows that waiting was about both of you."}],"debrief":"Uncertain capacity means wait; there's no prize for not waiting.","relearn":"If you can't tell they have capacity and want it, wait."},
  {"id":"cr-025","cat":"drinks-and-capacity","type":"reflect","hook":"Lensy: when capacity is in doubt, waiting costs nothing and protects everyone. Sit right with you?","prompt":"What do you think?","options":["Yes","Wait, simple","No rush"],"affirm":"Waiting when unsure is never the wrong call; it protects you both.","relearn":"When capacity is in doubt, waiting protects everyone.","persona":"any","source":"the safe rule"},
  {"id":"cr-026","cat":"drinks-and-capacity","type":"strike-rewrite","hook":"\"They were too far gone to say no, so that's a yes.\"","myth":{"un":"They were too far gone to say no, so it's a yes.","re":"Too far gone to say no means too far gone to say yes; that's no consent.","why":"Incapacity can't produce a yes."},"relearn":"Too drunk to say no means too drunk to consent; that's no consent.","persona":"any","source":"incapacity"},
  {"id":"cr-027","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"unconscious","hook":"After a party at your place, your date Sameer falls asleep on your bed mid-sentence.","steps":[{"prompt":"You'd been hoping the night would go further. What do you do?","options":[{"text":"Nudge him. He's basically awake enough","then":"Sameer mumbles something and rolls away, still asleep."},{"text":"Wake him properly and ask if he still wants to","then":"Sameer blinks, groggy and confused. He can barely focus."},{"text":"Leave him and go back out to the party","then":"Sameer sleeps alone as guests wander in and out of the room."},{"text":"Let him sleep, and make sure he's safe","then":"You put a blanket over him and set water by the bed.","best":true}],"why":"Asleep is always a no. There's no grey area, only keeping him safe."},{"prompt":"An hour later, Sameer has rolled flat onto his back. He drank a lot tonight. What do you do?","options":[{"text":"Leave him flat. He's only asleep","then":"Later you hear him cough and splutter in his sleep."},{"text":"Turn him on his side, then go sleep elsewhere","then":"He's on his side. Nobody looks in on him till morning."},{"text":"Turn him on his side, and check on him later","then":"Sameer breathes steadily. When you check at two, he's fine.","best":true},{"text":"Wake him up to drink a lot of water","then":"Sameer can barely hold the glass and spills most of it."}],"why":"Looking after someone passed out means keeping them safe till they wake."},{"prompt":"Next morning, a friend jokes that you \"wasted a perfect chance\" last night. What do you say?","options":[{"text":"Laugh, and admit you were tempted","then":"Your friend laughs harder. The joke gets told again at lunch."},{"text":"\"He was asleep. That's a no, not a chance\"","then":"Your friend stops grinning. \"Yeah. Okay. Fair.\"","best":true},{"text":"\"Shut up. That's honestly disgusting\"","then":"Your friend rolls his eyes and calls you dramatic."},{"text":"\"Maybe next time he'll manage to stay awake\"","then":"Your friend grins. \"Next time, then.\""}],"why":"Saying plainly that asleep means no shifts what your friends think is a joke."}],"debrief":"Asleep or unconscious is always a no; there is no grey area.","relearn":"An asleep or unconscious person can never consent; there's no grey area."},
  {"id":"cr-028","type":"sort","hook":"Sort: capacity present, or absent?","items":[{"id":"a","text":"Alert, clear, saying yes"},{"id":"b","text":"Can't keep their eyes open"},{"id":"c","text":"Drifting in and out"},{"id":"d","text":"Tipsy but sharp and keen"},{"id":"e","text":"Talking clearly, eyes bright"},{"id":"f","text":"Slumped, head lolling"}],"bins":[{"id":"present","label":"Capacity present","valence":"pos"},{"id":"absent","label":"Absent","valence":"neg"}],"key":{"a":"present","b":"absent","c":"absent","d":"present","e":"present","f":"absent"},"relearn":"Alert and clear has capacity; can't-stay-awake or drifting does not.","persona":"any","source":"capacity","cat":"drinks-and-capacity"},
  {"id":"cr-029","type":"spot","hook":"Spot who cannot consent in this scene.","scene":[{"id":"a","text":"The friend who's blacked out on the sofa","trick":true},{"id":"b","text":"The two chatting clearly by the door","trick":false},{"id":"c","text":"The person being held up, eyes rolling","trick":true},{"id":"d","text":"The pair laughing and dancing, fully alert","trick":false},{"id":"e","text":"Two sober friends deciding to head upstairs","trick":false}],"why":"Blacked-out or barely-conscious people cannot consent; alert people talking can.","relearn":"Blacked-out or barely-conscious people cannot consent.","persona":"any","source":"capacity","cat":"drinks-and-capacity"},
  {"id":"cr-030","cat":"drinks-and-capacity","type":"strike-rewrite","hook":"\"What people do at a party isn't anyone else's responsibility.\"","myth":{"un":"What happens at a party is no one else's business.","re":"A consent culture means we do look out for each other, especially when drink is involved.","why":"Bystanders prevent a lot of harm."},"relearn":"In a consent culture we look out for each other, especially around drink.","persona":"any","source":"consent culture"},
  {"id":"cr-031","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They didn't say no, so it was consent.\"","myth":{"un":"They didn't say no, so it was consent.","re":"Consent is an active, willing yes; the absence of a no is not it.","why":"Many people freeze and can't say no."},"relearn":"Consent is an active yes; the absence of a no is not consent.","persona":"any","source":"the no myth"},
  {"id":"cr-032","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"We're in a relationship, so it's assumed.\"","myth":{"un":"We're together, so consent is assumed.","re":"A relationship never assumes consent; it's asked and given freely each time.","why":"Partners can still say no, any time."},"relearn":"A relationship never assumes consent; it's freely given each time.","persona":"any","source":"relationship myth"},
  {"id":"cr-033","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They came back to mine, so they wanted it.\"","myth":{"un":"They came back to mine, so they wanted it.","re":"Coming over, kissing, or anything earlier is never agreement to what comes next.","why":"Every step needs its own yes."},"relearn":"Coming over or kissing is never agreement to anything further.","persona":"any","source":"escalation myth"},
  {"id":"cr-034","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They were dressed for it.\"","myth":{"un":"They were dressed for it, so they were asking.","re":"Clothes never imply consent; only a person's words and willingness do.","why":"What someone wears says nothing about consent."},"relearn":"Clothes never imply consent; only a willing yes does.","persona":"any","source":"clothing myth"},
  {"id":"cr-035","cat":"spot-the-pressure","type":"spot","hook":"Spot the two coercive lines (3 are okay).","scene":[{"id":"a","text":"\"If you loved me you would\"","trick":true},{"id":"b","text":"\"Only if you want to, no pressure\"","trick":false},{"id":"c","text":"\"Everyone will hear you said no\"","trick":true},{"id":"d","text":"\"We can just sit and chat instead\"","trick":false},{"id":"e","text":"\"Your call, honestly, either way\"","trick":false}],"why":"Guilt-trips and threats are coercion; a genuine 'only if you want to' or backing off isn't.","relearn":"Guilt-trips and threats are coercion, not persuasion.","persona":"any","source":"coercion"},
  {"id":"cr-036","cat":"spot-the-pressure","type":"sort","hook":"Sort: respectful persuasion, or pressure?","items":[{"id":"a","text":"Asking once and accepting no"},{"id":"b","text":"Nagging until they give in"},{"id":"c","text":"Sharing what you'd like, then leaving it"},{"id":"d","text":"Threatening to leave if they refuse"},{"id":"e","text":"Taking 'not tonight' with a smile"},{"id":"f","text":"Sulking until they cave"}],"bins":[{"id":"ok","label":"Respectful","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"ok","b":"pressure","c":"ok","d":"pressure","e":"ok","f":"pressure"},"relearn":"Asking once and accepting no is respectful; nagging, threats or sulking are pressure.","persona":"any","source":"persuasion vs pressure"},
  {"id":"cr-037","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"If there was no struggle, it wasn't assault.\"","myth":{"un":"If there was no struggle, it wasn't assault.","re":"Freezing is a common, involuntary response; assault doesn't require a fight.","why":"The body often freezes under threat."},"relearn":"Freezing is common; assault doesn't require a struggle.","persona":"any","source":"freeze response"},
  {"id":"cr-038","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"Men can't be assaulted.\"","myth":{"un":"Men can't be assaulted.","re":"Anyone of any gender can be harmed, and male and LGBTQ+ survivors deserve the same belief and support.","why":"This myth silences many survivors."},"relearn":"Anyone of any gender can be assaulted and deserves belief and support.","persona":"Rohan","source":"even-handed"},
  {"id":"cr-039","cat":"spot-the-pressure","type":"spot","hook":"Spot the two power-plays (3 are clean).","scene":[{"id":"a","text":"A senior hinting your marks depend on it","trick":true},{"id":"b","text":"A peer asking openly, no strings","trick":false},{"id":"c","text":"A boss implying your job is on the line","trick":true},{"id":"d","text":"A date shrugging off your no, fine either way","trick":false},{"id":"e","text":"A classmate fine with either answer","trick":false}],"why":"Tying sex to marks or a job is coercion through power, never consent; the rest ask freely.","relearn":"Tying sex to marks, a job or status is coercion, not consent.","persona":"any","source":"power-play"},
  {"id":"cr-040","cat":"spot-the-pressure","type":"sort","hook":"Sort: consent, or coercion?","items":[{"id":"a","text":"A free, willing yes between equals"},{"id":"b","text":"A yes bought with threats"},{"id":"c","text":"A yes after guilt and nagging"},{"id":"d","text":"A relaxed, mutual yes"},{"id":"e","text":"A sober, eager yes"},{"id":"f","text":"A yes given out of fear"}],"bins":[{"id":"consent","label":"Consent","valence":"pos"},{"id":"coercion","label":"Coercion","valence":"neg"}],"key":{"a":"consent","b":"coercion","c":"coercion","d":"consent","e":"consent","f":"coercion"},"relearn":"A free, mutual yes is consent; a yes from threats, guilt or fear is coercion.","persona":"any","source":"consent vs coercion"},
  {"id":"cr-041","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They said yes before, so it carries over.\"","myth":{"un":"They said yes before, so it carries over.","re":"A past yes never covers today; consent is fresh each time.","why":"Yesterday's yes isn't today's."},"relearn":"A past yes never carries over; consent is fresh each time.","persona":"any","source":"past consent"},
  {"id":"cr-042","cat":"spot-the-pressure","type":"branch","persona":"any","source":"guilt as coercion","hook":"Aman covered your phone repair last month. Tonight he wants more than you do.","steps":[{"prompt":"When you say no, he sighs, \"After all I've done for you...\" What do you do?","options":[{"text":"Offer to pay him back for the phone right away","then":"He waves it off. \"It's not about money.\" The guilt stays."},{"text":"Say a favour isn't a debt, and your no stands","then":"Aman goes quiet, then mutters that you're being dramatic.","best":true},{"text":"Think a partner shouldn't really say no","then":"Aman sees you waver. \"See? You know I'm right.\""},{"text":"Wonder if he has a point, since he's been so generous","then":"You feel like you owe him, and the no gets harder to say."}],"why":"Owing someone a favour never means owing them your body. Your no stands."},{"prompt":"The next day Aman texts that he was hurt, since he does so much and gets nothing. What do you do?","options":[{"text":"Send a long apology so he stops feeling so hurt","then":"\"Apology accepted,\" he replies. \"Show me you mean it.\""},{"text":"Ask his friends if he's always this sensitive","then":"One of them tells Aman, who accuses you of gossiping."},{"text":"Screenshot it to your group chat to mock him","then":"Your friends pile on with jokes. Aman hears about it and is furious."},{"text":"Say you care, but guilt won't change your no","then":"\"So I'm guilt-tripping you now?\" he replies. He sounds annoyed.","best":true}],"why":"Guilt is a pressure tactic. You can care about him and still say no."},{"prompt":"A week later it happens again, same words. What do you do?","options":[{"text":"Talk to a friend you trust about the pattern","then":"\"That's not okay,\" your friend Neha says. \"It's not on you.\"","best":true},{"text":"Tell yourself every couple has this fight","then":"The words keep coming back, and each no gets harder."},{"text":"Decide you must be a bad partner for saying no","then":"You start saying sorry before he even asks."},{"text":"Keep it to yourself, since it's private","then":"Nobody knows, and the weight of it sits with you alone."}],"why":"A pattern of guilt-trips is coercion. It's never your fault, and support helps."},{"prompt":"Later your cousin Priya asks why you seem so low. What do you tell her?","options":[{"text":"That it's just exam stress","then":"\"Take a break, yaar,\" she says, and the real thing stays unsaid."},{"text":"That you'll fix it by being a better partner","then":"Priya looks worried. \"Better how? What's going on?\""},{"text":"That Aman is right, and you're being selfish","then":"\"Selfish for what?\" Priya asks, frowning."},{"text":"The truth, and that you want her help","then":"Priya hugs you. \"Whatever you decide, I'm with you.\"","best":true}],"why":"Getting support keeps the choice yours, and reminds you the guilt isn't yours."}],"debrief":"Guilt is a pressure tactic, and owing someone a favour never means owing them your body.","relearn":"Guilt-tripping is coercion; you never owe anyone your body."},
  {"id":"cr-043","cat":"spot-the-pressure","type":"sort","hook":"Sort: implies consent, or implies nothing?","items":[{"id":"a","text":"A clear, spoken yes"},{"id":"b","text":"What they were wearing"},{"id":"c","text":"That they'd hooked up before"},{"id":"d","text":"That they paid for dinner"},{"id":"e","text":"An eager 'yes, please'"},{"id":"f","text":"That they came to the party"}],"bins":[{"id":"yes","label":"Implies consent","valence":"pos"},{"id":"nothing","label":"Implies nothing","valence":"neutral"}],"key":{"a":"yes","b":"nothing","c":"nothing","d":"nothing","e":"yes","f":"nothing"},"relearn":"Only a spoken, willing yes implies consent; clothes, history, money and showing up imply nothing.","persona":"any","source":"what implies consent"},
  {"id":"cr-044","cat":"spot-the-pressure","type":"spot","hook":"Spot the two pressured 'yeses' (3 are freely given).","scene":[{"id":"a","text":"\"Yes, I'd love to\" with no strings","trick":false},{"id":"b","text":"\"Okay, just stop asking\"","trick":true},{"id":"c","text":"\"Fine, or you'll be angry\"","trick":true},{"id":"d","text":"\"Yes, I'm really into this\"","trick":false},{"id":"e","text":"\"Definitely, let's\"","trick":false}],"why":"A free, willing yes is consent; a yes to end nagging or avoid anger isn't.","relearn":"A free, willing yes is consent; a yes to stop pressure isn't.","persona":"any","source":"freely given"},
  {"id":"cr-045","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: nothing about someone's clothes, choices or past ever implies consent. Land clearly?","prompt":"What do you think?","options":["Yes","Only a yes counts","Clear"],"affirm":"Only a willing yes means consent; nothing else ever stands in for it.","relearn":"Nothing about clothes, choices or past implies consent; only a yes does.","persona":"any","source":"the standard"},
  {"id":"cr-046","cat":"after-harm-support","type":"role-play","persona":"any","source":"disclosure / believe","hook":"In a quiet corner of the library, your friend Farah says she has something to tell you.","setup":"She keeps her eyes on the table.","steps":[{"prompt":"Farah says quietly: \"Someone assaulted me. At that party last month.\"","options":[{"text":"\"Oh no. Who was it? Tell me everything.\"","then":"She flinches. \"I don't want to say his name yet.\""},{"text":"\"I believe you. I'm so glad you told me. This wasn't your fault.\"","then":"Farah's eyes fill. \"I was so scared you'd ask what I did.\"","best":true},{"text":"\"Are you sure? What were you wearing?\"","then":"Farah pulls back. \"This is why I didn't tell anyone.\""},{"text":"\"That's awful. Let's get you to the police right now.\"","then":"Farah freezes. \"No. I can't. I just wanted to tell you.\""}],"why":"Belief, thanks and \"not your fault\" answer the fear most survivors carry."},{"prompt":"Farah asks: \"Do you think I should have left earlier?\"","options":[{"text":"\"Let's not think about what you could have done differently, okay?\"","then":"She nods, but the question stays in her eyes."},{"text":"\"No. Leaving or staying doesn't change who's responsible. He is.\"","then":"She nods slowly. \"I keep going over it.\"","best":true},{"text":"\"Honestly, parties like that can be risky.\"","then":"She looks down. \"So it's on me for going.\""},{"text":"\"Maybe. But you couldn't have known.\"","then":"Farah's face falls. \"So I could have stopped it.\""}],"why":"Only the person who ignored consent is responsible, whatever she did or didn't do."},{"prompt":"Farah says: \"I don't know what to do now.\"","options":[{"text":"\"Try to forget it. Dwelling only makes it worse.\"","then":"She nods. She doesn't bring it up again."},{"text":"\"You should talk to a counsellor. I'll book it now.\"","then":"Farah hesitates. \"Can I think about it first?\""},{"text":"\"You have to report him, or he'll just go and do it to someone else.\"","then":"Farah's breathing quickens. \"I can't carry that too.\""},{"text":"\"There's no rush. A counsellor or 181 is there when you want.\"","then":"She nods. \"Maybe later. Tonight I just don't want to be alone.\"","best":true}],"why":"No deadlines, and help she can choose when ready, put her back in charge."}],"relearn":"Start with belief: 'I believe you. It wasn't your fault.'"},
  {"id":"cr-047","cat":"after-harm-support","type":"branch","persona":"Mehta","source":"survivor-centred","hook":"After a club meeting, Tanvi tells you someone assaulted her last month.","steps":[{"prompt":"She watches your face, waiting. What do you say first?","options":[{"text":"Believe her, say it's not her fault, and ask what she needs","then":"Tanvi's shoulders drop. \"I don't know yet. I just needed someone to know.\"","best":true},{"text":"Ask gently why she didn't leave or shout for help at the time","then":"Tanvi goes quiet, then says maybe she's making too much of it."},{"text":"Ask if she's okay, and whether she's told anyone else yet","then":"She shakes her head. \"No one. Should I have?\" She looks less sure now."},{"text":"Tell her you'll find out who did it and sort them out yourself","then":"She looks alarmed. \"Please don't. That's not why I told you.\""}],"why":"Belief and \"not your fault\" come first. Asking what she needs keeps her in charge."},{"prompt":"A few minutes later, Tanvi says she keeps replaying it at night. What do you do?","options":[{"text":"Ask her to go through exactly what happened, step by step","then":"Her voice shakes as she starts. She stops halfway and looks away."},{"text":"Tell her to try not to think about it before bed","then":"She says she's tried. She goes quiet, as if she's failed at that too."},{"text":"Listen, and say it makes sense to feel this way","then":"She nods slowly. \"So I'm not going mad?\" She keeps talking.","best":true},{"text":"Tell her she really must see a counsellor, this week","then":"She stiffens at the must. \"Maybe. I don't know.\""}],"why":"Listening and validating tells her that her reaction is normal, without rushing her."},{"prompt":"She asks if there's anyone she could talk to who isn't a friend. What do you say?","options":[{"text":"Mention the campus counsellor or 181, and let her choose","then":"She saves 181 in her phone. \"Not today. But good to know.\"","best":true},{"text":"Say a friend who knows her is better than a stranger","then":"She nods, but she still has questions you can't answer."},{"text":"Say those services are really meant for serious cases","then":"Tanvi shrinks. \"Right. Maybe mine isn't serious enough.\""},{"text":"Offer to book her a slot with the campus counsellor right now","then":"She hesitates as you open the portal. \"Can I think about it first?\""}],"why":"Naming real options, then letting her choose, keeps the help in her hands."},{"prompt":"As you leave, Tanvi asks you not to treat her differently now. What do you do?","options":[{"text":"Say it's hard not to, after something like this","then":"Her face falls. \"That's what I was scared of.\""},{"text":"Text her every few hours from now on to check she's okay","then":"By evening she mutes the chat. It feels like being watched."},{"text":"Agree, and never bring any of it up again","then":"Weeks pass in silence. She wonders if you'd rather not know."},{"text":"Say you'll be the same, and ask if she'd like check-ins","then":"\"Maybe a text now and then,\" she says. \"Not every hour.\"","best":true}],"why":"Asking how she wants support lets her set the terms, the control that was taken from her."}],"debrief":"Believe, don't blame, ask what they need: the survivor-centred basics.","relearn":"Believe, don't blame, and ask what they need."},
  {"id":"cr-048","cat":"after-harm-support","type":"strike-rewrite","hook":"\"If it were real, they'd have fought or reported it right away.\"","myth":{"un":"If it were real, they'd have fought or reported at once.","re":"Freezing and delaying are common, normal responses to trauma; they don't mean it didn't happen.","why":"Trauma doesn't follow a script."},"relearn":"Freezing and delaying are normal trauma responses, not proof it wasn't real.","persona":"any","source":"trauma responses"},
  {"id":"cr-049","cat":"after-harm-support","type":"role-play","persona":"any","source":"no blame","hook":"Aditya tells you he was assaulted after the fest, then starts blaming himself.","setup":"He's sitting on your bed, head down.","steps":[{"prompt":"Aditya mutters: \"Maybe it was my fault. I'd been drinking.\"","options":[{"text":"\"Guys can handle that stuff. You'll be fine.\"","then":"He goes quiet. \"Right. I should be able to.\""},{"text":"\"It wasn't your fault. The one who ignored consent is responsible.\"","then":"He looks up. \"Even though I was drunk?\"","best":true},{"text":"\"Everyone drinks at fests. Don't be so hard on yourself about it, yaar.\"","then":"\"But I drank too much,\" he says. The blame stays put."},{"text":"\"Well, maybe be more careful next time.\"","then":"He nods, jaw tight. \"Yeah. Lesson learnt.\""}],"why":"Drinking never causes assault. Only the one who ignored consent is responsible."},{"prompt":"Aditya adds: \"I don't even remember all of it. Maybe it wasn't really assault.\"","options":[{"text":"\"Maybe ask the others who were there that night.\"","then":"He goes pale. \"Then everyone will know.\""},{"text":"\"If you can't remember it, maybe it wasn't really all that bad.\"","then":"He looks hurt. \"It felt bad. That's the problem.\""},{"text":"\"Being that drunk meant you couldn't consent. That's enough.\"","then":"He's quiet a long moment. \"Nobody's ever said that to me.\"","best":true},{"text":"\"Let's just focus on you feeling better.\"","then":"He agrees, but the doubt stays on his face."}],"why":"Someone too drunk to remember couldn't consent. Gaps don't make it less real."},{"prompt":"Aditya says: \"I don't want anyone thinking I'm weak.\"","options":[{"text":"\"You're not weak at all, man. You just need to toughen up a little.\"","then":"He laughs bitterly. \"That's the same thing.\""},{"text":"\"Being harmed isn't weakness. Want to see a counsellor together?\"","then":"He hesitates, then nods. \"Maybe. If you come.\"","best":true},{"text":"\"No one will think that. I promise.\"","then":"He wants to believe you. \"You can't know that.\""},{"text":"\"Then keep it to yourself. People talk.\"","then":"He nods, and pulls the secret back inside."}],"why":"Being harmed is never weakness. A counsellor is for anyone, and your company makes it easier."}],"relearn":"Responsibility lies only with the person who ignored consent, never the survivor."},
  {"id":"cr-050","cat":"after-harm-support","type":"branch","persona":"any","source":"respect their choices","hook":"Your friend Aman tells you he was assaulted at a party, and he doesn't want to report it.","steps":[{"prompt":"He says he just wants to forget about it. What do you say?","options":[{"text":"Say okay, but ask him to promise he'll think about reporting","then":"He nods to end the topic. You can tell he's bracing for the next push."},{"text":"Agree to never talk about it again","then":"He looks relieved, then lonely. The one door he opened has shut."},{"text":"Tell him if he doesn't report, he'll do it to someone else","then":"Aman flinches. Now he's carrying guilt about strangers too."},{"text":"Tell him it's not his fault, and reporting is his call","then":"Aman looks up, surprised. \"Really? I thought you'd push me.\"","best":true}],"why":"It's his choice, and none of it is his fault. Backing him fully gives back some control."},{"prompt":"A few days later, Aman says he isn't sleeping and feels jumpy on campus. What do you do?","options":[{"text":"Say this is exactly why he should have reported it","then":"Aman goes quiet and changes the subject."},{"text":"Ask what would help, and mention a counsellor is an option","then":"He thinks. \"Maybe walking back together at night, for now.\"","best":true},{"text":"Start walking him to class and back every day, without asking","then":"He's grateful at first, then feels watched like a child."},{"text":"Tell him it'll pass if he keeps himself busy","then":"He fills his days. The nights stay just as bad."}],"why":"Support he chooses, like a walk home or a counsellor, helps without taking over."},{"prompt":"Weeks later, Aman says he might report after all, but he isn't sure. What do you do?","options":[{"text":"Remind him he said he wanted to forget it","then":"He looks confused. \"So I'm not allowed to change my mind?\""},{"text":"Say reporting rarely leads anywhere, so why bother","then":"The idea deflates. He drops it without really deciding."},{"text":"Tell him to go and report it right now, before he changes his mind","then":"He goes pale. \"I said I'm not sure.\""},{"text":"Say either choice is okay, and offer to find out how it works","then":"He nods. \"Just knowing the steps would help me decide.\"","best":true}],"why":"It's still his choice, now or later. Helping him find information supports it either way."}],"debrief":"Whether and when to report is the survivor's choice; your job is support, not pressure.","relearn":"Whether and when to report is the survivor's choice; respect it."},
  {"id":"cr-051","cat":"after-harm-support","type":"reflect","hook":"Lensy: responsibility lies only ever with the person who ignored consent. Sit firmly with you?","prompt":"What do you think?","options":["Yes","Always","Never the survivor"],"affirm":"That truth never moves: the fault is only ever with the one who ignored consent.","relearn":"Responsibility lies only with the person who ignored consent.","persona":"any","source":"responsibility"},
  {"id":"cr-052","cat":"after-harm-support","type":"role-play","persona":"any","source":"ask, don't take over","hook":"Two days after a classmate assaulted her, your friend Rhea comes to your room.","setup":"She sits down without a word.","steps":[{"prompt":"Rhea says: \"I don't even know why I came here.\"","options":[{"text":"\"You came because you need help. Let me handle it.\"","then":"She hesitates. \"I don't want it handled. Not yet.\""},{"text":"\"I'm glad you did. What would help right now?\"","then":"She shrugs. \"Maybe some chai. And not talking yet.\"","best":true},{"text":"\"Here's exactly what you have to do now.\"","then":"Rhea goes stiff as you start listing. \"Can you just stop?\""},{"text":"\"Did something new happen? Tell me everything.\"","then":"She pulls her knees up. \"I can't do everything right now.\""}],"why":"Asking what would help, and following her answer, gives her back some control."},{"prompt":"Later, Rhea asks: \"Should I tell my parents?\"","options":[{"text":"\"What do you think they'd do? I'll back what you decide.\"","then":"She thinks. \"Mum would listen. Dad would panic.\"","best":true},{"text":"\"I'll call them for you, so you don't have to say it.\"","then":"Her eyes widen. \"No. Please don't call anyone.\""},{"text":"\"No way. They'll only make it worse for you.\"","then":"She frowns. \"You don't know that either.\""},{"text":"\"Yes. Parents should always know about something like this.\"","then":"Rhea looks away. \"You don't know my dad.\""}],"why":"Helping her think it through, instead of deciding, keeps the choice hers."},{"prompt":"Rhea asks: \"Is it even worth going to the committee?\"","options":[{"text":"\"Only if you want him punished. Do you?\"","then":"She looks lost. \"I don't know what I want.\""},{"text":"\"It can be. Want to find out how it works, then decide?\"","then":"She nods. \"Knowing would help. I hate guessing.\"","best":true},{"text":"\"Honestly, those committees just protect the college.\"","then":"She deflates. \"Then there's no point.\""},{"text":"\"Definitely. You have to go this week, while it's fresh.\"","then":"Rhea stiffens. \"I said I'm not sure.\""}],"why":"Information helps her decide freely. The timing and the choice stay hers."},{"prompt":"At the door, Rhea says: \"Sorry for taking up your whole evening.\"","options":[{"text":"\"It's fine. Next time maybe message me first.\"","then":"Her face falls. \"Right. Sorry.\""},{"text":"\"Never apologise. None of this is your fault. Come back anytime.\"","then":"She manages a small smile. \"Okay. Maybe tomorrow.\"","best":true},{"text":"\"Don't be silly. I'll check on you every single hour tonight, okay?\"","then":"She laughs weakly. \"Please don't. But thanks.\""},{"text":"\"No problem. Just try to get some sleep, okay?\"","then":"She nods and leaves, still unsure she's welcome."}],"why":"Saying it's not her fault, and welcoming her back, tells her support is steady."}],"relearn":"Ask what would help and follow their lead; don't take over."},
  {"id":"cr-053","cat":"after-harm-support","type":"branch","persona":"Mehta","source":"signpost help","hook":"Months after an assault, your friend Kavya says she's ready to get some help.","steps":[{"prompt":"She asks where people even go for this. What do you tell her?","options":[{"text":"Say it's been months, so maybe it's best to move on","then":"Kavya's face drops. \"Right. Maybe I missed my chance.\""},{"text":"Say you'll search online tonight and get back to her","then":"She waits two days. The courage she had that evening fades a little."},{"text":"Suggest she ask anonymously in the class group","then":"The replies are a mix of guesses and jokes. She closes the chat."},{"text":"Name real routes: 181, a counsellor, the campus ICC","then":"Kavya writes them down. \"I didn't know there were so many.\"","best":true}],"why":"Real, confidential routes let her choose. It's never too late for help, and never her fault."},{"prompt":"A few days later, Kavya reads out a list: 181, a counsellor, the campus ICC. She asks how they differ. What do you say?","options":[{"text":"Say the ICC, since a formal complaint is the only real step","then":"She tenses. \"I'm not ready to complain. I just want to talk.\""},{"text":"Say they're all much the same, just paperwork","then":"Kavya sighs. \"Then what's the point?\""},{"text":"Explain each one: to talk, to get advice, or to complain","then":"\"So I don't have to complain to get help,\" she says, relieved.","best":true},{"text":"Say you're not sure, so she should just pick one","then":"She hesitates, worried about picking the wrong door."}],"why":"Knowing what each route does lets her pick one that fits, without pressure to complain."},{"prompt":"She says she's nervous about making the first call. What do you do?","options":[{"text":"Tell her there's nothing to be nervous about","then":"She nods, but the nerves don't go anywhere."},{"text":"Make the call for her yourself and explain everything","then":"She listens as you tell her story. It no longer feels like hers."},{"text":"Offer to sit with her while she calls, if she'd like","then":"\"Would you? Tomorrow evening?\" She sounds steadier.","best":true},{"text":"Say she can wait until the nerves pass","then":"Days go by. The nerves don't shrink on their own."}],"why":"Company, if she wants it, makes the first step easier while it stays her own."}],"debrief":"Knowing the routes lets you signpost confidential help when they're ready.","relearn":"Signpost real help when ready: 181, 1091, 112, a counsellor, campus ICC."},
  {"id":"cr-054","cat":"after-harm-support","type":"strike-rewrite","hook":"\"A real friend would force them to report it.\"","myth":{"un":"A real friend would force them to report.","re":"A real friend supports the survivor's own choices, including if and when to report.","why":"Taking over removes the control they need back."},"relearn":"A real friend supports the survivor's choices, not forces a report.","persona":"any","source":"respect autonomy"},
  {"id":"cr-055","cat":"after-harm-support","type":"role-play","persona":"Rohan","source":"even-handed support","hook":"Over late-night Maggi, your friend Vivek says someone assaulted him at a party.","setup":"He laughs nervously, watching you.","steps":[{"prompt":"Vivek says: \"You probably think that's ridiculous. I'm a guy.\"","options":[{"text":"\"Seriously? Who was it? Was it a girl?\"","then":"He looks away. \"Does it matter?\""},{"text":"\"Whoa. You okay, though? You seem totally fine, at least.\"","then":"He forces a grin. \"Yeah. Fine.\" He isn't."},{"text":"\"Come on. That doesn't really happen to guys.\"","then":"Vivek's grin slips. \"It does, though. It happened to me.\""},{"text":"\"I believe you, and it wasn't your fault. I'm here.\"","then":"His laugh stops. \"Okay. I didn't expect that.\"","best":true}],"why":"Men are harmed too. Plain belief tells him it's safe to go on."},{"prompt":"Vivek asks: \"Why didn't I just stop it? I'm not exactly small.\"","options":[{"text":"\"Honestly, I think I'd have fought back.\"","then":"Vivek's face hardens. \"Thanks. That helps.\""},{"text":"\"Were you drunk at the time? That would explain it, I guess.\"","then":"He shrinks. \"So it was my fault.\""},{"text":"\"Don't think about that part too much. It's done now.\"","then":"He nods and goes quiet, still stuck on the question."},{"text":"\"Size doesn't matter. People freeze. It's on them, not you.\"","then":"He stares at his hands. \"I did freeze.\"","best":true}],"why":"Freezing is common and involuntary. Only the person who ignored consent is responsible."},{"prompt":"Vivek says: \"If the guys find out, I'm done.\"","options":[{"text":"\"They won't hear it from me. Who you tell is your call.\"","then":"He relaxes a little. \"Maybe no one. Maybe just you.\"","best":true},{"text":"\"Then act normal around them and nobody will know.\"","then":"He nods, already pulling his mask back on."},{"text":"\"They're your friends. I'm sure they'd understand.\"","then":"\"You don't know them like I do,\" he says quietly."},{"text":"\"If they mock you, then they were never real friends anyway.\"","then":"He sighs. \"Easy for you to say.\""}],"why":"His story is his. Keeping it private lets him choose who knows."},{"prompt":"Vivek asks: \"Is there even anyone who helps guys with this?\"","options":[{"text":"\"Just talk to me instead. You don't need some stranger for this.\"","then":"He's grateful. Neither of you knows what comes next."},{"text":"\"Yes. The campus counsellor sees men too. Want me to come?\"","then":"He hesitates, then nods. \"Just to the door.\"","best":true},{"text":"\"Not really. Most of that is set up for women.\"","then":"He shrugs. \"Figured.\" The door he opened closes."},{"text":"\"Man up and go talk to the warden tomorrow.\"","then":"He bristles. \"That's exactly what I can't do.\""}],"why":"Support is for everyone who's been harmed. Offering to go along makes it easier to use."}],"relearn":"Believe male and LGBTQ+ survivors fully and equally."},
  {"id":"cr-056","cat":"after-harm-support","type":"branch","persona":"any","source":"self-support","hook":"Reading a post about consent, you realise something an ex did last year was assault.","steps":[{"prompt":"A wave of shame hits you. What do you tell yourself?","options":[{"text":"\"We were together at the time, so maybe it doesn't count.\"","then":"You try to file it away. It keeps coming back."},{"text":"\"I should have seen it coming.\"","then":"The thought loops all night, and you feel more alone with it."},{"text":"\"It's in the past. I'll just move on.\"","then":"You push it down. It surfaces again at odd moments all week."},{"text":"\"It wasn't my fault. What I feel makes sense.\"","then":"The shame doesn't vanish, but it loosens enough to breathe.","best":true}],"why":"It was never your fault. Saying so is the first step to being kind to yourself."},{"prompt":"Days later, it's still on your mind at night. What do you do?","options":[{"text":"Keep it to yourself so no one sees you differently","then":"The secret sits between you and everyone. The nights stay long."},{"text":"Tell one person you trust, at your own pace","then":"Your friend listens and tells you they believe you. Something eases.","best":true},{"text":"Message the ex to ask why they did it","then":"They reply that you're remembering it wrong. You feel worse."},{"text":"Write it all down in a journal, and leave it there","then":"Writing helps a little. You're still carrying it alone."}],"why":"You deserve support. Telling someone you trust means you don't carry it alone."},{"prompt":"You wonder whether talking to someone trained would help. What do you do?","options":[{"text":"Decide it wasn't serious enough to need help","then":"You close the tab. The heaviness stays."},{"text":"Assume a counsellor would ask why you didn't stop it","then":"Just picturing that question, you put off calling anyone."},{"text":"Call 181 or book the counsellor to talk it through","then":"The person you talk to is calm. No one asks why you didn't stop it.","best":true},{"text":"Wait till exams are over, since it's old news","then":"Exams end. The weight is still there, and you still haven't talked."}],"why":"A counsellor, or 181, is there for exactly this, whenever it happened."},{"prompt":"Weeks later, you keep asking yourself whether to report it. What do you tell yourself?","options":[{"text":"\"I haven't decided yet, and that's okay for now.\"","then":"The pressure eases. You can decide later, or not at all.","best":true},{"text":"\"I'll report it, so no one thinks I'm making it up.\"","then":"A flash of resolve, then dread. It feels like it's for them, not you."},{"text":"\"What's the point? Nobody would believe me anyway.\"","then":"The thought shuts the question down, and the loneliness grows."},{"text":"\"I have to report now, or it won't count.\"","then":"The deadline you've set yourself makes your chest tight."}],"why":"Whether and when to report is yours to decide. Taking time is okay."}],"debrief":"If it happened to you, it isn't your fault, and support is there (181, a counsellor, someone you trust).","relearn":"If it happened to you, it isn't your fault; reach for support."},
  {"id":"cr-057","cat":"after-harm-support","type":"reflect","hook":"Lensy: believe, don't blame, ask what they need, signpost help. A toolkit worth carrying?","prompt":"What do you think?","options":["Yes","I've got it","Worth carrying"],"affirm":"Those four steps make you someone a survivor can safely turn to.","relearn":"Believe, don't blame, ask what they need, signpost help.","persona":"any","source":"the support toolkit"},
  {"id":"cr-058","cat":"after-harm-support","type":"sort","hook":"Sort: helps a survivor, or harms?","items":[{"id":"a","text":"\"I believe you\""},{"id":"b","text":"\"What did you expect?\""},{"id":"c","text":"\"What do you need from me?\""},{"id":"d","text":"\"You have to report it now\""},{"id":"e","text":"\"None of this was your fault\""},{"id":"f","text":"\"Why didn't you stop him?\""}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Belief, no-blame and 'what do you need?' help; blame and pressure to report harm.","persona":"any","source":"support responses"},
  {"id":"cr-059","cat":"after-harm-support","type":"sort","hook":"Sort: a survivor-centred response, or not?","items":[{"id":"a","text":"Letting them set the pace"},{"id":"b","text":"Questioning their story for holes"},{"id":"c","text":"Keeping what they share private"},{"id":"d","text":"Telling others without asking"},{"id":"e","text":"Asking what they need"},{"id":"f","text":"Deciding they must report"}],"bins":[{"id":"centred","label":"Survivor-centred","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"centred","b":"not","c":"centred","d":"not","e":"centred","f":"not"},"relearn":"Setting the pace, privacy and asking what they need are survivor-centred; interrogating, outing or forcing a report aren't.","persona":"any","source":"survivor-centred"},
  {"id":"cr-060","cat":"after-harm-support","type":"role-play","persona":"any","source":"holding space","hook":"Your friend Mahima was assaulted a few weeks ago. Tonight she turns up at your door.","setup":"She sits on your floor, hugging her knees.","steps":[{"prompt":"Mahima says: \"I don't want advice. I just can't be alone.\"","options":[{"text":"\"Okay. But first, have you thought about reporting it?\"","then":"Mahima closes her eyes. \"I said no advice.\""},{"text":"\"I'm here. We don't have to do anything right now.\"","then":"She nods and leans against the bed. The room goes quiet.","best":true},{"text":"\"Let's go out. It'll take your mind off it.\"","then":"She shakes her head. \"I can't face people.\""},{"text":"\"Sure. Do you want to talk about what happened that night?\"","then":"She shakes her head. \"Not tonight.\""}],"why":"Being present, without a plan, is exactly what she asked for."},{"prompt":"After a long silence, Mahima says: \"Sorry. This must be boring for you.\"","options":[{"text":"\"It's not. Sitting with you is what I want tonight.\"","then":"She almost smiles. \"Okay.\"","best":true},{"text":"\"A bit. Should we put on a film or something?\"","then":"She nods, and seems to feel like a burden now."},{"text":"\"Then talk to me. Tell me what's going on in your head.\"","then":"She tenses. \"I can't. Not yet.\""},{"text":"\"Don't worry about me. Just focus on healing.\"","then":"\"I'm trying,\" she says, and goes quiet."}],"why":"She's never a burden, and what happened is never her fault. She can stay as long as she needs."},{"prompt":"The next morning, Mahima texts: \"I can't keep turning up at yours.\"","options":[{"text":"\"Just try to push through the nights on your own.\"","then":"\"I've been trying,\" she writes back."},{"text":"\"You can. And a counsellor could help with the nights too.\"","then":"\"Maybe. If you help me find one,\" she writes.","best":true},{"text":"\"You're right. Maybe you should just see a therapist instead.\"","then":"Her reply comes slowly. \"So I'm too much.\""},{"text":"\"Of course you can. You don't need anyone else.\"","then":"She's relieved, and still awake most nights."}],"why":"Keeping your door open, while mentioning more help, means she's never on her own."}],"relearn":"Sometimes support is just being present, no fixing required."},
  {"id":"cr-061","cat":"consent-culture","type":"reflect","hook":"Lensy: an enthusiastic yes is the warm, positive core of all this, not just a rule. Feel that?","prompt":"What do you think?","options":["Yes","The good part","Enthusiasm"],"affirm":"Consent isn't only protection; a real, eager yes is what makes intimacy good.","relearn":"An enthusiastic yes is the positive core of consent, not just a rule.","persona":"any","source":"the positive core"},
  {"id":"cr-062","cat":"consent-culture","type":"branch","persona":"any","source":"checking in","hook":"A month into dating Aryan, things are heating up. You worry checking in will kill the mood.","steps":[{"prompt":"You're kissing on his sofa and want to go further. What do you do?","options":[{"text":"Joke about needing a consent form, to keep it light","then":"He laughs, and the question never actually gets asked."},{"text":"Ask, \"You're okay, right?\" and keep going","then":"He nods quickly. You can't tell if he meant it."},{"text":"Pause and ask warmly, \"Is this good? Want more?\"","then":"Aryan grins. \"Yes. And thanks for asking.\" He pulls you closer.","best":true},{"text":"Keep going, and read his body language as you go","then":"He seems into it, mostly. You're not quite sure, and neither is he."}],"why":"A warm check-in shows you care about his yes, and it usually makes things better."},{"prompt":"Later, Aryan slows down and seems less sure. What do you do?","options":[{"text":"Ask if he wants to stop, sounding a little hurt about it","then":"\"No, it's fine,\" he says quickly. He's worried about upsetting you."},{"text":"Try a bit harder to get the mood back","then":"He smiles politely, but he's somewhere else now."},{"text":"Keep going, since he hasn't actually said stop","then":"He goes quiet. You're no longer sure he wants this."},{"text":"Stop, and ask how he's feeling, with no pressure","then":"He exhales. \"Can we slow down?\" You do, and he relaxes into you.","best":true}],"why":"Consent is ongoing. A pause with no pressure lets him say what he really wants."},{"prompt":"The next day, you wonder whether checking in makes you seem unsure. What do you do?","options":[{"text":"Ask your friends whether checking in is uncool","then":"They argue both ways. None of them was there."},{"text":"Decide never to ask, so you come across as confident","then":"It feels smoother in your head, but you'd be guessing, not knowing."},{"text":"Ask Aryan how last night felt, and what he'd like","then":"Aryan thinks. \"I like being asked. It makes it easier to say what I want.\"","best":true},{"text":"Look up tips online for reading someone's signals","then":"The tips are vague. None of them replaces just asking."}],"why":"His answer matters most. Checking in builds trust and makes intimacy better."}],"debrief":"Checking in is hot, not awkward; it builds trust and makes intimacy better.","relearn":"Checking in builds trust and makes intimacy better, not worse."},
  {"id":"cr-063","cat":"consent-culture","type":"sort","hook":"Sort: builds a consent culture, or erodes it?","items":[{"id":"a","text":"Taking no gracefully, no sulking"},{"id":"b","text":"Mocking someone for a boundary"},{"id":"c","text":"Looking out for friends at parties"},{"id":"d","text":"Treating pressure as normal"},{"id":"e","text":"Asking 'is this good?' midway"},{"id":"f","text":"Keeping a tally of your hook-ups"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Taking no gracefully, looking out, and checking in builds consent culture; mocking, pressure and scorekeeping erode it.","persona":"any","source":"consent culture"},
  {"id":"cr-064","cat":"consent-culture","type":"branch","persona":"any","source":"bystander","hook":"At a house party, your friend Dev keeps pulling Aisha toward the terrace. She keeps stepping back.","steps":[{"prompt":"She glances around the room for a way out. What do you do?","options":[{"text":"Walk over and ask Aisha to help you find the snacks","then":"Aisha jumps at it. \"Yes. Let's go.\" Dev lets go of her arm.","best":true},{"text":"Shout at Dev from across the room to leave her alone","then":"Heads turn. Dev laughs it off, and Aisha looks mortified."},{"text":"Text Dev from across the room to back off","then":"Dev glances at his phone, shrugs, and pockets it."},{"text":"Stay out of it, since Dev's your mate","then":"Dev keeps at it. Aisha's smile gets tighter and tighter."}],"why":"A simple distraction gets her out of the moment safely, without a scene."},{"prompt":"A little later, Aisha is by the stairs, alone. What do you do?","options":[{"text":"Ask her what exactly Dev said to her out there","then":"She shrugs, uncomfortable. \"Doesn't matter. He's just pushy.\""},{"text":"Tell her Dev's harmless, just a bit drunk","then":"Aisha's face tightens. \"Harmless doesn't feel like this.\""},{"text":"Ask quietly if she's okay, and if she wants company","then":"She nods. \"Can you stay with me? He's being a lot.\"","best":true},{"text":"Leave her be, since she probably wants some space right now","then":"She stays by the stairs, checking over her shoulder."}],"why":"Checking in privately, and offering company, lets her say what she needs."},{"prompt":"Dev walks up and tells Aisha, \"Come on, one drink with me.\" What do you do?","options":[{"text":"Say you two are grabbing food, and walk off with her","then":"Dev rolls his eyes, but lets you both go.","best":true},{"text":"Laugh it off and change the subject to something else","then":"Dev laughs too, and stays right where he is."},{"text":"Suggest the three of you have a drink together","then":"Dev perks up. Aisha looks at you, trapped."},{"text":"Tell Dev to back off or you'll tell everyone","then":"Dev's face darkens. A crowd gathers, and Aisha shrinks back."}],"why":"A calm exit line takes her away from the pressure without starting a fight."},{"prompt":"Later, Dev grumbles that Aisha has been avoiding him all night. What do you do?","options":[{"text":"Say you'll talk about it when he's sober","then":"He shrugs and wanders off. It can wait till he's sober."},{"text":"Tell him he's a creep and that you're done with him for good","then":"Dev storms off, angry, and hears nothing else you say."},{"text":"Say she's probably just tired, and leave it there","then":"Dev relaxes. He thinks he did nothing wrong."},{"text":"Tell him plainly she wanted out, and pushing isn't cool","then":"Dev scoffs, then goes quiet. \"She could've just said.\"","best":true}],"why":"She made her answer clear, and the pressure was never her fault. Naming it calmly lets Dev see that."},{"prompt":"The next day, Dev says she was just playing hard to get. What do you do?","options":[{"text":"Stop replying to his messages for a while without saying why","then":"Dev never finds out why. Nothing changes for him."},{"text":"Say stepping back is an answer, not a game","then":"Dev shrugs. \"Maybe.\" A few days later, he admits he was pushy.","best":true},{"text":"Say it's not your business what she wanted","then":"Dev takes that as agreement."},{"text":"Agree, so the friendship stays easy","then":"Dev nods, sure he was right all along."}],"why":"\"Playing hard to get\" is a myth. Saying so helps a friend do better next time."}],"debrief":"Bystanders who interrupt, distract or check in prevent a lot of harm.","relearn":"If a friend is pressuring someone, interrupt, distract or check in."},
  {"id":"cr-065","cat":"consent-culture","type":"role-play","persona":"any","source":"interrupting","hook":"At a party, your friend Vikram keeps pestering Nisha after she's said no twice.","setup":"You walk over as he leans in again.","steps":[{"prompt":"Vikram grins at you and says: \"Relax. She's just shy. Give me five minutes.\"","options":[{"text":"\"Ha. Good luck, bro\"","then":"Vikram laughs. \"Watch and learn,\" he says, turning back to Nisha."},{"text":"\"She said no, man. Leave it. Come help me a sec\"","then":"Vikram glances at Nisha, then follows you. \"Fine. What?\"","best":true},{"text":"\"Vikram, you're being a creep. Everyone can see it\"","then":"He flushes. \"Seriously? In front of everyone?\""},{"text":"\"Maybe give her a bit of space for now?\"","then":"\"Yeah, yeah. In a bit,\" Vikram says, not moving."}],"why":"A light, firm line plus an exit ends it without humiliating anyone."},{"prompt":"A few minutes later, Vikram says: \"She's so uptight. What's her problem?\"","options":[{"text":"\"No problem. She said no, and that's the end of it\"","then":"Vikram sighs. \"Fine. She did say no. I heard her.\"","best":true},{"text":"\"Some girls are just like that, man\"","then":"\"Exactly,\" Vikram says, looking back towards Nisha."},{"text":"\"The problem is you, honestly\"","then":"\"Wow. Okay,\" he snaps, and walks ahead."},{"text":"\"Forget it, bro. Let's just go get a drink\"","then":"\"Yeah. Whatever,\" he says, and heads to the bar."}],"why":"Naming her no as the end of it keeps the focus on her choice, not his pride."},{"prompt":"Later, by the drinks, Vikram asks: \"Honestly, how do you ever tell if a no is a real no?\"","options":[{"text":"\"Girls sometimes say no when they mean maybe\"","then":"\"See? That's what I thought,\" Vikram says, perking up."},{"text":"\"You can't, really. Dating is confusing\"","then":"\"Right?\" he says, relieved. \"It's impossible.\""},{"text":"\"Next time, ask her friends if she likes you\"","then":"\"Good idea,\" Vikram says. \"I'll ask Priya tomorrow.\""},{"text":"\"She said no. That's how you know\"","then":"Vikram is quiet for a bit. \"Yeah. Okay. That's fair.\"","best":true}],"why":"A clear no is the answer. Believing it is the whole skill."},{"prompt":"As Nisha gets ready to leave, Vikram asks: \"Should I go and talk to her?\"","options":[{"text":"\"Yes. Go right now and explain yourself properly\"","then":"\"Okay,\" he says, already heading back towards Nisha."},{"text":"\"No need. She's probably forgotten already\"","then":"\"Cool,\" Vikram says, and orders another drink."},{"text":"\"Give her space tonight. Maybe a short sorry later\"","then":"Vikram nods. \"Yeah. I'll leave her alone tonight.\"","best":true},{"text":"\"Send her a long message about it later tonight\"","then":"\"Good thinking,\" he says, pulling out his phone."}],"why":"Giving her space means she doesn't have to deal with him again tonight."}],"relearn":"A light, firm interruption can stop a friend crossing a line."},
  {"id":"cr-066","cat":"consent-culture","type":"reflect","hook":"Lensy: a boundary heard and respected instantly, that's what respect feels like. Recognise it?","prompt":"What do you think?","options":["Yes","That's respect","Instantly"],"affirm":"A no met with instant respect is exactly how you know someone's safe.","relearn":"A boundary respected instantly is what respect feels like.","persona":"any","source":"respect"},
  {"id":"cr-067","cat":"consent-culture","type":"branch","persona":"any","source":"equals / power","hook":"You head the college drama club. Ritu, a first-year member, keeps staying back to chat.","steps":[{"prompt":"She asks if you'd like to get coffee sometime. What do you do?","options":[{"text":"Say yes, and ask her out to dinner instead","then":"Ritu hesitates, then agrees. You can't tell if she wanted dinner."},{"text":"Ask the other seniors if it's okay first","then":"Word spreads through the club before you've even had coffee."},{"text":"Say yes, and don't bring up the club or casting at all","then":"The coffee is fun. Ritu seems unsure whether to mention auditions."},{"text":"Say yes, and make clear it won't affect her roles","then":"Ritu relaxes. \"Good. I'd hate for it to get weird.\"","best":true}],"why":"Naming the power gap up front helps keep her yes free."},{"prompt":"A few weeks on, you and Ritu are close, and she's auditioning for the annual play. What do you do?","options":[{"text":"Give her a smaller role so no one says favouritism","then":"Ritu is confused. She auditioned well and doesn't know why."},{"text":"Step back from casting her part, and say why","then":"Another senior runs her audition. The part she gets is hers alone.","best":true},{"text":"Cast her fairly, trusting yourself to be objective","then":"She gets a lead. Others whisper, and Ritu hears it."},{"text":"Keep your closeness quiet so nobody suspects anything","then":"Ritu feels she has to hide it too, even from friends."}],"why":"Stepping back from casting her keeps the power gap out of the part she gets."},{"prompt":"Ritu often agrees to your plans fast, even when she seems unsure. What do you do?","options":[{"text":"Take it as a yes, since she's an adult","then":"She comes along, quieter than usual."},{"text":"Tell her she can always say no, then carry on planning","then":"She nods. Nothing changes, and she keeps agreeing."},{"text":"Ask what she'd like, and make it easy to say no","then":"She pauses. \"Honestly? A quiet evening.\" She seems surprised to be asked.","best":true},{"text":"Ask a mutual friend whether she's really happy","then":"The friend is awkward. Ritu hears about it and feels watched."}],"why":"With a power gap, you make no easy to say. Her real yes matters more than a quick one."}],"debrief":"When there's a power gap, the person with more power carries the responsibility.","relearn":"With a power gap, the person with more power must be the careful one."},
  {"id":"cr-068","cat":"consent-culture","type":"sort","hook":"Sort: an enthusiastic-yes culture, or a pressure culture?","items":[{"id":"a","text":"\"Only if you really want to\""},{"id":"b","text":"\"Don't be such a prude\""},{"id":"c","text":"Celebrating a clear no as fine"},{"id":"d","text":"Keeping score of conquests"},{"id":"e","text":"\"No worries, your call\" when refused"},{"id":"f","text":"\"Everyone's done it, why won't you\""}],"bins":[{"id":"yes","label":"Enthusiastic-yes","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"yes","b":"pressure","c":"yes","d":"pressure","e":"yes","f":"pressure"},"relearn":"'Only if you want to' and accepting no warmly is enthusiastic-yes; shaming, scorekeeping and 'everyone's done it' is pressure.","persona":"any","source":"culture"},
  {"id":"cr-069","cat":"consent-culture","type":"branch","persona":"Rohan","source":"modelling consent","hook":"Sid tells your hostel group he got a date by asking a girl till she 'gave in'. Everyone cheers.","steps":[{"prompt":"The guys look at you, waiting for your reaction. What do you do?","options":[{"text":"Stay quiet, and message Sid privately later","then":"The room reads your silence as a thumbs-up. Sid carries on."},{"text":"Give the group a proper speech about respecting women","then":"Eyes roll. Someone mutters \"okay, professor\" and the room tunes out."},{"text":"Laugh along so you fit in","then":"Sid grins wider and starts on another story."},{"text":"Say, half-joking, \"Bro, that's pressure, not a win\"","then":"A couple of guys laugh awkwardly. Sid shrugs. \"She said yes, didn't she?\"","best":true}],"why":"A light, clear pushback in the moment shifts what the group treats as normal."},{"prompt":"Sid adds that a yes is a yes, however you get it. What do you say?","options":[{"text":"Say only losers need to beg for dates","then":"Sid gets defensive, and it turns into a roast of him."},{"text":"Say, \"Whatever works for you, bro\"","then":"Sid takes it as a win. The group moves on."},{"text":"Say a yes you had to grind out isn't a free yes","then":"Sid pauses. Someone adds, \"Yeah, bit much, man.\"","best":true},{"text":"Say girls often say no when they actually mean maybe","then":"A few nod. The idea that no means maybe gets stronger."}],"why":"Pressure makes a yes less than free. Saying so plainly is what shifts the idea."},{"prompt":"Later, Nikhil, a junior in the group, quietly asks you how he should ask someone out. What do you say?","options":[{"text":"Tell him: ask once, take the answer, move on if it's no","then":"Nikhil nods slowly. \"Kind of a relief, honestly.\"","best":true},{"text":"Tell him to be confident, and not to take a no so seriously","then":"Nikhil nods. He's learnt persistence, not respect."},{"text":"Say dating apps make the whole thing easier","then":"He downloads one. How to take a no stays unanswered."},{"text":"Tell him to ask in a group, so a no won't feel awkward","then":"Nikhil likes that. She'd have to answer in front of everyone."}],"why":"Asking once and taking the answer is confident and respectful. That's what works."},{"prompt":"A week later, in the hostel group chat, the guys joke about 'wearing someone down' again. What do you do?","options":[{"text":"Let it go, since it's only the group chat","then":"The joke runs on. Nikhil laughs along too."},{"text":"Leave the group chat without explaining","then":"No one notices why. The joke keeps going."},{"text":"Screenshot the chat and post it publicly to shame them","then":"It blows up. The guys get defensive, and nothing changes."},{"text":"Reply, \"That's pressure, guys,\" and change the subject","then":"Someone groans, but the joke fizzles out quickly.","best":true}],"why":"Pushing back lightly, every time, keeps shifting what's normal. Consistency is what counts."}],"debrief":"Modelling consent for your group quietly changes what everyone treats as normal.","relearn":"Push back on 'wearing someone down'; that's pressure, not a win."},
  {"id":"cr-070","cat":"consent-culture","type":"reflect","hook":"Lensy: consent makes intimacy better, freer and safer, not less. Believe it?","prompt":"What do you think?","options":["Yes","Better, not less","Freer"],"affirm":"Real, mutual willingness is what makes intimacy good; consent is the best part.","relearn":"Consent makes intimacy better, freer and safer, not less.","persona":"any","source":"the positive frame"},
  {"id":"cr-071","cat":"consent-culture","type":"strike-rewrite","hook":"\"Asking for consent kills the mood.\"","myth":{"un":"Asking for consent kills the mood.","re":"Asking and hearing a real yes builds trust and makes the mood better.","why":"Confidence that it's wanted is what's actually hot."},"relearn":"Asking for consent builds trust and improves the mood; it doesn't kill it.","persona":"any","source":"mood myth"},
  {"id":"cr-072","cat":"consent-culture","type":"branch","persona":"any","source":"accountability","hook":"Replaying a night months ago, you realise you pushed past Tara's hesitation.","steps":[{"prompt":"The memory keeps coming back at odd moments. What do you do with it?","options":[{"text":"Tell yourself everyone pushes a little. It's just dating","then":"The thought quiets the memory for a day. It comes back sharper the next time."},{"text":"Decide you're a terrible person and try not to think about it","then":"You feel sick for an evening. Nothing about how you act actually changes."},{"text":"Wait and see if Tara ever brings it up","then":"Weeks pass. Tara says nothing, and you tell yourself that settles it."},{"text":"Admit to yourself it wasn't okay, and ask what you'd change","then":"It stings to name it plainly. You start to see the moment you should have stopped.","best":true}],"why":"Naming it honestly, without drowning in shame, is where changing starts."},{"prompt":"Your friend Nikhil notices you seem off and asks what's up. What do you tell him?","options":[{"text":"That it's nothing, just work stress","then":"He shrugs and changes the subject. You carry it home alone again."},{"text":"That Tara sent mixed signals and it confused you","then":"Nikhil nods along. Hearing it framed that way, you feel oddly worse."},{"text":"That you pressured someone once and want to do better","then":"Nikhil goes quiet, then says he's glad you're facing it instead of burying it.","best":true},{"text":"That you're a monster and don't deserve friends","then":"Nikhil looks worried and spends the evening reassuring you instead of listening."}],"why":"Saying it plainly to someone you trust keeps it honest, away from both excuses and spirals."},{"prompt":"You think about what to change next time. What rule do you set yourself?","options":[{"text":"I'll ask once at the start of the night, then relax","then":"It feels like progress, though it says nothing about what happens later."},{"text":"A pause or hesitation means I stop and ask","then":"It feels simple written down. You wonder why it took this long to see it.","best":true},{"text":"I'll wait for a clear no before I stop","then":"The rule sounds firm. You realise it would have changed nothing that night."},{"text":"I'll only date people who are very confident","then":"You feel relieved for a moment. Then you notice the rule asks nothing of you."}],"why":"Hesitation is already an answer. Treating it as a stop is the habit that prevents harm."},{"prompt":"Weeks later, someone you're kissing pauses and goes a bit stiff. What do you do?","options":[{"text":"Stop and ask: \"Want to slow down, or stop?\"","then":"They let out a breath and say they'd like to just talk for a bit.","best":true},{"text":"Slow down a little and keep going","then":"They stay stiff. You can't tell if they're okay, and you don't ask."},{"text":"Ask \"You're fine, right?\" and carry on","then":"They say \"yeah\" quickly. It's the same quick yes you heard that night."},{"text":"Stop, then apologise over and over","then":"They end up reassuring you, and the moment becomes about your guilt."}],"why":"Stopping and asking an open question puts the lesson into practice when it counts."}],"debrief":"Honest accountability, without excuses or a shame spiral, is how you make sure it never repeats.","relearn":"Own past mistakes honestly and commit to doing better."},
  {"id":"cr-073","cat":"consent-culture","type":"reflect","hook":"Lensy: looking out for each other, that's what a consent culture really is. Want to be part of it?","prompt":"What do you think?","options":["Yes","Count me in","Look out for each other"],"affirm":"A culture where people look out for each other is one you help build every day.","relearn":"A consent culture is people looking out for each other.","persona":"any","source":"consent culture"},
  {"id":"cr-074","cat":"tools-and-help","type":"match","hook":"Match the need to the route (India).","pairs":[{"left":"A woman facing any violence","right":"Women Helpline 181"},{"left":"Immediate danger right now","right":"Emergency 112"},{"left":"Harassment on campus","right":"The campus Internal Committee"},{"left":"A woman in distress, separate line","right":"1091"},{"left":"Want to talk it through privately","right":"A campus counsellor"}],"relearn":"181 for women, 112 for danger, the campus committee for harassment, 1091 in distress, a counsellor to talk.","persona":"any","source":"help routes"},
  {"id":"cr-075","cat":"tools-and-help","type":"sort","hook":"Sort: a real support route, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"Asking a random group chat"},{"id":"c","text":"A campus counsellor"},{"id":"d","text":"Just bottling it up"},{"id":"e","text":"The campus Internal Committee"},{"id":"f","text":"Hoping it sorts itself out"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"not","label":"Not a route","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"181, a counsellor and the ICC are real routes; a random chat, bottling it up or hoping aren't.","persona":"any","source":"real routes"},
  {"id":"cr-076","cat":"tools-and-help","type":"reflect","hook":"Lensy: the whole consent reference fits in one line, freely-given, ongoing, sober-enough, revocable. Handy?","prompt":"What do you think?","options":["Yes","Easy to carry","Got it"],"affirm":"Freely-given, ongoing, sober-enough, revocable, that's the whole standard in your pocket.","relearn":"Consent in one line: freely-given, ongoing, sober-enough, revocable.","persona":"any","source":"the reference"},
  {"id":"cr-077","cat":"tools-and-help","type":"match","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"\"They didn't say no\"","right":"Consent is an active yes"},{"left":"\"They were drunk, so it's a yes\"","right":"Incapacity means no consent"},{"left":"\"It was their fault\"","right":"Fault sits only with the one ignoring consent"},{"left":"\"Men can't be assaulted\"","right":"Anyone of any gender can be harmed"},{"left":"\"No struggle, so it was fine\"","right":"Freezing is normal, not a yes"}],"relearn":"Active yes; incapacity is no consent; fault sits with the one ignoring it; anyone can be harmed; freeze isn't a yes.","persona":"any","source":"myth to truth"},
  {"id":"cr-078","cat":"tools-and-help","type":"match","hook":"Match who you'd point a friend to.","pairs":[{"left":"Wants to talk it through confidentially","right":"A campus counsellor"},{"left":"Needs urgent help tonight","right":"Emergency 112"},{"left":"Wants formal campus action","right":"The Internal Committee"},{"left":"Facing violence, any form","right":"Women Helpline 181"},{"left":"Just needs to be believed","right":"A trusted person"}],"relearn":"Counsellor to talk, 112 for urgent help, ICC for action, 181 for violence, a trusted person to be heard.","persona":"Mehta","source":"pointing to help"},
  {"id":"cr-079","cat":"tools-and-help","type":"sort","hook":"Sort: a campus Internal Committee handles this, or not its remit?","items":[{"id":"a","text":"Sexual harassment by a student or staff"},{"id":"b","text":"A lost library book"},{"id":"c","text":"A hostile, unsafe campus environment"},{"id":"d","text":"Your exam timetable"},{"id":"e","text":"Quid-pro-quo pressure from a senior"},{"id":"f","text":"A delayed scholarship cheque"}],"bins":[{"id":"icc","label":"ICC handles","valence":"pos"},{"id":"not","label":"Not its remit","valence":"neutral"}],"key":{"a":"icc","b":"not","c":"icc","d":"not","e":"icc","f":"not"},"relearn":"The campus ICC handles harassment, unsafe environments and quid-pro-quo, not books, timetables or cheques.","persona":"any","source":"campus ICC"},
  {"id":"cr-080","cat":"tools-and-help","type":"reflect","hook":"Lensy: you can keep yourself and others safer now, and you know where help lives. Feel equipped?","prompt":"What do you think?","options":["Yes","Equipped","I know the routes"],"affirm":"Knowing the standard and the routes makes you someone people are safer around.","relearn":"You're equipped to keep yourself and others safer, and you know the routes.","persona":"any","source":"equipped"},
  {"id":"cr-081","cat":"tools-and-help","type":"match","hook":"Match the support step to why it matters.","pairs":[{"left":"\"I believe you\"","right":"Belief is what survivors fear losing"},{"left":"\"What do you need?\"","right":"Gives back control"},{"left":"Signpost help","right":"Connects them to real support"},{"left":"Don't force a report","right":"Respects their autonomy"},{"left":"No blaming questions","right":"Keeps the fault where it belongs"}],"relearn":"Belief, control, signposting, not forcing, no blame, that's why each support step matters.","persona":"any","source":"support steps"},
  {"id":"cr-082","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's nowhere to turn and nothing can be done.\"","myth":{"un":"There's nowhere to turn and nothing can be done.","re":"There are real, confidential routes, helplines, counsellors and campus committees, and you're never alone with it.","why":"Stigma lies; help genuinely exists."},"relearn":"There are real, confidential routes; you're never alone with it.","persona":"Meena","source":"help exists"},
  {"id":"cr-083","cat":"tools-and-help","type":"reflect","hook":"Lensy: whatever happened, it isn't your fault, and you won't be shamed here. Hear that?","prompt":"What do you think?","options":["Yes","Thank you","No shame"],"affirm":"No shame, no blame, just support; that's the promise this game keeps.","relearn":"Whatever happened, it isn't your fault, and there's no shame here.","persona":"any","source":"no shame"},
  {"id":"cr-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: carry the enthusiastic-yes standard and the look-out-for-each-other habit into the world?","prompt":"What will you carry?","options":["Enthusiasm is the bar","Capacity matters","Believe survivors","Look out for each other"],"affirm":"Carry any of those and you make the world around you safer and kinder.","relearn":"Carry the enthusiastic-yes standard and look out for each other.","persona":"any","source":"carry forward"},
  {"id":"cr-1170","cat":"after-harm-support","type":"role-play","persona":"any","source":"disclosure / believe","hook":"Your cousin Simran texts at 2am: someone at the family wedding forced himself on her.","setup":"You call her back at once.","steps":[{"prompt":"Simran whispers: \"Please don't tell me I'm overreacting.\"","options":[{"text":"\"At a family wedding? Are you really sure it wasn't a mix-up?\"","then":"The line goes quiet. \"I knew no one would believe me.\""},{"text":"\"Okay. Let's talk in the morning, once you're calmer.\"","then":"\"I can't sleep,\" she says. \"Please don't hang up.\""},{"text":"\"Who was it? Tell me his name right now.\"","then":"She hesitates. \"I'm scared of what you'll do.\""},{"text":"\"I believe you. None of this is your fault. I'm right here.\"","then":"Simran starts crying. \"I didn't know who else to call.\"","best":true}],"why":"Belief and \"not your fault\" come first, even when it's family."},{"prompt":"Simran says: \"He's sleeping in the next room. Everyone's still here.\"","options":[{"text":"\"I'm calling and waking up the whole house right now.\"","then":"\"No!\" she hisses. \"Please. Not like this.\""},{"text":"\"He's family. He won't try anything more.\"","then":"Simran goes silent, less sure of you now."},{"text":"\"Just stay quiet. Don't make a scene tonight.\"","then":"She stays put, awake, listening to every sound."},{"text":"\"Can you lock your door, or go to someone you trust?\"","then":"\"Mami's room,\" she whispers. \"I'll go now.\"","best":true}],"why":"Getting her somewhere safe tonight, her way, comes before everything else."},{"prompt":"At breakfast, Simran texts: \"Everyone's acting normal. I feel crazy.\"","options":[{"text":"\"Maybe you misread things after such a late night?\"","then":"No reply comes for an hour."},{"text":"\"You're not crazy. What you told me is real.\"","then":"\"Okay,\" she texts back. \"Just keep messaging me.\"","best":true},{"text":"\"Want me to say something to everyone at the table?\"","then":"\"Please no,\" she replies fast. \"Not like this.\""},{"text":"\"Just smile through it till the guests leave.\"","then":"\"I'm trying,\" she writes. \"It's making me sick.\""}],"why":"When everyone acts normal, your steady belief keeps her from doubting herself."},{"prompt":"Simran says: \"If I tell Mummy, the whole family will fight.\"","options":[{"text":"\"Leave it to me. I'll talk to the elders quietly.\"","then":"\"No,\" she says sharply. \"It's mine to tell.\""},{"text":"\"You have to tell her. She's your mother and she'd want to know.\"","then":"Simran's breath catches. \"I'm not ready for that.\""},{"text":"\"That's your call. Want to think who'd be safest to tell?\"","then":"She thinks. \"Maybe Didi. She'd listen first.\"","best":true},{"text":"\"Family peace matters. Maybe keep it quiet for now.\"","then":"She goes quiet. \"So I protect him too?\""}],"why":"Who to tell, and when, is hers to decide. Helping her think it through supports that."},{"prompt":"Simran asks: \"Is there anyone outside the family I could talk to?\"","options":[{"text":"\"Yes. 181 is confidential, any hour. Want me on the call?\"","then":"\"Yes,\" she says. \"Tonight, after everyone sleeps.\"","best":true},{"text":"\"Go straight to the police tomorrow morning. Don't wait on it.\"","then":"\"I didn't ask about the police,\" she says, overwhelmed."},{"text":"\"You could post about it anonymously online.\"","then":"She pictures the comments and shudders."},{"text":"\"Outsiders won't get how our family works.\"","then":"She sighs. \"So I'm stuck with this.\""}],"why":"181 is confidential and outside the family, so she can talk freely, with you there if she wants."}],"relearn":"Lead with belief and 'it's not your fault', even when it's family."},
  {"id":"cr-1171","cat":"after-harm-support","type":"role-play","persona":"any","source":"believe / power","hook":"After your project meeting, Mitali, a junior on the team, stays back.","setup":"She speaks quietly, eyes on the door.","steps":[{"prompt":"Mitali says: \"Karthik wouldn't take no for an answer. At his flat.\"","options":[{"text":"\"Why did you go to his flat on your own?\"","then":"Mitali looks down. \"So it's my fault.\""},{"text":"\"He's senior. Are you sure you read it right?\"","then":"She stiffens. \"I knew it. Everyone loves him.\""},{"text":"\"Thank you for trusting me. I believe you, and this isn't on you.\"","then":"Mitali's eyes fill. \"I was sure you'd take his side.\"","best":true},{"text":"\"That's serious. I'm getting him taken off the project today itself.\"","then":"She panics. \"He'll know I said something.\""}],"why":"Belief doesn't depend on who he is. Her trust deserves it, and it isn't her fault."},{"prompt":"Mitali asks: \"Do I have to keep working with him?\"","options":[{"text":"\"You shouldn't have to. Want to look at options together?\"","then":"She nods. \"I'd like to know what's possible.\"","best":true},{"text":"\"Keep it strictly professional and it'll be fine.\"","then":"\"Professional,\" she repeats. \"With him.\""},{"text":"\"It's only till the project ends. Just grit it out.\"","then":"She nods slowly. \"I'll just avoid his eyes.\""},{"text":"\"I'll quietly swap you onto my sub-team, no questions asked.\"","then":"It helps, but others start asking why the sudden change."}],"why":"Exploring options with her, not for her, protects her while she stays in charge."},{"prompt":"Mitali says: \"If I complain, he'll ruin my marks. He's close to the prof.\"","options":[{"text":"\"The campus committee exists for cases like this. It's your call.\"","then":"She considers it. \"Can you find out how it works?\"","best":true},{"text":"\"Complain anyway. You can't let him get away with it.\"","then":"She feels pushed. \"You don't have to face him.\""},{"text":"\"Then don't complain. Your marks matter more than anything right now.\"","then":"She nods, defeated. He stays on the team."},{"text":"\"I'll go and talk to the prof about him for you.\"","then":"Mitali pales. \"He'll tell Karthik straight away.\""}],"why":"The committee is there when power is involved. Using it, or not, stays her call."},{"prompt":"A few days later, Mitali says: \"I've read about the campus committee. Will you come if I go?\"","options":[{"text":"\"Yes, and I'll tell them everything I've seen of him too.\"","then":"She hesitates. \"Only if I ask you to, okay?\""},{"text":"\"Yes. I'll be there, and you'll lead.\"","then":"\"Okay,\" she says. \"Just knowing that helps.\"","best":true},{"text":"\"Maybe not. It could hurt my own marks with the prof.\"","then":"Her face drops. \"Right. Of course.\""},{"text":"\"You should go alone. It'll look more believable.\"","then":"She looks scared. \"I don't think I can.\""}],"why":"Going as support, with her leading, backs her without taking over."}],"relearn":"Believe a survivor even when the person they name holds power."},
  {"id":"cr-1172","cat":"after-harm-support","type":"role-play","persona":"any","source":"patience","hook":"Your roommate Jaya starts telling you about last night's date, then stops.","setup":"She stares at the floor, ashamed.","steps":[{"prompt":"Jaya whispers: \"He didn't stop. I can't even say it.\"","options":[{"text":"\"Just spit it out. What actually happened?\"","then":"Jaya's face closes. After a long pause: \"Give me a second. It's hard.\""},{"text":"\"You don't have to explain. I get it. Let's go and report him.\"","then":"Her eyes widen. \"Report? I haven't even said it yet.\""},{"text":"\"Take your time. I'm not going anywhere, and I believe you.\"","then":"She lets out a shaky breath. \"Okay. Give me a minute.\"","best":true},{"text":"\"Maybe you're overthinking it. First dates get awkward.\"","then":"She goes still. \"Yeah. Maybe.\""}],"why":"Patience and belief let her speak at her own pace, or not at all."},{"prompt":"Jaya says: \"I feel so stupid for going back to his place.\"","options":[{"text":"\"Don't think about it anymore. It's done now.\"","then":"She tries to stop, but she can't."},{"text":"\"Why did you go back there, though?\"","then":"Jaya's shoulders tense. \"I don't know. I trusted him.\""},{"text":"\"You're not stupid. Going there wasn't a yes to anything.\"","then":"She looks at you. \"I keep thinking I should have known.\"","best":true},{"text":"\"You couldn't have known. Maybe next time, just stick to cafés.\"","then":"She nods, and hears that it was hers to prevent."}],"why":"Going to his place was never consent. Only he is responsible, and it's not her fault."},{"prompt":"The next morning, Jaya says: \"I can't stop replaying it.\"","options":[{"text":"\"You have to report it, or it'll keep eating at you.\"","then":"Jaya's breathing quickens. \"I can't do that yet.\""},{"text":"\"Keep yourself busy. It'll fade on its own.\"","then":"She tries. It doesn't fade."},{"text":"\"That's common after this. Want help finding a counsellor?\"","then":"She considers it. \"Maybe. Can you sit with me when I call?\"","best":true},{"text":"\"Maybe going over it all again with me will help it settle.\"","then":"She hesitates. Going over it again feels like too much."}],"why":"Replaying is a common response. Gently offering to find a counsellor keeps the choice hers."}],"relearn":"Give a survivor time and patience; don't push them to perform the story."},
  {"id":"cr-1173","cat":"after-harm-support","type":"role-play","persona":"Ananya","source":"no blame / his room","hook":"Ananya, your friend from the hostel, tells you a guy assaulted her after a party.","setup":"She pulls her sleeves over her hands.","steps":[{"prompt":"Ananya says: \"I went up to his room myself. So it's on me.\"","options":[{"text":"\"Going to a room is never a yes. Only he crossed a line.\"","then":"She looks up. \"Then why do I feel so guilty?\"","best":true},{"text":"\"Anyone could have done that. Don't beat yourself up over it.\"","then":"She shrugs. \"But I did do it.\" The guilt stays."},{"text":"\"Yeah, going up there was probably a mistake.\"","then":"Ananya nods slowly. \"That's what my parents would say.\""},{"text":"\"Did you give him any signals, maybe?\"","then":"Ananya shrinks. \"I don't know. Maybe?\""}],"why":"Going somewhere is never consent. Only the one who ignored consent is responsible."},{"prompt":"Ananya says: \"If my parents find out, they'll pull me out of college.\"","options":[{"text":"\"Maybe being at home would be safer for you anyway.\"","then":"Her eyes fill. \"So I lose everything because of him?\""},{"text":"\"It's your call who knows. I'll keep it with me.\"","then":"She exhales. \"Okay. I can't lose this place.\"","best":true},{"text":"\"Tell them yourself, before somebody else does.\"","then":"Panic crosses her face. \"Who else would?\""},{"text":"\"They'd understand. They're your parents, after all.\"","then":"She laughs bitterly. \"You haven't met them.\""}],"why":"Who knows is hers to decide. Keeping it private protects her freedom and her trust."},{"prompt":"Ananya asks: \"Is there anyone here I could talk to, who won't judge?\"","options":[{"text":"\"Post on the college confessions page. Keep it anonymous.\"","then":"She imagines the comments and closes the app."},{"text":"\"The campus counsellor, or 181. Both are confidential.\"","then":"She nods. \"The counsellor, maybe. Next week.\"","best":true},{"text":"\"The warden. She'll sort things out for you.\"","then":"Ananya freezes. \"She calls parents about everything.\""},{"text":"\"Just me. Others might think you're a bit wild.\"","then":"She goes quiet, more alone than before."}],"why":"Confidential help like a counsellor or 181 lets her talk without judgement or family pressure."}],"relearn":"Going somewhere is never consent; only the one ignoring it is at fault."},
  {"id":"cr-1174","cat":"after-harm-support","type":"role-play","persona":"any","source":"delayed disclosure","hook":"On a walk, your friend Yash says he was assaulted months ago. He's only telling you now.","setup":"He braces, as if for doubt.","steps":[{"prompt":"Yash says: \"You're going to ask why I waited.\"","options":[{"text":"\"Months ago? Why bring it up only now?\"","then":"His face shuts. \"See? This is why I didn't.\""},{"text":"\"Better late than never, I suppose.\"","then":"He winces. \"So I was late.\""},{"text":"\"Are you sure it was that serious, if you waited this long?\"","then":"Yash looks away. \"I don't know anymore.\""},{"text":"\"No. Time passing doesn't change anything. I believe you.\"","then":"Yash lets out a long breath. \"I kept thinking it was too late.\"","best":true}],"why":"Delay is common and never makes it less true. Belief is what he needs."},{"prompt":"Yash says: \"I kept acting normal. Doesn't that mean it wasn't bad?\"","options":[{"text":"\"Maybe. Only you can know how bad it really was for you.\"","then":"He shrugs. \"That's the problem. I can't tell.\""},{"text":"\"Guys bounce back from stuff. Looks like you did.\"","then":"He laughs, empty. \"Clearly.\""},{"text":"\"If you were fine, maybe it's best to leave it be.\"","then":"He goes quiet. \"Yeah. Maybe.\""},{"text":"\"People cope by acting normal. It doesn't make it less real.\"","then":"He nods slowly. \"I've been so tired of pretending.\"","best":true}],"why":"Acting normal is a way to cope, not proof that nothing happened. It's not his fault."},{"prompt":"Yash asks: \"Is it too late to do anything about it?\"","options":[{"text":"\"Probably. It's been too long for anything now.\"","then":"Yash nods, and the door he opened swings shut."},{"text":"\"Just move on. It's behind you now.\"","then":"He says okay, but his hands are shaking."},{"text":"\"No. You can talk to a counsellor whenever you're ready.\"","then":"He thinks. \"Maybe that's what I need first.\"","best":true},{"text":"\"Not if you report it this week, before any more time goes by.\"","then":"His shoulders tense at the deadline."}],"why":"It's never too late for support. A counsellor can help him, on his own timeline."}],"relearn":"Delay never makes a disclosure less true; believe them regardless of timing."},
  {"id":"cr-1175","cat":"after-harm-support","type":"role-play","persona":"Rohan","source":"even-handed support","hook":"Your friend Sahil admits that the woman he was seeing forced him, after he'd said no.","setup":"He's half-grinning, ready for a joke.","steps":[{"prompt":"Sahil says: \"Go on. Say I got lucky.\"","options":[{"text":"\"Honestly? Lucky you, man. Most guys would want that kind of thing.\"","then":"He laughs along, a beat too long. Then, quietly: \"It didn't feel lucky.\""},{"text":"\"I believe you. This happens to men too. It wasn't your fault.\"","then":"The grin drops. \"I didn't think anyone would say that.\"","best":true},{"text":"\"Wait, how is that even possible with a guy?\"","then":"His face reddens. \"I know how it sounds. It still happened.\""},{"text":"\"No jokes. That's rough, man. You good, though?\"","then":"\"Yeah, I'm good,\" he says. He isn't."}],"why":"Men can be harmed too. Belief and \"not your fault\" take the joke off the table."},{"prompt":"Sahil asks: \"I'm stronger than her. Shouldn't I have stopped it?\"","options":[{"text":"\"Strength isn't the point. You said no. It was ignored.\"","then":"He goes quiet. \"I did say no. Twice.\"","best":true},{"text":"\"Did you maybe give her some mixed signals before?\"","then":"He flushes. \"I don't know. Did I?\""},{"text":"\"Don't overthink it, man. It's all over and done with now.\"","then":"He nods, but the question is still there."},{"text":"\"Honestly? I think I'd have just pushed her off.\"","then":"Sahil's jaw tightens. \"Thanks. Really.\""}],"why":"His no was ignored. Strength doesn't change who's responsible, and that's only her."},{"prompt":"Sahil says: \"She's telling people we're still together.\"","options":[{"text":"\"That's not okay. What would help you feel safe from her?\"","then":"He thinks. \"Blocking her. And not eating in the canteen alone.\"","best":true},{"text":"\"Just play along until she moves on to someone else.\"","then":"He sighs. \"So I pretend it's all fine.\""},{"text":"\"Talk it out with her. Clear the air once and for all.\"","then":"He looks sick. \"Be alone with her? No.\""},{"text":"\"I'll set everyone straight about what she's really like. Leave it to me.\"","then":"He grabs your arm. \"Please don't. It's my story.\""}],"why":"Asking what makes him feel safe puts his needs first, not a confrontation."},{"prompt":"A week later, Sahil says: \"Maybe I'm making it a bigger deal than it is.\"","options":[{"text":"\"It is a big deal. Talking to a counsellor could help.\"","then":"He nods slowly. \"Maybe. Would you come with me?\"","best":true},{"text":"\"Honestly, maybe. Lots of guys wouldn't mind at all.\"","then":"His face closes. \"Right. Forget I said it.\""},{"text":"\"Then let's just not talk about it anymore, if it helps.\"","then":"He agrees. He carries it alone again."},{"text":"\"It's a big deal. But try not to dwell on it.\"","then":"He tries. It keeps coming back at night."}],"why":"What happened was real and serious. A counsellor can help him make sense of it."}],"relearn":"Men can be harmed too; believe male survivors fully and equally."},
  {"id":"cr-1176","cat":"after-harm-support","type":"role-play","persona":"any","source":"queer survivor","hook":"Your friend Zoya was assaulted by a woman she dated. Her family doesn't know she's queer.","setup":"She talks fast, her voice tight.","steps":[{"prompt":"Zoya says: \"If I report, everyone finds out about me too.\"","options":[{"text":"\"Maybe sort out coming out first, then we'll see.\"","then":"She stares at you. \"That's the part I'm most scared of.\""},{"text":"\"I believe you. We go only as fast as you want, on both.\"","then":"Zoya slows down. \"Okay. I needed someone to say that.\"","best":true},{"text":"\"Was it really assault, if you two were dating?\"","then":"Her face goes cold. \"Dating isn't a yes.\""},{"text":"\"Reporting matters more. The rest will sort itself out later.\"","then":"Zoya shakes her head. \"It won't. Not with my family.\""}],"why":"What happened isn't her fault. Belief, and her pace on both, keep her safe and in charge."},{"prompt":"Zoya asks: \"Would anyone even take it seriously between two women?\"","options":[{"text":"\"Probably not. A lot of people just don't get it.\"","then":"Zoya's shoulders slump. \"So why bother.\""},{"text":"\"Of course they will. Don't worry about that part at all.\"","then":"She wants to believe you. \"You don't know that.\""},{"text":"\"Harm is harm, whoever did it. We can ask how it works.\"","then":"She nods. \"Quietly, though. Before I decide anything.\"","best":true},{"text":"\"Maybe just talk to her yourself and sort it out.\"","then":"Zoya flinches. \"Be alone with her? No.\""}],"why":"Harm is harm, whoever did it. Finding out quietly helps her choose."},{"prompt":"Zoya says: \"Mummy keeps asking why I'm so quiet lately.\"","options":[{"text":"\"You don't owe anyone either story yet. What do you want to say?\"","then":"She thinks. \"Maybe that exams are stressful. For now.\"","best":true},{"text":"\"Want me to talk to her for you, if it helps?\"","then":"\"No,\" she says quickly. \"Please don't.\""},{"text":"\"Just act more cheerful at home so she stops asking.\"","then":"She sighs. Acting fine is already wearing her out."},{"text":"\"Maybe tell her everything. It could even bring the two of you closer.\"","then":"Zoya's breath catches. \"Or it could blow everything up.\""}],"why":"What she tells her family, and when, is hers to decide."},{"prompt":"Zoya asks: \"Is there someone I can talk to who won't out me?\"","options":[{"text":"\"Talk to our friends. They're all fine with it.\"","then":"Zoya hesitates. \"Not all of them. Not with this.\""},{"text":"\"Just me. It's safer to keep it that way.\"","then":"She agrees, and you're both left without real help."},{"text":"\"A counsellor or 181 is confidential. You can stay vague at first.\"","then":"She nods. \"Vague I can do. Maybe 181 tonight.\"","best":true},{"text":"\"Post anonymously in a queer group online, and see what people say.\"","then":"Replies pour in, some kind, some not. She logs off shaken."}],"why":"Confidential help lets her get support without having to out herself."}],"relearn":"Support a survivor without forcing other disclosures on their timeline."},
  {"id":"cr-1177","cat":"after-harm-support","type":"role-play","persona":"any","source":"freeze / no blame","hook":"Your sister Gauri told you last week that a colleague assaulted her.","setup":"Tonight she brings it up again.","steps":[{"prompt":"Gauri says: \"I should have fought harder. I just froze.\"","options":[{"text":"\"Well, a bit more resistance might've helped, na.\"","then":"She goes silent and turns away."},{"text":"\"At least it's over now. Try to look ahead.\"","then":"Gauri flinches. \"It doesn't feel over.\""},{"text":"\"Don't say that. You did your best.\"","then":"She shakes her head. \"My best wasn't enough.\""},{"text":"\"Freezing is your body protecting you. It wasn't yours to fight off.\"","then":"Gauri stares at you. \"Protecting me? It felt like failing.\"","best":true}],"why":"Freezing is involuntary. It was never her job to stop him, and it's not her fault."},{"prompt":"After a while, Gauri asks: \"Why do I feel so ashamed?\"","options":[{"text":"\"Shame is common after this. But the shame is his, not yours.\"","then":"She wipes her eyes. \"I've never heard it put that way.\"","best":true},{"text":"\"Everyone feels ashamed of things sometimes. It'll pass on its own.\"","then":"She nods, not convinced."},{"text":"\"Maybe because you kept seeing him at work after?\"","then":"Her face crumples. \"I had to. It's my job.\""},{"text":"\"You shouldn't feel ashamed. Just try to let it go.\"","then":"\"I can't just let it go,\" she says quietly."}],"why":"Shame often follows harm, but it belongs to the one who caused it, never to her."},{"prompt":"Gauri says: \"I can't keep going to work and seeing him.\"","options":[{"text":"\"I'll go to your office myself tomorrow and confront him for you.\"","then":"Gauri panics. \"Please don't. I'll lose my job.\""},{"text":"\"Keep your head down. It'll get easier with time.\"","then":"She nods. Her stomach knots every morning."},{"text":"\"181 can talk through your options. Want to call together?\"","then":"She hesitates, then nods. \"After dinner?\"","best":true},{"text":"\"Just quit. Your health matters more than any job.\"","then":"She looks stricken. \"I can't afford to quit.\""}],"why":"181 can explain her options, and your company makes the call easier. The choice stays hers."}],"relearn":"Freezing is an involuntary trauma response, never a failure to resist."},
  {"id":"cr-1178","cat":"after-harm-support","type":"role-play","persona":"any","source":"don't take over","hook":"Your friend Naina wants to tell you something about her ex, but she's hesitating.","setup":"She glances at your clenched fists.","steps":[{"prompt":"Naina asks: \"If I tell you, will you go and beat him up?\"","options":[{"text":"\"No. Nothing happens that you don't choose. What would help?\"","then":"She breathes out. \"Okay. He assaulted me. I needed you to know.\"","best":true},{"text":"\"Depends on what he did to you.\"","then":"Naina looks uneasy, but tells you in a small voice."},{"text":"\"I'll try not to. Just tell me.\"","then":"She hesitates. \"Try?\" She tells you, watching you closely."},{"text":"\"Honestly, I might. Just give me his name and where he lives.\"","then":"Naina goes pale. \"Please don't.\" After a long pause, she tells you anyway."}],"why":"Promising she stays in control makes it safe for her to tell you."},{"prompt":"Naina says: \"He's in our friend group. I don't want drama.\"","options":[{"text":"\"Okay. What would make being around the group easier?\"","then":"She thinks. \"Skipping a few hangouts. And you not asking why.\"","best":true},{"text":"\"Then I'll quietly drop him from the group chat myself.\"","then":"She tenses. \"People will ask why. Then what?\""},{"text":"\"You'll see him anyway, so just act normal.\"","then":"She nods slowly. The thought makes her feel sick."},{"text":"\"The group deserves to know. They'd back you up.\"","then":"Naina's eyes widen. \"Not yet. Maybe never.\""}],"why":"Asking what makes it easier keeps her in charge of her own space."},{"prompt":"Naina asks: \"So what am I supposed to do now?\"","options":[{"text":"\"Just avoid him, and try to forget it ever happened.\"","then":"She nods, but she knows she won't forget."},{"text":"\"Report him. Let the system do the beating up.\"","then":"She manages a weak smile, then shakes her head. \"Not yet.\""},{"text":"\"Nothing, unless you want to. 181 or a counsellor is there.\"","then":"She nods. \"Good to know. Not yet, though.\"","best":true},{"text":"\"Let me handle it from here. You've been through enough already.\"","then":"Naina tenses. \"That's exactly what I didn't want.\""}],"why":"What he did is never her fault. Help is there, and she decides if and when to use it."}],"relearn":"Support means following the survivor's lead, not acting out your anger."},
  {"id":"cr-1179","cat":"after-harm-support","type":"role-play","persona":"any","source":"holding space","hook":"Your hostel-mate Anjali told you about an assault yesterday. Tonight she's crying in her room.","setup":"She waves you in but won't look up.","steps":[{"prompt":"Anjali says: \"Please don't give me advice. Just stay.\"","options":[{"text":"\"I'll sit right here as long as you want. No plan needed.\"","then":"She nods and shifts over on the bed to make space.","best":true},{"text":"\"Let me get the warden. She'll know what to do.\"","then":"Anjali grabs your hand. \"No. Please. Just you.\""},{"text":"\"Okay, first thing tomorrow, we file a complaint. Decided.\"","then":"She cries harder. \"You're not listening.\""},{"text":"\"Okay. But you'll feel better if you talk about it.\"","then":"\"Maybe later,\" she says, pulling the blanket tight."}],"why":"None of this is her fault. Staying, without a plan, is exactly the support she asked for."},{"prompt":"Someone knocks. A girl from next door calls: \"Everything okay in there?\"","options":[{"text":"\"She's just upset. Some guy stuff, you know.\"","then":"Anjali stiffens. The neighbour lingers at the door, curious."},{"text":"\"Come on in. She could use a bit more company.\"","then":"Anjali pulls the blanket over her face as the girl walks in."},{"text":"\"We're fine, thanks. Just having a quiet night.\"","then":"\"Okay!\" The footsteps move off, and Anjali relaxes.","best":true},{"text":"\"Can you get us some food? It's been a rough day for her.\"","then":"She agrees, and asks what happened when she gets back."}],"why":"A simple answer at the door protects her privacy without making it awkward."},{"prompt":"Near curfew, Anjali asks: \"Will you check on me tomorrow?\"","options":[{"text":"\"Yes. And if the nights get hard, 181 is there too.\"","then":"She nods, almost smiling. \"Okay. Tomorrow, then.\"","best":true},{"text":"\"Sure. But you really do need to see a counsellor.\"","then":"She nods tiredly. The \"need\" sits heavy."},{"text":"\"Only if you promise me you'll report it.\"","then":"Her face falls. \"So there's a condition.\""},{"text":"\"Of course. I'll sleep here tonight so you're not alone.\"","then":"She hesitates. \"I think I need some space too.\""}],"why":"A steady yes, plus help she can reach any time, means she isn't on her own."}],"relearn":"Sometimes the support a survivor needs is simply being there, quietly."},
  {"id":"cr-1180","cat":"after-harm-support","type":"role-play","persona":"any","source":"privacy","hook":"Isha told you and Karan that a guy from your batch assaulted her.","setup":"Karan storms into your room, phone in hand.","steps":[{"prompt":"Karan says: \"I'm posting his name in the group. Everyone should know.\"","options":[{"text":"\"Calm down. It's none of our business, honestly.\"","then":"Karan glares. \"She's our friend. Of course it is.\""},{"text":"\"It's not ours to share. Let's ask Isha what she wants first.\"","then":"Karan hesitates. \"Fine. But he can't just get away with it.\"","best":true},{"text":"\"Good idea. Everyone should know. Post it.\"","then":"Karan starts typing, then stops. \"Wait. Should we ask Isha?\""},{"text":"\"Don't name him. Just warn people there's a creep around here.\"","then":"Karan considers it. \"People will guess who, though.\""}],"why":"Her story is hers, and none of it is her fault. Asking her first protects her from being outed."},{"prompt":"Karan says: \"I hate that he just walks around like nothing happened.\"","options":[{"text":"\"Then let's go and confront him ourselves, tonight.\"","then":"Karan perks up. Then you both realise Isha never asked for this."},{"text":"\"We could quietly tell his girlfriend what he did.\"","then":"Karan frowns. \"And she'd tell everyone by morning.\""},{"text":"\"Just ignore him. It's not worth all the drama.\"","then":"Karan stares. \"Seriously? That's it?\""},{"text":"\"We back Isha, and let her decide what happens.\"","then":"Karan exhales. \"Okay. I just feel so useless.\"","best":true}],"why":"Supporting her choices is doing something. Acting without her can harm her."},{"prompt":"Karan says: \"People are already asking why Isha's missing classes.\"","options":[{"text":"\"Let's ask Isha to post something herself, to clear it up.\"","then":"Karan asks. Isha feels pushed to explain before she's ready."},{"text":"\"We just say it's her business, and leave it there.\"","then":"Karan nods. \"Simple. I can do that.\"","best":true},{"text":"\"Tell them she's been sick. It's simpler.\"","then":"The story spreads, and Isha has to keep it up."},{"text":"\"Hint that something happened, so they're kind to her.\"","then":"Karan tries it. By evening, people are guessing out loud."}],"why":"A plain answer that shares nothing keeps her story private."},{"prompt":"Karan asks: \"How can I actually help her, then?\"","options":[{"text":"\"Ask her what she needs. Mention 181 or the ICC if she wants.\"","then":"Karan nods. \"Ask, don't decide. Got it.\"","best":true},{"text":"\"Keep checking on her every few hours, just in case.\"","then":"Karan does. Isha starts leaving his messages on read."},{"text":"\"Act like nothing happened when you're around her.\"","then":"Karan tries. Isha wonders if he's forgotten, or doesn't care."},{"text":"\"Help her write a post naming him, so it's all out there for good.\"","then":"Karan brings it up. Isha goes pale and changes the subject."}],"why":"Asking what she needs, and knowing where help is, is the most useful thing a friend can do."}],"relearn":"What a survivor shared is theirs; don't out them or the story without consent."},
  {"id":"cr-1181","cat":"after-harm-support","type":"role-play","persona":"any","source":"self-support","hook":"Months after a breakup, you realise something your ex did last year was assault.","setup":"Your best friend Priya notices you've gone quiet.","steps":[{"prompt":"Priya asks: \"Hey. What's going on with you?\"","options":[{"text":"\"Nothing. Just tired, that's all.\"","then":"\"Okay,\" Priya says, unconvinced. \"I'm around if that changes.\""},{"text":"\"I think something my ex did was assault. Can we talk?\"","then":"Priya puts her phone down. \"I'm here. Take your time.\"","best":true},{"text":"\"My ex and I were together, so it probably doesn't count.\"","then":"Priya tilts her head. \"Doesn't count as what?\""},{"text":"\"Can I ask you a hypothetical, about a friend?\"","then":"Priya nods slowly. \"Sure. A friend.\" She waits."}],"why":"Naming it to someone you trust is a first step toward support. You deserve it."},{"prompt":"Once you've told her about your ex, Priya says: \"I'm not judging you. At all.\"","options":[{"text":"\"I stayed with them for a while after, so maybe I've got it wrong.\"","then":"Priya frowns. \"Staying doesn't change what they did.\""},{"text":"\"It's fine. It was a long time ago anyway.\"","then":"Priya looks at you. \"It doesn't sound fine.\""},{"text":"\"It wasn't my fault. I'm still learning to believe that.\"","then":"Priya nods. \"It wasn't. I'll say it as often as you need.\"","best":true},{"text":"\"You should. I really should have known better.\"","then":"Priya shakes her head. \"No. I won't let you say that.\""}],"why":"It was never your fault, whatever happened before or after. Saying it helps you believe it."},{"prompt":"Priya asks: \"Would talking to someone trained help, do you think?\"","options":[{"text":"\"I'll read about it online first, on my own.\"","then":"\"Okay,\" Priya says. \"Just not alone at 2am, please.\""},{"text":"\"Only if it gets any worse. For now it's manageable, honestly.\"","then":"Priya pauses. \"You don't have to wait for worse.\""},{"text":"\"No. They'll just think I'm making a fuss.\"","then":"Priya frowns. \"Making a fuss about something real?\""},{"text":"\"Maybe. I'll book the campus counsellor this week.\"","then":"Priya nods. \"Want me to walk you there?\"","best":true}],"why":"You deserve support now, not only when it gets worse. A counsellor is there for exactly this."},{"prompt":"Priya asks: \"Do you want to confront your ex about it?\"","options":[{"text":"\"I should, or it means I'm weak.\"","then":"Priya shakes her head. \"Not confronting isn't weak.\""},{"text":"\"I'd rather post about it and name them publicly.\"","then":"Priya hesitates. \"That could blow up fast. Are you ready?\""},{"text":"\"Not now. Staying away is what feels safe to me.\"","then":"\"Then that's the plan,\" Priya says. \"Your call, always.\"","best":true},{"text":"\"Maybe. I'll message them alone tonight and have it out.\"","then":"Priya looks worried. \"Alone? At least let me be nearby.\""}],"why":"Your safety and your choices come first. You never owe anyone a confrontation."}],"relearn":"If it happened to you, it wasn't your fault and you deserve support."},
  {"id":"cr-1182","cat":"after-harm-support","type":"role-play","persona":"Meena","source":"signpost / offline","hook":"Your co-worker Meena says a man at her lodging assaulted her.","setup":"She speaks low, so no one hears.","steps":[{"prompt":"Meena says: \"Help is for college girls. Not for people like me.\"","options":[{"text":"\"Just move to another lodging and forget it.\"","then":"\"With what money?\" she asks quietly."},{"text":"\"I believe what you told me. 181 is for you too, any phone, any hour.\"","then":"Meena looks up. \"Any phone? Even this old one?\"","best":true},{"text":"\"Tell your family back home. They'll know what to do.\"","then":"She shakes her head. \"They'll call me back to the village.\""},{"text":"\"Without a college office, there's not really much you can do, na.\"","then":"She nods, as if she knew. \"I'll just manage.\""}],"why":"Belief first: it's not her fault. 181 is for every woman, any phone, any hour, no campus needed."},{"prompt":"Next day, Meena asks: \"If I call a helpline like 181, will they want my papers, or call my boss?\"","options":[{"text":"\"181 is confidential. You can ask them that first thing.\"","then":"She thinks. \"So I can ask before I say my name?\"","best":true},{"text":"\"Maybe that's a real risk. It's better not to call them at all.\"","then":"She nods, and the fear decides for her."},{"text":"\"They won't. I promise nothing will go wrong.\"","then":"She wants to believe you. \"How do you know?\""},{"text":"\"I'll call for you and give them all your details.\"","then":"Meena's eyes widen. \"Not my name. Not yet.\""}],"why":"It's confidential, and she can ask her questions before sharing anything."},{"prompt":"Meena says: \"He's there every night when I get back.\"","options":[{"text":"\"I'll go and talk to him myself, and tell him to stop it right now.\"","then":"She grabs your arm. \"He'll know I told. Please.\""},{"text":"\"Keep your door locked and your phone charged, always.\"","then":"She nods. She still has to walk past him each night."},{"text":"\"Try not to make him angry, and you'll be okay.\"","then":"Meena goes quiet, as if keeping him calm is her job."},{"text":"\"If you're in danger, call 112. Want to stay at mine for now?\"","then":"Meena hesitates, then nods. \"Just for a few nights.\"","best":true}],"why":"112 is there for danger, and a safer place for now protects her while she decides."}],"relearn":"Help like 181 reaches everyone, with no campus or office needed."},
  {"id":"cr-1183","cat":"after-harm-support","type":"role-play","persona":"Mehta","source":"signpost help","hook":"Your friend Rukhsar wants help after an assault, but she's scared of being judged.","setup":"She holds her phone, not dialling.","steps":[{"prompt":"Rukhsar says: \"They'll ask what I was doing there. I know it.\"","options":[{"text":"\"Well, what were you doing there?\"","then":"Rukhsar stiffens. \"See? That's exactly it.\""},{"text":"\"If they judge you, you can just hang up on them.\"","then":"She nods, but fear of that moment keeps her from dialling."},{"text":"\"181 is confidential and won't judge you. I'll dial it with you.\"","then":"She looks at the phone. \"Right now? Okay. Stay close.\"","best":true},{"text":"\"Just deal with it on your own. Those helplines never help anyway.\"","then":"She lowers the phone, then grips it. \"No. I still want to try.\""}],"why":"181 is confidential, and your company makes the first call less frightening."},{"prompt":"Rukhsar whispers: \"Even if I call, what do I say first?\"","options":[{"text":"\"Start with: I need to talk about something that happened.\"","then":"She repeats it softly. \"That, I can say.\"","best":true},{"text":"\"Tell them everything from the very start, in full detail.\"","then":"She looks overwhelmed. \"I can't do it all at once.\""},{"text":"\"Say it's about a friend, so it feels less awkward.\"","then":"She considers it, but it feels like hiding again."},{"text":"\"Let me do the talking. I'll explain it all for you.\"","then":"She hesitates. \"It's my story, though.\""}],"why":"A simple first line lets her begin, and share only what she chooses."},{"prompt":"Later that day, Rukhsar says: \"Even thinking about it makes me shake.\"","options":[{"text":"\"Push through it. The hardest part's already over.\"","then":"She tries to smile. The shaking doesn't stop."},{"text":"\"Maybe it's a sign you're not ready for any of this.\"","then":"She goes quiet, doubting herself again."},{"text":"\"Let's make a list of all your next steps, right now, together.\"","then":"She stares at the list, and the shaking gets worse."},{"text":"\"That's normal. This is a lot. Want to rest a bit?\"","then":"She nods and curls up on the sofa. \"Just ten minutes.\"","best":true}],"why":"Shaking is a normal response. Rest and company help more than a to-do list."},{"prompt":"Rukhsar asks: \"Will you tell anyone about this?\"","options":[{"text":"\"Why? Are you embarrassed about it?\"","then":"Her face falls. \"Shouldn't I be?\""},{"text":"\"Only our close friends, so they can support you too.\"","then":"Rukhsar tenses. \"Please don't. Not yet.\""},{"text":"\"No, but you should really tell your family soon.\"","then":"She sighs. \"You sound like everyone else.\""},{"text":"\"Not unless you're ever in danger. It's your story.\"","then":"She lets out a breath. \"Thank you. Really.\"","best":true}],"why":"Keeping it private respects her. It's never her fault, and nothing to be ashamed of."}],"relearn":"Signpost confidential help (181) gently, and offer to be there for it."},
  {"id":"cr-1184","cat":"after-harm-support","type":"role-play","persona":"any","source":"their words","hook":"After lab, your classmate Devika says something happened with a guy last weekend.","setup":"She stops, searching for words.","steps":[{"prompt":"Devika says: \"I don't even know what to call it.\"","options":[{"text":"\"You don't have to call it anything yet. I'm listening.\"","then":"She nods, relieved. \"It just felt wrong. Really wrong.\"","best":true},{"text":"\"Maybe it was just a bad hookup, you know?\"","then":"She hesitates. \"Maybe. It doesn't feel like that.\""},{"text":"\"Was it assault or not? I need to know to help.\"","then":"Devika goes quiet. \"I don't know. Forget it.\""},{"text":"\"It sounds like assault to me. You should call it that, then.\"","then":"She flinches at the word. \"I'm not ready for that.\""}],"why":"She gets to name her own experience, in her own time. Listening comes first."},{"prompt":"Devika says: \"I keep thinking maybe I'm overreacting.\"","options":[{"text":"\"Everyone overthinks things after a weird night.\"","then":"She nods, unconvinced. \"Maybe it's just me.\""},{"text":"\"If it felt wrong, that matters. You're not overreacting.\"","then":"She looks up. \"You really think so?\"","best":true},{"text":"\"Maybe. Sleep on it and see how you feel.\"","then":"She shrugs. The feeling doesn't shrink overnight."},{"text":"\"What exactly did he do? Then I can tell you if it was bad.\"","then":"She pulls back. \"I don't want to go through it.\""}],"why":"If it felt wrong, that matters. Her feelings are real, and it's not her fault."},{"prompt":"Devika asks: \"Is there someone I could talk to, without making it official?\"","options":[{"text":"\"Just talk to me. Officials make everything into a big deal.\"","then":"She's relieved, and still unsure where to turn."},{"text":"\"The ICC, but only once you're sure it was assault.\"","then":"Devika sighs. \"That's the thing. I'm not sure.\""},{"text":"\"Not really. Everything becomes official in the end.\"","then":"She looks worried. \"Then maybe I won't.\""},{"text":"\"A counsellor, or 181. Just talking isn't a complaint.\"","then":"She nods. \"Okay. Just talking, I can do.\"","best":true}],"why":"Talking to a counsellor or 181 is support, not a report. She can take it step by step."}],"relearn":"Let a survivor name their experience in their own time, if at all."},
  {"id":"cr-1185","cat":"after-harm-support","type":"role-play","persona":"any","source":"no blame / timing","hook":"Your friend Bhavna was assaulted walking back from a late shift. Her family doesn't know.","setup":"She's pacing your kitchen.","steps":[{"prompt":"Bhavna says: \"They'll say I asked for it, being out so late.\"","options":[{"text":"\"Being out late is never a reason. Only he's responsible. Full stop.\"","then":"She stops pacing. \"Say that again.\"","best":true},{"text":"\"Maybe just don't tell them you were out that late.\"","then":"She pauses. \"So I lie, to be believed?\""},{"text":"\"They have a point about the timing, to be fair.\"","then":"Bhavna's face crumples. \"So even you think so.\""},{"text":"\"They're just old-fashioned. Don't take it to heart.\"","then":"\"It's hard not to,\" she says. \"They're my parents.\""}],"why":"Where or when she was never excuses harm. Only the one who ignored consent is to blame."},{"prompt":"Bhavna asks: \"Should I even tell them?\"","options":[{"text":"\"No. They'll only make it worse for you.\"","then":"She frowns. \"You don't know that.\""},{"text":"\"Let me tell them for you. I'll do it gently.\"","then":"\"No,\" she says quickly. \"If anyone tells, it's me.\""},{"text":"\"That's your call. Want to think who'd be safest to tell?\"","then":"She thinks. \"Maybe my brother. He listens.\"","best":true},{"text":"\"Yes. In the end, families always come around to these things.\"","then":"She looks doubtful. \"Or they stop me working.\""}],"why":"Who she tells is her choice. Thinking it through with her supports that."},{"prompt":"Bhavna says: \"I still have to walk that road every night for work.\"","options":[{"text":"\"Just quit that job. It's not safe for you anymore.\"","then":"\"I can't afford to,\" she says flatly."},{"text":"\"You'll just have to be a lot more careful on that road from now on.\"","then":"She stiffens. \"So it's still on me.\""},{"text":"\"It won't happen twice. Try not to worry about it.\"","then":"She nods, but her hands are shaking."},{"text":"\"Want to plan safer ways home together? 112's there for danger.\"","then":"She nods. \"Maybe share an auto with Rekha.\"","best":true}],"why":"Planning together, on her terms, supports her safety without blaming her choices."}],"relearn":"Where or when someone was never excuses harm; only the one crossing the line."},
  {"id":"cr-1186","cat":"after-harm-support","type":"role-play","persona":"any","source":"welcome the disclosure","hook":"After kabaddi practice, your teammate Kritika tells you she was assaulted last month.","setup":"She keeps wiping her eyes.","steps":[{"prompt":"Kritika says: \"Sorry. I'm dumping all of this on you.\"","options":[{"text":"\"Don't worry. It's honestly not a big deal.\"","then":"She blinks. \"It feels like a big deal to me.\""},{"text":"\"You don't owe me an apology. I'm glad you told me.\"","then":"She lets out a shaky laugh. \"Okay. I wasn't sure.\"","best":true},{"text":"\"Honestly, it is quite a lot to take in all at once. But go on.\"","then":"She nods, and cuts her story in half."},{"text":"\"It's fine. Just maybe keep it short.\"","then":"Kritika stops mid-sentence. \"Right. Sorry. That's all.\""}],"why":"Welcoming her story tells her she's not a burden, so she can keep talking."},{"prompt":"Kritika says: \"I haven't told anyone else. I didn't want to be a bother.\"","options":[{"text":"\"Maybe keep it that way. People do gossip.\"","then":"She nods, and the secret feels heavier."},{"text":"\"You're never a bother. And none of it is your fault.\"","then":"She nods, eyes wet. \"I needed to hear that.\"","best":true},{"text":"\"Why didn't you tell anyone sooner, though?\"","then":"Kritika looks down. \"I don't know. I just couldn't.\""},{"text":"\"You should tell more people. Share the load around a bit.\"","then":"She tenses. \"I'm not ready for more people.\""}],"why":"It's never her fault. Saying so, without pushing her to tell more people, lets her set the pace."},{"prompt":"Kritika asks: \"Can I message you if it gets bad at night?\"","options":[{"text":"\"Yes. And 181 is there any hour, if I'm asleep.\"","then":"She smiles a little. \"Both. Okay.\"","best":true},{"text":"\"Only if it's really bad, okay?\"","then":"She nods, and wonders how bad counts as really bad."},{"text":"\"Of course. Any time at all. I'll always answer.\"","then":"She's grateful. You both know you can't always answer."},{"text":"\"Maybe try to sleep it off instead, yeah?\"","then":"Her smile fades. \"Sure. Okay.\""}],"why":"A warm yes, plus help that's always there, means she's never alone with it."}],"relearn":"Reassure a survivor that telling you is welcome, never a burden."},
  {"id":"cr-1187","cat":"after-harm-support","type":"branch","persona":"any","source":"believe / pace","hook":"On a late walk back, Ishita tells you a guy from her class assaulted her, then goes silent.","steps":[{"prompt":"She's watching your face closely. What do you do?","options":[{"text":"Hug her tightly without saying anything","then":"She goes stiff, then relaxes a little. She still doesn't know what you think."},{"text":"Ask what exactly he did, step by step, so you understand","then":"She answers two questions, then stops. \"Can we not do this?\""},{"text":"Say you believe her and it's not her fault, then wait","then":"Ishita exhales. After a moment she keeps talking, slowly.","best":true},{"text":"Say you're shocked, since he always seems so nice","then":"Her face closes. \"Forget it. I knew it sounded unbelievable.\""}],"why":"Belief and \"not your fault\" come first, out loud. Then quiet lets her set the pace."},{"prompt":"Ishita says she doesn't want to go into the details. What do you do?","options":[{"text":"Tell her it's better to get it all out now, while it's fresh","then":"She goes quiet. \"Maybe I shouldn't have said anything.\""},{"text":"Say that's fine, and ask what would help tonight","then":"She thinks. \"Can you walk me to my room and stay a bit?\"","best":true},{"text":"Say okay, and change the subject to cheer her up","then":"She laughs weakly at your story and doesn't bring it up again."},{"text":"Gently ask just one question about what happened","then":"She shakes her head and pulls her jacket tighter."}],"why":"She never owes you details. Asking what helps now respects her pace."},{"prompt":"A few days later, you see him in the canteen and your anger rises. What do you do?","options":[{"text":"Avoid him, and check in with Ishita. Mention a counsellor","then":"She texts back a thank-you. \"Maybe the counsellor. I'll think about it.\"","best":true},{"text":"Message Ishita that you saw him and how angry it made you","then":"Now she's worried about your reaction as well as her own."},{"text":"Tell your friends why they should stay away from him","then":"Word spreads by evening. Ishita hears her own story from someone else."},{"text":"Glare at him until he notices","then":"He asks loudly what your problem is. People start looking."}],"why":"Her story stays hers. A quiet check-in, with help on offer, supports her without adding strain."}],"debrief":"Belief first, then follow her lead; never interrogate.","relearn":"Believe first and let the survivor set the pace."},
  {"id":"cr-1188","cat":"after-harm-support","type":"branch","persona":"any","source":"respect their choices","hook":"Your flatmate Riya was assaulted by a man she met on a dating app. She doesn't want to report it.","steps":[{"prompt":"Riya asks whether you think she's wrong not to report. What do you say?","options":[{"text":"Say she has a duty to report him, for other women's sake","then":"Her eyes fill. Now it feels like she's failing strangers too."},{"text":"Say it's her choice and you'll back her either way","then":"Riya nods slowly. \"Okay. I needed to hear that.\"","best":true},{"text":"Say you don't want to influence her, and change the topic","then":"She's left alone with the question she asked you for help with."},{"text":"Say it's her choice, but you'd report if it were you","then":"She goes quiet, wondering if you secretly think she's weak."}],"why":"None of it is her fault. Backing her choice, with no \"but\", gives back the control taken from her."},{"prompt":"Riya's cousin, whom she also told, insists she go to the police tonight. What do you do?","options":[{"text":"Tell the cousin to back off, speaking for Riya","then":"The cousin is hurt, and Riya has to calm you both down."},{"text":"Stay out of it, since it's between family","then":"Riya faces the argument alone that evening."},{"text":"Side with the cousin, since two voices might convince her","then":"Riya feels cornered and stops replying to both of you."},{"text":"Ask Riya privately what she wants, and back that","then":"Riya says she needs time. You help her say that to her cousin.","best":true}],"why":"Asking her, not deciding for her, keeps the choice hers even under family pressure."},{"prompt":"A month later, Riya says she's still unsure and hates feeling stuck. What do you say?","options":[{"text":"Say she's fine as she is and doesn't need anyone else's help","then":"She feels reassured, and still stuck, with no one to think it through with."},{"text":"Say there's no rush, and a counsellor could help her think","then":"She considers it. \"Maybe just to talk. Not to decide.\"","best":true},{"text":"Say she's had enough time and should decide now","then":"Riya flinches. The deadline feels like one more pressure."},{"text":"Say it will count for less the longer she waits","then":"Riya's stomach turns. She wonders if she's already too late."}],"why":"Taking time is okay and never her fault. A counsellor can help her think at her own pace."}],"debrief":"Whether and when to report is the survivor's call; support either way.","relearn":"Reporting is the survivor's choice; never force or override it."},
  {"id":"cr-1189","cat":"after-harm-support","type":"branch","persona":"Rohan","source":"even-handed","hook":"Late at night in the hostel, your friend Kunal says a senior guy assaulted him last week.","steps":[{"prompt":"He adds, \"Go on, laugh,\" and won't look at you. What do you do?","options":[{"text":"Say it's awful, and ask if that senior has done this to others","then":"Kunal shrugs. \"How would I know?\" He's still waiting to hear you believe him."},{"text":"Say you're not laughing. You believe him, and it's not on him","then":"Kunal looks up. \"Seriously? I thought you'd make it a joke.\"","best":true},{"text":"Ask why he didn't just fight back, being a big guy","then":"Kunal's jaw sets. \"You think I didn't want to?\""},{"text":"Say, \"Bro, you serious?\" to lighten the mood","then":"He forces a laugh, then stops. \"I'm serious, man. That's the problem.\""}],"why":"Men are harmed too. Plain belief tells him he's safe with you."},{"prompt":"Kunal says the worst part is feeling like less of a man. What do you say?","options":[{"text":"Say it says nothing about his manhood. It's on the senior","then":"He's quiet a long moment. \"I needed someone to say that.\"","best":true},{"text":"Change the subject to cricket, to take his mind off it all","then":"He plays along. What he just said hangs there, unanswered."},{"text":"Say you understand exactly how he feels","then":"He knows you don't. He nods, but pulls back a little."},{"text":"Tell him to toughen up and not let it get to him","then":"He goes stiff. \"That's what I keep telling myself. It isn't working.\""}],"why":"Being harmed says nothing about who he is. Only the senior is responsible."},{"prompt":"Later that night, Kunal asks if anyone else could help, but he's scared of being mocked. What do you say?","options":[{"text":"Tell him to go to the warden tomorrow, first thing","then":"He tenses. \"The warden knows that senior. I'm not ready.\""},{"text":"Say he can just talk to you, so he won't need anyone else","then":"He's grateful. You both know you're out of your depth."},{"text":"Mention the campus counsellor, and that it's for men too","then":"He writes down the counsellor's hours. \"No one else has to know?\"","best":true},{"text":"Say it's better to tell no one, for his reputation","then":"He agrees. The weight goes back to being his alone."}],"why":"Help like a counsellor is for anyone who's been harmed. Mentioning it gently leaves the choice with him."},{"prompt":"A week later, the group jokes that guys can't be assaulted, with Kunal right there. What do you do?","options":[{"text":"Tell them to grow up, and walk out of the room","then":"The group mocks your exit. Kunal is left sitting with them."},{"text":"Say, \"Careful. It happens to people we know\"","then":"Heads turn. Kunal goes red, wondering if you meant him."},{"text":"Say plainly that anyone can be, and move on","then":"The laughter stops. Kunal catches your eye for a second.","best":true},{"text":"Laugh along so Kunal isn't singled out","then":"Kunal laughs too, a beat late, then leaves early."}],"why":"Naming the myth plainly protects him without pointing at him."}],"debrief":"Male and LGBTQ+ survivors are often most silenced; believe them fully.","relearn":"Anyone can be harmed; believe male survivors equally."},
  {"id":"cr-1190","cat":"after-harm-support","type":"branch","persona":"Mehta","source":"accompany / ICC","hook":"Pooja, who was assaulted by a senior last term, has decided to go to the campus committee.","steps":[{"prompt":"She asks you to come with her tomorrow. What do you say?","options":[{"text":"Say it's better to go alone, so it looks more serious","then":"Pooja looks scared. \"Please. I can't walk in there alone.\" You agree to go."},{"text":"Say yes, and ask what she'd like you to do there","then":"\"Just sit next to me,\" she says. \"Maybe hold my water.\"","best":true},{"text":"Say yes, and offer to do the talking so it's easier on her","then":"She hesitates. \"I think I need to say it myself.\""},{"text":"Say you're not sure it's worth all the stress","then":"She goes quiet. \"I'm going anyway. Will you come?\" You say yes."}],"why":"What happened was never her fault. Going as support, and asking what she wants, lets her lead."},{"prompt":"That night, Pooja asks you to help her prepare what to say. What do you do?","options":[{"text":"Help her list her own points, in her words","then":"She reads it back. \"It sounds like me. That helps.\"","best":true},{"text":"Say she should just wing it, so it sounds natural","then":"She lies awake, rehearsing alone."},{"text":"Tell her to leave out anything that makes her look bad","then":"She starts cutting details, doubting herself as she goes."},{"text":"Write a strong statement for her to read out","then":"It's clear, but she stumbles over words that aren't hers."}],"why":"Her own words, organised with your help, keep the complaint hers."},{"prompt":"At the meeting, a member asks Pooja why she took months to come. What do you do?","options":[{"text":"Answer for her, since delay is so normal after trauma","then":"The member nods. Pooja looks down, feeling spoken over."},{"text":"Let her answer, and stay ready if she turns to you","then":"Pooja takes a breath. \"I needed time to feel safe,\" she says steadily.","best":true},{"text":"Tell the committee that the question is unfair","then":"The room tenses. Pooja now has to smooth things over."},{"text":"Whisper to Pooja to keep her answer short","then":"She cuts her answer off halfway and looks unsure."}],"why":"Delay is normal and never her fault. Letting her answer keeps the complaint in her hands."},{"prompt":"Afterwards, Pooja says she's exhausted and unsure it went well. What do you say?","options":[{"text":"Say she did something hard, and ask what she needs now","then":"\"Food. And not talking about it,\" she says, with a tired laugh.","best":true},{"text":"Say it definitely went well, so she shouldn't worry at all","then":"She wants to believe you, but you can't know that."},{"text":"Go over what she could have said better","then":"Her shoulders sink with every point you make."},{"text":"Say she should post about it now so others know","then":"Pooja stiffens. \"I'm not ready for everyone to know.\""}],"why":"Honest encouragement, and asking what she needs, look after her without false promises."}],"debrief":"You can accompany a survivor to the campus committee while she leads.","relearn":"Support a survivor's process; let her lead, don't take over."},
  {"id":"cr-1191","cat":"after-harm-support","type":"branch","persona":"any","source":"no blame / drinks","hook":"Sana tells you a guy assaulted her at a party, then says she'd been drinking, so maybe she's wrong.","steps":[{"prompt":"She's searching your face for a reaction. What do you say?","options":[{"text":"Say let's not worry about who's to blame right now","then":"She nods, but the question of blame keeps circling in her."},{"text":"Say drinking never makes it okay. Only he's responsible","then":"Sana blinks. \"Even though I was drunk?\" she asks, quieter.","best":true},{"text":"Ask how many drinks she'd had, exactly","then":"Sana starts counting drinks out loud, as if she's on trial."},{"text":"Say she should drink less from now on, so it doesn't happen again","then":"Sana nods and looks at the floor. The blame settles on her."}],"why":"Drinking never causes assault. The fault is only with the one who ignored consent."},{"prompt":"Sana says she barely remembers parts of the night and feels ashamed. What do you say?","options":[{"text":"Say she doesn't need to remember it all to be believed","then":"Her eyes fill. \"I thought I had to be sure of every detail.\"","best":true},{"text":"Say that's why she shouldn't drink that much","then":"Sana shrinks. \"So it is my fault.\""},{"text":"Suggest she ask others from the party to fill in the gaps","then":"The thought of others knowing makes her panic."},{"text":"Say it's probably better that she doesn't remember","then":"She looks unsettled. Not remembering feels worse, not better."}],"why":"Gaps in memory don't make it less real. Being drunk meant she couldn't consent, never that she's to blame."},{"prompt":"Later, Sana wonders if she should talk to someone who knows about this. What do you do?","options":[{"text":"Say only people who remember it clearly should report","then":"She drops the idea, sure her memory rules her out."},{"text":"Book her a counsellor slot without asking her first","then":"She finds the booking in her inbox and feels managed, not helped."},{"text":"Say it's better to just move on quietly","then":"Sana nods. The shame stays with her, unspoken."},{"text":"Mention a counsellor or 181, and offer to be there","then":"She saves the number. \"Maybe this week. With you nearby.\"","best":true}],"why":"Offering real routes, with you beside her, gives her support at her own pace."}],"debrief":"Drinking is never the cause; only the one ignoring consent is at fault.","relearn":"Drinking never excuses harm; the survivor is never to blame."},
  {"id":"cr-1192","cat":"after-harm-support","type":"branch","persona":"any","source":"privacy","hook":"Meher tells you that a man at her coaching centre assaulted her.","steps":[{"prompt":"She begs you not to tell anyone else. What do you say?","options":[{"text":"Promise, but say you might ask your mum for advice","then":"Meher tenses. \"Your mum knows my mum.\""},{"text":"Promise it stays with you unless she says otherwise","then":"Meher lets out a breath. \"Thank you. I needed that.\"","best":true},{"text":"Say two close friends could help her more than you alone","then":"She shakes her head fast. \"No. Please. Just you.\""},{"text":"Say she should tell everyone so he can't do it again","then":"Meher goes pale. That's the last thing she can face right now."}],"why":"Her story is hers, and none of it is her fault. Keeping it private protects her trust."},{"prompt":"A week later, your friend Tara asks why Meher skipped coaching all week. What do you say?","options":[{"text":"Say only Meher can answer that, and Tara could check on her","then":"Tara shrugs. \"Fair. I'll message her.\"","best":true},{"text":"Hint that something happened, without giving names","then":"Tara's curiosity sparks. By evening she's guessing out loud."},{"text":"Make up a story about Meher being ill","then":"The story spreads, and Meher has to keep up a lie she didn't choose."},{"text":"Tell Tara, since she's trustworthy and really cares about Meher","then":"Tara means well, but Meher can tell from her face that she knows."}],"why":"Keeping it private, without lies or hints, protects Meher's story and her trust."},{"prompt":"Meher says she's thinking of telling a counsellor, but worries it'll spread. What do you do?","options":[{"text":"Say it'll come out eventually, so she shouldn't worry","then":"Meher's worry turns to dread."},{"text":"Say it's safer to keep it only between you two","then":"She agrees, and carries it with only you to lean on."},{"text":"Say she can ask how privacy works before she shares","then":"She nods. \"I'll ask how it works before I say anything.\"","best":true},{"text":"Offer to tell the counsellor for her, to save her the stress","then":"Meher hesitates. It's her story, and you'd be the one telling it."}],"why":"A counsellor is a private place to talk. Asking about privacy first keeps her in control."}],"debrief":"A survivor's story is theirs; keep it private unless they choose to share.","relearn":"Keep a disclosure private; sharing it is the survivor's choice."},
  {"id":"cr-1193","cat":"after-harm-support","type":"branch","persona":"Mehta","source":"signpost help","hook":"Early morning, Nisha calls. She says she was assaulted last night and asks what she should do.","steps":[{"prompt":"Her voice is shaking. What do you say first?","options":[{"text":"Ask if she's safe right now, and what she needs","then":"\"I'm home. I'm safe. I just don't want to be alone,\" she says.","best":true},{"text":"Ask whether she'd been drinking last night","then":"\"Why does that matter?\" she asks, and her voice closes up."},{"text":"Say you're coming over, and hang up to get ready","then":"You're on your way, but she's alone with no answer to her question."},{"text":"Start listing everything she needs to do today","then":"Nisha goes quiet under the list. \"I can't even think.\""}],"why":"Checking she's safe and asking what she needs puts her first, before any plan."},{"prompt":"Nisha asks if you think she should see a doctor. What do you say?","options":[{"text":"Say it's probably not needed if she feels okay","then":"She hesitates, unsure, and puts it off."},{"text":"Say you're not really the right person to ask","then":"Nisha falls quiet. She called you because she didn't know who else to ask."},{"text":"Say it could help, and you'll go with her if she wants","then":"\"Could you? I don't want to go alone.\"","best":true},{"text":"Say yes, and tell her she must go to a doctor right now","then":"She agrees, but her voice sounds far away, like she's following orders."}],"why":"Some care works best when started soon. Offering company makes it easier, and the choice stays hers."},{"prompt":"Later, Nisha asks whether she has to go to the police. What do you say?","options":[{"text":"Say it's her choice, and she doesn't have to decide today","then":"She breathes out. \"Okay. One thing at a time.\"","best":true},{"text":"Say the police won't do anything anyway","then":"She drops the idea, sure now that no one will help."},{"text":"Say yes, and the sooner the better","then":"Nisha's chest tightens. Another must, on a morning full of them."},{"text":"Say her parents should be the ones to decide something like that","then":"She pictures telling her parents and feels sick."}],"why":"Reporting is her choice, on her timeline. None of this is her fault, and nothing must be decided today."},{"prompt":"That evening, she says she wants someone to talk to besides you. What do you say?","options":[{"text":"Mention 181, a counsellor or the ICC, and let her pick","then":"She picks the counsellor. \"Talking first. The rest later.\"","best":true},{"text":"Say she doesn't need anyone else, since she has you","then":"She thanks you, but she still has questions you can't answer."},{"text":"Suggest she post in an online forum for advice","then":"The replies are a mix of kindness and strangers' opinions."},{"text":"Give her the ICC contact, since a complaint comes first","then":"She frowns. \"I just want to talk. Not complain yet.\""}],"why":"Knowing the real routes lets her choose the help that fits what she needs now."}],"debrief":"Ask what she needs first, then signpost 181, a counsellor or the ICC when ready.","relearn":"Ask what they need, then signpost real help when they're ready."},
  {"id":"cr-1194","cat":"after-harm-support","type":"branch","persona":"Meena","source":"offline routes","hook":"Your neighbour Laxmi works at a garment unit. She tells you a relative assaulted her.","steps":[{"prompt":"She says there's no warden or college office for people like her. What do you tell her?","options":[{"text":"Say those services are really only meant for college students","then":"She nods, resigned. \"I thought so. People like me just manage.\""},{"text":"Say she should tell the family elders first","then":"Laxmi looks frightened. The relative is close to those elders."},{"text":"Tell her to stay away from him and keep it quiet","then":"She agrees. The fear stays, and so does he."},{"text":"Say 181 is confidential and she can call from any phone","then":"Laxmi looks surprised. \"Even from my small phone? Anytime?\"","best":true}],"why":"None of it is her fault, and 181 is for everyone, confidential, from any phone."},{"prompt":"Days later, a coworker tells Laxmi about 181. She worries the relative will find out if she calls. What do you say?","options":[{"text":"Promise that nothing bad can come of calling","then":"She relaxes, trusting a promise you can't really keep."},{"text":"Say maybe she should wait until things calm down","then":"She waits. The relative still visits every Sunday."},{"text":"Offer to go and confront the relative yourself, so she doesn't have to","then":"Laxmi panics. \"He'll know I told. Please don't.\""},{"text":"Say it's confidential, and offer your phone and a quiet room","then":"\"Your phone?\" she says. \"Then it won't show on mine.\"","best":true}],"why":"A private phone and a quiet space make a confidential call safer for her."},{"prompt":"One night she texts that the relative is at her door and she's scared. What do you do?","options":[{"text":"Rush over to her house on your own","then":"You arrive to a locked gate and raised voices. You can't get in."},{"text":"Tell her to call 112 now, and stay on text with her","then":"She calls 112 and keeps texting you until help arrives.","best":true},{"text":"Tell her to lock her door and wait till morning","then":"She locks it. The night is long, and she's alone with the fear."},{"text":"Say it's family, so it will probably settle down by itself","then":"She stops replying. You don't know if she's okay."}],"why":"Immediate danger means 112, right away. Staying on text means she's not alone."}],"debrief":"Help like 181 and 112 reaches the non-college majority too, offline and free.","relearn":"Confidential help (181, 112) exists for everyone, no campus required."},
  {"id":"cr-1195","cat":"after-harm-support","type":"branch","persona":"any","source":"don't take over","hook":"Your close friend Divya tells you her ex assaulted her. You know exactly where he lives.","steps":[{"prompt":"Your hands are shaking with anger. What do you do?","options":[{"text":"Grab your keys to go and confront him","then":"Divya grabs your arm. \"Please. He'll know I told you.\""},{"text":"Tell her how furious you are and what you'd like to do to him","then":"She ends up calming you down, instead of the other way round."},{"text":"Take a breath, and ask Divya what she needs","then":"Divya looks relieved. \"I just need you here. Not a fight.\"","best":true},{"text":"Ask how she never saw this side of him before","then":"Divya flinches. \"You think I should have known?\""}],"why":"Your anger is valid, but it's never her fault and not your fight. Asking what she needs keeps her central."},{"prompt":"Divya says she's afraid he'll find out she told anyone. What do you say?","options":[{"text":"Say he deserves to find out, and to be scared himself","then":"Her fear doubles. Now she's afraid of what you might do."},{"text":"Say your brother could have a quiet word with him, to scare him off","then":"Divya shakes her head. \"That's exactly what I don't want.\""},{"text":"Tell her she's overthinking it, since he won't find out","then":"She wants to believe you, but you can't know that."},{"text":"Say it stays private unless she's in danger, and ask what helps","then":"She thinks. \"Maybe blocking him everywhere. Can you help?\"","best":true}],"why":"Her safety plan should come from her fears, not from your anger."},{"prompt":"A week later, you run into her ex at a friend's party. What do you do?","options":[{"text":"Quietly tell the host what he did so he's asked to leave","then":"The host is shocked, and now Divya's story is out."},{"text":"Keep your distance, and leave if you need to","then":"You step out for air. The anger passes without a scene.","best":true},{"text":"Tell him loudly that you know what he did","then":"The room goes silent. By morning, he's messaging Divya."},{"text":"Stay friendly with him so he doesn't suspect anything","then":"You fake smiles all evening and feel sick about it."}],"why":"Keeping away from him protects Divya's privacy and safety. Her story isn't yours to tell."},{"prompt":"Divya says she's thinking about reporting him, but isn't sure. What do you do?","options":[{"text":"Offer to go and report it yourself, if she's too scared to do it","then":"Divya stiffens. \"Without me? No. It's mine to decide.\""},{"text":"Urge her to report him, so he finally pays for it","then":"She feels your anger pushing her, not her own choice."},{"text":"Say reporting will only drag it out for her","then":"She drops the idea for now, unsure whose choice that was."},{"text":"Say you'll back her either way, and mention 181 or a counsellor","then":"She nods. \"Let me think. It helps to know the options.\"","best":true}],"why":"It's her choice. Naming options like 181 or a counsellor supports it without pushing."}],"debrief":"Your anger is valid, but the survivor decides what happens, not you.","relearn":"Let the survivor lead; don't let your anger override her choices."},
  {"id":"cr-1196","cat":"after-harm-support","type":"branch","persona":"any","source":"holding space","hook":"Weeks after an assault, your friend Alisha breaks down in your room.","steps":[{"prompt":"She says she'll never feel normal again. What do you do?","options":[{"text":"Suggest going out somewhere, to take her mind off it for a bit","then":"She agrees to a walk, but she's somewhere else the whole time."},{"text":"Say, \"Of course you will. You're so strong\"","then":"She shakes her head. \"I don't feel strong.\" Now she has to be."},{"text":"List the ways she'll start feeling better soon","then":"She nods through tears. Being told how to heal feels like one more test."},{"text":"Sit with her, and say it makes sense to feel this way","then":"Alisha cries harder for a while, then slowly quietens beside you.","best":true}],"why":"Being present and validating her feelings helps more than rushing her to feel better."},{"prompt":"Once she's calmer, Alisha asks if she's broken for not being over it yet. What do you say?","options":[{"text":"Say no. Healing takes its own time, and it's not her fault","then":"She wipes her eyes. \"So it's not just me being weak.\"","best":true},{"text":"Say you felt the same for months after your breakup","then":"She nods politely, but it doesn't feel like the same thing."},{"text":"Say she should focus on the good things in her life","then":"She agrees, and feels guilty for not managing it."},{"text":"Say it's been quite a while now, so maybe she's dwelling on it","then":"She withdraws. \"Right. I should be over it by now.\""}],"why":"There's no deadline for healing. It isn't weakness, and it's never her fault."},{"prompt":"Later, as she gets up to go, she says some nights are really hard. What do you do?","options":[{"text":"Tell her she should really be in therapy by now","then":"Alisha tenses at the \"should\" and drops the subject."},{"text":"Tell her to call you any time at all, and you'll always pick up","then":"She thanks you. Later, she hesitates to wake you at 3am."},{"text":"Say it'll get easier soon, so she should hang in there","then":"She smiles thinly. Tonight still has to be got through."},{"text":"Say you're a call away, and 181 or a counsellor can help too","then":"She saves the numbers. \"Just knowing helps,\" she says.","best":true}],"why":"Being there, plus support she can reach any hour, means she's never without help."}],"debrief":"Be present and validating; mention help gently, never minimise her pain.","relearn":"Sit with a survivor's pain; offer support without rushing healing."},
  {"id":"cr-1197","cat":"after-harm-support","type":"branch","persona":"Mehta","source":"validate / ICC","hook":"Five months after a senior assaulted her, Zara wants to go to the campus committee.","steps":[{"prompt":"She's scared no one will believe her after so long. What do you say?","options":[{"text":"Say you believe her, and that a delay like hers is common","then":"Zara breathes out. \"I thought I'd missed my chance.\"","best":true},{"text":"Ask why she didn't go to them straight away","then":"Zara stiffens. \"Everyone's going to ask that, aren't they?\""},{"text":"Promise her the committee will definitely believe every word","then":"She smiles weakly. \"You can't know that, though.\""},{"text":"Agree it's probably too late to bother now","then":"Zara's face falls. She puts her phone away."}],"why":"Belief comes first. What happened, and the delay, are never her fault. She can explain it to the committee."},{"prompt":"Zara asks how she'd even explain the delay to them. What do you say?","options":[{"text":"Offer to explain the delay for her, so she doesn't have to","then":"She considers it, then says it should come from her."},{"text":"Say she should skip it and hope nobody asks","then":"She worries the question will catch her off guard in the room."},{"text":"Say she can tell it simply, since many people need time","then":"She nods slowly. \"I needed time to feel safe. That's true.\"","best":true},{"text":"Help her come up with a stronger-sounding reason","then":"Zara hesitates. \"Wouldn't the truth be enough?\""}],"why":"The honest reason is the right one to give. Needing time is normal and nothing to hide."},{"prompt":"The night before, Zara says she wants to back out. What do you do?","options":[{"text":"Tell her she can't back out after coming this far","then":"She goes through with it, feeling cornered the whole way."},{"text":"Say backing out is wise, since it's such a hassle","then":"Zara feels relief, then doubt. Was that her choice or yours?"},{"text":"Say she'll regret it for years if she doesn't go through with it","then":"The fear of regret drowns out what she actually wants."},{"text":"Say it's her choice whether to go, and you'll back either one","then":"She's quiet, then says, \"I'll sleep on it. Thanks for not pushing.\"","best":true}],"why":"Supporting her timeline means backing her whatever she decides, even the night before."}],"debrief":"Delayed reporting is common and valid; she can explain the delay, and the committee can still consider it.","relearn":"Delay doesn't invalidate a complaint; support reporting on her timeline."},
  {"id":"cr-1198","cat":"after-harm-support","type":"branch","persona":"any","source":"anonymous disclosure","hook":"You volunteer on your college's anonymous support chat. Someone writes that she was assaulted.","steps":[{"prompt":"She won't share her name and seems ready to log off. What do you say?","options":[{"text":"Say anonymous reports usually aren't taken seriously","then":"She types \"ok\" and goes silent for a long time."},{"text":"Ask which hostel she's in, just so you can help","then":"She hesitates. \"Why do you need that?\" Her replies slow down."},{"text":"Say she's believed here, and her name is her choice","then":"A pause. Then: \"Okay. I'll stay a bit.\"","best":true},{"text":"Urge her to tell you everything now, before she logs off","then":"She types a few lines, then stops. \"This is too fast.\""}],"why":"Belief doesn't need a name, and it's never her fault. Staying anonymous keeps her safe enough to talk."},{"prompt":"She asks what happens to what she tells you. What do you say?","options":[{"text":"Promise that no one will ever see any of it, whatever happens","then":"She relaxes, trusting a promise you may not be able to keep."},{"text":"Explain honestly who sees the chat, and that she decides","then":"She reads it twice. \"Okay. That feels safer.\"","best":true},{"text":"Say she doesn't need to worry about that part","then":"She asks again, more worried. Vague answers don't feel safe."},{"text":"Say it depends, then ask her to tell you what happened","then":"Her typing stops. Minutes pass before she replies."}],"why":"Honest, clear answers about privacy let her decide what she's comfortable sharing."},{"prompt":"She says she wants real help, but not face to face yet. What do you do?","options":[{"text":"Share 181, which is confidential and over the phone","then":"She notes it down. \"A phone call I can manage.\"","best":true},{"text":"Tell her the only real way is a formal complaint","then":"She goes quiet. That's the one thing she can't face yet."},{"text":"Say she can keep talking here, so she won't need more","then":"She's grateful. But you aren't trained for what she's asking."},{"text":"Suggest the counsellor, and offer to book a slot for her","then":"She hesitates. \"That means someone seeing my face.\""}],"why":"181 is confidential and by phone, so she can get real help her own way."}],"debrief":"Anonymous disclosures deserve belief; let her control how much she reveals.","relearn":"Believe and support a survivor even when they stay anonymous."},
  {"id":"cr-1199","cat":"after-harm-support","type":"branch","persona":"any","source":"believe / stranger","hook":"Shreya, from your elective, tells you on the bus that she was assaulted. You barely know her.","steps":[{"prompt":"She says she told you because you seemed safe. What do you do?","options":[{"text":"Say she should tell a close friend instead of you","then":"She looks lost. \"I don't really have one here.\""},{"text":"Thank her for trusting you, and say you believe her","then":"Shreya nods, eyes wet. \"I didn't know who else to tell.\"","best":true},{"text":"Ask whether she's sure it really counts as assault","then":"Her face tightens. She goes quiet and stares out of the window."},{"text":"Say it's not really your business, since you're not close","then":"She pulls back. \"Sorry. Forget I said anything.\""}],"why":"Belief and thanks honour her trust. It's never her fault, whoever she chose to tell."},{"prompt":"At her stop, Shreya hesitates before getting off. What do you do?","options":[{"text":"Say bye, and hope she'll be okay","then":"She steps off. You wonder all evening how she is."},{"text":"Insist on walking her all the way home","then":"She says no, politely. She doesn't know you that well."},{"text":"Tell her she should report it tomorrow, first thing in the morning","then":"She nods, but she looks more overwhelmed than before."},{"text":"Ask what she needs, and offer your number if she wants it","then":"She takes your number. \"Maybe just to text sometimes.\"","best":true}],"why":"Asking what she needs, and offering a way to reach you, leaves her in charge."},{"prompt":"A few days later, Shreya finds you after class to ask where people go for help. What do you do?","options":[{"text":"Share 181, the counsellor and the ICC, and let her choose","then":"She nods. \"The counsellor first. Thank you for this.\"","best":true},{"text":"Say you're not really the right person to ask about this stuff","then":"She says okay and doesn't bring it up again."},{"text":"Tell her to talk to her parents about it first","then":"She goes quiet. Her parents are the last people she'd tell."},{"text":"Send her a long article you found online","then":"She skims it. It's general, and doesn't say where to go."}],"why":"Real routes, shared simply, let her pick the help that fits."}],"debrief":"Even a near-stranger's disclosure deserves belief and a 'what do you need?'","relearn":"Believe and support a survivor, close friend or not."},
  {"id":"cr-1200","cat":"after-harm-support","type":"branch","persona":"any","source":"emergency / 112","hook":"Late at night, your friend Tanya calls in a whisper. The man who assaulted her is outside her door.","steps":[{"prompt":"She says he's banging on the door. What do you do?","options":[{"text":"Tell her to call 112 now, and stay on text with her","then":"She calls. Then her texts come: \"They're coming. Stay with me.\"","best":true},{"text":"Tell her to wait till morning, since he'll give up and go","then":"The banging goes on. She stays by the door, alone and terrified."},{"text":"Call her parents in another city to handle it","then":"They panic and ring her again and again. No help reaches her door."},{"text":"Rush over there yourself to deal with him","then":"You're twenty minutes away. She's alone with him outside until then."}],"why":"Immediate danger means 112 right away. Staying in touch means she isn't alone."},{"prompt":"Minutes later, she texts that he's still outside. What do you tell her?","options":[{"text":"Shout through the door that the police are already on their way","then":"He swears loudly, and the banging gets harder."},{"text":"Stay quiet, so she doesn't bother the neighbours","then":"She stays silent and afraid, and no one next door knows."},{"text":"Film him through the peephole, for proof","then":"She leans close to the door to film. Her hands shake."},{"text":"Stay back from the door, and call 112 if she hasn't yet","then":"She moves to the bathroom and locks it. \"Okay. Done.\"","best":true}],"why":"Distance from the door, and emergency help, keep her safest until help arrives."},{"prompt":"An hour later, he's gone, but Tanya says she can't sleep there tonight. What do you do?","options":[{"text":"Offer her your place, or help her get to someone she trusts","then":"She packs a bag. \"Can I stay at yours?\"","best":true},{"text":"Say he's gone now, so she'll be fine","then":"She stays, and jumps at every sound all night."},{"text":"Tell her to push a heavy chair against the door and just stay put","then":"She tries. She doesn't sleep at all."},{"text":"Say you'll come by first thing in the morning","then":"She's on her own for the night, listening for footsteps."}],"why":"Asking where she'd feel safe, and offering a place, helps her get through the night."},{"prompt":"Next day, Tanya wonders if she's overreacting by thinking about reporting. What do you say?","options":[{"text":"Ask what she did to make him so angry","then":"Tanya goes silent. \"Nothing. I did nothing.\""},{"text":"Say she's not overreacting, and 181 can talk through options","then":"She saves the number. \"Maybe this afternoon.\"","best":true},{"text":"Tell her she must report it today, no question","then":"She feels the pressure pile on top of the fear."},{"text":"Say maybe it's best to let it all go, now that he's finally left","then":"She nods. She checks the lock every hour."}],"why":"She isn't overreacting, and it's never her fault. 181 can help her weigh options at her own pace."}],"debrief":"Immediate danger means 112 now; you can stay with her through the call.","relearn":"For immediate danger, reach 112 right away and stay present."},
  {"id":"cr-1201","cat":"after-harm-support","type":"strike-rewrite","hook":"\"If she really didn't want it, she'd have screamed or run.\"","myth":{"un":"If she really didn't want it, she'd have screamed or run.","re":"Freezing is a common, involuntary response; many people can't scream or move.","why":"The brain's freeze response isn't a choice."},"relearn":"Freezing is involuntary; not screaming or running is never consent.","persona":"any","source":"freeze response"},
  {"id":"cr-1202","cat":"after-harm-support","type":"strike-rewrite","hook":"\"He's a guy, so it couldn't really have hurt him.\"","myth":{"un":"He's a guy, so it couldn't really have hurt him.","re":"Anyone of any gender can be assaulted and harmed, and deserves belief.","why":"Harm isn't decided by the survivor's gender."},"relearn":"Men can be assaulted and harmed too; believe them equally.","persona":"Rohan","source":"even-handed"},
  {"id":"cr-1203","cat":"after-harm-support","type":"strike-rewrite","hook":"\"She took so long to tell anyone, she's probably exaggerating.\"","myth":{"un":"She took so long to tell anyone, she's probably exaggerating.","re":"Delaying disclosure is normal after trauma; it doesn't mean it didn't happen.","why":"Shame and fear routinely delay telling."},"relearn":"Delay in telling is a normal trauma response, not proof it's untrue.","persona":"any","source":"delayed disclosure"},
  {"id":"cr-1204","cat":"after-harm-support","type":"strike-rewrite","hook":"\"A good friend would drag her to the police, like it or not.\"","myth":{"un":"A good friend would drag her to the police, like it or not.","re":"A good friend supports the survivor's own choices, including whether to report.","why":"Forcing a report repeats the loss of control."},"relearn":"Support the survivor's choices; never force a report on them.","persona":"any","source":"autonomy"},
  {"id":"cr-1205","cat":"after-harm-support","type":"strike-rewrite","hook":"\"Look how she was dressed, what did she expect?\"","myth":{"un":"Look how she was dressed, what did she expect?","re":"Clothes never cause or excuse assault; only the one ignoring consent is at fault.","why":"Responsibility lies with the person, not the outfit."},"relearn":"Clothes never excuse harm; the fault is only the one ignoring consent.","persona":"any","source":"no blame / clothes"},
  {"id":"cr-1206","cat":"after-harm-support","type":"strike-rewrite","hook":"\"She'd been drinking, so really she brought it on herself.\"","myth":{"un":"She'd been drinking, so she brought it on herself.","re":"Drinking never causes assault; the fault is only the one ignoring consent.","why":"A drink is never a cause or an excuse."},"relearn":"Drinking never excuses harm; the survivor is never to blame.","persona":"any","source":"no blame / drinks"},
  {"id":"cr-1207","cat":"after-harm-support","type":"strike-rewrite","hook":"\"They were a couple, so it can't have been assault.\"","myth":{"un":"They were a couple, so it can't have been assault.","re":"A relationship never assumes consent; assault can happen between partners.","why":"Consent is freely given each time, even with a partner."},"relearn":"Being a couple never assumes consent; partners can be harmed too.","persona":"any","source":"relationship / consent"},
  {"id":"cr-1208","cat":"after-harm-support","type":"reflect","hook":"Lensy: a survivor's first need is to be believed, not questioned. Sit right with you?","prompt":"What do you think?","options":["Yes","Belief first","Always"],"affirm":"Belief is the gift only you can give in that first moment; it changes everything.","relearn":"A survivor's first need is belief, not interrogation.","persona":"any","source":"believe"},
  {"id":"cr-1209","cat":"after-harm-support","type":"reflect","hook":"Lensy: whether and when to report is the survivor's call, not yours. Feel true?","prompt":"What do you think?","options":["Yes","Their call","I'll respect it"],"affirm":"Leaving that choice with them returns the control harm tried to take away.","relearn":"Reporting is the survivor's choice; respect their timing.","persona":"any","source":"autonomy"},
  {"id":"cr-1210","cat":"after-harm-support","type":"reflect","hook":"Lensy: a man telling you he was assaulted deserves the same full belief. Land for you?","prompt":"What do you think?","options":["Yes","Of course","Same belief"],"affirm":"Equal belief is what lets the most-silenced survivors finally speak.","relearn":"Male and LGBTQ+ survivors deserve full, equal belief.","persona":"Rohan","source":"even-handed"},
  {"id":"cr-1211","cat":"after-harm-support","type":"reflect","hook":"Lensy: freezing instead of fighting is the body protecting itself, never a fault. Sit with you?","prompt":"What do you think?","options":["Yes","Makes sense","Never a fault"],"affirm":"Knowing this frees a survivor from blaming themselves for a reflex they didn't choose.","relearn":"Freezing is an involuntary protection response, never a fault.","persona":"any","source":"freeze response"},
  {"id":"cr-1212","cat":"after-harm-support","type":"reflect","hook":"Lensy: support can be just sitting with someone, no fixing required. Worth holding?","prompt":"What do you think?","options":["Yes","Just being there","Worth holding"],"affirm":"Presence without a fix-it plan is often exactly the support a survivor needs.","relearn":"Being present, without fixing, is real support.","persona":"any","source":"holding space"},
  {"id":"cr-1213","cat":"after-harm-support","type":"reflect","hook":"Lensy: nothing a survivor wore, drank or did ever caused the harm. Settle in you?","prompt":"What do you think?","options":["Yes","Only the one crossing","Settled"],"affirm":"That line never moves: the fault is only ever the one ignoring consent.","relearn":"Nothing a survivor did caused harm; only the one ignoring consent.","persona":"any","source":"no blame"},
  {"id":"cr-1214","cat":"after-harm-support","type":"reflect","hook":"Lensy: a disclosure someone trusts you with is theirs to share, not yours. Holds up?","prompt":"What do you think?","options":["Yes","It's theirs","I'll keep it"],"affirm":"Guarding their privacy keeps the trust that let them tell you at all.","relearn":"A disclosure is the survivor's to share; keep it private.","persona":"any","source":"privacy"},
  {"id":"cr-1215","cat":"after-harm-support","type":"sort","hook":"Sort each response: does it help a survivor, or harm?","items":[{"id":"a","text":"\"I believe you, this wasn't your fault\""},{"id":"b","text":"\"What were you wearing, though?\""},{"id":"c","text":"\"What do you need from me right now?\""},{"id":"d","text":"\"You have to go to the police tonight\""},{"id":"e","text":"\"Take all the time you need\""},{"id":"f","text":"\"Are you sure you didn't lead him on?\""}],"bins":[{"id":"helps","label":"Helps a survivor","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Belief, patience and 'what do you need?' help; blame and pressure harm.","persona":"any","source":"support responses"},
  {"id":"cr-1216","cat":"after-harm-support","type":"sort","hook":"Sort: survivor-centred, or not?","items":[{"id":"a","text":"Letting them set the pace"},{"id":"b","text":"Picking their story apart for holes"},{"id":"c","text":"Keeping what they shared private"},{"id":"d","text":"Telling the group chat without asking"},{"id":"e","text":"Asking what they need"},{"id":"f","text":"Deciding for them that they must report"}],"bins":[{"id":"centred","label":"Survivor-centred","valence":"pos"},{"id":"not","label":"Not survivor-centred","valence":"neg"}],"key":{"a":"centred","b":"not","c":"centred","d":"not","e":"centred","f":"not"},"relearn":"Pace, privacy and asking what they need centre the survivor; the rest don't.","persona":"any","source":"survivor-centred"},
  {"id":"cr-1217","cat":"after-harm-support","type":"sort","hook":"Sort each line: does it return control to the survivor, or take it?","items":[{"id":"a","text":"\"What would help right now?\""},{"id":"b","text":"\"Here's exactly what you must do\""},{"id":"c","text":"\"It's your call whether to report\""},{"id":"d","text":"\"I've already told the warden for you\""},{"id":"e","text":"\"I'll follow your lead\""},{"id":"f","text":"\"Give me his name, I'll handle it\""}],"bins":[{"id":"returns","label":"Returns control","valence":"pos"},{"id":"takes","label":"Takes control","valence":"neg"}],"key":{"a":"returns","b":"takes","c":"returns","d":"takes","e":"returns","f":"takes"},"relearn":"Asking and following their lead returns control; deciding for them takes it.","persona":"any","source":"autonomy / control"},
  {"id":"cr-1218","cat":"after-harm-support","type":"sort","hook":"Sort: a real support route, or not a real route?","items":[{"id":"a","text":"181, Women Helpline"},{"id":"b","text":"Posting it on social media"},{"id":"c","text":"The campus committee, ICC"},{"id":"d","text":"A random WhatsApp group"},{"id":"e","text":"112 in immediate danger"},{"id":"f","text":"Bottling it up alone"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"notroute","label":"Not a real route","valence":"neg"}],"key":{"a":"real","b":"notroute","c":"real","d":"notroute","e":"real","f":"notroute"},"relearn":"181, the campus committee and 112 are real routes; posts and silence aren't.","persona":"Mehta","source":"real routes"},
  {"id":"cr-1219","cat":"after-harm-support","type":"sort","hook":"Sort each belief: true about trauma, or a myth?","items":[{"id":"a","text":"Freezing is a normal response"},{"id":"b","text":"No struggle means it wasn't real"},{"id":"c","text":"Delaying telling is common"},{"id":"d","text":"Men can't really be assaulted"},{"id":"e","text":"Memory can be patchy after trauma"},{"id":"f","text":"A real victim reports at once"}],"bins":[{"id":"true","label":"True about trauma","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Freezing, delay and patchy memory are normal; the rest are blaming myths.","persona":"any","source":"trauma facts"},
  {"id":"cr-1220","cat":"after-harm-support","type":"sort","hook":"Sort each first response: steady support, or a stumble?","items":[{"id":"a","text":"\"I'm so glad you told me\""},{"id":"b","text":"\"Why didn't you just leave?\""},{"id":"c","text":"\"Take your time, I'm here\""},{"id":"d","text":"\"Let's not make a big deal of it\""},{"id":"e","text":"\"None of this is your fault\""},{"id":"f","text":"\"Are you exaggerating a bit?\""}],"bins":[{"id":"steady","label":"Steady support","valence":"pos"},{"id":"stumble","label":"A stumble","valence":"neg"}],"key":{"a":"steady","b":"stumble","c":"steady","d":"stumble","e":"steady","f":"stumble"},"relearn":"Glad-you-told-me, patience and no-blame steady; doubt and minimising stumble.","persona":"any","source":"first responses"},
  {"id":"cr-1221","cat":"after-harm-support","type":"sort","hook":"Sort what a survivor keeps, versus what they don't owe.","items":[{"id":"a","text":"Their own decision on reporting"},{"id":"b","text":"Proof they fought back"},{"id":"c","text":"Healing at their own pace"},{"id":"d","text":"A perfect, gap-free account"},{"id":"e","text":"Choosing whom to tell"},{"id":"f","text":"An apology for telling you"}],"bins":[{"id":"theirs","label":"Theirs to keep","valence":"pos"},{"id":"owesnot","label":"They owe none of this","valence":"neg"}],"key":{"a":"theirs","b":"owesnot","c":"theirs","d":"owesnot","e":"theirs","f":"owesnot"},"relearn":"Survivors keep their choices and pace; they owe no proof, account or apology.","persona":"any","source":"what they owe"},
  {"id":"cr-1222","cat":"after-harm-support","type":"spot","hook":"Spot the responses that quietly blame the survivor.","scene":[{"id":"a","text":"\"I believe you, and it wasn't your fault\"","trick":false},{"id":"b","text":"\"What were you wearing that night?\"","trick":true},{"id":"c","text":"\"Take all the time you need\"","trick":false},{"id":"d","text":"\"Why did you even go to his room?\"","trick":true},{"id":"e","text":"\"What do you need from me?\"","trick":false}],"why":"Belief and 'what do you need?' help; 'what were you wearing' and 'why go there' blame.","relearn":"Belief and asking what they need help; 'what were you wearing' blames.","persona":"any","source":"spot the blame"},
  {"id":"cr-1223","cat":"after-harm-support","type":"spot","hook":"Spot the responses that take control away from the survivor.","scene":[{"id":"a","text":"\"It's your choice whether to report\"","trick":false},{"id":"b","text":"\"I've already messaged the warden for you\"","trick":true},{"id":"c","text":"\"What would help you right now?\"","trick":false},{"id":"d","text":"\"Give me his name, I'll deal with him\"","trick":true},{"id":"e","text":"\"I'll follow your lead\"","trick":false}],"why":"Acting without asking, or going after him, overrides her; asking and following don't.","relearn":"Asking and following their lead supports; acting for them overrides.","persona":"any","source":"spot taking over"},
  {"id":"cr-1224","cat":"after-harm-support","type":"spot","hook":"Spot the myths hiding in these 'reasons' to doubt a survivor.","scene":[{"id":"a","text":"\"Trauma can make memory patchy\"","trick":false},{"id":"b","text":"\"If it were real she'd have screamed\"","trick":true},{"id":"c","text":"\"Freezing is a normal response\"","trick":false},{"id":"d","text":"\"A real victim reports immediately\"","trick":true},{"id":"e","text":"\"Delay is common after assault\"","trick":false}],"why":"Patchy memory, freezing and delay are real; 'she'd have screamed' and 'reports at once' are myths.","relearn":"Freezing, patchy memory and delay are normal; 'she'd have screamed' is a myth.","persona":"any","source":"spot the myth"},
  {"id":"cr-1225","cat":"after-harm-support","type":"spot","hook":"Spot the lines that are not real support routes.","scene":[{"id":"a","text":"Call 181, the Women Helpline","trick":false},{"id":"b","text":"Just vent in a random group chat","trick":true},{"id":"c","text":"Reach the campus committee, ICC","trick":false},{"id":"d","text":"Post his name online for justice","trick":true},{"id":"e","text":"Talk to a campus counsellor","trick":false}],"why":"181, the committee and a counsellor are real routes; a group chat and outing him aren't.","relearn":"181, the campus committee and a counsellor are real routes; posts aren't.","persona":"Mehta","source":"spot the route"},
  {"id":"cr-1226","cat":"after-harm-support","type":"spot","hook":"Spot the responses that fail a male survivor.","scene":[{"id":"a","text":"\"I believe you, it wasn't your fault\"","trick":false},{"id":"b","text":"\"Bro, men can't get assaulted\"","trick":true},{"id":"c","text":"\"I'm here, take your time\"","trick":false},{"id":"d","text":"\"Honestly, most guys would've liked it\"","trick":true},{"id":"e","text":"\"What do you need from me?\"","trick":false}],"why":"Belief and presence support; 'men can't' and 'would've liked it' silence male survivors.","relearn":"Believe male survivors; 'men can't be assaulted' is a silencing myth.","persona":"Rohan","source":"spot / male survivor"},
  {"id":"cr-1227","cat":"after-harm-support","type":"spot","hook":"Spot the responses that rush a survivor's healing.","scene":[{"id":"a","text":"\"There's no timeline for this\"","trick":false},{"id":"b","text":"\"You should be over it by now\"","trick":true},{"id":"c","text":"\"I'll be here as long as it takes\"","trick":false},{"id":"d","text":"\"Just move on, it's done\"","trick":true},{"id":"e","text":"\"Heal at your own pace\"","trick":false}],"why":"Patience and no-timeline support; 'be over it' and 'just move on' rush healing.","relearn":"Healing has no timeline; 'get over it' rushes a survivor.","persona":"any","source":"spot / rushing"},
  {"id":"cr-1228","cat":"after-harm-support","type":"spot","hook":"Spot the responses that break a survivor's privacy.","scene":[{"id":"a","text":"\"I'll keep this just between us\"","trick":false},{"id":"b","text":"\"I told a couple of friends to help\"","trick":true},{"id":"c","text":"\"It's yours to share, not mine\"","trick":false},{"id":"d","text":"\"I hinted to others to watch out for him\"","trick":true},{"id":"e","text":"\"Tell me only what you want to\"","trick":false}],"why":"Keeping it private respects her; telling others or hinting outs her without consent.","relearn":"Keep a disclosure private; sharing it is the survivor's choice.","persona":"any","source":"spot / privacy"},
  {"id":"cr-1229","cat":"after-harm-support","type":"spot","hook":"Spot the responses that aren't survivor-led.","scene":[{"id":"a","text":"\"What would help you most?\"","trick":false},{"id":"b","text":"\"Here's the five-step plan you'll follow\"","trick":true},{"id":"c","text":"\"You decide, I'll support it\"","trick":false},{"id":"d","text":"\"I'll go confront him for you\"","trick":true},{"id":"e","text":"\"I'll move at your pace\"","trick":false}],"why":"Asking and following her lead is survivor-led; a fixed plan or confronting him isn't.","relearn":"Follow the survivor's lead; a fixed plan or revenge isn't support.","persona":"any","source":"spot / survivor-led"},
  {"id":"cr-1230","cat":"after-harm-support","type":"match","hook":"Match each survivor's need to the response that meets it.","pairs":[{"left":"Wants to be believed","right":"\"I believe you, this wasn't your fault\""},{"left":"Wants the choice on reporting","right":"\"It's your call, whatever you decide\""},{"left":"Wants to be heard, not fixed","right":"\"I'm here, no plan needed\""},{"left":"Wants confidential help now","right":"Call 181, the Women Helpline"},{"left":"In immediate danger","right":"Reach 112 right away"}],"relearn":"Belief, choice, presence and the right route each meet a real need.","persona":"Mehta","source":"need to response"},
  {"id":"cr-1231","cat":"after-harm-support","type":"match","hook":"Match each blaming myth to the truth that answers it.","pairs":[{"left":"\"She'd have fought if it were real\"","right":"Freezing is a normal, involuntary response"},{"left":"\"She told us too late\"","right":"Delay is common and doesn't make it untrue"},{"left":"\"Men can't be assaulted\"","right":"Anyone of any gender can be harmed"},{"left":"\"Her clothes invited it\"","right":"Clothes never cause or excuse assault"},{"left":"\"A friend would force a report\"","right":"A friend supports the survivor's own choice"}],"relearn":"Each blaming myth has a clear, survivor-centred truth that answers it.","persona":"any","source":"myth to truth"},
  {"id":"cr-1232","cat":"after-harm-support","type":"match","hook":"Match each support step to why it matters.","pairs":[{"left":"Believe them","right":"It's the survivor's first and biggest need"},{"left":"Don't blame","right":"Fault is only the one ignoring consent"},{"left":"Ask what they need","right":"It keeps them in control, not you"},{"left":"Respect their choices","right":"Returns the control harm took away"},{"left":"Signpost help","right":"Points to real, confidential routes"}],"relearn":"Believe, don't blame, ask, respect, signpost: each step has a clear reason.","persona":"Mehta","source":"step to why"},
  {"id":"cr-1233","cat":"after-harm-support","type":"match","hook":"Match each route to what it's for.","pairs":[{"left":"181","right":"Women Helpline, confidential, any violence"},{"left":"1091","right":"Women-in-distress line"},{"left":"112","right":"Immediate danger, emergency"},{"left":"Campus committee, ICC","right":"Campus harassment complaints"},{"left":"A campus counsellor","right":"Confidential support and signposting"}],"relearn":"181, 1091, 112, the campus committee and a counsellor each fit a real need.","persona":"Mehta","source":"route to purpose"},
  {"id":"cr-1234","cat":"after-harm-support","type":"match","hook":"Match each thing a survivor says to the steadiest reply.","pairs":[{"left":"\"Maybe it was my fault\"","right":"\"It wasn't, only he is responsible\""},{"left":"\"I should've fought back\"","right":"\"Freezing is your body protecting you\""},{"left":"\"No one will believe me\"","right":"\"I believe you, completely\""},{"left":"\"I don't want to report it\"","right":"\"That's your choice, I've got you\""},{"left":"\"I just can't talk yet\"","right":"\"Take your time, I'm here\""}],"relearn":"Self-blame, freeze-guilt and fear of disbelief each meet a no-blame reply.","persona":"any","source":"says to reply"},
  {"id":"cr-1235","cat":"after-harm-support","type":"match","hook":"Match each survivor situation to the right next move.","pairs":[{"left":"Wants company to the committee","right":"Go along, let them lead the talking"},{"left":"Has no campus or warden","right":"Share 181, callable from any phone"},{"left":"Isn't ready to name it","right":"Listen, don't push a label"},{"left":"Asks you to keep it secret","right":"Keep it private unless they say otherwise"},{"left":"Man scared he won't be believed","right":"Believe him plainly and fully"}],"relearn":"Each situation has a survivor-led next move that keeps them in control.","persona":"any","source":"situation to move"},
  {"id":"cr-1236","cat":"after-harm-support","type":"match","hook":"Match each unhelpful response to what would help instead.","pairs":[{"left":"\"Why didn't you leave?\"","right":"\"That wasn't yours to prevent\""},{"left":"\"You must report him\"","right":"\"It's your call if and when\""},{"left":"\"Just forget it happened\"","right":"\"We'll go at your pace\""},{"left":"\"What did you expect?\"","right":"\"This was never your fault\""},{"left":"\"I'll post about him\"","right":"\"I'll keep this private for you\""}],"relearn":"Each blaming or controlling line has a survivor-centred line that helps.","persona":"any","source":"unhelpful to helpful"},
  {"id":"cr-1237","cat":"after-harm-support","type":"match","hook":"Match each survivor worry to the reassurance that meets it.","pairs":[{"left":"\"It's too late to come forward\"","right":"Delay doesn't void a complaint"},{"left":"\"They'll say I'm exaggerating\"","right":"Your experience is valid, full stop"},{"left":"\"A man won't be taken seriously\"","right":"Male survivors are believed equally"},{"left":"\"I'm scared to use my name\"","right":"You can reach help confidentially"},{"left":"\"I'll be a burden to you\"","right":"I'm glad you told me; you're not"}],"relearn":"Each worry, lateness, doubt, gender, anonymity, burden, has a true reassurance.","persona":"any","source":"worry to reassurance"},
  {"id":"cr-1260","cat":"consent-culture","type":"reflect","hook":"Lensy: a quick 'you good?' midway isn't a buzzkill. It's you both staying close. Sit right?","prompt":"What do you think?","options":["Yes","Stays close","Not a buzzkill"],"affirm":"A warm check-in keeps you both present; that closeness is the point, not a pause.","relearn":"Checking in midway keeps you both present; it isn't a buzzkill.","persona":"any","source":"checking in"},
  {"id":"cr-1261","cat":"consent-culture","type":"reflect","hook":"Lensy: when someone takes your no with an easy 'all good', that ease tells you a lot. Notice it?","prompt":"What do you think?","options":["Yes","That's the green flag","Easy 'all good'"],"affirm":"A no met with easy grace is one of the clearest signs someone's safe to be around.","relearn":"A no taken with easy grace is a clear sign someone is safe.","persona":"any","source":"green flag"},
  {"id":"cr-1262","cat":"consent-culture","type":"reflect","hook":"Lensy: your enthusiastic yes matters exactly as much as anyone's, whoever you are. Land?","prompt":"What do you think?","options":["Yes","Mine counts too","Equally"],"affirm":"Everyone's eager yes counts the same; a consent culture is yours to expect, not just to give.","relearn":"Your enthusiastic yes matters equally; consent culture is everyone's.","persona":"any","source":"even-handed"},
  {"id":"cr-1263","cat":"consent-culture","type":"reflect","hook":"Lensy: changing your mind midway, with no penalty, is the culture working, not you being difficult.","prompt":"What do you think?","options":["Yes","Not difficult","No penalty"],"affirm":"A culture that lets you re-check and change your mind freely is one that respects you.","relearn":"Changing your mind with no penalty is the culture working, not you being difficult.","persona":"Ananya","source":"revocable"},
  {"id":"cr-1264","cat":"consent-culture","type":"reflect","hook":"Lensy: you don't have to be the loud hero: quietly checking on someone can be the whole rescue.","prompt":"What do you think?","options":["Yes","Quietly counts","Small move"],"affirm":"A small, quiet check-in is real bystander courage; you don't need a scene to help.","relearn":"A quiet check-in is real bystander courage; you don't need a scene.","persona":"any","source":"bystander"},
  {"id":"cr-1265","cat":"consent-culture","type":"reflect","hook":"Lensy: if a yes only happened because you outrank them, it isn't really a free yes. Feel that?","prompt":"What do you think?","options":["Yes","Not free then","Equals"],"affirm":"Consent lives between equals; where you hold more power, the free yes matters even more.","relearn":"A yes that only happened because of your power isn't a free yes.","persona":"any","source":"equals"},
  {"id":"cr-1266","cat":"consent-culture","type":"reflect","hook":"Lensy: 'tell me what you like' is a generous thing to say, not an awkward one. Try it on?","prompt":"What do you think?","options":["Yes","Generous","I'll try it"],"affirm":"Asking what someone likes is warm and generous; it makes intimacy better for you both.","relearn":"Asking what someone likes is generous, not awkward; it makes intimacy better.","persona":"any","source":"checking in"},
  {"id":"cr-1267","cat":"consent-culture","type":"reflect","hook":"Lensy: you can be the friend who shifts what your group jokes about. Want that role?","prompt":"What do you think?","options":["Yes","I'll model it","Shift the room"],"affirm":"How you treat consent quietly sets the bar for everyone around you; you change the room.","relearn":"How you treat consent sets the bar for your group; you change the room.","persona":"Rohan","source":"modelling"},
  {"id":"cr-1268","cat":"consent-culture","type":"reflect","hook":"Lensy: enthusiasm isn't a hoop to clear. It's the warm part, the bit that makes it good. Feel it?","prompt":"What do you think?","options":["Yes","The warm part","Not a hoop"],"affirm":"A real, eager yes is the warm core of intimacy, not a box to tick before the 'real' thing.","relearn":"Enthusiasm is the warm core of intimacy, not a hoop to clear.","persona":"any","source":"positive core"},
  {"id":"cr-1269","cat":"consent-culture","type":"reflect","hook":"Lensy: a consent culture means nobody's left looking out for themselves alone at a party. In?","prompt":"What do you think?","options":["Yes","Nobody alone","Count me in"],"affirm":"A room where people look out for each other is one you help build every time you show up.","relearn":"A consent culture means nobody's left to look out for themselves alone.","persona":"any","source":"looking out"},
  {"id":"cr-1270","cat":"consent-culture","type":"reflect","hook":"Lensy: 'no' is a full sentence: yours and theirs. You don't owe a reason. Sit right?","prompt":"What do you think?","options":["Yes","Full sentence","No reason owed"],"affirm":"A no needs no justification; a culture that accepts that without a fuss is one worth keeping.","relearn":"No is a full sentence; you never owe a reason for it.","persona":"any","source":"taking no"},
  {"id":"cr-1271","cat":"consent-culture","type":"reflect","hook":"Lensy: owning a moment you got wrong, without spiralling, is how you grow, not how you're cancelled.","prompt":"What do you think?","options":["Yes","Growth, not shame","Own it"],"affirm":"Honest accountability, free of shame-spiralling, is exactly how a consent culture gets better.","relearn":"Owning a past mistake without spiralling is how you grow, not how you're cancelled.","persona":"any","source":"accountability"},
  {"id":"cr-1272","cat":"consent-culture","type":"reflect","hook":"Lensy: pleasure and respect aren't a trade-off: the eager yes is what makes both true at once.","prompt":"What do you think?","options":["Yes","Both at once","Not a trade-off"],"affirm":"Respect and a great time aren't opposites; an enthusiastic yes is where they meet.","relearn":"Pleasure and respect aren't a trade-off; an eager yes is where they meet.","persona":"any","source":"positive frame"},
  {"id":"cr-1273","cat":"consent-culture","type":"reflect","hook":"Lensy: 'we can stop any time' is a sexy thing to know, not a sad one. Believe it?","prompt":"What do you think?","options":["Yes","Sexy, not sad","Any time"],"affirm":"Knowing you can both stop freely makes it safer to fully say yes; that's the good part.","relearn":"Knowing you can stop any time makes it safer to fully say yes.","persona":"any","source":"revocable"},
  {"id":"cr-1274","cat":"consent-culture","type":"reflect","hook":"Lensy: looking out for a stranger you'll never see again still counts. Worth doing?","prompt":"What do you think?","options":["Yes","Strangers too","Still counts"],"affirm":"Helping someone you'll never meet again is consent culture at its purest; it counts.","relearn":"Looking out for a stranger you'll never see again still counts.","persona":"any","source":"bystander"},
  {"id":"cr-1275","cat":"consent-culture","type":"reflect","hook":"Lensy: you can want someone a lot and still be completely fine if they're not feeling it. Both true?","prompt":"What do you think?","options":["Yes","Both true","Still fine"],"affirm":"Wanting someone and accepting a no gracefully live together easily in a healthy person.","relearn":"You can want someone a lot and still be fine if they're not feeling it.","persona":"Rohan","source":"taking no"},
  {"id":"cr-1276","cat":"consent-culture","type":"reflect","hook":"Lensy: in a long relationship, still asking 'this okay?' isn't distrust. It's care. Feel it?","prompt":"What do you think?","options":["Yes","It's care","Still ask"],"affirm":"Checking in years on isn't doubt; it's how a long relationship keeps consent alive and warm.","relearn":"Checking in within a long relationship is care, not distrust.","persona":"Aarti","source":"ongoing"},
  {"id":"cr-1277","cat":"consent-culture","type":"branch","persona":"any","source":"enthusiasm","hook":"You ask Dev if he wants to go further. He says \"yeah, sure\" but won't meet your eyes.","steps":[{"prompt":"His shoulders are tense. What do you do?","options":[{"text":"Take the yes at face value and carry on","then":"Dev says \"okay\" again, flatter this time. The room feels tense."},{"text":"Ask \"You're okay, right?\" and keep going","then":"He nods fast. The nod tells you nothing new."},{"text":"Stop abruptly and move away, a bit hurt","then":"Dev looks confused and starts apologising for ruining the night."},{"text":"Slow down: \"Only if you're really into it\"","then":"Dev exhales. \"Honestly, I'm not sure tonight,\" he says quietly.","best":true}],"why":"An unsure yes isn't an enthusiastic one. Making room lets the real answer come out."},{"prompt":"Later, Dev says sorry for being \"weird\" tonight. What do you say?","options":[{"text":"\"It's fine. Just tell me earlier next time\"","then":"Dev nods, but he looks like he's been told off."},{"text":"\"No worries. We'll make up for it next time\"","then":"Dev laughs a little too quickly. Next time already feels like a promise."},{"text":"\"You weren't weird. I'd rather know how you feel\"","then":"Dev smiles properly for the first time tonight.","best":true},{"text":"\"Honestly, it did kill the mood a bit\"","then":"Dev goes red and says nothing for a while."}],"why":"Thanking someone for honesty makes their real answer feel safe to give next time."},{"prompt":"A week later, things heat up again and Dev seems keen. What do you do?","options":[{"text":"Skip asking. He's the one who started it","then":"Dev seems happy, though you realise you're guessing."},{"text":"Check in warmly, and keep noticing his face","then":"Dev grins and says yes like he means it. It feels completely different.","best":true},{"text":"Ask for a clear yes once, then stop checking","then":"He says yes. Later he goes quiet, and you're not sure when that changed."},{"text":"Ask first whether he's \"over last week\"","then":"Dev tenses up, as if last week was a problem he caused."}],"why":"Reading the whole person, all the way through, is what a real yes looks like."}],"debrief":"Reading body and tone, not just the word 'yes', keeps a consent culture warm.","relearn":"Read the whole person, not just the word 'yes'."},
  {"id":"cr-1278","cat":"consent-culture","type":"branch","persona":"Rohan","source":"taking no","hook":"You finally asked Meher out. She said no, kindly, and it stings more than you'd admit.","steps":[{"prompt":"She's waiting for your reply. What do you say?","options":[{"text":"\"No worries at all\", and actually leave it there","then":"Meher relaxes. \"Thanks for being cool about it,\" she says.","best":true},{"text":"\"No worries. Maybe once you know me better?\"","then":"Meher's smile tightens. \"Maybe,\" she says, and looks away."},{"text":"Ask what you did wrong so you can fix it","then":"Meher shifts awkwardly and starts listing reasons she doesn't owe you."},{"text":"Laugh and say you were only joking anyway","then":"Meher looks unsure whether to believe you. The air stays awkward."}],"why":"One ask, then a clean \"no worries\", keeps your dignity and hers."},{"prompt":"That night your flatmate Gaurav says she's just playing hard to get. What do you do?","options":[{"text":"Wonder if he's right, and plan to ask again next week","then":"The idea keeps you up. Next week starts to feel like a plan."},{"text":"Agree, and ask Gaurav to put in a word for you","then":"Gaurav grins and says he'll mention you. Meher will hear your name again."},{"text":"Say nothing, and quietly hope she changes her mind","then":"You don't argue. The hope sticks around."},{"text":"Say a no is a no, and change the subject","then":"Gaurav shrugs. \"Fair,\" he says, and puts on a match.","best":true}],"why":"\"Playing hard to get\" turns a clear no into a maybe. Taking her at her word respects her."},{"prompt":"A week later you see Meher in the canteen with friends. What do you do?","options":[{"text":"Go over and ask if she's rethought it","then":"Her friends go quiet. Meher says no again, more firmly this time."},{"text":"Avoid her completely from now on","then":"You dodge her for weeks. The canteen starts to feel like a minefield."},{"text":"Nod hello and carry on with your day","then":"She waves back. It's a bit awkward, and then it passes.","best":true},{"text":"Post a sad song on your story that she'll see","then":"A mutual friend replies asking if you're okay. Meher sees it too."}],"why":"Being normal around her shows the no truly landed, with no pressure attached."},{"prompt":"A month on, you still feel low about it. What helps most?","options":[{"text":"Decide asking people out just isn't worth it","then":"You stop trying. The loneliness gets quieter and heavier."},{"text":"Admit to a friend it hurt, and let it pass","then":"Your friend Joseph says he's been there. Saying it out loud takes the edge off.","best":true},{"text":"Tell yourself she missed out, and move on fast","then":"It feels good for an evening. The sting is still there the next morning."},{"text":"Watch videos on how to change a no into a yes","then":"The videos promise tricks. None of them feel like you."}],"why":"Rejection stings. Letting it hurt honestly helps you move on without holding it against anyone."}],"debrief":"Taking a no gracefully, with no second or third ask, is a core consent-culture habit.","relearn":"After a clear no, take it gracefully; repeated asking becomes pressure."},
  {"id":"cr-1279","cat":"consent-culture","type":"branch","persona":"any","source":"equals","hook":"You like Aditi, a first-year who looks up to you as a final-year senior and agrees to everything.","steps":[{"prompt":"She says she's free whenever you are. What do you do?","options":[{"text":"Plan a late dinner, since she's happy with anything","then":"She agrees at once. You can't tell if it's what she'd have picked."},{"text":"Let her pick the plan and the pace, and mean it","then":"Aditi hesitates, then suggests coffee with her friends around. It's her idea.","best":true},{"text":"Enjoy it. She clearly likes the attention","then":"She keeps saying yes. You never find out what she actually wants."},{"text":"Keep it low-key so no one on campus finds out","then":"Aditi agrees to the secrecy too. She has no one to talk it over with."}],"why":"When you hold more status, letting her lead is how you know her yes is really hers."},{"prompt":"Your friend Pranav teases that juniors never say no to you. How do you respond?","options":[{"text":"Say that's why you have to be careful with Aditi","then":"Pranav stops smirking. \"Huh. Never thought of it like that.\"","best":true},{"text":"Laugh along. Being admired is a perk of final year","then":"Pranav high-fives you. The joke follows you round the hostel."},{"text":"Say Aditi's an adult who can decide for herself","then":"Pranav shrugs and moves on. The thought nags at you on the walk back."},{"text":"Get defensive and tell him to mind his business","then":"Pranav raises his hands. The teasing gets louder behind your back."}],"why":"Naming the power gap out loud keeps you honest about what her yes might carry."},{"prompt":"One evening, Aditi says she'll come back to your room \"if you want her to\". What do you do?","options":[{"text":"Take her up on it. She's an adult who offered","then":"She follows you, quieter than you've ever seen her."},{"text":"Ask \"You sure?\" and head there if she nods","then":"She nods quickly, the same way she agrees with everything."},{"text":"Say yes, but promise her nothing will happen","then":"Aditi nods. She still hasn't said what she wants."},{"text":"Say it's about what she wants, and suggest a walk","then":"Aditi looks relieved. \"A walk sounds nice,\" she says.","best":true}],"why":"An \"if you want\" across a power gap isn't her own yes. Handing the choice back makes it free."},{"prompt":"A month later, Aditi disagrees with you in a club meeting. What do you do?","options":[{"text":"Tease her that the junior's getting bold","then":"The room laughs. Aditi goes quiet for the rest of the meeting."},{"text":"Agree quickly so things stay smooth between you","then":"The meeting moves on. You wonder if she'll risk disagreeing again."},{"text":"Welcome it, and take her point seriously","then":"She looks surprised, then keeps talking. She sounds like herself.","best":true},{"text":"Remind her you've run the club for three years","then":"Aditi apologises and drops her point."}],"why":"When she can disagree with you freely, her yes starts to mean something too."}],"debrief":"With a power gap, the person with more power must be the careful one.","relearn":"With a status gap, more power means more responsibility to be careful."},
  {"id":"cr-1280","cat":"consent-culture","type":"branch","persona":"any","source":"bystander","hook":"At a party, your close friend Varun keeps leaning in on Shreya, who keeps stepping back.","steps":[{"prompt":"She glances around the room. What do you do?","options":[{"text":"Wait and see. Maybe you've misread it","then":"Shreya backs up against the wall. Varun leans closer."},{"text":"Pull Varun away: \"Come help me a sec\"","then":"Varun follows you, grumbling. Shreya slips off towards her friends.","best":true},{"text":"Shout across the room at Varun to back off","then":"Heads turn. Varun goes red and Shreya looks mortified."},{"text":"Catch Shreya's eye and give her a sympathetic smile","then":"She gives a tight smile back. Nothing about the moment changes."}],"why":"A quick, friendly interruption ends it without a scene or an accusation."},{"prompt":"Later, Varun tells you he thinks Shreya was into him. What do you say?","options":[{"text":"\"She kept stepping back, man. That's a no\"","then":"Varun frowns. \"I didn't notice that,\" he says after a pause.","best":true},{"text":"\"Maybe. Try again when she's on her own\"","then":"Varun perks up and starts looking round for her."},{"text":"\"Just drop it. It's a party\"","then":"Varun shrugs and grabs another drink. He hasn't changed his mind."},{"text":"\"You're being a creep. Seriously\"","then":"Varun bristles. \"Wow. Thanks a lot,\" he says, and walks off."}],"why":"Naming what you saw plainly, without an insult, gives him a chance to actually hear it."},{"prompt":"Near midnight, Varun heads back towards Shreya. What do you do?","options":[{"text":"Let it go. You already stepped in once","then":"Varun corners her by the kitchen. She looks round for someone she knows."},{"text":"Grab Varun and argue with him in front of everyone","then":"It turns into a shouting match. Shreya leaves on her own, shaken."},{"text":"Stand near them and watch, just in case","then":"You hover. Shreya still can't get past Varun to the door."},{"text":"Get to Shreya first: \"We're heading out. Coming?\"","then":"Shreya nods fast and grabs her bag.","best":true}],"why":"Offering her an easy way out works fast and puts her choice first."},{"prompt":"Next day, Varun texts asking if he was really that bad last night. What do you reply?","options":[{"text":"\"Nah, you were fine. Everyone was drunk\"","then":"Varun sends a relieved emoji. The next party looks just the same."},{"text":"\"Ask Shreya. She'll tell you herself\"","then":"Varun messages Shreya. Now she has to deal with him again."},{"text":"\"You kept going when she stepped back. Read that next time\"","then":"A long pause. Then: \"Okay. That's on me. I'll be more careful.\"","best":true},{"text":"Leave him on read and hope it sinks in","then":"Varun sends a second message, then gives up. Nothing gets talked through."}],"why":"An honest, specific answer from a friend is what actually changes his next party."}],"debrief":"Interrupting or redirecting a friend is how bystanders quietly stop harm.","relearn":"Redirect a friend not reading a no; you can defuse without a scene."},
  {"id":"cr-1281","cat":"consent-culture","type":"branch","persona":"Rohan","source":"modelling","hook":"In the hostel common room, the group cheers Sahil for \"finally wearing her down till she said yes\".","steps":[{"prompt":"Everyone looks at you to join in. What do you do?","options":[{"text":"Chuckle along and let it slide","then":"The story gets bigger with every retelling. You keep smiling."},{"text":"Stand up and give them a talk on consent","then":"Eyes roll. Sahil mutters \"here we go\" and the group tunes you out."},{"text":"Cut in lightly: \"Wearing someone down isn't a win\"","then":"The cheering stalls. Sahil laughs awkwardly and looks at you.","best":true},{"text":"Say nothing now, and plan to raise it with Sahil later","then":"The cheering carries on. You tell yourself you'll catch Sahil later."}],"why":"A light, direct line names the pressure without a lecture, so people actually hear it."},{"prompt":"Sahil adds that she did say yes in the end, so it's all fine. What do you say?","options":[{"text":"\"Fair enough. As long as she said yes\"","then":"Sahil grins. The group takes that as the final word."},{"text":"\"A yes you had to grind out isn't a free yes\"","then":"Sahil opens his mouth, then shuts it. A couple of guys nod slowly.","best":true},{"text":"\"You're basically a predator, man\"","then":"Sahil storms off. The others side with him, and the point is lost."},{"text":"\"Whatever. It's not my business\"","then":"The talk moves on. The idea that it was a win stays in the room."}],"why":"Pointing at how the yes was got shifts what the group calls normal."},{"prompt":"A week later, your friend Imran brags he'll keep asking a girl until she gives in. What do you do?","options":[{"text":"Say it straight: \"If she's said no, that's the answer\"","then":"Imran rolls his eyes, but he doesn't bring her up again.","best":true},{"text":"Laugh and wish him luck","then":"Imran takes it as backup and texts her again that night."},{"text":"Tell him to try sending gifts instead of asking","then":"Imran likes the idea and orders flowers to her hostel."},{"text":"Let it go this time. He's all talk and he'll get bored","then":"Imran keeps going. The others follow his lead."}],"why":"Saying it plainly, every time, shows the group this is a standard, not a one-off."}],"debrief":"Renaming 'wore her down' as pressure resets what the group calls normal.","relearn":"Name 'wearing someone down' as pressure, not a win."},
  {"id":"cr-1283","cat":"consent-culture","type":"branch","persona":"any","source":"ongoing","hook":"You and your partner Neel have a great rhythm, and tonight you want to try something new.","steps":[{"prompt":"The mood is warm and relaxed. What do you do?","options":[{"text":"Ask first: \"Would you be up for trying something?\"","then":"Neel laughs. \"Depends. Tell me more.\"","best":true},{"text":"Just go for it. You're close enough","then":"Neel freezes for a second and pulls back a little."},{"text":"Drop hints and hope Neel picks up on them","then":"Neel only catches on after a while, and looks a little unsure."},{"text":"Ask, but say you'll be hurt if the answer's no","then":"Neel hesitates. \"Um. Okay, I guess,\" he says."}],"why":"Asking before something new keeps every step chosen, even in a close relationship."},{"prompt":"Neel says he's curious but a bit nervous about it. What do you say?","options":[{"text":"\"Don't be nervous. You'll love it\"","then":"Neel nods, but he still looks unsure."},{"text":"\"Forget it. I don't want to make it a thing\"","then":"Neel looks relieved and a little confused. The idea hangs there."},{"text":"\"Nervous is normal. Let's just try it now\"","then":"Neel agrees, though his hands are tense."},{"text":"\"Not tonight is fine. Or we go slow. You pick\"","then":"Neel thinks, then smiles. \"Slowly. I do want to.\"","best":true}],"why":"Making \"not tonight\" as easy as \"yes\" turns a nervous maybe into his own real choice."},{"prompt":"Some time later, while you're close, Neel suddenly goes quiet. What do you do?","options":[{"text":"Keep going. He already said yes earlier","then":"Neel stays quiet. The closeness from before has gone."},{"text":"Ask \"You okay?\" without slowing down","then":"He says \"mm\" and you can't tell what it means."},{"text":"Pause and ask: \"Still good, or shall we stop?\"","then":"\"Can we stop for now?\" Neel asks. You settle in and talk instead.","best":true},{"text":"Stop and ask what you did wrong","then":"Neel ends up comforting you instead of saying how he feels."}],"why":"Consent is ongoing. A pause and a real question keep the new thing chosen."}],"debrief":"Even in a happy relationship, anything new gets its own ask.","relearn":"Closeness doesn't pre-approve something new; each step gets its own yes."},
  {"id":"cr-1284","cat":"consent-culture","type":"branch","persona":"any","source":"freeze / culture","hook":"Your friend Pooja confides that she froze and went along with something she didn't want.","steps":[{"prompt":"She says she should have just said something. What do you say?","options":[{"text":"\"Why didn't you just say something, though?\"","then":"Pooja goes quiet and pulls her sleeves over her hands."},{"text":"\"Freezing is normal. Going along isn't wanting it\"","then":"Pooja's eyes fill. \"I thought it made it my fault,\" she says.","best":true},{"text":"\"Next time, just say no really clearly\"","then":"Pooja nods, then says quietly, \"I keep going over it, though.\""},{"text":"\"Who was it? Tell me and I'll deal with him\"","then":"Pooja panics. \"Please don't do anything,\" she says."}],"why":"Freezing is involuntary. Saying so lifts a blame she's carrying that was never hers."},{"prompt":"Pooja asks if you think she's overreacting. What do you say?","options":[{"text":"\"No. How you feel makes sense. I believe you\"","then":"She lets out a long breath and leans against you.","best":true},{"text":"\"Maybe sleep on it and see how you feel\"","then":"Pooja nods, then comes back to it. \"I can't just sleep on this.\""},{"text":"\"Were you drinking? That could explain it\"","then":"Pooja stiffens. \"A bit. Does that matter?\" she asks."},{"text":"\"Everyone has nights they regret\"","then":"Pooja looks away. \"It's not regret,\" she says quietly."}],"why":"Believing her, and saying so, matters more than any advice."},{"prompt":"She says she doesn't know what to do next. What do you do?","options":[{"text":"Tell her she has to report it tomorrow","then":"Pooja shuts down. \"I'm not ready for that,\" she says."},{"text":"Tell her to try to forget it and move on","then":"Pooja nods, but her hands are still shaking."},{"text":"Book her a counsellor's slot without asking her","then":"Pooja feels cornered. She cancels it the next morning."},{"text":"Ask what she needs, and mention 181 if she wants it","then":"Pooja says she just wants company tonight. She saves 181 in her phone.","best":true}],"why":"Asking what she needs keeps her in charge, and knowing about help keeps it in reach."},{"prompt":"A week later, Pooja says she's decided not to report. What do you do?","options":[{"text":"Try to change her mind, for her own good","then":"Pooja stops replying to your texts for a few days."},{"text":"Say you'll report it for her anyway","then":"Pooja looks scared. \"Please don't,\" she whispers."},{"text":"Respect it, and tell her you're still around","then":"Pooja hugs you. \"Thank you for not pushing,\" she says.","best":true},{"text":"Drop the topic and never bring it up again","then":"Pooja wonders if you're uncomfortable. She stops sharing."}],"why":"It's her choice. Staying close without pressure is what real support looks like."}],"debrief":"Freezing is normal and never the person's fault. Meet it with belief, never 'why didn't you say no'.","relearn":"Freezing is normal; going along under pressure isn't wanting it."},
  {"id":"cr-1285","cat":"consent-culture","type":"branch","persona":"Rohan","source":"even-handed","hook":"You overhear two guys in your class joking that \"a guy can't really turn it down anyway\".","steps":[{"prompt":"One of them, Karan, looks at you for a laugh. What do you do?","options":[{"text":"Leave it. It's just banter","then":"They keep going. A quieter guy nearby stops laughing."},{"text":"Laugh along so you're not the odd one out","then":"Karan grins and tells a worse version of the joke."},{"text":"\"Men get to say no too. That's the point\"","then":"Karan blinks. The other guy mutters \"fair\" and looks at his phone.","best":true},{"text":"Tell them the joke is unfair to women","then":"They look confused. \"It's about guys,\" Karan says, and laughs."}],"why":"Men can say no and be pressured too. Saying it plainly makes room for any guy listening."},{"prompt":"Later, Karan says a guy who turns a girl down is just weak. What do you say?","options":[{"text":"\"Maybe, but it's still his choice\"","then":"Karan takes the \"maybe\" and runs with it."},{"text":"\"Knowing what you want isn't weak\"","then":"Karan shrugs, but he doesn't argue.","best":true},{"text":"\"Yeah, most guys would never say no\"","then":"Karan nods, pleased you agree."},{"text":"\"Whatever, bro. Who even cares\"","then":"The idea hangs there, unchallenged."}],"why":"A no from a man is as real as anyone's. Calling it weakness is pressure."},{"prompt":"That night, your friend Ishaan says he went along with something he didn't want, since guys \"can't refuse\". What do you say?","options":[{"text":"\"I believe you. It wasn't your fault. Want to talk?\"","then":"Ishaan exhales. \"I thought I'd sound pathetic,\" he says.","best":true},{"text":"\"Lucky you, bro\"","then":"Ishaan forces a laugh and doesn't say anything else."},{"text":"\"Why didn't you just leave?\"","then":"Ishaan looks down. \"I don't know,\" he says, and goes quiet."},{"text":"\"Maybe you'll feel better about it tomorrow\"","then":"Ishaan nods and changes the subject, but he looks worn out."}],"why":"Men who are pressured deserve the same belief and support. It's never their fault."},{"prompt":"A few days later, Ishaan admits he still can't stop thinking about it. What do you do?","options":[{"text":"Ask what he needs, and mention the campus counsellor","then":"Ishaan thinks, then asks if you'd sit with him while he books a slot.","best":true},{"text":"Tell him he has to report it, today","then":"Ishaan tenses. \"I'm not ready for that,\" he says."},{"text":"Tell him to shake it off. Dwelling makes it worse","then":"Ishaan nods, but he seems more alone than before."},{"text":"Tell your mates quietly, so he has more support","then":"Ishaan finds out and feels exposed. He stops confiding in you."}],"why":"Offering the counsellor, and letting him choose, gives him real help without taking over."}],"debrief":"Consent culture is even-handed: men get to say no, and it counts the same.","relearn":"Men get to say no too; consent culture holds for every gender."},
  {"id":"cr-1286","cat":"consent-culture","type":"branch","persona":"any","source":"bystander","hook":"At a party, your friend Ritika is backed against the stairs by a guy, and she looks tense.","steps":[{"prompt":"She catches your eye for a second. What do you do?","options":[{"text":"Assume she'll handle it herself","then":"The guy steps closer. Ritika's smile gets tighter."},{"text":"March over and tell the guy to get lost","then":"He squares up to you. Ritika is now stuck in the middle of a row."},{"text":"Text her \"You okay?\" from across the room","then":"Her phone buzzes in her bag. She can't check it without seeming rude."},{"text":"Wander over: \"We're getting snacks. Come?\"","then":"Ritika grabs the chance. \"Yes, please,\" she says, and walks off with you.","best":true}],"why":"A friendly exit gets her out fast, with no confrontation to manage."},{"prompt":"Later, Ritika says she felt stupid for not just walking away. What do you say?","options":[{"text":"\"You should have told him to back off\"","then":"Ritika's face falls. \"I know,\" she says, and stops talking."},{"text":"\"Honestly, he was probably harmless. Don't worry\"","then":"Ritika shrugs, unsure now whether she should even have felt scared."},{"text":"\"You did nothing wrong. He wouldn't let you go\"","then":"Ritika nods slowly. \"Yeah. He really wouldn't,\" she says.","best":true},{"text":"\"Let's not dwell on it. Enjoy the party\"","then":"Ritika agrees, but she keeps an eye on the stairs all night."}],"why":"Getting cornered is never her fault. Saying so lifts the blame she's putting on herself."},{"prompt":"Before the next party, your group chat plans who's going. What do you suggest?","options":[{"text":"That the girls dress down a bit this time, to be safe","then":"The chat goes quiet. Ritika leaves the group for a day."},{"text":"That we all look out for each other and leave together","then":"Everyone likes it. Ritika sends a thumbs-up and a heart.","best":true},{"text":"That you'll keep a close eye on Ritika in particular","then":"Ritika replies that she's not a child. The chat gets awkward."},{"text":"Nothing. Last time was a one-off","then":"Plans get made. Nobody mentions looking out for anyone."}],"why":"Looking out for each other, as a group, makes every night safer without singling anyone out."}],"debrief":"Offering a cornered person a graceful exit is a kind bystander move, and it's never their fault.","relearn":"Offer a cornered person an easy exit; a way out is real bystander care."},
  {"id":"cr-1287","cat":"consent-culture","type":"branch","persona":"any","source":"ongoing","hook":"Mid-hookup with Farah, you're not sure she's still into it. The vibe has changed.","steps":[{"prompt":"She's gone quiet and still. What do you do?","options":[{"text":"Pause: \"Still good, or shall we just chill?\"","then":"Farah lets out a breath. \"Chill, I think,\" she says softly.","best":true},{"text":"Keep going. She hasn't said anything","then":"Farah goes stiller. After a moment she gently pulls away."},{"text":"Ask \"You're good, yeah?\" and carry on","then":"She says \"yeah\" too quickly. You're no surer than before."},{"text":"Stop suddenly and move away without a word","then":"Farah looks confused and worried she upset you."}],"why":"A vibe shift is a cue to re-check. Consent is ongoing, not banked at the start."},{"prompt":"Farah says she's sorry for killing the mood. What do you say?","options":[{"text":"\"It's fine. Maybe next time, then\"","then":"Farah nods. She looks like she's already worrying about next time."},{"text":"\"Yeah, it was a bit sudden\"","then":"Farah goes red and pulls the blanket up."},{"text":"\"What changed? Did I do something?\"","then":"Farah ends up reassuring you instead of saying how she feels."},{"text":"\"You didn't. I'd much rather know\"","then":"Farah smiles properly. \"Okay. Good,\" she says.","best":true}],"why":"Welcoming a stop, with no guilt attached, makes the next check-in easy."},{"prompt":"Next time you're together, things are going well. What do you do?","options":[{"text":"Skip checking. Last time was a one-off","then":"It seems fine, though you're guessing more than you'd like."},{"text":"Ask once at the start, then relax","then":"Farah says yes happily. Later you stop noticing her face."},{"text":"Enjoy it, and check in as it goes","then":"Farah laughs at your \"still good?\" and pulls you closer.","best":true},{"text":"Ask every few seconds, just to be safe","then":"Farah laughs, then gets a bit annoyed. \"I'll tell you,\" she says."}],"why":"Checking in is part of the fun, and it keeps every moment chosen."}],"debrief":"Consent is ongoing; re-checking when energy changes is the culture in action.","relearn":"When the vibe shifts, re-check; consent is ongoing."},
  {"id":"cr-1288","cat":"consent-culture","type":"branch","persona":"any","source":"welcoming boundaries","hook":"Your partner Kavya says she's not ready to stay over yet. You'd been hoping she would.","steps":[{"prompt":"She looks nervous about how you'll react. What do you say?","options":[{"text":"Nothing. Sulk a little so she knows you're let down","then":"Kavya apologises twice and the evening goes flat."},{"text":"\"Thanks for telling me. Totally fine\"","then":"Kavya relaxes. \"Really? Okay. Thank you,\" she says.","best":true},{"text":"\"Sure. Just tell me when you'll be ready\"","then":"Kavya hesitates. \"I don't know when,\" she says."},{"text":"\"Fine, but everyone else's partners stay over\"","then":"Kavya looks hurt and goes quiet."}],"why":"Welcoming a boundary warmly, even a disappointing one, builds deep trust."},{"prompt":"Your friend Rahul teases that Kavya never stays over. What do you say?","options":[{"text":"\"She'll decide when she's ready. Fine by me\"","then":"Rahul shrugs. \"Fair enough,\" he says.","best":true},{"text":"\"She will soon enough. I'm working on it\"","then":"Rahul grins. You feel oddly uneasy saying it."},{"text":"\"Yeah, it's a bit annoying, honestly\"","then":"Rahul laughs and makes a joke you don't like."},{"text":"Change the subject fast","then":"Rahul keeps teasing. You go home irritated with Kavya."}],"why":"Backing her boundary even when she's not there is what makes it real."},{"prompt":"A few weeks on, Kavya says she'd like to stay over, but just to sleep. What do you say?","options":[{"text":"\"Sure, and we'll see what happens\"","then":"Kavya's smile slips. \"I said just sleep,\" she says."},{"text":"\"Okay, but why only sleep?\"","then":"Kavya shifts. She starts explaining herself again."},{"text":"\"Sure. I'll try my best to behave myself\"","then":"Kavya laughs uneasily, as if she might have to say no again."},{"text":"\"I'd love that. Just sleeping sounds great\"","then":"Kavya grins. \"I'll bring my own pillow,\" she says.","best":true}],"why":"Taking her yes exactly as she gives it keeps her boundaries safe to say."}],"debrief":"Welcoming a boundary without sulking builds trust; sulking is soft pressure.","relearn":"Welcome a boundary warmly; sulking is soft pressure."},
  {"id":"cr-1289","cat":"consent-culture","type":"branch","persona":"Zoya","source":"inclusive","hook":"Your friend Zoya says consent talk \"is only ever about straight couples\", and she's tired of it.","steps":[{"prompt":"She's half joking, half fed up. What do you say?","options":[{"text":"\"Eh, it's basically the same thing anyway\"","then":"Zoya shrugs. \"Easy to say when every example is about you.\""},{"text":"\"Maybe it's less of an issue for queer couples\"","then":"Zoya stares at you. \"You really think that?\""},{"text":"\"It's for everyone. Your yes counts the same\"","then":"Zoya raises an eyebrow. \"Then why does nobody ever say so?\"","best":true},{"text":"\"Ugh, let's not get heavy tonight\"","then":"Zoya lets it drop, but she looks a little let down."}],"why":"Saying out loud that it's for everyone is what makes the culture actually include her."},{"prompt":"Your group is making a consent poster for the college fest. What do you suggest?","options":[{"text":"Keep it generic so nobody feels singled out","then":"The poster looks neat. Zoya says it looks like every other one."},{"text":"Examples with couples of every kind","then":"The poster ends up with three different couples. Zoya shares it on her story.","best":true},{"text":"A small separate corner for LGBTQ+ couples","then":"It fits in a box at the bottom, under the main poster."},{"text":"Skip it. Posters don't change anything","then":"Someone else designs it. Every example is a boy and a girl."}],"why":"Showing every kind of couple makes inclusion the default, not an add-on."},{"prompt":"At the fest stall, a guy laughs that two women can't really pressure each other. What do you do?","options":[{"text":"Say pressure can happen in any couple, and so can a real yes","then":"He pauses. Zoya catches your eye and nods.","best":true},{"text":"Laugh it off to keep the stall friendly","then":"The joke passes around. Zoya goes quiet behind the stall."},{"text":"Let Zoya answer, since it's about her","then":"Zoya sighs and explains it, again, on her own."},{"text":"Tell him he's a bigot and should leave the stall","then":"He storms off. A few people drift away from the stall."}],"why":"Pressure and consent work the same in every relationship. Saying so shares the load."}],"debrief":"A consent culture is inclusive by default; everyone's yes counts the same.","relearn":"Consent culture is for every relationship; everyone's yes counts the same."},
  {"id":"cr-1290","cat":"consent-culture","type":"branch","persona":"any","source":"looking out","hook":"You're the sober one at Aryan's birthday, and as the night goes on, things are getting loose.","steps":[{"prompt":"Your friends are dancing and drinking fast. What do you do?","options":[{"text":"Tune out. Everyone here is an adult","then":"You scroll in a corner. You miss who leaves with whom."},{"text":"Tell everyone to slow down on the drinks","then":"A few roll their eyes. Someone calls you \"the warden\"."},{"text":"Keep an eye out quietly, and stay reachable","then":"You keep your phone charged and do a round of the room every so often.","best":true},{"text":"Offer to be everyone's ride home, then relax","then":"You're the ride, but nobody's watching the room till then."}],"why":"An alert sober friend can quietly guard the night without killing the vibe."},{"prompt":"Near midnight, Megha can barely stand, and a guy offers to \"take her home\". What do you do?","options":[{"text":"Let him. He seems like a nice enough guy","then":"They head for the door. Megha stumbles and grabs the wall."},{"text":"Say you'll take her, and grab two friends","then":"The guy shrugs and backs off. Two friends help Megha into a cab with you.","best":true},{"text":"Ask Megha if she wants to go with him","then":"Megha mumbles something you can't make out. The guy says \"see, she's fine\"."},{"text":"Warn him off loudly in front of everyone","then":"He gets angry and a crowd gathers around Megha."}],"why":"Someone who can barely stand can't decide. Getting her home with friends keeps her safe."},{"prompt":"Next morning, Megha texts asking what happened last night. What do you reply?","options":[{"text":"Tell her what you saw, and ask how she is","then":"Megha calls you straight away, and you talk it through.","best":true},{"text":"Tease her about how wasted she was","then":"Megha sends a single \"lol\" and goes quiet all day."},{"text":"Tell her she really needs to drink less","then":"Megha feels judged and doesn't reply."},{"text":"Say nothing happened. No need to worry her","then":"Megha hears the story from someone else a few days later."}],"why":"Honest facts without judgement help her feel safe, not ashamed."}],"debrief":"The sober friend staying alert is often why a night stays safe.","relearn":"If you're the sober one, staying alert for wobbly friends is real protection."},
  {"id":"cr-1291","cat":"consent-culture","type":"branch","persona":"any","source":"apps","hook":"You matched with Kabir on an app and he's keen to meet. You want it to feel consent-first.","steps":[{"prompt":"He asks where you'd like to go. What do you suggest?","options":[{"text":"Your place, since it's easier for you both","then":"Kabir hesitates. \"Maybe somewhere public first?\" he asks."},{"text":"Wherever he likes, so you seem easygoing","then":"Kabir picks a rooftop bar across town. You'd have preferred closer."},{"text":"Call it a done deal so neither of you backs out","then":"Kabir sends a thumbs-up, then a slightly uncertain \"sure\"."},{"text":"A busy café, and say plans can change any time","then":"Kabir replies: \"Perfect. No pressure either way.\"","best":true}],"why":"A public, flexible plan lowers the pressure, so any yes is real."},{"prompt":"The morning of the date, Kabir says he's feeling off and asks to reschedule. What do you reply?","options":[{"text":"\"I cleared my whole evening for this\"","then":"Kabir apologises and says he'll come anyway."},{"text":"\"Fine. Whatever works for you, I guess\"","then":"Kabir reads the tone and apologises twice."},{"text":"\"No problem. Want to pick another day?\"","then":"Kabir sounds relieved and suggests Sunday.","best":true},{"text":"\"Okay, but please don't flake again\"","then":"Kabir says he won't. He sounds a little tense."}],"why":"Taking a change of plan easily keeps the whole frame free of pressure."},{"prompt":"When you do meet, it goes well. At the end, you'd like to kiss him goodbye. What do you do?","options":[{"text":"Lean in. The date clearly went well","then":"Kabir turns slightly and you catch his cheek. It's awkward."},{"text":"Ask: \"Can I kiss you?\"","then":"Kabir laughs. \"I was hoping you'd ask,\" he says.","best":true},{"text":"Wait for him to make the first move","then":"Neither of you moves. You part with an awkward wave."},{"text":"Suggest going back to yours instead","then":"Kabir hesitates. \"Maybe next time?\" he says."}],"why":"Asking turns a guess into a real yes, and it's a sweet moment in itself."}],"debrief":"Starting a first meet low-pressure and public is the consent-first frame.","relearn":"Start a first meet low-pressure: public, free to change plans."},
  {"id":"cr-1292","cat":"consent-culture","type":"branch","persona":"any","source":"digital consent","hook":"Your friend Nishant brags that he secretly filmed his hookup last weekend, \"just for laughs\".","steps":[{"prompt":"He offers to show you on his phone. What do you do?","options":[{"text":"Refuse: \"That's not yours to do. Delete it\"","then":"Nishant's grin drops. \"Relax. It's not a big deal,\" he says.","best":true},{"text":"Laugh, and look away without watching","then":"Nishant takes the laugh as approval and shows the next person."},{"text":"Watch a few seconds so it isn't awkward","then":"You feel sick almost at once. Nishant thinks you're in on it."},{"text":"Say \"not cool, man\" and change the subject","then":"Nishant shrugs. The video stays on his phone."}],"why":"Refusing to watch and naming it clearly keeps you out of the harm."},{"prompt":"Nishant says she won't ever know, so no one's hurt. What do you say?","options":[{"text":"\"Fine, but just don't send it to anyone\"","then":"Nishant nods. \"Obviously,\" he says, pocketing the phone."},{"text":"\"Bro, what if she finds out, though?\"","then":"Nishant laughs. \"She won't. Chill.\""},{"text":"\"Whatever. It's your life\"","then":"Nishant grins. The conversation's over for him."},{"text":"\"She never agreed. That's the harm\"","then":"Nishant hesitates. \"You're making it sound so serious,\" he says.","best":true}],"why":"The violation is filming without her yes, whether or not she ever finds out."},{"prompt":"Two days later, you hear Nishant has shared the clip with a few friends. What do you do?","options":[{"text":"Stay out of it. It's his phone, his problem","then":"The clip reaches another group chat by the weekend."},{"text":"Post about Nishant publicly to shame him","then":"The post spreads fast, and so do questions about who the girl is."},{"text":"Tell him and them to delete every copy","then":"Two friends delete it. Nishant grumbles, but deletes his copy too.","best":true},{"text":"Ask a friend to send you the clip as proof","then":"Now you have a copy too. It's one more phone it lives on."}],"why":"Stopping the spread firmly protects her. Shaming him in public can expose her more."},{"prompt":"You realise you know who the girl is. What do you do?","options":[{"text":"Say nothing. Knowing would only upset her","then":"Weeks later, she hears about it from a stranger at a fest."},{"text":"Tell her privately it's not her fault, and share help options","then":"She's shaken, and thanks you. She saves 181 and asks about the campus committee.","best":true},{"text":"Report it to the campus committee for her, without asking her","then":"She's called to a meeting about a video she didn't know existed."},{"text":"Tell her in a group, so she has support around her","then":"She finds out in front of people and walks out without a word."}],"why":"It's never her fault. Telling her privately, with 181 or the campus committee as options, keeps the choice hers."}],"debrief":"Consent covers being filmed. A real friend names the violation, helps stop the spread, and never blames the person filmed.","relearn":"Recording someone intimately without their yes is a violation; name it."},
  {"id":"cr-1295","cat":"consent-culture","type":"branch","persona":"any","source":"checking in","hook":"Your friend Anmol asks how you make consent \"not awkward\" with new partners.","steps":[{"prompt":"He's genuinely curious and a bit embarrassed. What do you say?","options":[{"text":"\"Don't overthink it. Just read the room\"","then":"Anmol nods, but he still looks unsure how you'd read it."},{"text":"\"Get one clear yes at the start and you're set\"","then":"Anmol files that away. It sounds tidy and simple."},{"text":"\"It's always awkward, honestly. Just push through\"","then":"Anmol winces. \"So it's just awkward forever?\""},{"text":"\"Keep it warm and curious. Ask what they like\"","then":"Anmol laughs. \"That sounds way less scary than I thought.\"","best":true}],"why":"Framing consent as curiosity makes it feel natural, not like a form to fill in."},{"prompt":"Anmol asks what to do if someone seems into it but then goes quiet. What do you say?","options":[{"text":"\"Keep going. Quiet usually means they're enjoying it\"","then":"Anmol looks relieved, which worries you a little."},{"text":"\"Ask once. If they nod, you're fine\"","then":"Anmol shrugs. A nod sounds easy enough to him."},{"text":"\"Pause and check. Quiet can mean they've frozen\"","then":"Anmol nods slowly. \"I'd never have thought of that.\"","best":true},{"text":"\"Just stop and leave. Better safe than sorry\"","then":"Anmol frowns. \"Just leave? Without saying anything?\""}],"why":"People can freeze. A gentle pause and a question are the reliable way to know."},{"prompt":"Later, your group jokes that asking kills the mood. What do you do?","options":[{"text":"Laugh along. It's just the group being silly","then":"The joke sticks. Anmol stops mentioning what you told him."},{"text":"Say a warm check-in makes things better, not worse","then":"A couple of people look thoughtful. Anmol backs you up.","best":true},{"text":"Tell them they're all clueless about consent","then":"The group gets defensive and mocks you instead."},{"text":"Say it depends on the person, and leave it there","then":"The group moves on. Nobody's view has shifted."}],"why":"Sharing the warm version out loud helps consent feel normal for everyone."}],"debrief":"Spreading the 'warm and curious' version helps consent feel natural.","relearn":"Make consent warm and curious: 'what do you like?'"},
  {"id":"cr-1296","cat":"consent-culture","type":"branch","persona":"Aarti","source":"bystander","hook":"At a family wedding, your aunt keeps pushing your cousin Pallavi to dance with a guest she's declined.","steps":[{"prompt":"Pallavi's smile is getting tight. What do you do?","options":[{"text":"Step in: \"She's with me. Let's get food\"","then":"Pallavi squeezes your arm as you walk to the buffet.","best":true},{"text":"Stay out of it. It's a family thing","then":"Your aunt tugs Pallavi towards the dance floor."},{"text":"Tell your aunt off in front of the guests","then":"Your aunt is furious, and relatives start gossiping about Pallavi."},{"text":"Dance with the guest yourself to cover for her","then":"Your aunt laughs and pushes Pallavi in for the next song anyway."}],"why":"A light redirect backs her no and gets her out without a scene."},{"prompt":"Later, your aunt complains that Pallavi is being rude to guests. What do you say?","options":[{"text":"\"You're right. She should be more polite\"","then":"Your aunt nods and goes off to find Pallavi again."},{"text":"\"Don't worry. I'll talk her into one dance\"","then":"Your aunt beams. Pallavi now has two people pushing her."},{"text":"\"Let's not argue at a wedding, Aunty\"","then":"Your aunt keeps complaining to the next relative she meets."},{"text":"\"She said no, Aunty. That's allowed\"","then":"Your aunt huffs, but she stops pushing for the evening.","best":true}],"why":"Saying calmly that a no is allowed backs her, even against family."},{"prompt":"Pallavi asks why nobody ever stands up for her at these things. What do you say?","options":[{"text":"\"That's just how family is. Ignore it\"","then":"Pallavi sighs. It sounds like years more of the same."},{"text":"\"Maybe dance once, so they leave you alone\"","then":"Pallavi looks at the floor. \"Maybe,\" she says."},{"text":"\"You don't owe anyone a dance. I've got your back\"","then":"Pallavi laughs, relieved. \"Stay near me at the sangeet, then.\"","best":true},{"text":"\"You should really tell them off yourself\"","then":"Pallavi says she can't, not with her mum watching."}],"why":"Backing her choice openly shows her the no is hers, and she's not alone."},{"prompt":"At the next function, the same guest comes over to ask Pallavi again. What do you do?","options":[{"text":"Answer for her before she can speak","then":"The guest leaves, and Pallavi looks a little annoyed with you."},{"text":"Stay beside her, and let her answer","then":"Pallavi says no firmly. The guest nods and walks away.","best":true},{"text":"Go get a drink. She handled it last time","then":"Your aunt swoops in. Pallavi ends up on the dance floor."},{"text":"Loudly tell the guest to stop bothering her","then":"The whole table turns. Pallavi wishes she could disappear."}],"why":"Standing with her while she speaks backs her choice without taking it over."}],"debrief":"Bystander care includes backing a no against family and social pressure, gently.","relearn":"Back a no even against family pressure; a redirect supports their choice."},
  {"id":"cr-1297","cat":"consent-culture","type":"branch","persona":"any","source":"looking out","hook":"You're hosting. Ronak and Jiya are into each other, but Jiya is getting quite drunk.","steps":[{"prompt":"They head towards the balcony together. What do you do?","options":[{"text":"Let it run. They're both adults","then":"The balcony door slides shut. Jiya is laughing and unsteady."},{"text":"Slow things down: water, food, a comfy corner","then":"Jiya happily takes a plate. Ronak sits with her on the sofa.","best":true},{"text":"Pull Ronak aside and loudly warn him off","then":"Ronak is embarrassed and angry. The party goes quiet."},{"text":"Tell Jiya she's had too much and should stop","then":"Jiya looks stung and heads for the balcony anyway."}],"why":"Water, food and a calmer spot protect capacity and keep the night fun."},{"prompt":"An hour later, Ronak asks if Jiya can crash in the spare room with him. What do you say?","options":[{"text":"\"She can have the room. You take the sofa\"","then":"Ronak shrugs and grabs a blanket. Jiya is asleep in minutes.","best":true},{"text":"\"Sure, if she's okay with it\"","then":"Ronak goes to ask Jiya. She can barely keep her eyes open."},{"text":"\"Up to you two. I'm not your parent\"","then":"Ronak heads to the room with Jiya leaning on him."},{"text":"\"No way. I think you should leave now\"","then":"Ronak leaves, hurt. Jiya wakes later asking where he went."}],"why":"Someone that drunk can't decide. Separate spaces keep her safe tonight."},{"prompt":"Next morning, Jiya asks if she embarrassed herself last night. What do you say?","options":[{"text":"\"Honestly? You were a bit of a mess\"","then":"Jiya winces and leaves quickly after breakfast."},{"text":"\"You were all over Ronak. Be more careful\"","then":"Jiya goes red, as if she did something wrong."},{"text":"\"Don't worry about it\", then change the subject","then":"Jiya keeps worrying about what she doesn't remember."},{"text":"Tell her what you saw, and ask how she feels","then":"Jiya takes it in, and thanks you for being straight with her.","best":true}],"why":"Plain facts without judgement help her make sense of her night, not feel ashamed of it."}],"debrief":"A host quietly protecting capacity is doing consent culture, not killing the vibe.","relearn":"As a host, protecting a guest's capacity is care, not a buzzkill."},
  {"id":"cr-1298","cat":"consent-culture","type":"role-play","persona":"any","source":"reinforcing","hook":"You told your friend Siddharth you didn't want to go on a date. He took it really well.","setup":"Later, he catches you in the corridor.","steps":[{"prompt":"Siddharth asks: \"Hey, all good between us? No weirdness?\"","options":[{"text":"\"Yeah, yeah. Let's not talk about it\"","then":"\"Sure,\" he says. Then, unsure: \"I just want to know I handled it okay.\""},{"text":"\"Sorry. I still feel so bad about it\"","then":"Siddharth looks awkward. \"You don't have to be sorry.\""},{"text":"\"All good. Thanks for not making that weird\"","then":"He smiles. \"Of course. You were honest. That's all I'd want.\"","best":true},{"text":"\"Of course. Maybe some other time, who knows\"","then":"He looks confused. \"Oh. So was that a no, or a maybe?\""}],"why":"Naming what he did well tells him, and you, that a no can be easy."},{"prompt":"Siddharth shrugs and says: \"For me, a no is just a no. That's normal, right?\"","options":[{"text":"\"Yeah, true. Nothing to talk about\"","then":"\"Cool,\" he says, and the moment passes."},{"text":"\"It should be. Not everyone makes it that easy\"","then":"He grins. \"Well, now I feel like a hero.\"","best":true},{"text":"\"Most guys would have sulked for a week\"","then":"Siddharth frowns. \"That's a bit harsh on most guys.\""},{"text":"\"Normal? You were almost too chill about it\"","then":"He laughs uncertainly. \"Should I have been upset?\""}],"why":"Saying it out loud makes taking a no well something people notice and copy."},{"prompt":"At lunch, your friend Kunal laughs and says: \"Sid got turned down? Ouch.\"","options":[{"text":"\"He asked. I said no. He was great about it\"","then":"Kunal pauses. \"Huh. Fair play to him, then.\"","best":true},{"text":"\"Yeah, poor guy. Go easy on him\"","then":"Kunal snorts and keeps teasing Siddharth all through lunch."},{"text":"\"Ouch is right. He'll live, though\"","then":"Kunal laughs and starts calling Siddharth \"heartbreak boy\"."},{"text":"\"Anyway. Did anyone finish the assignment?\"","then":"Kunal lets it drop for now, then brings it up again at dinner."}],"why":"Backing him up in public makes taking a no gracefully the norm, not a joke."}],"relearn":"Naming when someone takes a no well reinforces the culture you both want."},
  {"id":"cr-1299","cat":"consent-culture","type":"role-play","persona":"any","source":"revocable","hook":"You and your partner Mihir are getting closer, and you want him to know stopping is always fine.","setup":"Tonight you're curled up together on the sofa.","steps":[{"prompt":"Mihir smiles and says: \"You've gone quiet. What's on your mind?\"","options":[{"text":"\"Nothing much. I'm just happy right now\"","then":"\"Me too,\" he says. Then, softer: \"Can I tell you something?\""},{"text":"\"You'd tell me if you weren't into something, right?\"","then":"\"Uh, yeah. Sure,\" Mihir says quickly."},{"text":"\"I hope you'd never just stop halfway on me\"","then":"Mihir's smile fades a little. \"Okay. I'll keep that in mind.\""},{"text":"\"At any point, 'let's stop' is fine. No explaining\"","then":"Mihir looks touched. \"Really? Even halfway through?\"","best":true}],"why":"Saying it out loud, before anything starts, makes stopping feel truly free."},{"prompt":"Mihir says: \"My last partner used to sulk whenever I changed my mind.\"","options":[{"text":"\"Well, it can be a bit frustrating when that happens\"","then":"Mihir nods slowly. \"Yeah. I know.\""},{"text":"\"Let's not talk about exes tonight\"","then":"\"Sorry,\" he says, and changes the subject."},{"text":"\"That's not okay. With me, changing your mind is fine\"","then":"Mihir exhales. \"That's a relief to hear.\"","best":true},{"text":"\"I'd never sulk. I'm just not like that\"","then":"\"Okay,\" Mihir says, though he doesn't sound sure."}],"why":"Making it clear a change of mind brings no sulking is what makes it real."},{"prompt":"A while later, Mihir pulls back and asks: \"Can we stop for now?\"","options":[{"text":"\"Sure. Did I do something wrong?\"","then":"\"No, no,\" he says, now worrying about your feelings."},{"text":"\"Of course. Want some tea?\"","then":"Mihir laughs, relieved. \"Yes. Tea sounds perfect.\"","best":true},{"text":"\"Okay. I thought we were having fun\"","then":"Mihir looks guilty. \"We were. I just need a minute.\""},{"text":"\"Just a little bit longer?\"","then":"Mihir hesitates, then shakes his head. \"I really want to stop.\""}],"why":"Stopping easily, with warmth, proves that what you said earlier was true."}],"relearn":"Saying 'you can stop any time, no explaining' out loud makes consent feel truly free."},
  {"id":"cr-1300","cat":"consent-culture","type":"role-play","persona":"Rohan","source":"bystander","hook":"Outside the club, your mate Aman says Riya turned him down, but he's going back in to try again.","setup":"He's already heading for the door.","steps":[{"prompt":"Aman says: \"She's playing hard to get. Girls like it when you keep trying.\"","options":[{"text":"\"Maybe she's just playing hard to get, yeah\"","then":"\"Exactly,\" Aman says, grinning. Then he hesitates at the door."},{"text":"\"Your call, bro. Good luck in there\"","then":"Aman heads for the door, then stops. \"Unless you think I shouldn't?\""},{"text":"\"Leave it, man. She said no. Let's get out of here\"","then":"Aman stops, frowning. \"You really think she meant it?\"","best":true},{"text":"\"Maybe try again next week instead\"","then":"Aman pauses. \"Yeah? Okay. Next week, then.\""}],"why":"A mate's straight \"she said no\" is what actually stops the next push."},{"prompt":"Aman lingers by the door and says: \"I really like her. Doesn't that count for something?\"","options":[{"text":"\"Then show her how much. Buy her a drink\"","then":"Aman goes in with a drink. He's back in a minute, red-faced. \"She said no again.\""},{"text":"\"It counts. But her no counts more\"","then":"Aman sighs. \"Yeah. Okay. It just sucks.\"","best":true},{"text":"\"Liking someone isn't enough, bro. Grow up\"","then":"Aman scowls. \"Thanks for nothing,\" he mutters."},{"text":"\"Then write her a long message tonight\"","then":"Aman starts typing, then stops. \"She'll just ignore it, won't she?\""}],"why":"Liking someone is real, and it still doesn't cancel her no."},{"prompt":"Aman kicks at the kerb and says: \"Why does nobody ever say yes to me?\"","options":[{"text":"\"Rejection sucks, man. It happens to everyone\"","then":"Aman half smiles. \"Fine. But you're buying the rolls.\"","best":true},{"text":"\"Because you come on too strong, honestly\"","then":"Aman's face drops. \"Wow. Great.\""},{"text":"\"Girls these days only want rich guys\"","then":"Aman nods bitterly. \"Knew it.\""},{"text":"\"Plenty will say yes. Try an app tonight\"","then":"Aman shrugs. \"Maybe,\" he says, still stinging."}],"why":"Owning that rejection hurts, without blaming anyone, helps him let it go."},{"prompt":"Walking back, Aman asks: \"Should I text her to say sorry for being pushy?\"","options":[{"text":"\"Yeah, and ask if she'll give you another chance\"","then":"\"Good plan,\" Aman says, typing it out."},{"text":"\"No. Just act like nothing happened\"","then":"\"Easier,\" Aman agrees, relieved."},{"text":"\"Send a few, so she knows you really mean it\"","then":"\"Right,\" Aman says. \"One tonight, one tomorrow.\""},{"text":"\"A short sorry is fine. Then leave it with her\"","then":"Aman nods. \"Short. Got it. No follow-ups.\"","best":true}],"why":"A brief apology with no ask attached respects her no fully."}],"relearn":"A no means no; a real mate redirects, never eggs on 'playing hard to get'."},
  {"id":"cr-1301","cat":"consent-culture","type":"role-play","persona":"any","source":"checking in","hook":"A few months in with your partner Ira, you want to know what she actually enjoys.","setup":"It's a slow, cosy evening at her place.","steps":[{"prompt":"Ira says: \"You look like you're thinking about something.\"","options":[{"text":"\"Nothing much. Just thinking how great you are\"","then":"Ira smiles. \"Aw.\" Then she adds: \"You can ask me things, you know.\""},{"text":"\"I'll just figure out what you like as we go\"","then":"Ira raises an eyebrow. \"Just by guessing?\""},{"text":"\"You enjoy everything we do anyway, right?\"","then":"Ira hesitates. \"Yeah. Mostly,\" she says."},{"text":"\"Tell me what you enjoy. I want it to be good\"","then":"Ira blushes, then grins. \"Okay. Nobody's asked me that before.\"","best":true}],"why":"Inviting her to say what she enjoys makes intimacy better for you both."},{"prompt":"Ira admits: \"I get a bit shy talking about what I like.\"","options":[{"text":"\"Come on. It's only me. Just say it\"","then":"Ira laughs nervously and changes the subject."},{"text":"\"Then I'll just keep guessing, I suppose\"","then":"\"Okay,\" Ira says, not sure if that's what she wants."},{"text":"\"No rush. Tell me whenever it feels easier\"","then":"Ira relaxes. \"Maybe I'll tell you bit by bit.\"","best":true},{"text":"\"Just tell me one thing, right now, then\"","then":"Ira squirms. \"Um. I don't know. Everything's fine?\""}],"why":"Letting her go at her own pace keeps the invite warm, not a demand."},{"prompt":"A few days later, Ira asks: \"Can I tell you something I'd like to try?\"","options":[{"text":"\"Sure, as long as it's nothing too weird\"","then":"Ira's face falls a little. \"Never mind, then.\""},{"text":"\"Yes, please. And anything you don't like too\"","then":"Ira smiles. \"Deal. That goes both ways.\"","best":true},{"text":"\"Only if I get to pick the next thing, though\"","then":"Ira laughs uncertainly. \"Is it a trade?\""},{"text":"\"Of course. I'll do whatever you want\"","then":"Ira pauses. \"I want you to want it too, though.\""}],"why":"Welcoming her wishes, and her limits, keeps it good for both of you."}],"relearn":"Inviting someone to say what they enjoy makes intimacy better for you both."},
  {"id":"cr-1302","cat":"consent-culture","type":"role-play","persona":"any","source":"equals","hook":"You're senior to Nandini at work, and she seems to feel she can't turn down your dinner invite.","setup":"She stops by your desk after the meeting.","steps":[{"prompt":"Nandini says quietly: \"About dinner. I mean, sure, if you want.\"","options":[{"text":"\"No obligation at all. A no won't change a thing\"","then":"Nandini looks relieved. \"Oh. Then maybe not this week.\"","best":true},{"text":"\"Great! It'll be good for your career too\"","then":"Nandini smiles tightly. \"Right. Yes. Of course.\""},{"text":"\"Perfect. I'll book somewhere nice\"","then":"\"Okay,\" she says, and hurries back to her desk."},{"text":"\"Only if you want to. Let me know by tonight\"","then":"She nods. \"I'll let you know,\" she says, looking tense."}],"why":"Where you hold power, saying no is safe makes any yes genuinely free."},{"prompt":"Your colleague Faisal says: \"Just take her out. Juniors love that kind of attention.\"","options":[{"text":"\"You're right. I'm overthinking it, aren't I?\"","then":"\"Exactly,\" Faisal says. \"Just ask her again.\""},{"text":"\"Mind your own business, Faisal\"","then":"Faisal holds up his hands. \"Okay. Touchy.\""},{"text":"\"Sure, she's an adult. I just don't want gossip\"","then":"Faisal grins. \"So it's about your image, then?\""},{"text":"\"I'm her senior. She might not feel free to say no\"","then":"Faisal thinks about it. \"Huh. I hadn't looked at it like that.\"","best":true}],"why":"Naming the power gap is what keeps her choice free."},{"prompt":"A week later, Nandini says: \"I'd actually like to join the team lunch on Friday.\"","options":[{"text":"\"Great. Sit next to me, then\"","then":"Nandini hesitates. \"Oh. Okay,\" she says."},{"text":"\"So, dinner after that, then?\"","then":"Nandini's smile slips. \"I'll have to see.\""},{"text":"\"Great. Glad you're coming\"","then":"She smiles properly. \"Me too.\"","best":true},{"text":"\"Great. We can go over your appraisal there\"","then":"Nandini nods, suddenly tense. \"Sure. Okay.\""}],"why":"Taking her yes at its real size, a team lunch, keeps it free of pressure."},{"prompt":"At the lunch, a colleague teases: \"Nandini finally said yes to the boss!\"","options":[{"text":"\"Took her long enough, didn't it?\"","then":"\"Persistence pays,\" the colleague says, winking at Nandini."},{"text":"\"She came to a team lunch. That's all, and it's great\"","then":"The colleague laughs. \"Fair. Pass the dal.\"","best":true},{"text":"\"Ha. Anyway, who ordered the paneer?\"","then":"The joke hangs in the air. Nandini stares at her plate."},{"text":"\"Don't embarrass her like that, yaar\"","then":"\"Oh, come on. She doesn't mind,\" the colleague says."}],"why":"Correcting the joke in public stops her yes turning into gossip."}],"relearn":"Where you hold power, explicitly remove obligation so any yes is genuinely free."},
  {"id":"cr-1303","cat":"consent-culture","type":"role-play","persona":"any","source":"checking in","hook":"Making out with your partner Yash, you want to check in without breaking the warmth.","setup":"The lights are low and he's laughing softly.","steps":[{"prompt":"Yash murmurs: \"This is nice.\"","options":[{"text":"\"Nice? Only nice? Come on\"","then":"Yash laughs, a little thrown. \"Okay, very nice.\""},{"text":"\"Mmm. You good? Want to keep going?\"","then":"Yash smiles against your cheek. \"Very good. Yes.\"","best":true},{"text":"\"You're good, right? Of course you are\"","then":"\"I mean, yes,\" Yash says. \"Not that you waited to hear.\""},{"text":"\"I knew you'd like this\"","then":"Yash laughs, but he doesn't really answer."}],"why":"A soft \"you good?\" keeps the mood and makes sure it's still a yes."},{"prompt":"A bit later, Yash says softly: \"Can we slow down a little?\"","options":[{"text":"\"Of course. Like this?\"","then":"Yash relaxes into you. \"Yeah. Perfect.\"","best":true},{"text":"\"Why? I thought you were into it\"","then":"Yash tenses. \"I was. I am. Just slower.\""},{"text":"\"Sure. Just a little longer like this first?\"","then":"Yash hesitates. \"I'd rather slow down now.\""},{"text":"\"Fine. Let's just stop, then\"","then":"Yash's face falls. \"Why do you sound annoyed? I only asked.\""}],"why":"Doing exactly what he asks, warmly, keeps him in charge of his yes."},{"prompt":"Later, Yash says quietly: \"My ex never asked how I was feeling.\"","options":[{"text":"\"Your ex sounds awful. What else did they do?\"","then":"Yash shifts. \"I don't really want to get into it.\""},{"text":"\"Honestly, asking feels like a formality to me\"","then":"Yash looks a little deflated. \"Oh. Okay.\""},{"text":"\"Don't get used to it. I won't always remember\"","then":"Yash laughs. \"Wait. Are you joking?\""},{"text":"\"Asking matters to me. It means we both want it\"","then":"Yash grins. \"Same. It's kind of hot, honestly.\"","best":true}],"why":"Checking in is part of what makes intimacy good, not a rule to put up with."}],"relearn":"A soft, warm 'you good?' midway keeps the mood and keeps it consensual."},
  {"id":"cr-1304","cat":"consent-culture","type":"role-play","persona":"any","source":"accountability","hook":"Your friend Ankit admits he once pushed past someone's hesitation, and he feels awful.","setup":"You're walking back from the canteen together.","steps":[{"prompt":"Ankit says: \"I keep thinking about it. I'm a terrible person, aren't I?\"","options":[{"text":"\"Don't worry about it. Everyone's done that\"","then":"Ankit looks relieved, then uneasy. \"Have they, though?\""},{"text":"\"Yeah, honestly, you kind of are\"","then":"Ankit goes pale. After a long silence, he says, \"So what do I do now?\""},{"text":"\"That wasn't okay. Owning it is how you do better\"","then":"Ankit nods slowly. \"Yeah. I needed someone to say that.\"","best":true},{"text":"\"You were probably just misreading her signals\"","then":"Ankit brightens a little. \"Yeah. Maybe it was mixed signals.\""}],"why":"Real accountability names the harm and points to doing better, without crushing him."},{"prompt":"Ankit asks: \"Should I message her and explain myself?\"","options":[{"text":"\"Yes. Tell her you never meant any harm\"","then":"\"Right,\" Ankit says, and opens his phone."},{"text":"\"Only if it's for her, not to make you feel better\"","then":"Ankit thinks. \"I guess I mostly want her to not hate me.\"","best":true},{"text":"\"No. Just act like it never happened\"","then":"\"That's easier,\" he says, but he doesn't look convinced."},{"text":"\"Ask her friends how she's doing first\"","then":"\"Good idea,\" Ankit says. \"I'll ask Mansi.\""}],"why":"An apology is for the person harmed. If it's only to ease his guilt, it can hurt more."},{"prompt":"Ankit says: \"What if I do it again without noticing?\"","options":[{"text":"\"Then slow down and ask. Hesitation means stop\"","then":"Ankit nods. \"Hesitation means stop. Okay. That's simple.\"","best":true},{"text":"\"You won't. You're not that kind of guy\"","then":"Ankit smiles weakly. \"I hope you're right.\""},{"text":"\"Just stay away from dating for a while\"","then":"Ankit shrugs. \"Maybe. That doesn't really fix anything.\""},{"text":"\"Only go for people who are really confident\"","then":"\"That could work,\" Ankit says, sounding unsure."}],"why":"A clear, simple habit is what stops it happening again."},{"prompt":"A week later, Ankit says: \"I think I should talk to someone about all this.\"","options":[{"text":"\"Nah, you've got me. That's enough\"","then":"\"Okay,\" Ankit says, though he still looks weighed down."},{"text":"\"Why? It's done now. Just let it go\"","then":"Ankit shrugs. \"I guess,\" he says, and drops it."},{"text":"\"Talk to her friends. They'll know what she thinks\"","then":"Ankit hesitates. \"Won't that make it worse for her?\""},{"text":"\"Good thought. The campus counsellor could help\"","then":"Ankit nods. \"I'll book a slot. Thanks for not bailing on me.\"","best":true}],"why":"Getting support to change is a strong, adult move, not a weakness."}],"relearn":"Real accountability names the harm and points to doing better, without 'everyone does it'."},
  {"id":"cr-1305","cat":"consent-culture","type":"strike-rewrite","hook":"\"Checking in mid-way kills the mood.\"","myth":{"un":"Checking in mid-way kills the mood.","re":"A warm check-in builds trust and tends to make intimacy better, not worse.","why":"Knowing it's truly wanted is what's hot."},"relearn":"Checking in builds trust and improves intimacy; it doesn't kill the mood.","persona":"any","source":"mood myth"},
  {"id":"cr-1306","cat":"consent-culture","type":"strike-rewrite","hook":"\"Taking a no gracefully makes you look weak.\"","myth":{"un":"Taking a no gracefully makes you look weak.","re":"Accepting a no with ease is a sign of confidence and self-respect, not weakness.","why":"Secure people don't need a yes to feel okay."},"relearn":"Accepting a no with ease shows confidence, not weakness.","persona":"Rohan","source":"taking no"},
  {"id":"cr-1307","cat":"consent-culture","type":"strike-rewrite","hook":"\"Stepping in for a stranger is none of your business.\"","myth":{"un":"Stepping in for a stranger is none of your business.","re":"Looking out for someone unable to look out for themselves is everyone's business.","why":"Bystanders prevent a lot of harm."},"relearn":"Looking out for someone unable to look out for themselves is everyone's business.","persona":"any","source":"bystander"},
  {"id":"cr-1308","cat":"consent-culture","type":"strike-rewrite","hook":"\"In a serious relationship you don't need to ask anymore.\"","myth":{"un":"In a serious relationship you don't need to ask anymore.","re":"A relationship never banks consent; it's freely chosen each time, however long you've been together.","why":"Partners can still say no, any time."},"relearn":"A relationship never banks consent; it's freely chosen each time.","persona":"Aarti","source":"relationship myth"},
  {"id":"cr-1309","cat":"consent-culture","type":"strike-rewrite","hook":"\"If you're really into someone, you'll keep pursuing till they say yes.\"","myth":{"un":"If you're really into someone, you'll keep pursuing till they say yes.","re":"Real interest respects a no; persistence past a no is pressure, not romance.","why":"A worn-down yes isn't a free yes."},"relearn":"Real interest respects a no; pursuing past it is pressure, not romance.","persona":"Rohan","source":"persistence myth"},
  {"id":"cr-1310","cat":"consent-culture","type":"strike-rewrite","hook":"\"Consent stuff is only for women to worry about.\"","myth":{"un":"Consent stuff is only for women to worry about.","re":"Consent culture is everyone's; every person's enthusiastic yes matters equally.","why":"Anyone of any gender can give or be denied a free yes."},"relearn":"Consent culture is everyone's; every person's enthusiastic yes matters equally.","persona":"any","source":"even-handed"},
  {"id":"cr-1311","cat":"consent-culture","type":"strike-rewrite","hook":"\"A power gap is fine as long as nobody complains.\"","myth":{"un":"A power gap is fine as long as nobody complains.","re":"A power gap can make a yes unfree even with no complaint; the one with more power must be careful.","why":"Fear of consequences silences people."},"relearn":"A power gap can make a yes unfree even with no complaint; the powerful one must be careful.","persona":"any","source":"equals"},
  {"id":"cr-1311b","cat":"consent-culture","type":"spot","hook":"Spot what builds a consent culture (and what quietly erodes it).","scene":[{"id":"a","text":"\"Only if you're into it\"","trick":false},{"id":"b","text":"Checking a wobbly friend got home","trick":false},{"id":"c","text":"\"Don't be boring, everyone's done it\"","trick":true},{"id":"d","text":"Taking a no with an easy 'all good'","trick":false},{"id":"e","text":"Sulking till they change their mind","trick":true}],"why":"Eager-yes language, looking out, and taking a no gracefully build the culture; shaming and sulking erode it.","relearn":"Eager-yes language, looking out, and taking a no gracefully build consent culture.","persona":"any","source":"culture cues"},
  {"id":"cr-1312","cat":"consent-culture","type":"spot","hook":"Spot the pressure hiding among the green flags.","scene":[{"id":"a","text":"\"No worries, your call\" after a no","trick":false},{"id":"b","text":"\"You owe me after dinner\"","trick":true},{"id":"c","text":"\"Tell me what you like\"","trick":false},{"id":"d","text":"\"Everyone's hooked up by now but you\"","trick":true},{"id":"e","text":"Offering a wobbly mate water","trick":false}],"why":"'You owe me' and 'everyone's done it' are guilt and shame pressure; the rest are consent-first.","relearn":"'You owe me' and 'everyone's done it' are pressure, not consent.","persona":"any","source":"spot pressure"},
  {"id":"cr-1313","cat":"consent-culture","type":"spot","hook":"Spot which moves a good bystander makes.","scene":[{"id":"a","text":"Offering a cornered guest an easy exit","trick":false},{"id":"b","text":"Filming the drama for the group chat","trick":true},{"id":"c","text":"Redirecting a pushy friend away","trick":false},{"id":"d","text":"Checking a drunk stranger is okay","trick":false},{"id":"e","text":"Egging your mate on 'for the story'","trick":true}],"why":"Exits, redirects and check-ins help; filming or egging a mate on makes things worse.","relearn":"Offering an exit, redirecting, and checking in are good bystander moves; filming or egging on aren't.","persona":"any","source":"bystander cues"},
  {"id":"cr-1314","cat":"consent-culture","type":"spot","hook":"Spot the genuinely free yes among these.","scene":[{"id":"a","text":"\"Yes! I've been hoping you'd ask\"","trick":false},{"id":"b","text":"\"Fine, since you've asked five times\"","trick":true},{"id":"c","text":"\"Yeah, I'm really into this\"","trick":false},{"id":"d","text":"\"Okay, you're my senior, so...\"","trick":true},{"id":"e","text":"\"Honestly yes, let's\"","trick":false}],"why":"A clear, eager yes is free; one worn down by asking or tied to a senior's status isn't.","relearn":"A clear, eager yes is free; one worn down or tied to power isn't.","persona":"any","source":"free yes cues"},
  {"id":"cr-1315","cat":"consent-culture","type":"spot","hook":"Spot what keeps consent alive in a long relationship.","scene":[{"id":"a","text":"Still asking before something new","trick":false},{"id":"b","text":"\"We're married, so it's assumed\"","trick":true},{"id":"c","text":"Checking 'this still good?' sometimes","trick":false},{"id":"d","text":"Welcoming a 'not tonight' warmly","trick":false},{"id":"e","text":"\"You can't say no to me now\"","trick":true}],"why":"Asking, re-checking and welcoming a no keep consent alive; 'it's assumed' and 'you can't say no' kill it.","relearn":"In a relationship, asking and welcoming a no keep consent alive; assuming it doesn't.","persona":"Aarti","source":"ongoing cues"},
  {"id":"cr-1316","cat":"consent-culture","type":"spot","hook":"Spot the even-handed truths about consent.","scene":[{"id":"a","text":"A man can say no and mean it","trick":false},{"id":"b","text":"\"Guys always want it\"","trick":true},{"id":"c","text":"Anyone's enthusiastic yes counts equally","trick":false},{"id":"d","text":"\"Real men don't turn it down\"","trick":true},{"id":"e","text":"A queer couple's consent works the same","trick":false}],"why":"Consent is even-handed; 'guys always want it' and 'real men don't refuse' are pressure myths.","relearn":"Consent is even-handed; 'guys always want it' is a pressure myth.","persona":"any","source":"even-handed cues"},
  {"id":"cr-1317","cat":"consent-culture","type":"spot","hook":"Spot accountability done right.","scene":[{"id":"a","text":"\"I crossed a line; I own that\"","trick":false},{"id":"b","text":"\"She probably wanted it anyway\"","trick":true},{"id":"c","text":"Apologising and changing the behaviour","trick":false},{"id":"d","text":"\"Everyone does it, it's nothing\"","trick":true},{"id":"e","text":"Committing to ask clearly next time","trick":false}],"why":"Owning it, apologising and changing course is accountability; minimising or excusing isn't.","relearn":"Owning it and changing the behaviour is accountability; minimising isn't.","persona":"any","source":"accountability cues"},
  {"id":"cr-1318","cat":"consent-culture","type":"spot","hook":"Spot the warm check-in (not the assumption).","scene":[{"id":"a","text":"\"Is this good for you?\"","trick":false},{"id":"b","text":"\"You didn't stop me, so...\"","trick":true},{"id":"c","text":"\"Want to keep going?\"","trick":false},{"id":"d","text":"\"You're not saying no, so it's fine\"","trick":true},{"id":"e","text":"\"Tell me if you want to slow down\"","trick":false}],"why":"Warm questions invite a real answer; 'you didn't stop me' treats silence as a yes, which it isn't.","relearn":"Warm questions invite a real answer; treating silence as a yes isn't checking in.","persona":"any","source":"check-in cues"},
  {"id":"cr-1319","cat":"consent-culture","type":"sort","hook":"Sort: a green flag in how someone treats consent, or a red flag?","items":[{"id":"a","text":"Takes your no with easy grace"},{"id":"b","text":"Sulks when you set a limit"},{"id":"c","text":"Checks in warmly midway"},{"id":"d","text":"Guilt-trips you into a yes"},{"id":"e","text":"Says 'only if you want to'"},{"id":"f","text":"Keeps a tally of conquests"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Easy grace, warm check-ins and 'only if you want to' are green flags; sulking, guilt-trips and scorekeeping are red.","persona":"any","source":"flags"},
  {"id":"cr-1320","cat":"consent-culture","type":"sort","hook":"Sort: a good bystander move, or making it worse?","items":[{"id":"a","text":"Offering a tense guest an exit"},{"id":"b","text":"Filming it for laughs"},{"id":"c","text":"Redirecting a pushy friend"},{"id":"d","text":"Standing back to 'not interfere'"},{"id":"e","text":"Quietly checking someone's okay"},{"id":"f","text":"Egging your mate on"}],"bins":[{"id":"good","label":"Good move","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"good","b":"worse","c":"good","d":"worse","e":"good","f":"worse"},"relearn":"Exits, redirects and check-ins are good bystander moves; filming, egging on or freezing out aren't.","persona":"any","source":"bystander"},
  {"id":"cr-1321","cat":"consent-culture","type":"sort","hook":"Sort: keeps a yes free, or compromises it?","items":[{"id":"a","text":"Asking as an equal, no strings"},{"id":"b","text":"Leaning on your seniority"},{"id":"c","text":"Making clear a no costs nothing"},{"id":"d","text":"Hinting their job depends on it"},{"id":"e","text":"Giving them real time to decide"},{"id":"f","text":"Asking again and again till they fold"}],"bins":[{"id":"free","label":"Keeps it free","valence":"pos"},{"id":"compromised","label":"Compromises it","valence":"neg"}],"key":{"a":"free","b":"compromised","c":"free","d":"compromised","e":"free","f":"compromised"},"relearn":"Asking as an equal, no-cost refusal and real time keep a yes free; power, threats and nagging compromise it.","persona":"any","source":"free yes"},
  {"id":"cr-1322","cat":"consent-culture","type":"sort","hook":"Sort: makes intimacy better, or worse?","items":[{"id":"a","text":"Asking what they enjoy"},{"id":"b","text":"Assuming and never asking"},{"id":"c","text":"Welcoming a 'not that'"},{"id":"d","text":"Sulking at a boundary"},{"id":"e","text":"Saying 'we can stop any time'"},{"id":"f","text":"Pushing past a hesitation"}],"bins":[{"id":"better","label":"Makes it better","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"better","b":"worse","c":"better","d":"worse","e":"better","f":"worse"},"relearn":"Asking, welcoming a boundary and 'we can stop any time' make intimacy better; assuming, sulking and pushing make it worse.","persona":"any","source":"positive core"},
  {"id":"cr-1323","cat":"consent-culture","type":"sort","hook":"Sort: keeps consent alive in a relationship, or lets it lapse?","items":[{"id":"a","text":"Asking before something new"},{"id":"b","text":"\"We're together, so it's assumed\""},{"id":"c","text":"Re-checking 'this still good?'"},{"id":"d","text":"Treating an old yes as standing"},{"id":"e","text":"Welcoming 'not tonight'"},{"id":"f","text":"Sulking when they're not up for it"}],"bins":[{"id":"alive","label":"Keeps it alive","valence":"pos"},{"id":"lapse","label":"Lets it lapse","valence":"neg"}],"key":{"a":"alive","b":"lapse","c":"alive","d":"lapse","e":"alive","f":"lapse"},"relearn":"Asking, re-checking and welcoming a no keep relationship consent alive; assuming and sulking let it lapse.","persona":"any","source":"ongoing"},
  {"id":"cr-1324","cat":"consent-culture","type":"sort","hook":"Sort: even-handed and true, or a pressure myth?","items":[{"id":"a","text":"Anyone of any gender can say no"},{"id":"b","text":"\"Guys can't really turn it down\""},{"id":"c","text":"Everyone's eager yes counts equally"},{"id":"d","text":"\"Consent is just a women's thing\""},{"id":"e","text":"A queer couple's yes works the same"},{"id":"f","text":"\"Real men never say no\""}],"bins":[{"id":"true","label":"Even-handed truth","valence":"pos"},{"id":"myth","label":"Pressure myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Consent is even-handed for every gender and orientation; 'guys can't refuse' and 'a women's thing' are myths.","persona":"any","source":"even-handed"},
  {"id":"cr-1325","cat":"consent-culture","type":"match","hook":"Match the consent-culture habit to why it matters.","pairs":[{"left":"Taking a no gracefully","right":"Shows you're safe to be around"},{"left":"Checking in midway","right":"Keeps it freely wanted throughout"},{"left":"Looking out at parties","right":"Protects people unable to right now"},{"left":"Owning a past mistake","right":"Is how the culture improves"},{"left":"Asking as an equal","right":"Keeps the yes genuinely free"}],"relearn":"Grace shows safety, check-ins keep it wanted, looking out protects, accountability improves, equality keeps it free.","persona":"any","source":"habits and why"},
  {"id":"cr-1326","cat":"consent-culture","type":"match","hook":"Match the line to what it really signals.","pairs":[{"left":"\"Only if you want to\"","right":"Respects a free choice"},{"left":"\"You owe me after dinner\"","right":"Guilt-trip, not consent"},{"left":"\"We can stop any time\"","right":"Makes consent revocable and safe"},{"left":"\"Everyone's done it but you\"","right":"Shame as pressure"},{"left":"\"Tell me what you like\"","right":"Makes intimacy better for both"}],"relearn":"'Only if you want to' respects choice; 'you owe me' and 'everyone's done it' are pressure dressed up.","persona":"any","source":"lines decoded"},
  {"id":"cr-1327","cat":"consent-culture","type":"match","hook":"Match each green flag to the value it shows.","pairs":[{"left":"Welcomes your boundary warmly","right":"Respect"},{"left":"Re-checks when the vibe shifts","right":"Attentiveness"},{"left":"Backs your no against the group","right":"Loyalty"},{"left":"Asks before anything new","right":"Care"},{"left":"Removes any pressure to say yes","right":"Fairness"}],"relearn":"Welcoming a boundary is respect; re-checking is attentiveness; backing your no is loyalty.","persona":"any","source":"green flags"},
  {"id":"cr-1328","cat":"consent-culture","type":"match","hook":"Match the bystander situation to the gentle move.","pairs":[{"left":"Friend not hearing someone's no","right":"Redirect: 'come help me a sec'"},{"left":"Someone cornered and tense","right":"Offer an easy exit together"},{"left":"A mate getting very drunk","right":"Bring water, slow it down"},{"left":"Group joking about pressure","right":"Lightly reframe it as not a win"},{"left":"A stranger looks unsafe","right":"Quietly check they're okay"}],"relearn":"Redirect a pushy friend, offer an exit, slow the drink, reframe the joke, check on a stranger.","persona":"any","source":"bystander moves"},
  {"id":"cr-1329","cat":"consent-culture","type":"match","hook":"Match the myth to the warm truth that replaces it.","pairs":[{"left":"\"Checking in kills the mood\"","right":"It builds trust and makes it better"},{"left":"\"Taking a no looks weak\"","right":"It shows real confidence"},{"left":"\"In a relationship you needn't ask\"","right":"Consent is chosen freely each time"},{"left":"\"Pursuing till yes is romantic\"","right":"Past a no it's pressure, not romance"},{"left":"\"Consent is a women's thing\"","right":"It's everyone's, equally"}],"relearn":"Checking in builds trust; taking a no shows confidence; consent is fresh each time and everyone's.","persona":"any","source":"myth to truth"},
  {"id":"cr-1330","cat":"consent-culture","type":"match","hook":"Match what makes a yes free to what makes it unfree.","pairs":[{"left":"Asked as an equal","right":"A senior leaning on rank"},{"left":"Free to refuse at no cost","right":"A job hinted to depend on it"},{"left":"Given real time to think","right":"Asked over and over till they fold"},{"left":"Sober enough to choose","right":"Too drunk to truly decide"},{"left":"Wanted, said eagerly","right":"Worn down into a tired 'fine'"}],"relearn":"Equality, no-cost refusal, time, capacity and real wanting make a yes free; power, threats, nagging and incapacity don't.","persona":"any","source":"free vs unfree"},
  {"id":"cr-1331","cat":"consent-culture","type":"match","hook":"Match the warm consent move to the moment it fits.","pairs":[{"left":"\"You good? Want to keep going?\"","right":"Midway, the energy's good"},{"left":"\"Only if you actually want to\"","right":"Their yes seemed just polite"},{"left":"\"We can stop, no explaining\"","right":"Making it feel truly free"},{"left":"\"Thanks for telling me\"","right":"They've named a boundary"},{"left":"\"No worries at all\"","right":"They've just said no"}],"relearn":"A warm line fits each moment: check in midway, test a polite yes, offer an out, welcome a boundary, accept a no.","persona":"any","source":"moves and moments"},
  {"id":"cr-1332","cat":"consent-culture","type":"branch","persona":"any","source":"checking in","hook":"Your partner Sneha wants to talk about pace before things get physical. You'd rather not.","steps":[{"prompt":"She brings it up over dinner. What do you do?","options":[{"text":"Say that talking about it ruins spontaneity","then":"Sneha goes quiet, then tries again. \"It matters to me, though.\""},{"text":"Agree to talk, but some other time","then":"Sneha nods. Two days later, she raises it again, more quietly."},{"text":"Joke that she's overthinking it","then":"Sneha laughs politely, then says, \"I mean it. Can we talk properly?\""},{"text":"Go with talking it out. Feeling ready matters","then":"Sneha looks relieved and starts explaining what she's comfortable with.","best":true}],"why":"Honouring how someone reaches a yes builds trust, even if it's slower than you'd like."},{"prompt":"Sneha says she'd like to take things slower than you expected. What do you say?","options":[{"text":"\"How much slower? Give me a timeline\"","then":"Sneha frowns. \"I can't put a date on it,\" she says."},{"text":"\"Sure, but don't make me wait too long\"","then":"Sneha laughs, but her shoulders tighten."},{"text":"\"Okay. Tell me what feels right to you\"","then":"Sneha smiles and describes it. It's clearer than you expected.","best":true},{"text":"\"Fine\", then scroll your phone for a while","then":"Sneha watches you scroll and wonders if she asked too much."}],"why":"Asking what feels right lets her set the pace without having to defend it."},{"prompt":"A few weeks later, things are going well between you. What do you do?","options":[{"text":"Assume that first talk covered everything","then":"One evening Sneha goes quiet. You weren't asking anymore."},{"text":"Keep checking in as things move along","then":"Sneha says she feels safe with you, and it shows.","best":true},{"text":"Remind her it's been a few weeks now","then":"Sneha feels a clock ticking and tenses up."},{"text":"Ask once a week if she's ready yet","then":"Sneha starts to dread the question. It feels like a deadline."}],"why":"A pace talk isn't a one-off. Checking in keeps her yes her own."}],"debrief":"Letting someone arrive at a yes their own way is consent culture.","relearn":"Honour how someone reaches a yes, even if it's slower."},
  {"id":"cr-1333","cat":"consent-culture","type":"branch","persona":"any","source":"digital consent","hook":"Your class group chat is sharing a private clip of Tanya and Dhruv, filmed without their knowledge.","steps":[{"prompt":"A friend forwards it to you and asks if you've seen it. What do you do?","options":[{"text":"Don't forward it, and say it should be deleted","then":"Your friend sends a sheepish \"yeah, fair\" and deletes it.","best":true},{"text":"Forward it on. You didn't make it","then":"It lands in another group within minutes."},{"text":"Delete it quietly and say nothing","then":"Your copy's gone. The clip keeps moving in the chat."},{"text":"Watch it once to see what the fuss is about","then":"You regret it at once. The clip stays on your phone."}],"why":"Refusing to pass it on, and saying so, breaks the chain of harm."},{"prompt":"In the group chat, people are joking about the clip. What do you do?","options":[{"text":"Mute the chat and stay out of it","then":"The jokes continue. Someone asks who has the full video."},{"text":"Send a laughing emoji so you don't seem uptight","then":"Your emoji gets a thumbs-up. The jokes get meaner."},{"text":"Post a meme to change the subject","then":"A few people laugh at the meme. Then the clip is back."},{"text":"Post: \"This was filmed without consent. Delete it\"","then":"The chat goes quiet. Two people reply that they've deleted it.","best":true}],"why":"A short, clear message in the chat makes deleting it the new normal."},{"prompt":"You see Tanya in the library, looking tense. What do you do?","options":[{"text":"Pretend you haven't heard anything about it","then":"Tanya catches your eye. After a moment, she comes over anyway, looking lost."},{"text":"Tell her everyone's seen it, so she knows","then":"Tanya's face drains. \"Everyone?\" she whispers, gripping her bag."},{"text":"Ask quietly if she's okay and wants any help","then":"Tanya says she's heard about it. She's glad someone asked.","best":true},{"text":"Tell her it'll all blow over in a week","then":"Tanya nods stiffly. It doesn't feel like it will."}],"why":"A quiet, caring check-in lets her decide what she needs."},{"prompt":"Tanya says she might go to the campus committee but feels embarrassed. What do you say?","options":[{"text":"\"Honestly, reporting might make it bigger\"","then":"Tanya's shoulders drop. She decides to just wait."},{"text":"\"It's not your fault. I can come with you\"","then":"Tanya exhales. \"Would you? Maybe Friday,\" she says.","best":true},{"text":"\"You have to report it today, no matter what\"","then":"Tanya feels rushed and says she'll think about it."},{"text":"\"Why were you even filmed in the first place?\"","then":"Tanya goes silent. She doesn't mention it to you again."}],"why":"Saying it's not her fault and offering to come along supports her own choice."}],"debrief":"Online, consent means never forwarding private content. Refusing breaks the chain, and it's never the fault of those filmed.","relearn":"Don't forward private content without consent; refusing breaks the harm."},
  {"id":"cr-1334","cat":"consent-culture","type":"branch","persona":"any","source":"honesty","hook":"Harsh is clearly more into you than you are into him, and keeps offering more: rides, gifts, plans.","steps":[{"prompt":"He asks if you'd like to go to a concert with him next week. What do you do?","options":[{"text":"Say yes. The tickets are free and he's fun","then":"Harsh beams and tells his friends it's a date."},{"text":"Be honest and kind about where you're at","then":"Harsh is quiet for a moment. \"Okay. Thanks for telling me straight.\"","best":true},{"text":"Say you're busy, and keep chatting like before","then":"Harsh suggests another night instead. He's still hopeful."},{"text":"Stop replying to his messages","then":"Harsh sends three worried texts, then goes quiet, confused."}],"why":"Honesty lets him choose freely, with a clear picture of where you stand."},{"prompt":"Your friend Diya says you should keep him around since he's so useful. What do you say?","options":[{"text":"\"That'd be using him. I'm not doing that\"","then":"Diya shrugs. \"True. I'd hate that if it were me.\"","best":true},{"text":"\"Yeah, the rides are really handy\"","then":"Diya laughs. You feel a flicker of guilt."},{"text":"\"Maybe I'll grow to like him over time\"","then":"Diya raises an eyebrow. You're not sure you believe it either."},{"text":"\"He's an adult. His feelings are his problem\"","then":"Diya looks uneasy and changes the subject."}],"why":"Keeping someone around for what they give, not who they are, isn't fair to them."},{"prompt":"A few weeks later, Harsh offers you a ride home and asks where you two stand. What do you say?","options":[{"text":"\"Things are great!\", so you don't hurt him","then":"Harsh beams. The gifts start coming faster."},{"text":"\"Let's just be friends\", and keep taking the rides","then":"Harsh agrees, and keeps offering rides and hoping."},{"text":"\"I don't know yet. Let's see how it goes\"","then":"Harsh hears the maybe and holds onto it."},{"text":"Tell him kindly you're not interested, without hedging","then":"Harsh nods slowly. \"Okay. I needed to hear that. Thanks.\"","best":true}],"why":"A clear, kind answer hurts less in the long run than a hopeful maybe."}],"debrief":"Consent culture cuts both ways: honesty about your interest lets them choose freely.","relearn":"Be honest about your interest; keeping someone guessing isn't fair."},
  {"id":"cr-1336","cat":"consent-culture","type":"sort","hook":"Sort: builds trust, or quietly chips at it?","items":[{"id":"a","text":"Saying 'tell me if you want to stop'"},{"id":"b","text":"Pretending not to hear a 'wait'"},{"id":"c","text":"Thanking them for naming a limit"},{"id":"d","text":"Acting hurt to get a yes"},{"id":"e","text":"Letting them set the pace"},{"id":"f","text":"Rushing past a hesitation"}],"bins":[{"id":"trust","label":"Builds trust","valence":"pos"},{"id":"chips","label":"Chips at it","valence":"neg"}],"key":{"a":"trust","b":"chips","c":"trust","d":"chips","e":"trust","f":"chips"},"relearn":"Inviting a stop, thanking a limit and letting them set the pace build trust; ignoring a wait, guilt and rushing chip at it.","persona":"any","source":"trust"},
  {"id":"cr-1337","cat":"consent-culture","type":"sort","hook":"Sort: a consent-first habit online, or not?","items":[{"id":"a","text":"Asking before sharing a couple photo"},{"id":"b","text":"Forwarding a private clip 'for laughs'"},{"id":"c","text":"Deleting a pic when asked"},{"id":"d","text":"Screenshotting chats to mock someone"},{"id":"e","text":"Checking a meet-up plan can change"},{"id":"f","text":"Pressuring for a photo they won't send"}],"bins":[{"id":"first","label":"Consent-first","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"first","b":"not","c":"first","d":"not","e":"first","f":"not"},"relearn":"Asking before sharing, deleting when asked and flexible plans are consent-first online; forwarding, mocking and pressuring aren't.","persona":"any","source":"digital consent"},
  {"id":"cr-1338","cat":"consent-culture","type":"match","hook":"Match the consent-culture value to a small everyday act.","pairs":[{"left":"Enthusiasm is the core","right":"Wait for an eager yes, not a polite one"},{"left":"Consent is between equals","right":"Drop any pressure from your rank"},{"left":"It's ongoing","right":"Re-check when the vibe changes"},{"left":"Take a no gracefully","right":"Say 'no worries' and mean it"},{"left":"Look out for each other","right":"Check a wobbly friend got home"}],"relearn":"Wait for an eager yes, drop your rank's pressure, re-check, accept a no, and look out for each other.","persona":"any","source":"values to acts"},
  {"id":"cr-990","type":"strike-rewrite","hook":"\"She drank, so she's fair game.\"","myth":{"un":"She drank, so she's fair game.","re":"Drinking is never an invitation; only a clear, willing yes is.","why":"A drink doesn't speak for anyone."},"relearn":"Drinking is never an invitation; only a willing yes is.","persona":"any","source":"capacity / drink-as-invite","cat":"drinks-and-capacity"},
  {"id":"cr-991","type":"strike-rewrite","hook":"\"He let me buy the drinks, so he owes me.\"","myth":{"un":"He let me buy the drinks, so he owes me.","re":"Buying someone a drink buys nothing; nobody owes you their body.","why":"A drink is a drink, not a debt."},"relearn":"Buying drinks buys nothing; nobody owes you their body.","persona":"Rohan","source":"transaction myth","cat":"drinks-and-capacity"},
  {"id":"cr-992","type":"strike-rewrite","hook":"\"He's a guy, so being drunk can't make it not okay.\"","myth":{"un":"He's a guy, so being drunk can't make it not okay.","re":"Anyone too drunk to agree can't consent; that's true for any gender.","why":"Capacity has no gender."},"relearn":"Anyone too drunk to agree can't consent, whatever their gender.","persona":"Rohan","source":"even-handed capacity","cat":"drinks-and-capacity"},
  {"id":"cr-993","type":"strike-rewrite","hook":"\"They came onto me first, so the drinking doesn't matter.\"","myth":{"un":"They came onto me first, so the drinking doesn't matter.","re":"If they're too far gone to agree, the first move changes nothing; help them get safe.","why":"Incapacity outranks any earlier flirting."},"relearn":"If they're incapacitated, the first move changes nothing; help them get safe.","persona":"any","source":"who-started-it","cat":"drinks-and-capacity"},
  {"id":"cr-994","type":"strike-rewrite","hook":"\"A few drinks just loosens people up, so a tipsy yes is a real yes.\"","myth":{"un":"A tipsy yes is always a real yes.","re":"Mildly tipsy-but-with-it can agree; slurring or barely standing cannot.","why":"The line is capacity, not the first sip."},"relearn":"With-it tipsy can agree; slurring or barely standing cannot.","persona":"any","source":"the capacity line","cat":"drinks-and-capacity"},
  {"id":"cr-995","type":"strike-rewrite","hook":"\"They were drinking too, so I'm off the hook.\"","myth":{"un":"They were drinking too, so I'm off the hook.","re":"Both drinking doesn't erase consent; if they couldn't agree, the harm is real.","why":"Two drinkers isn't a free pass."},"relearn":"Both drinking doesn't erase consent or the harm if they couldn't agree.","persona":"any","source":"mutual drinking","cat":"drinks-and-capacity"},
  {"id":"cr-996","type":"strike-rewrite","hook":"\"I was drunk too, so I can't be blamed for what happened.\"","myth":{"un":"I was drunk too, so I'm not responsible.","re":"Being drunk explains a choice; it never excuses ignoring that someone couldn't consent.","why":"Your drink isn't their consent."},"relearn":"Being drunk never excuses ignoring that someone couldn't consent.","persona":"any","source":"drunk-not-excuse","cat":"drinks-and-capacity"},
  {"id":"cr-997","type":"strike-rewrite","hook":"\"They didn't seem that drunk, so it's fine.\"","myth":{"un":"They didn't seem that drunk, so it's fine.","re":"If you're not sure they're sober enough and keen, you wait; doubt means stop.","why":"Unsure is a stop, not a maybe."},"relearn":"If you're unsure they're sober enough and keen, wait; doubt means stop.","persona":"any","source":"when in doubt","cat":"drinks-and-capacity"},
  {"id":"cr-998","type":"strike-rewrite","hook":"\"They woke up and didn't complain, so it was okay.\"","myth":{"un":"They didn't complain after, so it was okay.","re":"Anything done while they were passed out had no consent; silence after doesn't fix that.","why":"No capacity then means no consent then."},"relearn":"No consent is possible while passed out; silence after doesn't change that.","persona":"any","source":"passed-out","cat":"drinks-and-capacity"},
  {"id":"cr-999","type":"strike-rewrite","hook":"\"What people get up to once they're drunk is on them.\"","myth":{"un":"Whatever a drunk person does is on them.","re":"Someone too drunk to look after themselves needs a hand, not someone taking advantage.","why":"Incapacity calls for care, not opportunity."},"relearn":"Someone too drunk to look after themselves needs help, not someone taking advantage.","persona":"any","source":"looking out","cat":"drinks-and-capacity"},
  {"id":"cr-1000","type":"strike-rewrite","hook":"\"We hooked up drunk before, so tonight's a given.\"","myth":{"un":"We hooked up drunk before, so tonight's a given.","re":"Last time is never a yes for this time; each time needs its own clear, sober-enough yes.","why":"History isn't consent."},"relearn":"Last time is never a yes for this time; each time needs its own yes.","persona":"any","source":"history-isnt-consent","cat":"drinks-and-capacity"},
  {"id":"cr-1001","type":"strike-rewrite","hook":"\"She'd had a bit, but she was laughing, so she was into it.\"","myth":{"un":"She was laughing, so being drunk didn't matter.","re":"Laughing isn't a yes, and tipsy laughter can't stand in for capacity to agree.","why":"A mood isn't a yes."},"relearn":"Laughing isn't a yes; tipsy mood can't stand in for the capacity to agree.","persona":"any","source":"mood-isnt-yes","cat":"drinks-and-capacity"},
  {"id":"cr-1002","type":"strike-rewrite","hook":"\"He was the sober one, so it was all his call.\"","myth":{"un":"He was sober, so it was all his call.","re":"Being the sober one means you must wait, not that you decide for both.","why":"Sober means responsible, not in charge."},"relearn":"Being the sober one means you wait, not that you decide for both.","persona":"any","source":"sober-responsibility","cat":"drinks-and-capacity"},
  {"id":"cr-1003","type":"strike-rewrite","hook":"\"It's a party, not a place for being careful.\"","myth":{"un":"A party is no place for being careful.","re":"A party is exactly where looking out for each other keeps the night good for everyone.","why":"Care makes a party better, not duller."},"relearn":"A party is exactly where looking out for each other keeps it good for everyone.","persona":"any","source":"party-care","cat":"drinks-and-capacity"},
  {"id":"cr-1004","type":"strike-rewrite","hook":"\"They didn't push me off, so the drink was no problem.\"","myth":{"un":"They didn't push me off, so the drink was no problem.","re":"Not pushing away is never a yes, and someone too drunk often can't move or speak.","why":"Stillness isn't agreement."},"relearn":"Not pushing away is never a yes; someone too drunk often can't move or speak.","persona":"any","source":"passive-isnt-yes","cat":"drinks-and-capacity"},
  {"id":"cr-1005","type":"strike-rewrite","hook":"\"I was so drunk I don't remember, so it doesn't count.\"","myth":{"un":"They were too drunk to remember, so it doesn't count.","re":"If someone was too far gone to recall agreeing, they were too far gone to agree.","why":"No memory of a yes means no capacity for one."},"relearn":"Too far gone to recall agreeing means too far gone to agree.","persona":"Mehta","source":"blackout","cat":"drinks-and-capacity"},
  {"id":"cr-1006","type":"strike-rewrite","hook":"\"A guy can't be taken advantage of when he's drunk.\"","myth":{"un":"A guy can't be taken advantage of when drunk.","re":"Any person too drunk to consent can be harmed; men deserve the same belief and care.","why":"Harm isn't only women's to face."},"relearn":"Any person too drunk to consent can be harmed; men deserve the same care.","persona":"Rohan","source":"even-handed harm","cat":"drinks-and-capacity"},
  {"id":"cr-1007","cat":"drinks-and-capacity","type":"branch","persona":"Ananya","source":"date / capacity","hook":"Your date Kartik has had a lot to drink and is slurring. He leans in to kiss you.","steps":[{"prompt":"He says he's having the best night. What do you do?","options":[{"text":"Take the lean-in as a green light","then":"Kartik tries to stand and knocks his glass over."},{"text":"Kiss him once, but stop there","then":"Kartik barely notices. He's struggling to keep his eyes open."},{"text":"Slow it down: water, then call it a night","then":"Kartik sips the water and admits the room is spinning a bit.","best":true},{"text":"Tell him he's embarrassing himself","then":"Kartik looks hurt and orders another drink."}],"why":"Slurring isn't capacity. Slowing down keeps him safe and keeps the door open."},{"prompt":"Kartik suggests you both go back to his place. What do you do?","options":[{"text":"Go with him. He clearly wants you to","then":"Kartik needs your shoulder just to reach the door."},{"text":"Say not tonight, and call his flatmate to get him","then":"His flatmate arrives in twenty minutes and takes him home in a cab.","best":true},{"text":"Go with him, but only to see he gets in okay","then":"At his door, Kartik fumbles his keys and asks you to stay."},{"text":"Head home without telling anyone he's this drunk","then":"You're home by eleven. Kartik is still at the bar, alone."}],"why":"Handing him to his flatmate gets him home safe, and not going yourself respects you both."},{"prompt":"The next day, Kartik texts to apologise for being so drunk. What do you reply?","options":[{"text":"\"No stress. I'd love to see you again, sober\"","then":"Kartik replies with a relieved emoji and a date idea.","best":true},{"text":"\"You should really learn your limits\"","then":"Kartik replies \"sorry\" and goes quiet."},{"text":"\"It's fine. You were so cute when drunk\"","then":"Kartik sends a laughing emoji. It's unclear what he remembers."},{"text":"Leave it on read for a few days","then":"Kartik sends one more message, then stops."}],"why":"A warm, non-judgemental reply leaves the door open for a clear, sober yes."}],"debrief":"When they're slurring, you wait and look after them; capacity comes first.","relearn":"Slurring isn't capacity; slow it down and look after them."},
  {"id":"cr-1008","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"bystander / hostel","hook":"At a hostel party, your flatmate Arjun can barely stand, and a senior, Priyanka, is leading him off.","steps":[{"prompt":"Arjun is stumbling and laughing at nothing. What do you do?","options":[{"text":"Stay out of it. The senior knows him","then":"They head down the corridor. A minute later, Arjun stumbles back, lost."},{"text":"Shout at Priyanka to let go of him","then":"Priyanka snaps back and lets go. Arjun sways in the middle of a crowd."},{"text":"Call Arjun's name and wave from across the room","then":"Arjun waves back vaguely, then stops by the stairs, swaying."},{"text":"Step in: \"I've got him\", and get him water","then":"Priyanka shrugs and lets go. Arjun leans heavily on you.","best":true}],"why":"A calm \"I've got him\" is enough to change how a night ends."},{"prompt":"Arjun slurs that he's fine and wants to go and find Priyanka. What do you do?","options":[{"text":"Let him go. He says he's fine","then":"Arjun takes three steps and grabs the wall."},{"text":"Ask Arjun if he's sure, and let him decide","then":"Arjun says \"yeah\" and nearly falls over saying it."},{"text":"Keep him with you, and call his friends over","then":"Arjun grumbles but sits. Two friends come and sit with him.","best":true},{"text":"Sit him down, then go back to the party for a bit","then":"Ten minutes later, you find him slumped alone by the stairs."}],"why":"Someone barely standing can't decide. Keeping him with friends is the safe choice."},{"prompt":"Arjun goes pale and says he feels sick. What do you do?","options":[{"text":"Put him to bed and leave him to sleep it off alone","then":"Arjun lies flat on his back, alone, as you shut the door."},{"text":"Stay with him, get water, and keep him on his side","then":"Arjun is sick once, then settles. His breathing steadies.","best":true},{"text":"Give him strong coffee to sober him up","then":"Arjun takes a sip and pushes it away, feeling worse."},{"text":"Post in the hostel group asking what to do","then":"Replies pour in, half of them jokes. Arjun is still pale."}],"why":"Staying close and keeping him on his side helps. If he can't be woken or breathes oddly, call 112."},{"prompt":"Next morning, Arjun remembers little and asks what happened with Priyanka. What do you say?","options":[{"text":"Tell him plainly what you saw, and ask how he feels","then":"Arjun goes quiet. \"I don't remember agreeing to go anywhere,\" he says.","best":true},{"text":"\"Nothing. Don't worry about it\"","then":"Arjun later hears a very different version from others."},{"text":"\"Lucky you. A senior was into you\"","then":"Arjun forces a laugh, but he looks uneasy."},{"text":"\"You were a mess. You really need to drink less\"","then":"Arjun looks ashamed. \"Maybe. But the Priyanka thing keeps bugging me.\""}],"why":"Plain facts, with no jokes and no judgement, let him make sense of his own night."},{"prompt":"Arjun says it bothers him, but guys aren't supposed to mind. What do you say?","options":[{"text":"\"Honestly, most guys would be thrilled if a senior liked them\"","then":"Arjun nods and drops it. He stays quiet all day."},{"text":"\"You should go and confront her about it today, face to face\"","then":"Arjun looks panicked at the thought."},{"text":"\"Let's not make it into a big thing. It'll pass\"","then":"Arjun agrees, but he keeps checking his phone nervously."},{"text":"\"It's okay to mind, and not your fault. Want to see the counsellor?\"","then":"Arjun lets out a breath. \"Maybe. Would you come with me?\"","best":true}],"why":"Men can be harmed too, and it's never his fault. Believing him and offering help he can choose is support."}],"debrief":"A calm 'I've got him' can change how a night ends, and anyone of any gender deserves that care.","relearn":"Step in for someone too drunk to look out for themselves."},
  {"id":"cr-1009","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"roommate / capacity","hook":"Your PG roommate Simran stumbles in drunk after a party and starts coming onto you.","steps":[{"prompt":"You've both had a crush on each other for weeks. What do you do?","options":[{"text":"Gently steer her to bed with water. Not tonight","then":"Simran pouts, then flops onto her bed hugging the water bottle.","best":true},{"text":"Go along. You both fancy each other anyway","then":"Simran trips over her own bag and giggles at the floor."},{"text":"Kiss her once, but make it clear that's all","then":"Simran doesn't seem to register what you said."},{"text":"Tell her to stop being so ridiculous","then":"Simran looks hurt and turns to face the wall."}],"why":"Mutual feelings don't fix tonight's incapacity. Wait for a clear yes."},{"prompt":"Simran mumbles, half asleep, that she needs to know if you like her. What do you say?","options":[{"text":"\"Of course I do\", and lie down beside her","then":"Simran rolls over, already mostly asleep."},{"text":"\"Not like that. Just go to sleep\"","then":"Simran's face falls. You both know it isn't true."},{"text":"Nothing. Just slip out of the room","then":"Simran calls your name twice, then goes quiet."},{"text":"\"I do. Let's talk when you're sober\"","then":"Simran smiles sleepily and is out within a minute.","best":true}],"why":"Being honest about your feelings and clear about waiting keeps you both safe."},{"prompt":"Next morning, Simran is mortified and avoids your eyes. What do you do?","options":[{"text":"Pretend nothing happened last night","then":"The room stays awkward for days."},{"text":"Tease her about what she said last night","then":"Simran goes red and leaves for class early."},{"text":"Say you like her, and ask to talk sober","then":"Simran laughs with relief. \"Yes. Over chai, maybe?\"","best":true},{"text":"Say it's fine, and wait for her to bring it up","then":"Simran nods. Neither of you mentions it for a week."}],"why":"Raising it warmly and sober turns last night into a real, clear-headed choice."}],"debrief":"Liking someone never overrides the capacity rule; wait for a clear yes.","relearn":"Mutual feelings don't override incapacity; wait for a clear yes."},
  {"id":"cr-1010","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"check-in / with-it","hook":"You and Rhea are both a little tipsy, laughing, and clearly keen on each other.","steps":[{"prompt":"She pulls you closer. What do you do?","options":[{"text":"Ask warmly: \"You good? You sure you want this?\"","then":"Rhea grins. \"Very sure,\" she says, clear-eyed.","best":true},{"text":"Skip asking. The mood's obvious","then":"You carry on without asking, guessing at what she wants."},{"text":"Tell her she's too tipsy to know what she wants","then":"Rhea pauses, a bit hurt. \"Waiting's fine. Just ask me instead of telling me.\""},{"text":"Ask her exactly how many drinks she's had","then":"Rhea laughs. \"Two.\" You know the number, but not whether she wants this."}],"why":"Tipsy but with-it can agree. A warm check turns \"probably\" into a real yes."},{"prompt":"A bit later, as things heat up, Rhea goes quiet and reaches for her water. What do you do?","options":[{"text":"Keep going. She seemed into it earlier","then":"Rhea goes still and says nothing. You no longer know if she wants this."},{"text":"Stop, and ask if you did something wrong","then":"Rhea ends up reassuring you instead."},{"text":"Get her more water and carry on as before","then":"Rhea sips it, still quiet."},{"text":"Pause: \"Want a break, or keep going?\"","then":"\"Break,\" Rhea says, smiling. \"I'm getting sleepy.\"","best":true}],"why":"A yes can change. Checking again when the energy shifts keeps it real."},{"prompt":"Later, a friend asks how you \"know\" it's okay after a few drinks. What do you say?","options":[{"text":"\"If they're not saying no, you're fine\"","then":"Your friend shrugs. It sounds easy enough to him."},{"text":"\"You just feel it. It's hard to explain\"","then":"Your friend looks no wiser than before."},{"text":"\"They're clear-headed and keen, and you ask\"","then":"Your friend nods. \"Clear-headed and keen. Got it.\"","best":true},{"text":"\"Only if nobody's had anything to drink\"","then":"Your friend hesitates. \"Waiting's always fine. But how do I read a yes?\""}],"why":"The line is capacity plus an eager yes, not the number of drinks."}],"debrief":"With-it tipsy can agree; a warm check turns 'probably' into a real yes.","relearn":"Even when keen, a warm check-in confirms a real, sober-enough yes."},
  {"id":"cr-1011","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"friend in trouble","hook":"Your friend Shruti texts: she's alone at her flat, very drunk, and a guy from the party is on his way over.","steps":[{"prompt":"It's late and you're across town. What do you do?","options":[{"text":"Tell her to sleep it off, and reply later","then":"Shruti sends \"ok\". Ten minutes later, she calls you, sounding scared."},{"text":"Call her now, and head over to her flat","then":"Shruti picks up, slurring. You're in a cab within minutes, phone to your ear.","best":true},{"text":"Text her to lock the door, then go back to sleep","then":"She replies \"ok\". Twenty minutes later, your phone rings. It's Shruti."},{"text":"Message the guy and tell him to stay away","then":"He replies \"who is this?\" Shruti calls to say he's still coming."}],"why":"Alone, very drunk, a near-stranger on the way: that's exactly when a friend shows up."},{"prompt":"Shruti says she's fine and doesn't want to make a fuss. What do you say?","options":[{"text":"\"You're not a fuss. Stay on the phone with me\"","then":"Shruti laughs weakly and keeps talking. You can hear the TV.","best":true},{"text":"\"Okay. Just text me if anything happens\"","then":"Shruti says okay. The call ends."},{"text":"\"Why did you even drink so much?\"","then":"Shruti goes quiet. \"Sorry,\" she says."},{"text":"\"If you let him in, that's on you\"","then":"Shruti's voice wobbles. \"I just want to sleep.\""}],"why":"Staying on the line, without judgement, means she isn't alone."},{"prompt":"Shruti hears a knock at her door. What do you tell her?","options":[{"text":"\"Just open it and tell him to leave\"","then":"Shruti fumbles with the lock, unsteady on her feet."},{"text":"\"Your call. Let him in if you want\"","then":"Shruti hesitates. She's too drunk to think it through."},{"text":"\"Ask him through the door to come back tomorrow\"","then":"He says he just wants to talk for five minutes."},{"text":"\"Keep it shut. If he won't go, call 112\"","then":"Shruti whispers okay. After a minute, the knocking stops.","best":true}],"why":"A shut door, and 112 if he won't leave, keep her safe until help arrives."},{"prompt":"You get there as fast as you can. Shruti is crying on the sofa. What do you do?","options":[{"text":"Ask her why she gave him her address","then":"Shruti cries harder. \"I don't know,\" she says."},{"text":"Tell her to call the guy and sort it out","then":"Shruti stares at her phone, too scared to touch it."},{"text":"Sit with her, get water, and say you're staying","then":"Shruti nods, clutching the glass. After a while she stops shaking.","best":true},{"text":"Put her to bed, and head home once she's asleep","then":"She's asleep. At three she wakes up alone and panics."}],"why":"Staying close, with no questions yet, helps her feel safe again."},{"prompt":"Next day, Shruti says she feels stupid and it was her own fault. What do you say?","options":[{"text":"\"Next time, just don't drink so much\"","then":"Shruti nods, ashamed, and changes the subject."},{"text":"\"It's not your fault. Texting me was smart\"","then":"Shruti manages a small smile. \"I'm glad I texted you.\"","best":true},{"text":"\"You should report him right away\"","then":"Shruti tenses. \"Nothing happened. I just want to forget it.\""},{"text":"\"Let's just never talk about it again\"","then":"Shruti agrees, but she seems more alone than before."}],"why":"It's never her fault. Reaching out was the right instinct, and saying so helps her do it again."}],"debrief":"Showing up for a drunk friend in a risky spot is what looking out means, and it's never her fault.","relearn":"Show up for a friend left alone, very drunk and at risk."},
  {"id":"cr-1012","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"plying-with-drink","hook":"You've been pouring your date Tanisha strong drinks, hoping it'll \"help things along\".","steps":[{"prompt":"She holds out her glass for a refill. What do you do?","options":[{"text":"Keep her topped up so she relaxes more","then":"Tanisha's words start to blur together."},{"text":"Pour one more strong one, then switch to water","then":"The last strong one hits her hard. She sits down heavily."},{"text":"Stop. Switch to lighter drinks or water","then":"Tanisha shrugs and takes the water. The talk gets easier, not harder.","best":true},{"text":"Top her up, but go easy on your own","then":"Tanisha gets tipsier while you stay sharp."}],"why":"Anything real needs a clear, willing yes, not a lowered guard."},{"prompt":"Tanisha says she feels really relaxed with you. What do you do?","options":[{"text":"Take it as your cue to make a move","then":"Tanisha laughs, then blinks slowly. She's hazier than she seems."},{"text":"Suggest getting food, and just enjoy talking","then":"Over momos, Tanisha tells you about her sister. It feels real.","best":true},{"text":"Ask if she wants to come back to yours","then":"Tanisha says \"maybe?\" and looks unsure."},{"text":"Pour a little more to keep the mood going","then":"Tanisha's head starts to droop."}],"why":"Letting the night be what it is, with a clear head, is how anything real starts."},{"prompt":"Walking home, you think about why you poured those drinks. What do you tell yourself?","options":[{"text":"\"That was pressure. I won't do it again\"","then":"It stings to admit. You feel clearer by the time you reach your gate.","best":true},{"text":"\"Everyone does it. It's just how dates go\"","then":"The thought soothes you for a minute. The unease doesn't leave."},{"text":"\"It was her choice to keep drinking\"","then":"You try to believe it. You still remember reaching for the bottle."},{"text":"\"No harm done, since nothing happened\"","then":"You feel relieved, and stop thinking about the plan."}],"why":"Naming it as pressure, honestly, is what stops it happening next time."}],"debrief":"Loading someone's glass to lower their guard is pressure, not seduction.","relearn":"Loading someone's drink to lower their guard is pressure, not consent."},
  {"id":"cr-1013","cat":"drinks-and-capacity","type":"branch","persona":"Mehta","source":"accountability / after","hook":"You wake beside Ishita, who passed out mid-way last night. You're unsure exactly what happened.","steps":[{"prompt":"She's stirring and looks confused. What do you do first?","options":[{"text":"Make her tea and wait for her to bring it up","then":"Ishita drinks it in silence. Neither of you says anything real."},{"text":"Leave before she's properly awake","then":"You're gone before she opens her eyes. The question follows you home."},{"text":"Tell her she was into it, so she doesn't worry","then":"Ishita stares at you, unsure what to believe."},{"text":"Check she's okay, and be honest that you're unsure","then":"Ishita sits up slowly. \"I don't remember much after the party,\" she says.","best":true}],"why":"Checking on her and being honest puts her wellbeing ahead of your comfort."},{"prompt":"Later, Ishita asks what happened after she passed out. What do you say?","options":[{"text":"\"Nothing much. Don't worry about it at all\"","then":"Ishita looks unconvinced and gathers her things fast."},{"text":"\"We were both drunk. It just happened\"","then":"Ishita frowns. \"I was passed out,\" she says quietly."},{"text":"\"I'm not sure. Anything after that wasn't okay\"","then":"Ishita is quiet for a long time. \"I need to go,\" she says.","best":true},{"text":"\"You started it, remember? You wanted to\"","then":"Ishita flinches. She can't remember, and now she doubts herself."}],"why":"Honesty that owns it, with no excuses, is what she deserves."},{"prompt":"Ishita says she needs space and doesn't want to talk. What do you do?","options":[{"text":"Send a long message explaining yourself properly","then":"Ishita reads it and blocks your number."},{"text":"Respect it, and don't contact her unless she does","then":"Days pass in silence. It's hard, and it's hers to decide.","best":true},{"text":"Ask mutual friends how she's doing, quietly","then":"Word gets back to Ishita. She feels watched."},{"text":"Text her once a day to check she's okay","then":"Each message makes Ishita's stomach drop."}],"why":"Her need for space comes first. Owning it means not making her manage you."},{"prompt":"You can't stop thinking about it. What do you do next?","options":[{"text":"See a campus counsellor about owning it and changing","then":"The counsellor listens without excusing it, and helps you work out next steps.","best":true},{"text":"Tell yourself it was a grey area, and move on","then":"It works for a day. Then the memory comes back."},{"text":"Decide to stop drinking and put it behind you","then":"You stop drinking, but you never look at what went wrong."},{"text":"Ask friends if they think you did anything wrong","then":"Your friends say it's fine. It doesn't feel fine."}],"why":"Seeking help to own it and change is the adult move. The fault was never hers."}],"debrief":"Someone passed out can't consent. Owning a crossed line beats pretending, and it's never her fault.","relearn":"Anything while someone's passed out had no consent; own it and seek help."},
  {"id":"cr-1014","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"leaving the bar","hook":"Leaving a bar, your mate Rishi is wasted and wants to go home with a woman he just met.","steps":[{"prompt":"He's swaying and slurring his words. What do you do?","options":[{"text":"Slow it: \"Come with us. Swap numbers for later\"","then":"Rishi grumbles, but swaps numbers with her. She waves and heads off.","best":true},{"text":"Wave him off. He's a grown adult","then":"Rishi stumbles after her, patting his pockets for his wallet as she gets in her cab."},{"text":"Tell her loudly that Rishi's too drunk to think","then":"She looks embarrassed. Rishi, mortified, sways on the kerb."},{"text":"Get her number yourself, just in case","then":"You have her number. Rishi is still swaying by the cab door."}],"why":"Grown adults still can't consent when wasted. A gentle redirect keeps him safe."},{"prompt":"Her cab pulls away. Rishi slurs that he'll take the next one and follow her. What do you say?","options":[{"text":"\"Okay, but I'll ride along in the cab too\"","then":"Rishi shrugs. In the cab, he can't remember where she lives."},{"text":"\"Fine. Go. I'm not your mum\"","then":"Rishi grins, then gives up on booking a cab and sits on the kerb."},{"text":"\"You're too drunk to even stand straight\"","then":"Rishi scowls. \"I'm fine!\" he shouts, and nearly falls."},{"text":"\"Tomorrow, sober. Tonight we get you home\"","then":"Rishi mutters, then laughs. \"Fine. Home.\"","best":true}],"why":"Framing it as \"tomorrow\" keeps both his choice and his safety."},{"prompt":"Next morning, a hungover Rishi asks what happened last night. What do you say?","options":[{"text":"\"You nearly made a huge mistake last night, bro\"","then":"Rishi feels judged and stops replying."},{"text":"\"Ha. You were a total legend last night\"","then":"Rishi sends a laughing emoji. He still doesn't know what happened."},{"text":"Tell him plainly, and that seeing her is his call","then":"Rishi winces, then laughs. \"Sober me is less sure. We'll see.\"","best":true},{"text":"\"Don't worry about it. Nothing happened at all\"","then":"Rishi seems relieved, and a little confused."}],"why":"Clear, judgement-free facts let him decide sober what he wants."}],"debrief":"Numbers can be swapped tomorrow; a wasted mate gets home safe tonight.","relearn":"Redirect a wasted mate to safety; tomorrow they can decide clear-headed."},
  {"id":"cr-1015","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"sober-duty","hook":"You're sober. Parth, who you're with, has had three quick drinks and is getting sloppy.","steps":[{"prompt":"He pulls you closer and says he wants to go somewhere private. What do you do?","options":[{"text":"Use the moment while he's all loosened up","then":"Parth stumbles as he stands. He can barely keep his balance."},{"text":"Pause, get water, and check in once he's clearer","then":"Parth sighs but sips the water, and slumps back into his chair.","best":true},{"text":"Ask if he's sure, and go if he says yes","then":"Parth says \"so sure\" and nearly knocks over the table."},{"text":"Leave him there. He's not your problem tonight","then":"Parth sits alone, swaying. A few minutes later, he's calling you."}],"why":"As the sober one, you carry the duty to wait, not the right to proceed."},{"prompt":"Parth slurs that he's fine and wants to leave with you right now. What do you say?","options":[{"text":"\"I'd rather wait till you're clear. No rush\"","then":"Parth laughs. \"Fine. You're annoyingly sensible.\"","best":true},{"text":"\"Okay. If you say you're fine, you're fine\"","then":"Parth grins and stands, then grabs the table to steady himself."},{"text":"\"You're drunk and sloppy. It's not attractive\"","then":"Parth's face falls. He goes quiet and stares at his glass."},{"text":"\"Let's just go home and see how you feel there\"","then":"Parth agrees happily. You head somewhere private, and he's no clearer."}],"why":"Waiting until he's clear-headed is the sober person's job, however keen he sounds."},{"prompt":"Two days later, Parth texts, sober, that he'd love to see you again. What do you reply?","options":[{"text":"\"Only if you promise not to drink\"","then":"Parth replies \"lol ok\" but seems put off."},{"text":"\"You owe me for looking after you\"","then":"Parth sends an awkward \"haha\" and takes a while to reply."},{"text":"Wait a few days so you don't seem keen","then":"Parth assumes you're not interested and stops texting."},{"text":"\"I'd like that. Dinner this week?\"","then":"Parth replies with three yeses and a restaurant link.","best":true}],"why":"A sober yes on both sides is what makes it good. No need to punish the drinking."}],"debrief":"The sober person holds the duty to pause, not the right to proceed.","relearn":"As the sober one, you hold the duty to pause, not to proceed."},
  {"id":"cr-1016","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"spiking awareness","hook":"At a house party, a guy called Mohit tops up your drink with \"a little extra\" without asking.","steps":[{"prompt":"He grins and says it'll help you loosen up. What do you do?","options":[{"text":"Tell yourself you're overreacting, and keep the glass","then":"You hold it but don't drink. The unease doesn't go away."},{"text":"Pour it out, then leave your fresh drink on a table","then":"When you come back, your glass has moved slightly."},{"text":"Decline, get a fresh drink, and keep it with you","then":"Mohit shrugs and wanders off. Your new glass stays in your hand.","best":true},{"text":"Assume it's just extra rum, since he seems friendly","then":"You look at the glass again. You're not sure what \"extra\" was."}],"why":"Your glass, your call. Staying clear-headed is your right, not a fuss."},{"prompt":"Your friend Anjali notices you look uneasy. What do you tell her?","options":[{"text":"Nothing. You don't want to spoil her night","then":"Anjali goes back to dancing. You watch Mohit from across the room, alone."},{"text":"What Mohit did, and ask her to stick with you","then":"Anjali's eyes narrow. \"Okay. We stay together tonight,\" she says.","best":true},{"text":"That it's probably nothing, just a weird guy","then":"Anjali shrugs and says to ignore him. The feeling stays."},{"text":"That you'll go and confront Mohit on your own","then":"Anjali looks worried as you head across the room towards him."}],"why":"Telling a trusted friend means you're not handling it alone."},{"prompt":"Later, Anjali says she feels strangely dizzy after one drink. What do you do?","options":[{"text":"Stay with her, and call 112 if it gets worse","then":"You sit her down with water. Two friends come and stay close.","best":true},{"text":"Tell her to sleep it off in a spare room","then":"Anjali lies down alone as people drift in and out."},{"text":"Tell her she must have drunk more than she thinks","then":"Anjali frowns. \"I really only had one,\" she insists."},{"text":"Go find Mohit and demand to know what he did","then":"Mohit laughs you off. Anjali is left alone on the sofa."}],"why":"Staying with her, and calling 112 if it gets worse, is what keeps her safe."},{"prompt":"Next day, Anjali says she feels stupid for not watching her glass. What do you say?","options":[{"text":"\"Yeah, we both need to be more careful\"","then":"Anjali nods, and blames herself a little more."},{"text":"\"Let's just forget it. You're fine now\"","then":"Anjali agrees, but she stays quiet all day."},{"text":"\"You should report it, or it'll happen again\"","then":"Anjali tenses. \"I'm not ready for that,\" she says."},{"text":"\"It's not your fault. It's on whoever did this\"","then":"Anjali nods slowly. \"I needed to hear that,\" she says.","best":true}],"why":"It's never her fault, or yours. The blame sits only with whoever tampered with the drink."}],"debrief":"Your glass, your call. If a drink is tampered with, it's never your fault. Stay together and get help.","relearn":"You decide what's in your glass; staying clear-headed is your right."},
  {"id":"cr-1017","cat":"drinks-and-capacity","type":"branch","persona":"Ananya","source":"naming your own limit","hook":"After a party you're quite drunk, and your sober partner Kabir wants to be intimate.","steps":[{"prompt":"You're not really sure you want to. What do you do?","options":[{"text":"Tell yourself partners don't turn each other down","then":"You go quiet, and Kabir waits, unsure what you want."},{"text":"Say it: \"I'm too gone tonight. Let's wait.\"","then":"Kabir pauses, then nods and fetches you a glass of water.","best":true},{"text":"Ask Kabir what he thinks you should do","then":"He laughs and says it's your call. You still haven't said what you feel."},{"text":"Wonder if being drunk means your doubt doesn't count","then":"You talk yourself into doubting the feeling, and it only sits heavier."}],"why":"Naming your limit out loud is enough. Drunk and unsure already means wait."},{"prompt":"Next morning over chai, Kabir says last night felt a bit off. What do you say?","options":[{"text":"Apologise for ruining the night","then":"Kabir says it's fine, and now your wait feels like something to say sorry for."},{"text":"Promise it'll be different next time you drink","then":"Kabir looks pleased. You've promised something about a night you can't predict."},{"text":"Tell him drunk and unsure means you wait","then":"Kabir nods slowly. \"Okay. That's easy to remember.\"","best":true},{"text":"Change the subject to breakfast plans","then":"The talk moves on, and next time neither of you knows where you stand."}],"why":"Saying your rule while sober means he knows next time. A wait never needs an apology."},{"prompt":"A week later, your friend Ishita says a drunk 'no' is just nerves. What do you say?","options":[{"text":"Laugh it off to keep things light","then":"Ishita moves on, and the idea goes unanswered."},{"text":"Agree that maybe you overreacted","then":"Ishita nods, and you start wondering if you should have kept quiet."},{"text":"Say a drunk limit counts as much as a sober one","then":"Ishita pauses: \"Fair. I'd want mine to count too.\"","best":true},{"text":"Say it's fine if the drunk one said yes earlier","then":"Ishita nods, and a yes from hours ago starts to outrank tonight."}],"why":"Your own limit counts drunk or sober. \"I'm too gone, so let's wait\" is enough."}],"debrief":"You can stop yourself too. \"I'm too gone, so let's wait\" is a full sentence.","relearn":"You can name your own limit; \"I'm too gone, so let's wait\" is enough."},
  {"id":"cr-1018","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"power + drink","hook":"At the office party, Tanvi, a junior on your team, is drunk and very friendly with you.","steps":[{"prompt":"She leans on your arm and says you're her favourite boss. What do you do?","options":[{"text":"Step back and check she has a safe way home","then":"Tanvi points to her flatmate Megha, who takes her arm and books a cab.","best":true},{"text":"Read it as a sign she's interested","then":"You stay close, and a couple of colleagues start watching the two of you."},{"text":"Offer to drop her home yourself, just you two","then":"Tanvi agrees without really thinking, and a colleague glances at you, uneasy."},{"text":"Leave the party so there's no awkwardness","then":"You slip out. Tanvi stays on, drunk, with no one checking how she gets home."}],"why":"Rank plus drink means any yes isn't free. Your job is getting her home safe."},{"prompt":"That night, a colleague messages that Tanvi clearly has a crush on you. What do you say?","options":[{"text":"Laugh along, since it's only office banter","then":"The joke spreads, and by Monday it's a rumour with Tanvi's name in it."},{"text":"Say you'd go for it if she asked you sober","then":"Your colleague grins, and the idea that rank doesn't matter goes unchallenged."},{"text":"Shut it down: she was drunk, and you're her boss","then":"Your colleague replies: \"Fair. Didn't think of it that way.\"","best":true},{"text":"Ignore the joke and reply only about Monday's work","then":"Your colleague sends 'haha ok' and takes your dodge as a maybe."}],"why":"Naming the drink and the rank stops a rumour before it starts."},{"prompt":"On Monday, Tanvi messages, embarrassed about how she acted. How do you reply?","options":[{"text":"Tease her about how friendly she got","then":"Tanvi sends a stiff 'haha sorry' and goes quiet in meetings all week."},{"text":"Suggest a drink after work to clear the air","then":"Tanvi says yes quickly, unsure if she can say no to her boss."},{"text":"Say no harm done, and keep it about work","then":"Tanvi replies with relief, and the next team meeting feels normal.","best":true},{"text":"Say she can come to you for anything, anytime","then":"Tanvi thanks you, but she isn't sure what her boss means by it."}],"why":"Keeping it about work shows her the power gap won't be used."},{"prompt":"At the next team dinner, another senior keeps topping up Tanvi's glass. What do you do?","options":[{"text":"Arrange shared cabs home for the whole team","then":"Tanvi looks relieved, and the senior shrugs and joins another cab.","best":true},{"text":"Say nothing. It's not your business","then":"The senior offers Tanvi a lift, and you leave feeling uneasy."},{"text":"Accuse him of hitting on her, in front of everyone","then":"He gets defensive, the table goes silent, and Tanvi looks mortified."},{"text":"Offer to drive Tanvi home yourself instead","then":"Tanvi agrees awkwardly. One senior has just replaced another."}],"why":"A group plan protects her quietly, and no senior ends up alone with a drunk junior."}],"debrief":"Seniority plus alcohol erases a free yes; your job is to keep them safe.","relearn":"Rank plus drink means no free yes; use your position to protect."},
  {"id":"cr-1019","cat":"drinks-and-capacity","type":"branch","persona":"Meena","source":"bystander / stranger","hook":"At a mela, you spot a drunk stranger asleep on a bench, bag open, no friends around.","steps":[{"prompt":"People walk past without looking. What do you do?","options":[{"text":"Zip their bag shut and walk on","then":"The bag is safer. They're still out cold and alone as the crowd grows."},{"text":"Wake them gently and stay till someone comes","then":"They stir, confused, and mumble that their friends went for food.","best":true},{"text":"Walk on. It's not your problem","then":"You reach the food stalls but keep glancing back at the bench."},{"text":"Film them so someone in a group recognises them","then":"The video gets shared, and people laugh at it more than they help."}],"why":"A minute of looking out helps someone too far gone to look out for themselves."},{"prompt":"Soon a man they don't seem to know sits beside them and tries to get them up to leave. What do you do?","options":[{"text":"Let him, since he seems to know what to do","then":"He tugs their arm. They pull away, dazed, and he wanders off, leaving them alone."},{"text":"Ask if he knows them, then leave it to him","then":"He says \"yes, yes\" too quickly, then walks off when they won't get up."},{"text":"Shout at him to get lost","then":"He shouts back, and a crowd gathers before he stalks off."},{"text":"Sit with them and call a steward over","then":"The man shrugs and drifts off. A steward in a bright vest walks over.","best":true}],"why":"Staying close and bringing in a steward keeps them safe without a fight."},{"prompt":"A little later, they're sitting up, shaky, with a dead phone and no friends in sight. What do you do?","options":[{"text":"Lend your phone so they can call a friend","then":"Their friend picks up on the second ring and is there in ten minutes.","best":true},{"text":"Give them money for an auto and leave","then":"They take it and wobble towards the road alone, and you lose sight of them."},{"text":"Tell them they shouldn't drink alone at a mela","then":"They look ashamed, turn away from you, and stay sitting there, shaky."},{"text":"Take them back to your own room to rest","then":"They hesitate, unsure of you, and say they just want their friends."}],"why":"Getting them to their own people helps, without taking over their choices."}],"debrief":"Looking out extends to strangers, not just your own circle.","relearn":"A consent culture looks out for strangers too, not just your circle."},
  {"id":"cr-1020","cat":"drinks-and-capacity","type":"branch","persona":"any","source":"both-drunk","hook":"You and Siddharth, your crush for weeks, are both quite drunk and walking the same way.","steps":[{"prompt":"At his gate, he asks if you want to come up. What do you do?","options":[{"text":"Go up, since you both clearly want it","then":"Upstairs, you're both swaying too much to talk, and you doze off on his sofa."},{"text":"Say goodnight and plan to meet sober","then":"He looks a bit let down, then grins. \"Tomorrow, then? Sober?\"","best":true},{"text":"Go up, but agree nothing will happen","then":"Upstairs, the agreement already feels blurry. You both doze off mid-sentence."},{"text":"Walk off without a word, embarrassed","then":"Siddharth texts: \"Did I do something wrong?\" You don't know how to answer."}],"why":"Both wanting it doesn't make either of you sober enough to agree tonight."},{"prompt":"The next day, Siddharth asks if you're still keen on him. What do you say?","options":[{"text":"Say yes, and suggest dinner this week, clear-headed","then":"He grins and names a place near your college. It feels real.","best":true},{"text":"Give a vague 'haha, maybe'","then":"He says 'ok', and things go quiet between you."},{"text":"Suggest drinks again, to pick up where you left off","then":"He agrees. Whether you'll both be clear enough to choose never comes up."},{"text":"Pretend you don't remember much","then":"He sounds hurt: \"Oh. Okay.\" The spark cools."}],"why":"A sober plan lets something real start when you can both actually choose it."},{"prompt":"Your friend Nisha says drunk hook-ups are fine if both people want it. What do you say?","options":[{"text":"Agree, as long as both are into it","then":"Nisha nods, and 'into it' quietly replaces 'able to choose'."},{"text":"Say it's fine if nobody regrets it later","then":"Nisha shrugs, and whether you could both choose never comes up."},{"text":"Say drunk wanting isn't the same as choosing","then":"Nisha thinks for a second. \"Hm. Fair. Sober is clearer.\"","best":true},{"text":"Tell her it's none of her business","then":"Nisha raises her eyebrows and drops it, a bit stung."}],"why":"If it's real, it keeps till you're both clear. Sober beats rushed."}],"debrief":"If it's real, it keeps till you're both clear; no rush, no regret.","relearn":"If it's real it keeps till you're both clear; sober beats rushed."},
  {"id":"cr-1021","type":"sort","hook":"Sort: a free, sober-enough yes, or no real yes?","items":[{"id":"a","text":"Clear-eyed 'yes, I want to'"},{"id":"b","text":"Slurred 'mmhmm' while half-asleep"},{"id":"c","text":"Bright, eager 'absolutely'"},{"id":"d","text":"A mumble after passing out earlier"},{"id":"e","text":"Sober, smiling, 'let's'"},{"id":"f","text":"A blackout-drunk 'whatever'"}],"bins":[{"id":"yes","label":"A real yes","valence":"pos"},{"id":"no","label":"No real yes","valence":"neg"}],"key":{"a":"yes","b":"no","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"A real yes is clear and sober-enough; a slurred, half-asleep or blackout 'yes' isn't.","persona":"any","source":"real-yes vs not","cat":"drinks-and-capacity"},
  {"id":"cr-1022","type":"sort","hook":"Sort: keeping a party safe, or putting someone at risk?","items":[{"id":"a","text":"Walking a drunk friend to a cab"},{"id":"b","text":"Daring someone to down shots fast"},{"id":"c","text":"Keeping an eye on everyone's drinks"},{"id":"d","text":"Egging on someone already wasted"},{"id":"e","text":"Offering water and snacks around"},{"id":"f","text":"Locking a drunk guest in a room"}],"bins":[{"id":"safe","label":"Keeps it safe","valence":"pos"},{"id":"risk","label":"Puts at risk","valence":"neg"}],"key":{"a":"safe","b":"risk","c":"safe","d":"risk","e":"safe","f":"risk"},"relearn":"Cabs, water and watching out keep a party safe; pushing drink or trapping people doesn't.","persona":"any","source":"party safety","cat":"drinks-and-capacity"},
  {"id":"cr-1023","type":"sort","hook":"Sort: wait, or okay to go ahead?","items":[{"id":"a","text":"They're alert and keenly saying yes"},{"id":"b","text":"They've gone quiet and glassy-eyed"},{"id":"c","text":"They're clear and asking for you"},{"id":"d","text":"You can't tell if they're with it"},{"id":"e","text":"They're sober and enthusiastic"},{"id":"f","text":"They keep nodding off"}],"bins":[{"id":"go","label":"Okay to go ahead","valence":"pos"},{"id":"wait","label":"Wait","valence":"neg"}],"key":{"a":"go","b":"wait","c":"go","d":"wait","e":"go","f":"wait"},"relearn":"Alert, clear and keen is a go; quiet, unsure or nodding off means wait.","persona":"any","source":"go-or-wait","cat":"drinks-and-capacity"},
  {"id":"cr-1024","type":"sort","hook":"Sort: care for a drunk friend, or taking advantage?","items":[{"id":"a","text":"Holding their hair while they're sick"},{"id":"b","text":"Going through their phone while they're out"},{"id":"c","text":"Texting their roommate to expect them"},{"id":"d","text":"Kissing them while they're half-conscious"},{"id":"e","text":"Sitting with them till they sober up"},{"id":"f","text":"Posing them for a photo passed out"}],"bins":[{"id":"care","label":"Care","valence":"pos"},{"id":"abuse","label":"Taking advantage","valence":"neg"}],"key":{"a":"care","b":"abuse","c":"care","d":"abuse","e":"care","f":"abuse"},"relearn":"Holding their hair and sitting with them is care; touching or exposing them isn't.","persona":"any","source":"care vs advantage","cat":"drinks-and-capacity"},
  {"id":"cr-1025","type":"sort","hook":"Sort: this person has capacity to consent, or not right now?","items":[{"id":"a","text":"Steady, chatting, clearly present"},{"id":"b","text":"Can't finish a sentence"},{"id":"c","text":"One beer in, totally lucid"},{"id":"d","text":"Eyes closed, no response"},{"id":"e","text":"Laughing, sharp, fully here"},{"id":"f","text":"Stumbling, words a blur"}],"bins":[{"id":"has","label":"Has capacity","valence":"pos"},{"id":"none","label":"Not right now","valence":"neg"}],"key":{"a":"has","b":"none","c":"has","d":"none","e":"has","f":"none"},"relearn":"Present, lucid and steady has capacity; can't-finish-a-sentence or no-response does not.","persona":"any","source":"capacity present","cat":"drinks-and-capacity"},
  {"id":"cr-1026","type":"sort","hook":"Sort: builds a consent culture at parties, or erodes it?","items":[{"id":"a","text":"'You good? Want me to walk you out?'"},{"id":"b","text":"'Don't be boring, one more shot'"},{"id":"c","text":"Checking the quiet one's okay"},{"id":"d","text":"Laughing off a friend's 'I'm done'"},{"id":"e","text":"Making sure everyone gets home"},{"id":"f","text":"Cheering a blackout as a 'good night'"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Checking in and seeing people home builds it; pushing drink or mocking limits erodes it.","persona":"any","source":"builds vs erodes","cat":"drinks-and-capacity"},
  {"id":"cr-1027","type":"sort","hook":"Sort: a free choice, or a pressured-by-drink one?","items":[{"id":"a","text":"'I'd love to, yeah'"},{"id":"b","text":"'Fine, you keep filling my glass'"},{"id":"c","text":"'Yes, I'm really into this'"},{"id":"d","text":"'I guess, if you'll stop nagging'"},{"id":"e","text":"'Definitely, let's'"},{"id":"f","text":"'Okay, just so you'll leave it'"}],"bins":[{"id":"free","label":"Free choice","valence":"pos"},{"id":"pressed","label":"Pressured","valence":"neg"}],"key":{"a":"free","b":"pressed","c":"free","d":"pressed","e":"free","f":"pressed"},"relearn":"A keen 'I'd love to' is free; a worn-down or topped-up 'fine, I guess' is pressured.","persona":"any","source":"free vs pressured","cat":"drinks-and-capacity"},
  {"id":"cr-1028","type":"sort","hook":"Sort: looking after yourself at a party, or leaving yourself exposed?","items":[{"id":"a","text":"Pacing drinks, eating something"},{"id":"b","text":"Leaving a drink unwatched all night"},{"id":"c","text":"Telling a friend your plan"},{"id":"d","text":"Going off alone, too drunk to walk"},{"id":"e","text":"Keeping your phone charged"},{"id":"f","text":"Accepting an open drink from a stranger"}],"bins":[{"id":"care","label":"Looks after you","valence":"pos"},{"id":"expose","label":"Leaves you exposed","valence":"neg"}],"key":{"a":"care","b":"expose","c":"care","d":"expose","e":"care","f":"expose"},"relearn":"Pacing, eating and a charged phone look after you; unwatched drinks and going off alone don't.","persona":"Meena","source":"self-care (not blame)","cat":"drinks-and-capacity"},
  {"id":"cr-1029","type":"sort","hook":"Sort: a fact about capacity that's true, or a myth?","items":[{"id":"a","text":"Asleep means no consent, always"},{"id":"b","text":"'They drank, so it's allowed'"},{"id":"c","text":"Unsure of capacity means wait"},{"id":"d","text":"'Both drunk cancels it out'"},{"id":"e","text":"Tipsy-but-with-it can agree"},{"id":"f","text":"'Too gone to refuse is a yes'"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Asleep is no consent and unsure means wait; 'they drank so it's allowed' is a myth.","persona":"any","source":"true vs myth","cat":"drinks-and-capacity"},
  {"id":"cr-1030","type":"sort","hook":"Sort: a green flag at a party, or a red one?","items":[{"id":"a","text":"'Let's get you water first'"},{"id":"b","text":"'Drink up, you're no fun sober'"},{"id":"c","text":"'We can wait till you're clearer'"},{"id":"d","text":"'Nobody has to know'"},{"id":"e","text":"'I'll text when you're home safe'"},{"id":"f","text":"'Come on, you owe me after all this'"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Offering water and waiting are green; pushing drink, secrecy or 'you owe me' are red.","persona":"any","source":"green vs red","cat":"drinks-and-capacity"},
  {"id":"cr-1031","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"sober partner","hook":"You're sober, and Riya, the person you're with, is too drunk to really agree to anything.","setup":"Back at your place, she's leaning in, slurring a little.","steps":[{"prompt":"Riya says: \"Come on. I said yes earlier, remember?\"","options":[{"text":"\"You did say yes earlier, so I guess it's okay.\"","then":"Riya giggles and nearly loses her balance. She's clearly not all there."},{"text":"\"You're pretty gone. Let's get you water and wait.\"","then":"Riya pouts, then sighs: \"Fine. Water. But you're boring.\"","best":true},{"text":"\"Only if you're really, really sure, okay?\"","then":"Riya slurs: \"So sure.\" She's struggling to keep her eyes open."},{"text":"\"Not tonight. I don't do sloppy drunk people.\"","then":"Riya's face falls: \"Wow. Okay.\" She turns away, hurt."}],"why":"Someone that drunk can't consent, even after an earlier yes. Water and waiting is how you care."},{"prompt":"Riya mumbles, half asleep: \"Wait. What are we doing again?\"","options":[{"text":"\"You're a lot when you drink, you know.\"","then":"Riya pulls the blanket up: \"Sorry for existing, then.\""},{"text":"\"Getting you water and sleep. That's all.\"","then":"Riya smiles, eyes closing: \"Okay. That's nice.\" She's asleep in minutes.","best":true},{"text":"\"Nothing. Just go to sleep.\"","then":"Riya frowns: \"Are you annoyed with me?\" She sounds small."},{"text":"\"We'll do it in the morning. Promise.\"","then":"Riya grins sleepily: \"Promise?\" The morning now feels like a deal."}],"why":"Plain, warm words tell her you're simply looking after her, with no shame."},{"prompt":"Next morning, Riya asks: \"Did anything happen last night? I can't remember.\"","options":[{"text":"\"Don't worry about it.\"","then":"Riya looks worried: \"That's not an answer.\""},{"text":"\"You were all over me. It was funny.\"","then":"Riya goes red: \"Oh no. I'm so embarrassed.\""},{"text":"\"Nothing much. You were really fun, though.\"","then":"Riya frowns: \"Nothing much? What does that mean?\""},{"text":"\"No. You were too drunk, so we just slept.\"","then":"Riya breathes out: \"Thank you. Honestly. Let's try again sober.\"","best":true}],"why":"A clear, honest answer leaves her no doubt and no shame."}],"relearn":"Naming it kindly and waiting respects that they can't really agree now."},
  {"id":"cr-1032","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"stop the pile-on","hook":"At a birthday party, your friend Varun keeps pushing drinks at Pooja, who has clearly had enough.","setup":"You're standing right beside them at the snacks table.","steps":[{"prompt":"Varun laughs: \"One more, Pooja! Birthday rules!\"","options":[{"text":"\"Come on, Pooja, just one more for the birthday!\"","then":"Pooja takes the glass, looking unsure, and everyone cheers."},{"text":"\"Varun, you're being a total jerk right now.\"","then":"Varun bristles: \"Chill, it's a party.\" The table goes awkward."},{"text":"\"Pooja, you can say no, you know.\"","then":"Pooja gives a tight smile: \"I did.\" Varun keeps holding out the glass."},{"text":"\"She's good, yaar. Leave it. Let's get water.\"","then":"Varun shrugs: \"Fine, fine.\" He puts the glass down and turns to the cake.","best":true}],"why":"A light, firm line stops the pile-on without making a scene."},{"prompt":"Later, Varun asks: \"Was I too much with Pooja earlier?\"","options":[{"text":"\"Nah, she's an adult. Her call.\"","then":"Varun relaxes: \"Right. Just having fun.\" He fills another round."},{"text":"\"A bit. Once she says no, drop it.\"","then":"Varun winces: \"Yeah. Okay. I'll say sorry to her.\"","best":true},{"text":"\"You always do this at parties.\"","then":"Varun gets defensive: \"Always? Wow. Thanks.\""},{"text":"\"Doesn't matter. It's a party.\"","then":"Varun nods, relieved, and the question never gets answered."}],"why":"Honest and simple: a no ends the offer, whatever the occasion."},{"prompt":"At the next party, Varun shouts: \"Round two! Nobody's allowed to say no!\"","options":[{"text":"\"You heard him. No one says no!\"","then":"Varun cheers, and a couple of people take shots they didn't want."},{"text":"\"Not again, Varun. Seriously.\"","then":"Varun laughs it off: \"Killjoy!\" He keeps pouring for everyone."},{"text":"\"Anyone who wants one. No pushing.\"","then":"Varun grins: \"Fine. Anyone who wants one.\" A few people wave it off, relaxed.","best":true},{"text":"\"I'm out. You lot do what you want.\"","then":"Varun shrugs: \"Your loss.\" He pours for everyone anyway."}],"why":"Changing the rule for the room ends the pressure without shaming anyone."}],"relearn":"A light, firm 'they're good, leave it' stops the pile-on without a scene."},
  {"id":"cr-1033","cat":"drinks-and-capacity","type":"role-play","persona":"Ananya","source":"your own limit","hook":"You're drunk after a sangeet, and your partner Dev is keen, but you're not feeling it tonight.","setup":"Back in your room, he sits down beside you.","steps":[{"prompt":"Dev asks: \"Hey, you okay? You've gone quiet.\"","options":[{"text":"\"It's just a headache. Maybe later, okay?\"","then":"Dev nods: \"I'll get you something for it.\" The real reason stays unsaid."},{"text":"\"Sorry, I'm being so boring tonight.\"","then":"Dev laughs: \"You're not boring. Come here.\" He hasn't understood."},{"text":"\"I don't know. What do you want to do?\"","then":"Dev smiles: \"Honestly? I've missed you all day.\""},{"text":"\"I'm too out of it tonight. I'd rather sleep.\"","then":"Dev nods: \"Sure. Want some water first?\"","best":true}],"why":"Naming your limit plainly is enough, drunk or not."},{"prompt":"Dev says quietly: \"We haven't had a night alone in weeks.\"","options":[{"text":"\"You're right. I'm being unfair.\"","then":"Dev pauses, unsure what you mean: \"No, it's okay. Let's just sleep.\""},{"text":"\"I know. I guess partners can't really say no.\"","then":"Dev blinks: \"What? Of course they can.\""},{"text":"\"Can we just talk about it tomorrow instead?\"","then":"Dev shrugs: \"Sure.\" It hangs over breakfast the next day."},{"text":"\"I know. But I want to wait till I'm clear.\"","then":"Dev sighs, then smiles: \"Fair. Sleep, then. I'll get the lights.\"","best":true}],"why":"Holding your limit is fair, and it's never something to apologise for."},{"prompt":"Next morning, Dev asks: \"Did I make you feel bad last night?\"","options":[{"text":"\"Let's just never drink together again.\"","then":"Dev frowns: \"Never? That feels like a big fix for one night.\""},{"text":"\"No, no. Forget it.\"","then":"Dev shrugs: \"Okay.\" The pattern never gets talked about."},{"text":"\"No, it was my fault for drinking so much.\"","then":"Dev nods slowly, and the idea that drinking makes it your fault goes unchallenged."},{"text":"\"A little. When I'm that drunk, let's just wait.\"","then":"Dev nods: \"Sorry. Got it. When you're that drunk, we wait.\"","best":true}],"why":"Drinking never makes a no your fault. A simple rule, said sober, helps next time."}],"relearn":"You can name your own limit drunk too; 'I'd rather wait' is enough."},
  {"id":"cr-1034","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"redirect a stranger","hook":"Your friend Shreya is wasted at a party, and a guy she met tonight won't leave her side.","setup":"He's already got her bag on his shoulder by the exit.","steps":[{"prompt":"He says: \"Don't worry. I've got her. I'll drop her home.\"","options":[{"text":"\"Thanks, we've got her. I'll take her home.\"","then":"He hesitates, then hands the bag over: \"Fine. Just trying to help.\"","best":true},{"text":"\"Okay. Text me when she's home?\"","then":"He nods and steers Shreya to the door. She stumbles, and you catch her arm."},{"text":"\"Shreya, you're okay going with him, yeah?\"","then":"Shreya giggles: \"Sure, why not.\" She can barely stand."},{"text":"\"Back off, creep. I know what you're up to.\"","then":"He scoffs: \"I'm trying to help. What's your problem?\" Shreya looks confused."}],"why":"A friendly, firm 'we've got her' takes over the plan without a scene."},{"prompt":"Shreya slurs: \"I'm fine. I can decide who takes me home.\"","options":[{"text":"\"Fine, but he rides in our cab too.\"","then":"He climbs into the front seat, chatting like it's all settled."},{"text":"\"Sober, sure. Tonight, you're coming with me.\"","then":"Shreya pouts, then leans on you: \"Okay. You're bossy, but okay.\"","best":true},{"text":"\"You can't even stand. Look at yourself.\"","then":"Shreya's face crumples: \"Wow. Thanks a lot.\""},{"text":"\"Okay, he can wait here with us till you sober up.\"","then":"He sits down too, very close to Shreya, in no hurry to leave."}],"why":"It keeps her choice for when she can really make it, and keeps her safe till then."},{"prompt":"Next day, Shreya texts: \"Did I do anything stupid last night?\"","options":[{"text":"\"You almost left with a random guy!\"","then":"Shreya replies: \"Oh no. I'm such an idiot.\""},{"text":"\"Guys like him only want one thing.\"","then":"Shreya replies: \"You don't know that.\" She sounds annoyed."},{"text":"\"You should be more careful who you talk to.\"","then":"Shreya goes quiet, then replies: \"So it's my fault?\""},{"text":"\"Nothing stupid. He tried to take you home.\"","then":"Shreya replies: \"Wait, he did? Thanks for looking out for me.\"","best":true}],"why":"She deserves to know what happened, without shame or blame, and that you had her back."},{"prompt":"Shreya adds: \"He messaged. Should I see him again?\"","options":[{"text":"\"No way. Block him.\"","then":"Shreya replies: \"Relax. It's my decision.\""},{"text":"\"Sure, just don't drink as much this time.\"","then":"Shreya replies: \"So it's on me to stay sober?\""},{"text":"\"Only if I come along to check him out.\"","then":"Shreya replies: \"I'm not twelve.\""},{"text":"\"Your call. Maybe meet somewhere public, in daytime?\"","then":"Shreya replies: \"Coffee at noon. I like that.\"","best":true}],"why":"Respecting her choice, with a safer plan, treats her as the adult she is."}],"relearn":"'We've got them' redirects a stranger and keeps a wasted friend safe."},
  {"id":"cr-1035","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"hold your line","hook":"At a hostel party, Kunal keeps topping up your glass after you've had all you want.","setup":"A few people are watching, glasses raised.","steps":[{"prompt":"Kunal says: \"Just one more. Don't be so uptight.\"","options":[{"text":"\"Sorry, I've got an early class. Otherwise I would.\"","then":"Kunal grins: \"Class is at ten! Plenty of time.\""},{"text":"\"God, Kunal, no wonder nobody likes you.\"","then":"Kunal flushes: \"Wow. Harsh.\" Now everyone's talking about your dig, not his pushing."},{"text":"\"I'm good, thanks. I like staying clear.\"","then":"Kunal shrugs: \"Fair enough.\" He moves on to top up someone else.","best":true},{"text":"\"Maybe later, okay?\"","then":"Kunal winks: \"I'll hold you to that.\""}],"why":"A plain, friendly no needs no excuse and leaves nothing to argue with."},{"prompt":"Later, Kunal comes back and says: \"Last chance. Don't embarrass me.\"","options":[{"text":"\"Sorry, sorry. I know I'm being a buzzkill.\"","then":"Kunal laughs: \"Then fix it. One shot.\""},{"text":"\"At least I'll remember tonight, unlike you lot.\"","then":"Kunal's face hardens: \"Wow. Okay, judgy.\""},{"text":"\"Still good, thanks. I'm off to find Farah.\"","then":"Kunal rolls his eyes: \"Fine.\" Farah waves you over to her corner.","best":true},{"text":"\"I'm on antibiotics. That's the only reason.\"","then":"Kunal nods: \"Oh, fair.\" Next party, he'll ask again."}],"why":"Repeating your line and moving to a friend ends it. Being pushed is never your fault."},{"prompt":"A week later, Farah whispers: \"How do you say no to Kunal? He won't let me.\"","options":[{"text":"\"Fake a sip and tip it into a plant.\"","then":"Farah laughs: \"And do that all night?\""},{"text":"\"Just have one. Honestly, it's easier than arguing.\"","then":"Farah sighs: \"That's what I always end up doing.\""},{"text":"\"I'll go and tell Kunal off for you right now.\"","then":"Farah looks uneasy: \"Please don't make it a scene.\""},{"text":"\"Say 'I'm good', and repeat it. I'll stick by you.\"","then":"Farah smiles: \"I can say that. Stay near me next time?\"","best":true}],"why":"A short line, repeated, with a friend nearby, works better than any trick."}],"relearn":"You can hold your line on drinking without owing anyone an apology."},
  {"id":"cr-1036","cat":"drinks-and-capacity","type":"role-play","persona":"any","source":"back a friend up","hook":"At a club, your drunk friend Tara whispers that she feels unsafe with the guy she came with.","setup":"He's at the bar, glancing over at you both.","steps":[{"prompt":"Tara grips your arm: \"He keeps saying I owe him for the ticket.\"","options":[{"text":"\"You came with him, so you'll just have to deal.\"","then":"Tara's face drops: \"Right. Okay.\" She looks towards the bar, scared."},{"text":"\"I'll go and sort him out right now.\"","then":"Tara pulls you back: \"No! Please don't make it worse.\""},{"text":"\"Just pay him back for the ticket, then.\"","then":"Tara hesitates: \"Then he'll say I owe him something else.\""},{"text":"\"Stick with me. You go nowhere you don't want to.\"","then":"Tara lets out a breath: \"Okay. Thank you. I didn't know who to tell.\"","best":true}],"why":"Staying by her side tells her she's not alone, and the choice stays hers."},{"prompt":"Tara says: \"He's my ride home, and my phone's almost dead.\"","options":[{"text":"\"Ask him nicely to just drop you home.\"","then":"Tara shakes her head: \"He won't listen. He never does.\""},{"text":"\"Come in my cab. Use my power bank.\"","then":"Tara nods, plugs in the power bank, and stays close to you.","best":true},{"text":"\"Why did you even come with him?\"","then":"Tara flinches: \"I didn't know he'd be like this.\""},{"text":"\"Call your parents to come and get you.\"","then":"Tara panics: \"My parents? They'll never let me out again.\""}],"why":"A practical way home, with you, keeps her safe on her terms."},{"prompt":"Next day, Tara texts: \"Maybe I overreacted. He's not that bad.\"","options":[{"text":"\"You felt unsafe. That's real. Not your fault.\"","then":"Tara replies: \"Thanks. I think I needed someone to say that.\"","best":true},{"text":"\"Honestly? You did overreact a bit.\"","then":"Tara replies: \"Yeah. I'll say sorry to him.\""},{"text":"\"He's a creep. Block him right now.\"","then":"Tara replies: \"I can't just block him. We have the same friends.\""},{"text":"\"Either way, you're safe now. Just forget about it.\"","then":"Tara sends \"ok\". The fear she felt goes unspoken."}],"why":"Believing her, and saying it isn't her fault, helps her trust herself."},{"prompt":"A week later, Tara texts: \"He keeps messaging that I owe him. What do I do?\"","options":[{"text":"\"Just reply once and settle it with him yourself.\"","then":"Tara replies: \"He twists everything I say.\""},{"text":"\"You owe him nothing. I'm here, and 181 can help too.\"","then":"Tara replies: \"Could you sit with me when I call?\"","best":true},{"text":"\"I'll message him myself and tell him off.\"","then":"Tara replies: \"Please don't. It'll make him angrier.\""},{"text":"\"Ignore it. He'll get bored of messaging eventually.\"","then":"Tara replies: \"He's sent six today. It's not stopping.\""}],"why":"It's her call, with backup: you offer company and a real route, without taking over."}],"relearn":"'Stick with me' tells a scared friend they're not alone, and they choose."},
  {"id":"cr-1037","cat":"drinks-and-capacity","type":"role-play","persona":"Rohan","source":"honest with yourself","hook":"At a party, you realise Kavya, who you fancy, is far drunker than you thought.","setup":"She's been laughing at your jokes all night.","steps":[{"prompt":"Kavya says: \"Let's get out of here. Your place?\"","options":[{"text":"\"Eh, you seem fine enough. Let's go.\"","then":"Kavya stumbles on the stairs, and her friends insist on taking her home."},{"text":"\"Sure, but just to chill. Nothing else.\"","then":"Kavya grins: \"Whatever you say.\" She can't find her shoes, and a friend steps in."},{"text":"\"Whoa. How much have you had? That's a lot.\"","then":"Kavya's grin fades: \"Are you judging me?\""},{"text":"\"You're more gone than I thought. Coffee, sober?\"","then":"Kavya blinks, then laughs: \"You're sweet. Okay. Coffee.\"","best":true}],"why":"Calling it when she's that drunk is honest, and it keeps the door open."},{"prompt":"Your friend Aditya says: \"Drunk or not, if she asks, it's on her.\"","options":[{"text":"\"If she's that drunk, she can't really choose.\"","then":"Aditya pauses: \"Huh. Never thought about it like that.\"","best":true},{"text":"\"True. She's an adult who can make her own calls.\"","then":"Aditya nods: \"Exactly. Not your job to babysit.\""},{"text":"\"Whatever. I just wasn't feeling it.\"","then":"Aditya grins: \"Sure you weren't.\""},{"text":"\"Maybe, but it felt weird.\"","then":"Aditya shrugs: \"Weird how? You overthink.\""}],"why":"Capacity is the line. Too drunk means she can't really choose, whoever asks."},{"prompt":"Next day, Kavya texts: \"Sorry about last night. Was I a mess?\"","options":[{"text":"\"You were fun, just very drunk. Coffee this week?\"","then":"Kavya replies: \"Ha. Yes. Sober me would like that.\"","best":true},{"text":"\"Kind of, yeah. You were all over me.\"","then":"Kavya replies: \"Oh god. Sorry.\" She doesn't text again."},{"text":"\"No worries. We'll pick up where we left off.\"","then":"Kavya replies: \"Wait, where did we leave off?\" She sounds anxious."},{"text":"\"Totally fine. Hit me up next party.\"","then":"Kavya replies: \"Haha sure.\" It stays a party thing."}],"why":"A light, no-shame reply and a sober plan show real interest."}],"relearn":"Calling it when they're too drunk is the honest, respectful move."},
  {"id":"cr-1038","type":"reflect","hook":"Lensy: a night you both remember clearly beats one you have to piece together. Sit right?","prompt":"What do you think?","options":["Yeah","I'd rather wait","Clear is better"],"affirm":"Wanting a clear, mutual night isn't boring; it's what makes it good.","relearn":"A clear, mutual night is the good kind, not the dull kind.","persona":"any","source":"clarity is good","cat":"drinks-and-capacity"},
  {"id":"cr-1039","type":"reflect","hook":"Lensy: looking out for a drunk friend isn't being a buzzkill, it's being the friend. Agree?","prompt":"Where do you land?","options":["For sure","That's me","I'd want the same"],"affirm":"Watching out for a mate too drunk to watch out for themselves is real friendship.","relearn":"Watching out for a drunk friend is friendship, not being a buzzkill.","persona":"any","source":"friend not buzzkill","cat":"drinks-and-capacity"},
  {"id":"cr-1040","type":"reflect","hook":"Lensy: 'I'm too drunk, let's wait' is a sentence you're always allowed to say. True for you?","prompt":"How's that sit?","options":["True","Good to know","I'll use it"],"affirm":"You can stop things for yourself any time; being drunk doesn't take that away.","relearn":"You can stop things for yourself any time, including when drunk.","persona":"Ananya","source":"your own stop","cat":"drinks-and-capacity"},
  {"id":"cr-1041","type":"reflect","hook":"Lensy: there's no prize for not waiting when capacity is unclear. Make sense?","prompt":"What's your take?","options":["Makes sense","No rush","Waiting's fine"],"affirm":"Waiting when you're unsure costs nothing and protects you both.","relearn":"Waiting when capacity is unclear costs nothing and protects you both.","persona":"any","source":"no prize for rushing","cat":"drinks-and-capacity"},
  {"id":"cr-1042","type":"reflect","hook":"Lensy: you get to decide what's in your own glass and how clear you stay. Yours to call?","prompt":"Feel true?","options":["Mine to call","Yep","I'll own that"],"affirm":"Pacing yourself or skipping a round is yours to decide, no apology needed.","relearn":"How much you drink and how clear you stay is yours to decide.","persona":"any","source":"your glass your call","cat":"drinks-and-capacity"},
  {"id":"cr-1043","type":"reflect","hook":"Lensy: if a drink is being pushed to lower your guard, that's a flag worth trusting. Sit right?","prompt":"Where are you?","options":["Trust the flag","Good point","Noted"],"affirm":"Trusting that 'something's off' feeling about a pushed drink is wise, not paranoid.","relearn":"Trusting the 'something's off' feeling about a pushed drink is wise.","persona":"any","source":"trust the feeling","cat":"drinks-and-capacity"},
  {"id":"cr-1044","type":"reflect","hook":"Lensy: being the sober one is a quiet kind of responsibility, not a power. Agree?","prompt":"How's that land?","options":["Agree","Responsibility, yeah","I'll hold that"],"affirm":"Being clearer-headed means you carry the wait, never the right to decide for both.","relearn":"Being the sober one is responsibility to wait, not power over the other.","persona":"any","source":"sober responsibility","cat":"drinks-and-capacity"},
  {"id":"cr-1045","type":"spot","hook":"Spot who can't consent in this party scene.","scene":[{"id":"a","text":"Two friends chatting brightly over chai","trick":false},{"id":"b","text":"Someone slumped, eyes shut, not responding","trick":true},{"id":"c","text":"A couple clearly into each other, sober","trick":false},{"id":"d","text":"A person mumbling, being half-carried","trick":true},{"id":"e","text":"Mates laughing, fully alert, dancing","trick":false}],"why":"Slumped-and-unresponsive or mumbling-and-half-carried can't consent; alert people can.","relearn":"Slumped, unresponsive or barely-carried means no capacity to consent.","persona":"any","source":"who can't consent","cat":"drinks-and-capacity"},
  {"id":"cr-1046","type":"spot","hook":"Spot the pressure-by-drink moves here.","scene":[{"id":"a","text":"'Want a water or a soft drink instead?'","trick":false},{"id":"b","text":"'Down it, don't embarrass me'","trick":true},{"id":"c","text":"'No worries if you're done for tonight'","trick":false},{"id":"d","text":"'I'll keep your glass full so you relax'","trick":true},{"id":"e","text":"'Eat something, you'll feel better'","trick":false}],"why":"'Down it or embarrass me' and 'I'll keep you full to relax' are pressure, not offers.","relearn":"Daring someone to drink or topping them up to 'relax' is pressure.","persona":"any","source":"spot the pressure","cat":"drinks-and-capacity"},
  {"id":"cr-1047","type":"spot","hook":"Spot what is NOT a real, free yes.","scene":[{"id":"a","text":"A clear, smiling 'yes, I want this'","trick":false},{"id":"b","text":"A slurred 'mmh' before drifting off","trick":true},{"id":"c","text":"A sober, eager 'absolutely'","trick":false},{"id":"d","text":"A blackout 'whatever you want'","trick":true},{"id":"e","text":"A keen 'yeah, let's' wide awake","trick":false}],"why":"A slurred-then-drifting 'mmh' or a blackout 'whatever' isn't capacity to agree.","relearn":"A slurred or blackout 'yes' isn't a real, free yes.","persona":"any","source":"not a real yes","cat":"drinks-and-capacity"},
  {"id":"cr-1048","type":"spot","hook":"Spot the bystander moves that are NOT looking out.","scene":[{"id":"a","text":"Walking a wasted mate to a cab","trick":false},{"id":"b","text":"Filming a passed-out guest for laughs","trick":true},{"id":"c","text":"Texting to check they got home","trick":false},{"id":"d","text":"Leaving a drunk friend with a stranger","trick":true},{"id":"e","text":"Sitting with someone till they're okay","trick":false}],"why":"Filming a passed-out guest or abandoning a drunk friend isn't looking out, it's the opposite.","relearn":"Filming or abandoning a drunk person is the opposite of looking out.","persona":"any","source":"not looking out","cat":"drinks-and-capacity"},
  {"id":"cr-1049","type":"spot","hook":"Spot the red flags in this 'just have fun' pitch.","scene":[{"id":"a","text":"'We can stop any time, just say'","trick":false},{"id":"b","text":"'You owe me one after I paid all night'","trick":true},{"id":"c","text":"'Only if you actually want to'","trick":false},{"id":"d","text":"'Nobody needs to know about this'","trick":true},{"id":"e","text":"'Tell me if you're not feeling it'","trick":false}],"why":"'You owe me' and 'nobody needs to know' are pressure and secrecy, not a free invitation.","relearn":"'You owe me' and 'keep it secret' are red flags, not a free invitation.","persona":"any","source":"red flags in a pitch","cat":"drinks-and-capacity"},
  {"id":"cr-1050","type":"spot","hook":"Spot who is too far gone to give capacity.","scene":[{"id":"a","text":"Friend telling a clear story, laughing","trick":false},{"id":"b","text":"Person who can't stand without help","trick":true},{"id":"c","text":"Someone sober ordering food","trick":false},{"id":"d","text":"Guest asleep on the stairs, unwakeable","trick":true},{"id":"e","text":"Two sober mates planning a cab","trick":false}],"why":"Can't-stand-without-help and asleep-and-unwakeable are too far gone; the rest are fine.","relearn":"Can't stand alone or won't wake means too far gone for capacity.","persona":"any","source":"too far gone","cat":"drinks-and-capacity"},
  {"id":"cr-1051","type":"spot","hook":"Spot the harm-excusing lines about drinking.","scene":[{"id":"a","text":"'If we're unsure, we wait'","trick":false},{"id":"b","text":"'They drank, so they wanted it'","trick":true},{"id":"c","text":"'Asleep means no, always'","trick":false},{"id":"d","text":"'Both drunk, so it cancels out'","trick":true},{"id":"e","text":"'Tipsy-but-with-it can agree'","trick":false}],"why":"'They drank so they wanted it' and 'both drunk cancels out' excuse harm; the rest are true.","relearn":"'They drank so they wanted it' and 'both drunk cancels out' are harm-excusing myths.","persona":"any","source":"excuse-spotting","cat":"drinks-and-capacity"},
  {"id":"cr-1052","type":"match","hook":"Match each capacity state to the right call.","pairs":[{"left":"Sober and keen","right":"Can agree, go ahead"},{"left":"Slurring badly","right":"Too gone, wait"},{"left":"Passed out","right":"No consent, keep safe"},{"left":"One drink, lucid","right":"Still able to agree"},{"left":"Can't be woken","right":"Help, never proceed"}],"relearn":"Sober or lucid can agree; slurring, passed out or unwakeable means wait and keep safe.","persona":"any","source":"state to call","cat":"drinks-and-capacity"},
  {"id":"cr-1053","type":"match","hook":"Match the drink myth to the truth that busts it.","pairs":[{"left":"'They drank, so it's allowed'","right":"Only a willing yes allows anything"},{"left":"'Both drunk cancels out'","right":"Harm stays real if they couldn't agree"},{"left":"'Too gone to refuse is a yes'","right":"Too gone to refuse is too gone to agree"},{"left":"'They didn't push me off'","right":"Stillness is never agreement"},{"left":"'A tipsy yes always counts'","right":"With-it tipsy yes, blackout no"}],"relearn":"Each drink myth meets the truth: only a willing, sober-enough yes ever counts.","persona":"any","source":"myth to truth","cat":"drinks-and-capacity"},
  {"id":"cr-1054","type":"match","hook":"Match the situation to who you'd reach for help.","pairs":[{"left":"A friend in immediate danger now","right":"112"},{"left":"A woman facing violence, any time","right":"181"},{"left":"Harassment by a campus senior","right":"Campus Internal Committee"},{"left":"Want to talk it through privately","right":"A campus counsellor"},{"left":"Just need someone you trust","right":"A trusted adult"}],"relearn":"Danger now is 112; violence is 181; campus harm is the committee; talk to a counsellor or trusted adult.","persona":"Mehta","source":"need to route","cat":"drinks-and-capacity"},
  {"id":"cr-1055","type":"match","hook":"Match the bystander moment to the line that helps.","pairs":[{"left":"Mate being pushed to drink","right":"'They're good, leave the glass'"},{"left":"Stranger leading off a wasted guest","right":"'I've got them, thanks'"},{"left":"Friend feels unsafe with their date","right":"'Stick with me'"},{"left":"Someone alone and very drunk","right":"'Let's get you water and a ride'"},{"left":"You're too drunk yourself","right":"'I'm too gone, let's wait'"}],"relearn":"A short, calm line redirects pressure and keeps a drunk person safe.","persona":"any","source":"moment to line","cat":"drinks-and-capacity"},
  {"id":"cr-1056","type":"match","hook":"Match the action to looking out, or not.","pairs":[{"left":"Walking a drunk mate home","right":"Looking out"},{"left":"Filming them passed out","right":"Taking advantage"},{"left":"Watching everyone's drinks","right":"Keeping it safe"},{"left":"Daring shots on someone wasted","right":"Putting at risk"},{"left":"Texting that they got home","right":"Caring follow-up"}],"relearn":"Walking home, watching drinks and checking in is looking out; filming or daring shots isn't.","persona":"any","source":"action to label","cat":"drinks-and-capacity"},
  {"id":"cr-1057","type":"match","hook":"Match the phrase to whether it's a free yes or pressure.","pairs":[{"left":"'Yes, I really want to'","right":"A free yes"},{"left":"'Fine, you keep filling my glass'","right":"Pressured by drink"},{"left":"'Only if you actually want to'","right":"Inviting a real answer"},{"left":"'You owe me after tonight'","right":"Guilt-trip, not consent"},{"left":"'Let's wait till you're clearer'","right":"Respecting capacity"}],"relearn":"A keen yes and an honest check are free; a topped-up 'fine' or 'you owe me' is pressure.","persona":"any","source":"phrase to read","cat":"drinks-and-capacity"},
  {"id":"cr-1058","type":"match","hook":"Match the self-care move to what it protects.","pairs":[{"left":"Pacing your drinks","right":"Staying clear-headed"},{"left":"Telling a friend your plan","right":"Someone knows where you are"},{"left":"Watching your own glass","right":"Knowing what you drank"},{"left":"Charged phone on you","right":"You can call for help"},{"left":"Eating before drinking","right":"Staying steadier"}],"relearn":"Pacing, a told friend, a watched glass and a charged phone keep you clearer and safer.","persona":"Meena","source":"self-care to why","cat":"drinks-and-capacity"},
  {"id":"cr-1059","type":"match","hook":"Match the capacity word to its plain meaning.","pairs":[{"left":"Incapacitated","right":"Too far gone to choose"},{"left":"Sober-enough","right":"Clear enough to mean it"},{"left":"Blackout","right":"Awake but won't recall or reason"},{"left":"Revocable","right":"Can be taken back any time"},{"left":"Freely given","right":"Chosen, not pushed or owed"}],"relearn":"Consent is freely given, sober-enough and revocable; incapacitated or blackout can't give it.","persona":"any","source":"word to meaning","cat":"drinks-and-capacity"},
  {"id":"cr-900","cat":"real-situations","type":"branch","persona":"Ananya","source":"hostel room","hook":"You invite Karan back to your PG room after a movie. Once there, he assumes the night's plan is set.","steps":[{"prompt":"He kicks off his shoes and grins like it's all decided. What do you do?","options":[{"text":"Tell yourself inviting him up was a yes","then":"The thought knots your stomach. Karan sees you've gone quiet and pauses."},{"text":"Wonder if your outfit gave him ideas","then":"You glance down at your top as Karan pauses, noticing you've gone still."},{"text":"Say you wanted company, not more","then":"Karan's grin fades: \"Oh. Okay, my bad.\" He sits back.","best":true},{"text":"Apologise for giving him the wrong idea","then":"Karan says \"No worries\", as if the mix-up was yours."}],"why":"Saying it plainly is enough. Inviting someone in is never agreement to more."},{"prompt":"Karan says, a bit sulky, that people don't invite someone up just to talk. What do you do?","options":[{"text":"Say an invite is for company, not a promise of more","then":"Karan goes quiet, then nods: \"Fair. I shouldn't have assumed.\" He heads home.","best":true},{"text":"Agree it's partly your fault for inviting him","then":"Karan nods, as if the invite was a debt. Then he checks the time and leaves."},{"text":"Promise to be clearer before inviting anyone up","then":"Karan says \"Yeah, would've helped\", and leaves with the blame on you."},{"text":"Tell yourself guys can't help assuming things","then":"Karan pulls on his shoes and leaves, as if assuming was only natural."}],"why":"An invite is never a contract. What he assumed is on him."},{"prompt":"Next day, you're still shaken, and your friend Pallavi asks what's wrong. What do you do?","options":[{"text":"Say \"nothing\" and keep it to yourself","then":"Pallavi lets it go, and you carry it alone all day."},{"text":"Say you probably sent mixed signals","then":"Pallavi frowns, unsure, and you walk away blaming yourself."},{"text":"Joke about it so it sounds small","then":"Pallavi laughs along, and the shaky feeling stays hidden."},{"text":"Tell her what happened and how it felt","then":"Pallavi listens: \"That's not on you. Want me around if he calls?\"","best":true}],"why":"It's never your fault. Telling someone you trust means you don't carry it alone."},{"prompt":"At dinner in your PG, a girl says going to someone's room means you've agreed to more. What do you do?","options":[{"text":"Call it a bad take and leave it there","then":"The table shrugs, and no one hears why it's wrong."},{"text":"Say it depends on what the person was wearing","then":"A few heads nod, and the myth gets a little stronger."},{"text":"Say an invite in is never a yes to anything more","then":"She pauses: \"Huh. Put like that, yeah.\"","best":true},{"text":"Say girls should just never invite guys in","then":"A friend frowns: \"So it's on us, not on them?\""}],"why":"Every step needs its own yes, wherever you are."}],"debrief":"Inviting someone in is not a contract; every step needs its own willing yes.","relearn":"Inviting someone to your room is never agreement to anything further."},
  {"id":"cr-901","cat":"real-situations","type":"branch","persona":"any","source":"match thread","hook":"Aryan, a new match on a dating app, messages that he's booked a hotel for your first meet.","steps":[{"prompt":"He adds that he's paid already, so you have to come. What do you do?","options":[{"text":"Feel you owe him since he's paid","then":"The money sits in your head like a bill with your name on it."},{"text":"Ask a friend, who says he's paid, so just go","then":"Your friend shrugs it off, and your unease doesn't budge."},{"text":"Say you'll meet at a cafe first, at your pace","then":"Aryan replies: \"A cafe? Boring.\"","best":true},{"text":"Tell yourself this is how app dating works","then":"His plan starts to feel normal, and your unease feels silly."}],"why":"A match is interest, not a commitment. You set the where and the pace."},{"prompt":"Aryan follows up: real adults skip the small talk, so it's the hotel or nothing. What do you do?","options":[{"text":"Explain why hotels make you nervous","then":"Aryan says you're overthinking and sends the hotel link again."},{"text":"Say your pace isn't up for debate","then":"Aryan goes quiet for a few hours.","best":true},{"text":"Wonder if you're being too old-school","then":"You start doubting a pace that was always yours to set."},{"text":"Worry that backing out now would be rude","then":"The worry grows, and his plan starts to sound like yours."}],"why":"Pressure to skip your comfort is a red flag, not romance. Your pace stands."},{"prompt":"Your friend Jaya asks how the app chat is going. What do you do?","options":[{"text":"Say it's fine, so you don't look naive","then":"Jaya moves on, and you're left with the chat on your own."},{"text":"Laugh it off as a funny story","then":"Jaya laughs too, and the pushiness gets lost in the joke."},{"text":"Show her the chat and say it felt pushy","then":"Jaya reads it: \"That's a red flag. Your pace is your pace.\"","best":true},{"text":"Blame yourself for matching with him at all","then":"You end up talking about your choices instead of his pushing."}],"why":"Sharing it means someone has your back. His pushing is never your fault."}],"debrief":"Matching means interest, not a plan; you choose the place and the speed.","relearn":"Matching on an app is interest, not a yes; you set the pace."},
  {"id":"cr-902","cat":"real-situations","type":"branch","persona":"Rohan","source":"taking a no","hook":"You finally ask Simran out after weeks of working up the nerve. She says no, kindly.","steps":[{"prompt":"You're stung, and the loneliness hits hard. What do you do?","options":[{"text":"Tell her how lonely you've been lately","then":"Simran looks uncomfortable and says she has to go."},{"text":"Ask what's wrong with you, exactly","then":"Simran shifts, unsure how to answer a question that isn't about you."},{"text":"Say \"no worries\", then stop saying hi to her","then":"Next week she waves and you look away. Class gets awkward."},{"text":"Say \"Fair enough. Thanks for being honest\"","then":"Simran smiles, relieved: \"Thanks for asking, really.\"","best":true}],"why":"A graceful no keeps your dignity and hers. That's the confident move."},{"prompt":"That night, your friend Yash says girls like a chase, so keep trying. What do you do?","options":[{"text":"Agree to ask her again next week","then":"You start planning a second ask, and her no turns into 'not yet'."},{"text":"Plan to win her over with funny memes","then":"The memes get polite replies, and she grows more distant."},{"text":"Say women never go for guys like you anyway","then":"Yash laughs uneasily, and the loneliness sits heavier."},{"text":"Say a no is an answer, not a challenge","then":"Yash shrugs: \"Fair. Want to get food instead?\"","best":true}],"why":"A no isn't a challenge to argue with. Respecting it keeps you whole."},{"prompt":"A week later, you see Simran at a group lunch. What do you do?","options":[{"text":"Sit far away so she notices","then":"Simran glances over, uneasy, and the table goes a bit tense."},{"text":"Make a joke about being rejected","then":"A few laugh. Simran goes pink and looks at her plate."},{"text":"Say hi like normal and join the chat","then":"Simran laughs at something you say, and it's easy.","best":true},{"text":"Be extra nice so she changes her mind","then":"Simran thanks you, then keeps a careful distance."}],"why":"Being normal around her keeps things easy, with no strings."}],"debrief":"Taking a no gracefully is the strong, attractive move; pestering isn't.","relearn":"A graceful no, no sulking or guilt-trips, is the confident move."},
  {"id":"cr-903","cat":"real-situations","type":"branch","persona":"any","source":"first time together","hook":"It's your first time with a new partner, Neel, and you're unsure what he's comfortable with.","steps":[{"prompt":"Things are warming up. What do you do?","options":[{"text":"Assume the usual and hope it's fine","then":"You can't tell if Neel is enjoying it, and he doesn't say."},{"text":"Ask one big question at the start, then stop","then":"Neel says \"yes, all good\", and after that you're guessing again."},{"text":"Ask as you go: \"What feels good? Tell me\"","then":"Neel smiles and tells you. The nerves ease for both of you.","best":true},{"text":"Copy what you've seen in films","then":"Neel laughs, a bit awkward: \"Uh, maybe not that.\""}],"why":"Asking turns guessing into closeness and keeps you in sync."},{"prompt":"Partway through, Neel goes a bit quiet. What do you do?","options":[{"text":"Speed up to bring the mood back","then":"Neel tenses and eases away from you."},{"text":"Keep going, since he'd say if something was wrong","then":"Neel stays quiet, then says he's tired."},{"text":"Pause and ask: \"Still good?\"","then":"Neel says he needs a minute. You lie there talking, easy.","best":true},{"text":"Ask: \"Am I doing something wrong?\"","then":"Neel reassures you, and ends up looking after your nerves."}],"why":"Going quiet is a reason to check, not a signal to push on."},{"prompt":"Later, Neel says he was nervous about telling you what he likes. What do you do?","options":[{"text":"Say he should have just said","then":"Neel shrugs, embarrassed, and changes the subject."},{"text":"Laugh and say you were nervous too, then drop it","then":"You share a laugh, but his worry stays unspoken."},{"text":"Say you want to hear it, anytime","then":"Neel relaxes: \"Okay. Next time I'll just say it.\"","best":true},{"text":"Promise you'll always read him without words","then":"Neel smiles, but it's a promise nobody can keep."}],"why":"Making it easy to speak up keeps you in sync, and makes it better."}],"debrief":"Checking in beats assuming; it makes a first time better, not awkward.","relearn":"Ask as you go; checking in keeps you in sync and makes it better."},
  {"id":"cr-904","cat":"real-situations","type":"branch","persona":"any","source":"revocable consent","hook":"You're hooking up with Vikram, and partway through you realise you'd rather stop.","steps":[{"prompt":"You were the one who started it. What do you do?","options":[{"text":"Tell yourself you can't stop what you began","then":"The thought knots you up. Vikram feels you tense and pauses."},{"text":"Worry he'll think you're a tease","then":"The worry keeps you quiet, but Vikram notices you've gone still and stops."},{"text":"Apologise over and over for leading him on","then":"Vikram looks confused: \"Leading me on? Are you okay?\""},{"text":"Say \"I want to stop,\" and stop","then":"Vikram stops at once: \"Okay. You alright?\"","best":true}],"why":"Starting never binds you. You can stop at any point."},{"prompt":"Vikram asks if he did something wrong. What do you do?","options":[{"text":"Say yes, so he has a reason","then":"Vikram looks crushed, and you feel worse for making it up."},{"text":"Say no. You just want to stop, and that's all","then":"Vikram nods: \"Okay. Want some water?\"","best":true},{"text":"Invent a reason, like an ex texting","then":"Vikram nods. The made-up reason now needs more lies."},{"text":"Say sorry and promise to make it up next time","then":"Vikram says \"No need\", but the promise hangs in the air."}],"why":"No reason is owed. Stopping is enough on its own."},{"prompt":"Next day, your flatmate Rohit says stopping halfway is unfair on the other person. What do you say?","options":[{"text":"Agree and say you'll be more sure next time","then":"You decide to hold back from starting things at all."},{"text":"Say it was only fine because Vikram was nice about it","then":"Rohit nods, and the idea that stopping depends on him goes unchallenged."},{"text":"Say anyone can stop at any point, no reason owed","then":"Rohit thinks: \"Yeah. Same goes for me, I guess.\"","best":true},{"text":"Laugh it off and change the topic","then":"Rohit moves on, and so does his idea."}],"why":"Starting never obliges anyone to finish, you included."}],"debrief":"Consent is revocable mid-way; starting something never obliges you to finish.","relearn":"You can stop at any point; starting never obliges you to finish."},
  {"id":"cr-905","cat":"real-situations","type":"branch","persona":"any","source":"reading a partner","hook":"A moment with your partner Farida is going well, until she pulls back a little and goes quiet.","steps":[{"prompt":"She hasn't said stop. What do you do?","options":[{"text":"Keep going, since she didn't say stop","then":"Farida stays quiet, then gently moves away from you."},{"text":"Pause and ask softly if she's okay","then":"Farida exhales: \"I'm okay. My head just went somewhere else.\"","best":true},{"text":"Kiss her to bring her back into it","then":"Farida turns her face away slightly."},{"text":"Pull back too and wait for her to explain","then":"The silence stretches, and Farida can't tell what you're thinking either."}],"why":"A pull-back or going quiet means pause and check. It isn't a yes."},{"prompt":"Farida says she's been stressed about her exams. What do you do?","options":[{"text":"Tell her to forget exams and relax","then":"Farida gives a thin smile. It isn't that easy."},{"text":"Decide no intimacy till her exams are over","then":"Farida blinks: \"You don't get to decide that for me.\""},{"text":"Offer study tips right there","then":"Farida nods politely, still tense."},{"text":"Ask if she'd like to talk, or just rest","then":"Farida picks rest and curls up next to you.","best":true}],"why":"Asking what she needs, instead of deciding for her, keeps it her call."},{"prompt":"Your friend Ravi says couples shouldn't need to check in after a while. What do you say?","options":[{"text":"Say checking in is part of being close","then":"Ravi pauses: \"Huh. Maybe I should ask more.\"","best":true},{"text":"Agree it's more natural not to ask","then":"Ravi nods, and the idea that couples just know goes unanswered."},{"text":"Say you only check when something seems off","then":"Ravi shrugs, and small signs like Farida's pull-back become easy to miss."},{"text":"Tell him his relationship sounds boring","then":"Ravi laughs, a bit offended, and the point gets lost."}],"why":"Consent stays ongoing, even in a long relationship."}],"debrief":"A pull-back or going quiet means pause and check; it isn't a yes.","relearn":"If a partner pulls back or goes quiet, pause and check; it isn't a yes."},
  {"id":"cr-906","cat":"real-situations","type":"branch","persona":"Meena","source":"no warden, no campus","hook":"You rent a room near work, and a flatmate, Sunil, keeps trying it on after you've said no.","steps":[{"prompt":"Tonight he leans in your doorway, making comments. What do you do?","options":[{"text":"Tell yourself it's just his way of joking","then":"The comments keep coming, and you start dreading coming home."},{"text":"Wonder if you've been too friendly with him","then":"You replay every chat with him, looking for your mistake."},{"text":"Say no plainly and shut your door","then":"Sunil mutters \"Relax\" and walks off. Your heart is still racing.","best":true},{"text":"Try to reason with him about respect","then":"Sunil nods along, smirking, and doesn't move from the doorway."}],"why":"Your no is enough, and closing the door puts space between you."},{"prompt":"Next morning you're still shaken, and there's no warden to go to. What do you do?","options":[{"text":"Keep it to yourself so there's no fuss at home","then":"The day drags, and you carry it alone."},{"text":"Post about it in the flat's group chat","then":"Sunil sees it first and replies \"lol drama\". No one else says anything."},{"text":"Decide it's not bad enough to count","then":"You shrink it in your head, but your stomach knots when you hear his voice."},{"text":"Tell someone you trust, and note 181 for help","then":"Your friend Lata listens: \"Not your fault. Stay with me this weekend if you like.\"","best":true}],"why":"It's never your fault. A trusted person and 181 are there even with no warden."},{"prompt":"A week later, Sunil tries it on again when no one else is home. What do you do?","options":[{"text":"Tell yourself you must have encouraged him","then":"The doubt drowns out your gut, which is telling you to get out."},{"text":"Message his cousin to warn him off","then":"His cousin replies \"he's harmless\", and nothing changes."},{"text":"Get out of the room and call a friend or 181","then":"Your friend Lata picks up at once and says she's on her way.","best":true},{"text":"Plan to handle him alone, without help","then":"You brace every evening, alone with it."}],"why":"Getting to safety and reaching help comes first. You don't have to face him alone."}],"debrief":"Harassment is never your fault. Your no stands anywhere, and 181 helps even off-campus.","relearn":"Your no stands anywhere; help like 181 exists even off-campus."},
  {"id":"cr-907","cat":"real-situations","type":"branch","persona":"any","source":"ongoing consent","hook":"Your long-term partner Sameer reaches for you on a night you're just not in the mood.","steps":[{"prompt":"He's being affectionate, nothing pushy. What do you do?","options":[{"text":"Fake a headache so it's not a real no","then":"Sameer fetches you a tablet. The real reason stays unsaid."},{"text":"Tell yourself a good partner is always up for it","then":"The thought makes you feel like you're failing him."},{"text":"Say sorry three times and explain at length","then":"Sameer ends up reassuring you for twenty minutes."},{"text":"Say \"not tonight\", warmly, no guilt","then":"Sameer kisses your forehead: \"No worries. Chai?\"","best":true}],"why":"Being together never banks a yes. Tonight is its own answer."},{"prompt":"A week later, Sameer jokes that 'not tonight' is becoming a habit. What do you do?","options":[{"text":"Laugh it off and change the topic","then":"Sameer laughs too, but the joke keeps coming back."},{"text":"Say each night is its own answer, and the joke stings","then":"Sameer winces: \"Fair. I'll drop that joke.\"","best":true},{"text":"Snap that he's keeping score","then":"Sameer's smile drops: \"It was just a joke.\""},{"text":"Promise to make it up to him properly this weekend","then":"Sameer brightens, and now the weekend feels like a deadline."}],"why":"A no never needs guilt. Saying the joke stings lets him stop before it turns into pressure."},{"prompt":"A cousin tells you partners shouldn't need to ask after a few years. What do you say?","options":[{"text":"Nod along to keep things pleasant","then":"Your cousin carries on, and the idea goes unanswered."},{"text":"Say an old yes never carries over to tonight","then":"Your cousin pauses: \"Hm. Maybe we should ask more too.\"","best":true},{"text":"Say it's just different for you and Sameer","then":"Your cousin shrugs, and the idea stands for everyone else."},{"text":"Tell them they sound controlling","then":"Your cousin gets defensive, and it turns into an argument."}],"why":"Years together never replace asking. Saying so helps your cousin rethink it too."}],"debrief":"Long-term partners still ask each time; an old yes never carries to tonight.","relearn":"A relationship never banks consent; each time is freely given or it's a no."},
  {"id":"cr-908","cat":"real-situations","type":"branch","persona":"any","source":"drunk friend at a party","hook":"At a party, your very drunk friend Pranav is being led off by someone he barely knows.","steps":[{"prompt":"They're heading for the stairs. What do you do?","options":[{"text":"Step in and say you need Pranav for a sec","then":"You take Pranav's arm. He leans on you, barely steady.","best":true},{"text":"Stay out of it. It's not your business","then":"You turn back to your friends, but you can still see Pranav swaying by the stairs."},{"text":"Text Pranav to check he's okay","then":"The message goes unread. Pranav is still swaying near the stairs."},{"text":"Shout across the room that he's too drunk","then":"Heads turn, and the person pulls Pranav closer to the stairs."}],"why":"Someone that drunk can't consent. Stepping in is care, not interference."},{"prompt":"Pranav slurs loudly that he's fine and wants to go upstairs. What do you do?","options":[{"text":"Sit him down and get him water and air","then":"Pranav grumbles, then sits on the steps and drinks the water.","best":true},{"text":"Let him go, since he says he's fine","then":"He sways up two steps, then sits down hard, dizzy."},{"text":"Ask the other person to promise they'll look after him","then":"They say \"Of course\" with a smile, but Pranav slumps onto the steps."},{"text":"Pull him away and yell at the other person","then":"The person yells back, and Pranav gets upset and confused."}],"why":"Staying close with water and air keeps him safe without a fight."},{"prompt":"The other person takes Pranav's arm again and says: \"Come on. Let's go up.\" What do you do?","options":[{"text":"Apologise and leave the two of them to it","then":"They steer Pranav towards the stairs until the host blocks them: \"Not in that state.\""},{"text":"Tell them they're a predator","then":"They go red, and a crowd gathers to watch the shouting."},{"text":"Say he's too drunk tonight, and stay put","then":"They roll their eyes and walk off to the kitchen.","best":true},{"text":"Explain consent to them at length","then":"They cut you off halfway and turn back to Pranav."}],"why":"A calm, firm 'he's too drunk' puts his safety first without a scene."},{"prompt":"Next day, Pranav texts asking if he was a mess last night. What do you say?","options":[{"text":"Tell him someone kept trying to take him upstairs, and it's not on him","then":"Pranav goes quiet, then replies: \"Glad you were there. Thanks for telling me.\"","best":true},{"text":"Tease him about how completely wasted he was","then":"Pranav replies \"lol\", then goes quiet all day."},{"text":"Tell him he needs to drink less","then":"Pranav replies \"ok mum\", a bit stung."},{"text":"Say nothing happened and there's no need to talk about it","then":"Pranav says okay, and his questions about the night stay unanswered."}],"why":"Plain facts, no shame. Someone trying to take advantage of him is never his fault."}],"debrief":"Someone too drunk can't consent; bystanders looking out is part of the culture.","relearn":"Someone too drunk can't consent; stepping in for a friend is the right move."},
  {"id":"cr-909","cat":"real-situations","type":"branch","persona":"Rohan","source":"rejection isn't owed","hook":"After weeks of chatting every night, Aditi tells you she only sees you as a friend.","steps":[{"prompt":"It stings more than you expected. What do you do?","options":[{"text":"Say you're glad she told you, and mean it","then":"Aditi replies: \"Thank you. I was so nervous to say it.\"","best":true},{"text":"Tell her she led you on","then":"Aditi's reply is short: \"I never said it was more.\""},{"text":"Ask what you could change to be more than a friend","then":"Aditi says it isn't about changing anything, and sounds tired."},{"text":"Stop replying without saying why","then":"Aditi sends two messages asking if you're okay, then stops."}],"why":"No one owes attraction for your time. Respecting that keeps you whole."},{"prompt":"That night, a reel says nice guys get friend-zoned because women use them. What do you do?","options":[{"text":"Remind yourself she owed you honesty, and gave it","then":"You close the app. It still stings, but it's clean.","best":true},{"text":"Watch more reels like it","then":"Your feed fills with the same anger, and you feel worse."},{"text":"Share it with a 'too real, bro' comment","then":"A few friends laugh, and Aditi sees it too."},{"text":"Decide you'll stop being nice to anyone at all","then":"You go cold on people, and it's lonelier than before."}],"why":"Time spent doesn't buy a yes. An honest no isn't a trick."},{"prompt":"A week later, Aditi asks if you still want to hang out as friends. What do you do?","options":[{"text":"Say yes, hoping she'll change her mind","then":"You hang out, but each hangout feels like a test she doesn't know about."},{"text":"Be honest if you need some space first","then":"Aditi replies: \"Of course. Whenever you're ready.\"","best":true},{"text":"Say friends is a waste of your time","then":"Aditi goes quiet: \"Okay. Got it.\""},{"text":"Agree, then make it awkward on purpose","then":"The hangout is stiff, and she leaves early."}],"why":"Being honest about what you need respects you both, with no strings attached."}],"debrief":"No one owes you attraction for your time; respecting a no is the dignified move.","relearn":"No one owes you attraction for your time; respect the no."},
  {"id":"cr-910","cat":"real-situations","type":"branch","persona":"any","source":"photo pressure","hook":"Mihir, who you're seeing, keeps asking for a nude after you've said you'd rather not.","steps":[{"prompt":"Tonight he asks again: \"Just one, for me.\" What do you do?","options":[{"text":"Take a friend's view that one pic is harmless","then":"The advice makes his asking feel normal, and your no feel fussy."},{"text":"Explain again, more gently, why you'd rather not","then":"Mihir reads it and replies: \"But you could still try.\""},{"text":"Wonder if you're being unfair to him","then":"You start feeling like the problem, while he keeps asking."},{"text":"Say your no hasn't changed","then":"Mihir sends \"ok\" and goes offline.","best":true}],"why":"Consent covers photos. A repeated ask is pressure, not persuasion."},{"prompt":"Next day, he says his exes always sent them. What do you do?","options":[{"text":"Say that doesn't change your answer","then":"Mihir drops it for the day, sulking a little.","best":true},{"text":"Ask what exactly his exes sent","then":"Mihir starts describing, and you feel compared."},{"text":"Say you're not like them, as if apologising","then":"Mihir says: \"I know. You're special.\" Then he asks again."},{"text":"Tell yourself this is how dating works now","then":"The idea sits with you, making the pressure feel normal."}],"why":"What others did has nothing to do with your yes. Your no still stands."},{"prompt":"The asks keep coming, and you feel worn down. What do you do?","options":[{"text":"Keep it to yourself so no one thinks badly of him","then":"You carry it alone, and every new ask feels heavier."},{"text":"Decide it's your fault for dating him","then":"You go over the whole month, looking for your mistake."},{"text":"Ask his best friend to tell him off","then":"His friend tells him, and Mihir is angry you went to his mates."},{"text":"Talk it through with a friend you trust","then":"Your friend Ruhi says: \"That's pressure. Your no was enough the first time.\"","best":true}],"why":"Repeated pressure is never your fault. Someone you trust helps you hold your ground."},{"prompt":"Mihir says that if you won't send one, maybe you don't really care about him. What do you do?","options":[{"text":"Ask what else you could do to prove you care","then":"Mihir sends a list, and the ask just moves somewhere new."},{"text":"Wonder if he's right about you","then":"The doubt turns his pressure into your problem."},{"text":"Say caring never means doing what you don't want","then":"Mihir goes quiet, then says: \"Okay. I'll stop asking.\"","best":true},{"text":"Say you care, and argue it out for an hour","then":"The argument goes in circles, and he still asks at the end."}],"why":"Guilt is pressure too. Caring never means sending what you don't want to."}],"debrief":"Consent applies to photos; repeated asking is pressure and your no holds.","relearn":"Consent applies to photos; a repeated ask is pressure, and your no holds."},
  {"id":"cr-911","cat":"real-situations","type":"branch","persona":"any","source":"checking-in mid","hook":"Things are moving fast on a date with Tanya, and you're not sure you're both on the same page.","steps":[{"prompt":"She's laughing, but her hands have gone still. What do you do?","options":[{"text":"Pause: \"Hey, is this still good for you?\"","then":"Tanya smiles: \"Honestly? A bit slower would be nice.\"","best":true},{"text":"Keep the pace up so the mood isn't broken","then":"Tanya's laugh fades, and she glances towards the door."},{"text":"Slow down without saying anything","then":"Tanya relaxes a little, but you still don't know what she wants."},{"text":"Ask if she's always this shy","then":"Tanya flushes: \"I'm not shy.\" She pulls back, stiff."}],"why":"One quick check keeps it consensual and keeps you both genuinely in."},{"prompt":"A bit later, Tanya says she likes it when people check in, and asks what you think. What do you say?","options":[{"text":"Say it breaks the mood, so you'd rather not","then":"Tanya's smile fades, and you've lost your easiest way to know."},{"text":"Say it's just a rule you have to follow","then":"Tanya laughs: \"A rule? Very romantic.\""},{"text":"Say you'd only ask if something seemed wrong","then":"Tanya nods slowly: \"Things can seem fine and not be.\""},{"text":"Say you like knowing she's into it, so you'll ask","then":"Tanya grins: \"That's kind of hot, actually.\"","best":true}],"why":"Checking in because you care how she feels builds trust, not awkwardness."},{"prompt":"Next week, a friend says checking in mid-moment kills the vibe. What do you say?","options":[{"text":"Agree it's awkward, but necessary","then":"Your friend nods, and checking in stays a chore."},{"text":"Say checking in builds the mood, not breaks it","then":"Your friend looks thoughtful: \"Maybe I should try it.\"","best":true},{"text":"Agree to skip it, since it's a bit awkward","then":"Your friend grins, and next time you're guessing."},{"text":"Change the subject","then":"The idea that asking kills the mood goes unchallenged."}],"why":"A quick 'still good?' keeps consent ongoing and makes it better."}],"debrief":"A quick \"still good?\" mid-moment keeps consent ongoing and builds trust.","relearn":"A quick \"still good?\" keeps consent ongoing; it builds the mood, not breaks it."},
  {"id":"cr-912","cat":"real-situations","type":"branch","persona":"Ananya","source":"the freedom shock","hook":"It's your first house party away from home. Two drinks in, a guy called Rishabh gets handsy fast.","steps":[{"prompt":"His hand keeps drifting as you talk. What do you do?","options":[{"text":"Tell yourself this is just how city parties are","then":"You second-guess the knot in your stomach, until your friend Mahi calls you over."},{"text":"Blame the drinks for how uneasy you feel","then":"You doubt yourself instead of him, until your friend Mahi grabs your hand to dance."},{"text":"Recall a cousin's advice never to make a scene","then":"The advice holds your words back, until your friend Mahi spots you and pulls you away."},{"text":"Say \"slow down\" and step back to your friends","then":"Rishabh raises his eyebrows, then shrugs. Your friend Mahi waves you over.","best":true}],"why":"Tipsy but with it, you still set the pace. Your boundary leads."},{"prompt":"Rishabh laughs, loud enough for others, that you're being 'so small-town'. What do you do?","options":[{"text":"Say your pace is yours, wherever you're from","then":"Rishabh rolls his eyes and wanders off to the kitchen.","best":true},{"text":"Ask a new friend, who says just go with it","then":"She shrugs: \"Everyone's like this here.\" Your unease stays."},{"text":"Wonder if he's right and you're too sheltered","then":"The doubt sticks, and you feel you owe him proof you're not."},{"text":"Explain your hometown and upbringing to him","then":"Rishabh half-listens, then says you'll 'get used to it'."}],"why":"Your pace is yours, wherever you're from, and it owes no explanation."},{"prompt":"Later, you feel shaky and want to talk to someone. What do you do?","options":[{"text":"Keep it to yourself so no one thinks you're uncool","then":"You spend the rest of the night pretending you're fine."},{"text":"Text your hostel group a vague 'ugh, men'","then":"The chat fills with laughing emojis, and no one asks what happened."},{"text":"Decide it's your fault for coming to the party","then":"You head home early, feeling like you did something wrong."},{"text":"Tell your friend Mahi and stay close to her","then":"Mahi listens: \"Not your fault. Stick with me tonight.\"","best":true}],"why":"It's never your fault. A trusted friend close by makes you safer and less alone."},{"prompt":"Next week, a senior says anyone drinking at a party should expect this. What do you say?","options":[{"text":"Agree, since you'd had two drinks yourself","then":"The senior nods, and the blame slides off Rishabh and onto you."},{"text":"Say drinking is never an invitation to touch","then":"The senior pauses: \"Fair. Never thought of it like that.\"","best":true},{"text":"Say it depends on how much they drank","then":"The senior nods, and the idea that drinks decide stays standing."},{"text":"Laugh it off to keep the peace with a senior","then":"The senior carries on, and the idea goes unanswered."}],"why":"Having a drink never excuses anyone ignoring your pace."}],"debrief":"You set your own pace; a clear \"slow down\" is always yours to say.","relearn":"You set your own pace; a clear \"slow down\" is always yours."},
  {"id":"cr-913","cat":"real-situations","type":"branch","persona":"any","source":"after-the-fact ask","hook":"Dhruv leans in to kiss you. You turn your head, but he laughs and leans in again.","steps":[{"prompt":"He says \"Come on, just one.\" What do you do?","options":[{"text":"Say \"I'm not up for that,\" clearly","then":"Dhruv pulls back, but laughs as if it was all a joke.","best":true},{"text":"Tell yourself a kiss is too small to refuse","then":"You hesitate. Dhruv reads your face, laughs and pulls back a little."},{"text":"Recall friends saying it's rude to refuse a kiss","then":"You waver between that rule and your gut. Dhruv laughs and leans back."},{"text":"Apologise for giving mixed signals","then":"Dhruv says \"No worries\" and stays close, still smiling."}],"why":"A turned head is already a no. Saying it plainly removes any doubt."},{"prompt":"Dhruv laughs that it's only a kiss and asks why you're so serious. What do you do?","options":[{"text":"Walk over to your friends and tell them","then":"Your friend Noor puts an arm round you and glares at Dhruv until he leaves.","best":true},{"text":"Explain why a turned head means no","then":"Dhruv rolls his eyes, says \"Whatever\", and drifts off to the bar."},{"text":"Wonder if you are being too serious","then":"You start doubting yourself. Dhruv shrugs and wanders off."},{"text":"Blame yourself for dancing with him earlier","then":"You feel small as Dhruv strolls off, laughing with his friends."}],"why":"Getting to your friends puts you with people who have your back."},{"prompt":"Later, Dhruv's friend comes over and says he was only being playful. What do you do?","options":[{"text":"Agree it was nothing, since he was only messing about","then":"The friend nods, and 'playful' becomes the story."},{"text":"Tell the whole party what he did","then":"Everyone turns to look, and you feel on display."},{"text":"Say it's fine because he stopped in the end","then":"The friend relaxes, and the first lean-in gets forgotten."},{"text":"Say a turned head is already a no","then":"The friend goes quiet, then says: \"Fair. I'll tell him to back off.\"","best":true}],"why":"Even a kiss needs a yes. A turned head was already your answer."},{"prompt":"Walking home, you feel uneasy about the whole night. What do you do?","options":[{"text":"Tell yourself you're overreacting","then":"You push the feeling down, but it's still there at bedtime."},{"text":"Keep it quiet so it doesn't become a thing","then":"You say nothing and carry it alone."},{"text":"Call a close friend and tell them how it felt","then":"Your friend says: \"That's not okay, and it's not on you. Want to talk?\"","best":true},{"text":"Scroll Dhruv's profile to understand him","then":"You find nothing useful, only more unease."}],"why":"What he did is never your fault. Talking to someone you trust helps it settle."}],"debrief":"Even a kiss needs a yes; a dodge or turned head is a no to respect.","relearn":"Even a kiss needs a yes; a turned head is already a no."},
  {"id":"cr-914","cat":"real-situations","type":"branch","persona":"any","source":"voicing a limit","hook":"Things are going well with your partner Zubin, but there's one thing you don't want to do tonight.","steps":[{"prompt":"He starts heading that way. What do you do?","options":[{"text":"Gently steer things elsewhere without saying why","then":"Zubin follows your lead, and the moment passes, though he never learns why."},{"text":"Name it: \"I'm into this, not that, though\"","then":"Zubin nods: \"Got it. Thanks for telling me.\"","best":true},{"text":"Tell yourself a good partner goes along with everything","then":"You go tense, and Zubin notices and slows down, puzzled."},{"text":"Say you're sorry for being boring","then":"Zubin laughs, confused, and stops to ask what you mean."}],"why":"Naming a limit plainly keeps you comfortable and keeps things good."},{"prompt":"Next day, Zubin asks how last night was for you. What do you do?","options":[{"text":"Say everything was great, to be nice","then":"Zubin beams, and next time he'll try the same thing."},{"text":"Say \"it was fine\" and change the subject","then":"The chance to talk slips by."},{"text":"Hint that he should just know by now","then":"Zubin looks puzzled: \"I can't read your mind.\""},{"text":"Be honest about what worked and what didn't","then":"Zubin listens: \"Good to know. Tell me anytime.\"","best":true}],"why":"Honest feedback, kindly given, keeps things good for both of you."},{"prompt":"A friend says naming limits makes you seem difficult to date. What do you say?","options":[{"text":"Agree, and keep your limits to yourself","then":"Your friend nods, and your limits start to feel like a burden."},{"text":"Say a good partner welcomes it, no apology needed","then":"Your friend thinks: \"Honestly, I'd want to know too.\"","best":true},{"text":"Say you only name them with long-term partners","then":"Your friend shrugs, and newer partners are left guessing."},{"text":"Laugh and say you're difficult anyway","then":"The joke lands, and the point doesn't."}],"why":"Naming a limit plainly is your right, and a good partner welcomes it."}],"debrief":"Naming a limit plainly is your right; a good partner welcomes it.","relearn":"You can name a limit plainly; a good partner welcomes it, no apology needed."},
  {"id":"cr-915","cat":"real-situations","type":"branch","persona":"any","source":"ride-home pressure","hook":"Abhishek, a senior at college, gives you a lift home, then hints he'd like to come up.","steps":[{"prompt":"He jokes that his fee is a chai upstairs. What do you do?","options":[{"text":"Feel you owe him since he drove you","then":"You get out feeling you owe him, and he says he'll text."},{"text":"Thank him and say goodnight at the gate","then":"Abhishek pauses, then says \"Sure, goodnight.\" He drives off.","best":true},{"text":"Ask what he means by 'fee'","then":"Abhishek grins: \"You know what I mean.\" The hint gets heavier."},{"text":"Wonder if you led him on by accepting the lift","then":"You get out blaming yourself, and he waves: \"Next time.\""}],"why":"A favour earns thanks, not access. With a senior, a power gap makes a yes unfree."},{"prompt":"Next day, Abhishek messages offering you lifts 'anytime', with a wink. What do you do?","options":[{"text":"Wonder if refusing will hurt you in the department","then":"The worry grows, and his offer feels harder to turn down."},{"text":"Tell yourself a senior's wink means nothing","then":"You shrug it off, but the offer sits there in your chat."},{"text":"Screenshot it to the whole class group","then":"The group jokes about it, and he says you misread him."},{"text":"Say thanks, but you'll make your own way","then":"Abhishek replies \"ok\", and the winks stop.","best":true}],"why":"A plain no to the lifts closes the door without a fight."},{"prompt":"The hints make you uneasy around the department. What do you do?","options":[{"text":"Tell a trusted teacher, or the campus committee","then":"Your teacher listens: \"You did nothing wrong. Let's talk about options.\"","best":true},{"text":"Keep quiet, since he's a senior","then":"The unease follows you into every class he's in."},{"text":"Blame yourself for accepting the lift","then":"You replay the ride, looking for your mistake instead of his."},{"text":"Ask his friends to have a quiet word with him","then":"His friends laugh it off and tell him you complained."}],"why":"It's never your fault. A trusted teacher or the campus committee can help."},{"prompt":"In the canteen, a classmate says a senior hinting for more after a favour is just flattering. What do you say?","options":[{"text":"Say a senior's hint isn't a free, equal ask","then":"The classmate pauses: \"Huh. I hadn't thought about the senior part.\"","best":true},{"text":"Agree that it's harmless fun","then":"The classmate nods, and the power gap drops out of view."},{"text":"Say it's only a problem if you don't like them","then":"The classmate nods, and liking becomes the test, not the power gap."},{"text":"Shrug and say it's none of your business","then":"The classmate moves on, and the idea goes unchallenged."}],"why":"Consent needs equals. When a senior hints after a favour, that yes isn't freely given."}],"debrief":"A favour never buys access; a senior's ask carries a power gap, not a free choice.","relearn":"A favour never buys access; a power gap makes that yes unfree."},
  {"id":"cr-916","cat":"real-situations","type":"branch","persona":"Zoya","source":"same-gender date","hook":"You're on a date with Kiran, who shares your gender. You're unsure how to check what they want.","steps":[{"prompt":"Things are getting closer on the sofa. What do you do?","options":[{"text":"Assume you both want the same things","then":"You go with your guess. Kiran seems unsure and goes quiet."},{"text":"Just ask warmly: \"What are you into?\"","then":"Kiran smiles: \"Honestly? Slow. And I like that you asked.\"","best":true},{"text":"Wait for Kiran to take the lead","then":"Kiran waits for you too, and the moment stalls."},{"text":"Joke that you already know what they like","then":"Kiran laughs, a little stiffly: \"Do you, though?\""}],"why":"Shared identity doesn't mean shared wants. A warm ask fits any couple."},{"prompt":"Later, Kiran mentions past dates who assumed things without asking. What do you do?","options":[{"text":"Say you're not like them, so no worries","then":"Kiran smiles, unsure. It's an easy thing to say."},{"text":"Listen, and say you'd rather always ask","then":"Kiran relaxes: \"That means a lot.\"","best":true},{"text":"Ask for details of what happened","then":"Kiran shifts: \"I don't really want to go into it.\""},{"text":"Change the subject to keep it light","then":"Kiran goes along with the new topic, and the moment to connect passes."}],"why":"Listening, and showing how you'll act, builds more trust than a promise."},{"prompt":"A friend says consent talk is really for straight couples. What do you say?","options":[{"text":"Agree it's simpler between people like you","then":"Your friend nods, and assuming feels normal again."},{"text":"Say it matters, but only with new partners","then":"Your friend shrugs, and long-term couples get left out."},{"text":"Laugh it off","then":"The idea goes unanswered, and your friend repeats it later."},{"text":"Say consent works the same for every couple","then":"Your friend thinks: \"Fair. Asking is for everyone.\"","best":true}],"why":"Consent is the same for every couple. Ask, don't assume."}],"debrief":"Consent is the same for every couple; ask, don't assume shared wants.","relearn":"Consent works the same for all; ask warmly rather than assume shared wants."},
  {"id":"cr-917","cat":"real-situations","type":"branch","persona":"any","source":"morning-after clarity","hook":"You and a new partner, Reza, are about to take things further. You've each had a couple of drinks.","steps":[{"prompt":"You both seem keen. What do you do?","options":[{"text":"Carry on without thinking about it","then":"It probably seems fine, but neither of you actually checked."},{"text":"Have one more drink to relax first","then":"Now you're both fuzzier, and the question is harder to answer."},{"text":"Check you're both sober enough and keen","then":"Reza laughs: \"Tipsy, but very with it. You?\" You feel the same.","best":true},{"text":"Check that Reza's okay, but not yourself","then":"Reza says he's good. You're less sure how you feel."}],"why":"Sober enough and eager is the bar. A quick check makes it clear for both."},{"prompt":"Midway, Reza says he's suddenly feeling the drinks more. What do you do?","options":[{"text":"Stop and get you both some water","then":"Reza sips the water: \"Thanks. Let's just cuddle.\"","best":true},{"text":"Ask if he wants to keep going","then":"Reza mumbles \"Sure\", yawns and falls asleep, and the night ends there."},{"text":"Keep going, since he was fine earlier","then":"Reza's next words slur. You see he's too out of it to say yes, and you stop."},{"text":"Tease him for being a lightweight","then":"Reza laughs, embarrassed, goes quiet, and the mood fizzles out."}],"why":"Capacity can change mid-way. When it drops, you stop and look after each other."},{"prompt":"Next morning over chai, Reza asks how you both want to handle drinks next time. What do you do?","options":[{"text":"Say it's his job to know his own limits","then":"Reza looks hurt: \"I thought we'd look out for each other.\""},{"text":"Say \"let's not overthink it\"","then":"Reza shrugs, and the plan never gets made."},{"text":"Say you'll only check when things seem really drunk","then":"Reza nods, but 'really drunk' is hard to judge from the inside."},{"text":"Suggest you both wait if either of you is unsure","then":"Reza smiles: \"Deal. Sober enough and keen, both of us.\"","best":true}],"why":"A shared rule, made sober, carries you safely through tipsy nights."}],"debrief":"Sober-enough and eager is the bar; a quick check keeps it clearly consensual.","relearn":"Sober-enough and eager is the bar; a quick check keeps it consensual."},
  {"id":"cr-918","cat":"real-situations","type":"branch","persona":"any","source":"changing plans","hook":"You agreed to stay over at Omar's, but now you'd rather just sleep, nothing more.","steps":[{"prompt":"Omar is lighting a candle, clearly expecting more. What do you do?","options":[{"text":"Tell yourself staying over meant agreeing to more","then":"The thought makes you tense, and Omar notices you've gone stiff."},{"text":"Say so: \"I want to stay, just sleep tonight\"","then":"Omar blows out the candle: \"Sure. Sleep it is.\" He looks a little let down.","best":true},{"text":"Wonder if you're being unfair to Omar","then":"You go quiet, and Omar pauses, candle in hand."},{"text":"Apologise for giving him the wrong idea","then":"Omar says \"No, no, it's fine\", but looks confused about what you mean."}],"why":"Staying over is no yes to anything else. Saying so plainly is enough."},{"prompt":"Later, Omar asks quietly if something's wrong between you. What do you do?","options":[{"text":"Make up a stomach ache","then":"Omar fetches you a pill, and the real reason stays unsaid."},{"text":"Say plans can change, and you just want sleep","then":"Omar nods: \"Fair enough. Night.\"","best":true},{"text":"Say you'll make it up to him next weekend","then":"Omar brightens, and now next weekend feels like a promise."},{"text":"Ask why he's making it a big deal","then":"Omar's face tightens: \"I only asked.\""}],"why":"Plans aren't promises. Changing yours needs no excuse."},{"prompt":"A week later, a friend says staying over is basically a yes. What do you say?","options":[{"text":"Agree, and say you'll avoid staying over now","then":"Your friend nods, and your plans start shrinking."},{"text":"Say staying over is never a yes to anything else","then":"Your friend pauses: \"Yeah. I'd hate it if someone thought that about me.\"","best":true},{"text":"Say it depends how long you've been dating","then":"Your friend nods, and the idea that time buys a yes slips through."},{"text":"Laugh and say Omar's too sweet to mind","then":"Your friend shrugs. It makes Omar the reason, not your choice."}],"why":"Staying over is never agreement to more, and the plan can change any time."}],"debrief":"Staying over is never a yes to intimacy; you can change the plan freely.","relearn":"Staying over is never a yes to intimacy; you can change the plan any time."},
  {"id":"cr-919","cat":"real-situations","type":"branch","persona":"Rohan","source":"men can say no too","hook":"Your girlfriend Sneha wants to go further tonight. You're not feeling it, and worry that's 'unmanly'.","steps":[{"prompt":"She's clearly keen and leaning in. What do you do?","options":[{"text":"Tell yourself guys are always meant to be up for it","then":"The thought knots you up, and Sneha notices you're not really there."},{"text":"Wonder if Sneha will think less of you","then":"You hesitate, and Sneha pauses: \"Hey. What's going on?\""},{"text":"Crack a joke to change the subject","then":"Sneha laughs along, then gives you a puzzled look."},{"text":"Say \"not tonight\" plainly","then":"Sneha pauses: \"Oh. Okay. You alright?\"","best":true}],"why":"Your no counts too. Consent runs both ways."},{"prompt":"Sneha asks, half-joking, if you've gone off her. What do you do?","options":[{"text":"Say something's been wrong with you lately","then":"Sneha looks worried: \"Wrong how?\""},{"text":"Say it's not her, just your mood tonight","then":"Sneha smiles: \"Fair. Film, then?\"","best":true},{"text":"Turn it around and ask if she's gone off you","then":"Sneha frowns: \"I just asked a question.\""},{"text":"Say you're just tired from the gym","then":"Sneha nods, and the real reason stays unsaid."}],"why":"A simple, honest answer is kinder than an excuse or a deflection."},{"prompt":"At lunch, your friend Manav jokes that a real man never turns it down. What do you say?","options":[{"text":"Laugh along so you don't look weird","then":"The table laughs, and the joke sticks with you."},{"text":"Say you were just too tired that night","then":"Manav nods: \"Tired, sure.\" The myth stays standing."},{"text":"Say a man's no counts as much as anyone's","then":"Manav pauses: \"Yeah, fair. A no's a no.\"","best":true},{"text":"Snap that he's insecure","then":"Manav bristles, and the talk turns into an argument."}],"why":"There's nothing unmanly about a no. Your comfort counts as much as anyone's."}],"debrief":"A man's no is fully valid; consent and the right to stop run both ways.","relearn":"A man's no counts too; there's nothing unmanly about saying not tonight."},
  {"id":"cr-920","cat":"real-situations","type":"branch","persona":"any","source":"group-trip room","hook":"On a college trip, your roommate Nitin climbs into your bed late at night, uninvited.","steps":[{"prompt":"Everyone else is asleep. What do you do?","options":[{"text":"Recall a senior saying never make a fuss on trips","then":"The advice makes your alarm feel like the problem. Nitin shifts, sensing you're awake."},{"text":"Say clearly: \"Go back to your bed\"","then":"Nitin mutters \"Whatever\" and sits up, but stays on the edge of your bed.","best":true},{"text":"Tell yourself sharing a room makes this normal","then":"The thought clouds your gut, and you start doubting your own alarm."},{"text":"Wonder if you gave him the wrong idea earlier","then":"You search the day for a mistake while Nitin whispers: \"You awake?\""}],"why":"A clear word says what your space needs. Closeness is never an invitation."},{"prompt":"Nitin whispers that you're being weird about nothing. What do you do?","options":[{"text":"Tell yourself he's harmless and you're overreacting","then":"While you doubt yourself, Nitin sighs and goes back to his own bed."},{"text":"Switch on the light and go to a friend's room","then":"Your friend Aisha wakes, sees your face, and makes room for you.","best":true},{"text":"Keep arguing with him in whispers","then":"Nitin whispers back for a while, then gives up and returns to his bed."},{"text":"Threaten to post about him in the trip group","then":"He hisses that no one will believe you, then stomps back to his bed."}],"why":"Getting to safety and to a friend comes first. You don't have to handle him alone."},{"prompt":"Next morning, you're shaken and unsure who to tell. What do you do?","options":[{"text":"Keep quiet so the trip isn't ruined","then":"You smile through the day, carrying it alone."},{"text":"Blame yourself for how the rooms were picked","then":"You replay the room list as if it was your doing."},{"text":"Tell your friend Aisha, or a professor you trust","then":"Aisha listens and goes with you to Professor Menon, who sorts a new room.","best":true},{"text":"Confront Nitin at breakfast in front of everyone","then":"Nitin laughs it off loudly, and people look at you, not him."}],"why":"It's never your fault. Telling someone you trust gets you support and a safer room."},{"prompt":"That evening, Nitin messages that it was only a joke and you shouldn't make it a thing. What do you do?","options":[{"text":"Ask a trip-mate, who says just let it go","then":"The trip-mate shrugs: \"Boys, na.\" You feel more alone with it."},{"text":"Screenshot it and show someone you trust","then":"Your friend Aisha reads it: \"That's pressure. You don't owe him silence.\"","best":true},{"text":"Wonder if you're overreacting to a silly joke","then":"The doubt creeps back, just as he wanted."},{"text":"Reply with a long, angry message","then":"Nitin screenshots it and tells people you're unhinged."}],"why":"Pressure to stay quiet is part of the harm. You never owe anyone your silence."},{"prompt":"Back at college, a classmate says sharing a room means anything goes. What do you say?","options":[{"text":"Say it's fine if you're good friends","then":"The classmate nods, and 'friends' becomes the excuse."},{"text":"Agree, and wonder if you should have seen it coming","then":"The classmate nods, and the blame drifts from Nitin towards you."},{"text":"Joke that you'd sleep with one eye open","then":"People laugh, and the point gets lost."},{"text":"Say a shared room is never an invitation","then":"The classmate pauses: \"Yeah. Put like that, obviously.\"","best":true}],"why":"Closeness is never consent. Your space stays your call, wherever you sleep."}],"debrief":"A shared room or closeness is never an invitation; your space stays your call.","relearn":"A shared room is never an invitation; your space stays your call."},
  {"id":"cr-921","cat":"real-situations","type":"branch","persona":"any","source":"enthusiasm as core","hook":"Your partner Aarav is fully into the moment: eyes bright, leaning in, clearly keen.","steps":[{"prompt":"You're keen too. What do you do?","options":[{"text":"Hold back, worried eagerness is 'too much'","then":"Aarav notices you pulling back and wonders if he did something wrong."},{"text":"Match his energy and enjoy it together","then":"Aarav grins, and the moment feels easy and warm.","best":true},{"text":"Enjoy it, but keep your own feelings to yourself","then":"Aarav can't tell if you're as into it as he is."},{"text":"Tease him for being so eager","then":"Aarav blushes and dials it down, a bit embarrassed."}],"why":"A real, eager yes on both sides is what makes intimacy good."},{"prompt":"Midway, Aarav slows down to check you're still enjoying it. What do you do?","options":[{"text":"Say you'd rather he didn't break the mood","then":"Aarav hesitates, unsure whether to check next time."},{"text":"Nod quickly and hope he doesn't ask again","then":"Aarav smiles, but he isn't sure what the nod meant."},{"text":"Answer honestly and thank him for asking","then":"Aarav smiles wide, and the closeness deepens.","best":true},{"text":"Joke that he's being too careful","then":"Aarav laughs, a bit self-conscious."}],"why":"An honest answer and a warm thanks make checking in easy for both of you."},{"prompt":"Later, a friend says enthusiasm talk sounds like a rule, not romance. What do you say?","options":[{"text":"Agree it's mostly about staying out of trouble","then":"Your friend nods, and the warm part gets lost."},{"text":"Say an eager yes is what makes it good","then":"Your friend smiles: \"Huh. That actually sounds nice.\"","best":true},{"text":"Say you don't really think about it","then":"Your friend shrugs, and the chance to share it passes."},{"text":"Say only new couples need to care about it","then":"Your friend nods, and long-term couples get left out."}],"why":"Enthusiasm isn't just a rule. It's the warm core that makes it good."}],"debrief":"A real, eager yes is the positive core that makes intimacy good.","relearn":"A real, eager yes is what makes intimacy good, not just allowed."},
  {"id":"cr-922","cat":"real-situations","type":"branch","persona":"any","source":"text after a date","hook":"After a fun first date, Gaurav texts that tonight was great, but no pressure for anything more, ever.","steps":[{"prompt":"You read it twice. What do you do?","options":[{"text":"Reply that it kills the romance a bit","then":"Gaurav replies: \"Oh. Sorry. Didn't mean it like that.\""},{"text":"Read it as him not being interested","then":"You leave it on read, and Gaurav wonders what he said."},{"text":"Send \"ok\" and nothing else","then":"Gaurav can't tell if you're pleased or annoyed."},{"text":"Reply warmly. It's exactly the right note","then":"Gaurav sends a smiley and asks about a second date.","best":true}],"why":"Naming \"no pressure\" out loud is a green flag, not a buzzkill."},{"prompt":"Your friend Rhea says a guy saying 'no pressure' is trying too hard. What do you say?","options":[{"text":"Agree that it's a bit much","then":"Rhea nods, and the green flag starts to look like a red one."},{"text":"Say you'd rather someone who just goes for it","then":"Rhea grins, and 'goes for it' starts to sound like a compliment."},{"text":"Say it's a green flag, not a turn-off","then":"Rhea thinks: \"Okay, fair. That's actually sweet.\"","best":true},{"text":"Say you'll wait and see what he's really after","then":"The suspicion makes you cooler on the next text."}],"why":"Care said out loud is attractive. Pushiness dressed as confidence isn't."},{"prompt":"Gaurav texts again, asking if his message felt awkward. What do you do?","options":[{"text":"Say yes, a little, but it's fine","then":"Gaurav apologises, and he'll likely skip saying it next time."},{"text":"Say you forgot about it","then":"Gaurav replies \"oh ok\", a bit deflated."},{"text":"Say you'd rather he just knew what you want","then":"Gaurav replies: \"I can't read minds, though.\""},{"text":"Say it felt safe, and you'd like to meet again","then":"Gaurav replies: \"Phew. Friday?\"","best":true}],"why":"Meeting care with warmth builds trust and invites more of it."}],"debrief":"A clear \"no pressure\" is a green flag; meeting it warmly builds trust.","relearn":"A \"no pressure\" message is a green flag; meet it warmly, not with a push-back."},
  {"id":"cr-923","cat":"real-situations","type":"branch","persona":"Aarti","source":"consent inside marriage","hook":"Your spouse Vivek assumes marriage means a yes is automatic on any night.","steps":[{"prompt":"Tonight you're tired, and he doesn't ask. What do you do?","options":[{"text":"Tell yourself a spouse can't really refuse","then":"The thought weighs on you, but Vivek, half asleep, just rolls over."},{"text":"Say kindly you'd like to be asked, each time","then":"Vivek looks surprised: \"I thought, since we're married... But okay.\"","best":true},{"text":"Worry that raising it will hurt his feelings","then":"The worry keeps you quiet, and the question stays with you all night."},{"text":"Tell him sharply that marriage isn't a contract","then":"Vivek looks stung and goes quiet, not sure what he did."}],"why":"Marriage never banks consent. Being asked each time is your right."},{"prompt":"At dinner, Vivek shares a friend's joke that married couples never need to ask. What do you do?","options":[{"text":"Wonder if your tiredness is the real problem","then":"The doubt turns his assuming into something you must fix."},{"text":"Tell him his friends are backward","then":"Vivek bristles and defends his friends."},{"text":"Say marriage makes asking matter more, not less","then":"Vivek is quiet, then says: \"I never thought of it like that.\"","best":true},{"text":"Tell yourself his friends know marriage better","then":"The idea settles in, and their view starts to feel like the rule."}],"why":"Consent is freely given each time, and marriage makes that matter more."},{"prompt":"Weeks later, Vivek still doesn't ask some nights, and it weighs on you. What do you do?","options":[{"text":"Talk it over with a friend or cousin you trust","then":"Your cousin Nidhi listens: \"You deserve to be asked. It's not your fault.\"","best":true},{"text":"Keep it to yourself, since it's private","then":"You carry it alone, and it grows heavier."},{"text":"Tell yourself this is just part of marriage","then":"The thought settles in, and you stop expecting to be asked."},{"text":"Raise it with both families at once","then":"Everyone has an opinion, and it becomes about the families, not you."}],"why":"It's never your fault. A trusted person, and 181 if you need it, can help."},{"prompt":"At a family function, an aunt jokes that married people never say no. What do you do?","options":[{"text":"Laugh along so no one at the function is embarrassed","then":"The aunties laugh, and the idea goes round unchallenged."},{"text":"Smile and say everyone gets asked, married or not","then":"The aunt blinks, then laughs: \"Modern ideas!\" A cousin grins at you.","best":true},{"text":"Lecture her in front of everyone","then":"The room goes stiff, and the aunt looks offended."},{"text":"Quietly tell a cousin later instead","then":"Your cousin agrees, but the aunt's joke still stands."}],"why":"A light, clear line changes the joke without shaming anyone."}],"debrief":"Consent is freely given each time, marriage included; being asked is your right.","relearn":"Marriage never assumes a yes; consent is freely given each time."},
  {"id":"cr-924","cat":"real-situations","type":"role-play","persona":"any","source":"voicing a boundary","hook":"You've been seeing Ishaan for three weeks, and things are moving faster than you'd like.","setup":"He's walking you back to your PG.","steps":[{"prompt":"Ishaan asks: \"Come up to my place for a bit?\"","options":[{"text":"\"Not tonight. Early class tomorrow.\"","then":"\"Tomorrow then?\" he asks, already planning."},{"text":"\"I'm really into you. Can we take this slower?\"","then":"He smiles. \"Slower works. Thanks for telling me.\"","best":true},{"text":"\"Maybe? I don't know. What do you think we should do?\"","then":"He pauses. \"Only if you want to. Do you?\" You still don't know."},{"text":"\"Why are you always rushing things?\"","then":"He stops walking. \"Rushing? I just asked.\""}],"why":"Saying it plainly lets him meet you where you are. And a \"not sure\" should always mean stop."},{"prompt":"A few days later Ishaan asks: \"Did I come on too strong the other night?\"","options":[{"text":"\"No, no, you were fine. Forget it.\"","then":"\"Okay, cool,\" he says, relieved, and nothing changes."},{"text":"\"Maybe I'm just not experienced enough for you.\"","then":"He frowns. \"That's not it. I just want you comfortable.\""},{"text":"\"A bit. I like you. I just want to go slower.\"","then":"He nods. \"Okay. Tell me if I ever go too fast.\"","best":true},{"text":"\"You did. Honestly, it put me off you.\"","then":"His face falls. \"Oh. Should I back off completely?\""}],"why":"Naming it plainly, without apology, is what lets a good partner adjust."},{"prompt":"Your friend Meher asks: \"Won't asking to slow down make him lose interest?\"","options":[{"text":"\"Maybe. So I keep it short and don't make a fuss.\"","then":"\"Short like what?\" Meher asks. You don't really know."},{"text":"\"Maybe. I'll hint and hope he gets it.\"","then":"\"Hinting never works on me,\" Meher laughs."},{"text":"\"Probably. Nobody likes waiting.\"","then":"Meher sighs. \"So we just rush everything?\""},{"text":"\"Someone who likes me will want me comfortable.\"","then":"Meher nods slowly. \"True. I need to hear that myself.\"","best":true}],"why":"A boundary said plainly shows you who respects you. That's the point of saying it."}],"relearn":"You can ask to slow down plainly; a good partner welcomes it."},
  {"id":"cr-925","cat":"real-situations","type":"role-play","persona":"any","source":"changing your mind","hook":"You and Sana started kissing at her flat, but now you want to stop.","setup":"The fan whirs, and her phone buzzes, ignored.","steps":[{"prompt":"Sana pulls back and asks: \"What's up? You started this.\"","options":[{"text":"\"I know. I want to stop now.\"","then":"Sana sighs. \"Okay. Bit of a mood-killer, but okay.\"","best":true},{"text":"\"Sorry. I didn't mean to lead you on.\"","then":"Sana smiles. \"Then you're not really stopping, are you?\""},{"text":"\"I guess once you start, you're meant to finish?\"","then":"\"Usually, yeah,\" Sana says, and waits."},{"text":"\"Don't guilt me. You always do this.\"","then":"Sana stiffens. \"I only asked what's up.\""}],"why":"Starting something is never a promise to finish it, and stopping isn't leading anyone on."},{"prompt":"Sana says: \"Honestly, it's a bit unfair to stop halfway.\"","options":[{"text":"\"You're right. Sorry. I shouldn't have started.\"","then":"\"Well, you did,\" Sana says, still sulking."},{"text":"\"It's not unfair. I'm allowed to change my mind.\"","then":"Sana is quiet, then shrugs. \"Fine. I'll get us some tea.\"","best":true},{"text":"\"Unfair? You're being so selfish right now.\"","then":"Sana bristles. \"Selfish? I only said how I felt.\""},{"text":"\"Let me explain properly why I stopped. It's complicated.\"","then":"Sana listens, then says, \"That doesn't sound like a real reason.\""}],"why":"Changing your mind is always fair. You don't have to earn it or justify it."},{"prompt":"Back home your friend Dev asks: \"You seem off. Did something happen?\"","options":[{"text":"\"Nothing. I probably overreacted.\"","then":"\"Are you sure?\" Dev asks. You nod, and the knot stays."},{"text":"\"Just a date thing. I'd rather keep it private.\"","then":"\"Okay,\" Dev says. \"I'm here if that changes.\""},{"text":"\"Sana pushed after I stopped. Can we talk?\"","then":"Dev puts his phone down. \"Of course. Tell me.\"","best":true},{"text":"\"I'm going to post about her in the group.\"","then":"Dev winces. \"Maybe talk it out with me first?\""}],"why":"Being pushed after a no is never your fault. Talking to someone you trust helps."}],"relearn":"You can stop at any time and you don't owe a reason."},
  {"id":"cr-926","cat":"real-situations","type":"role-play","persona":"Mehta","source":"asking what they want","hook":"Things are heating up with Tanvi, and you want checking in to feel easy, not clinical.","setup":"You're curled up together at her place.","steps":[{"prompt":"Tanvi whispers: \"I'm glad we're here.\"","options":[{"text":"\"Me too. Just stop me if anything's not okay.\"","then":"She nods. \"Okay,\" she says, a little unsure."},{"text":"\"Me too. Let's not overthink it.\"","then":"\"Sure,\" she says, and her smile flickers."},{"text":"\"Me too. Tell me what you like. I want this good.\"","then":"She laughs softly. \"Slow. And I like when you ask.\"","best":true},{"text":"\"Me too. You seem relaxed, so I'll take that as a yes.\"","then":"She hesitates. \"I mean, I'm still deciding.\""}],"why":"Asking what she likes invites her voice in. Waiting for a stop puts it all on her."},{"prompt":"A bit later Tanvi asks: \"Is this okay for you, too?\"","options":[{"text":"\"Yes, really. And I love that you asked.\"","then":"She grins. \"Good. Then let's keep asking each other.\"","best":true},{"text":"\"Don't worry about me. This is about you.\"","then":"\"But I do,\" she says. \"I want it good for both of us.\""},{"text":"\"Of course. Why wouldn't it be?\"","then":"She shrugs. \"Just checking.\" She doesn't ask again."},{"text":"\"Mostly. I'll tell you later if something bugged me.\"","then":"She pulls back a little. \"Wait, is something bugging you now?\""}],"why":"An honest yes, and a warm welcome for her question, make asking feel normal."},{"prompt":"The next morning Tanvi says: \"I was nervous about asking stuff. Was it weird?\"","options":[{"text":"\"A little. Maybe we won't need to next time.\"","then":"\"Oh. Okay,\" she says, and looks down at her tea."},{"text":"\"No, but you can skip it with me. I'm easy.\"","then":"\"If you say so,\" she says, looking unconvinced."},{"text":"\"Ha, it did feel like a checklist.\"","then":"She flushes. \"Right. I'll stop doing that.\""},{"text":"\"Not weird at all. It made it better.\"","then":"She relaxes. \"Okay. Then I'll keep asking.\"","best":true}],"why":"Telling her it made things better keeps the habit alive for both of you."}],"relearn":"A warm \"tell me what you like\" makes intimacy better, not awkward."},
  {"id":"cr-927","cat":"real-situations","type":"role-play","persona":"Rohan","source":"hearing a no","hook":"You finally asked Mitali out after weeks of chatting in the canteen.","setup":"She puts her cup down, looking apologetic.","steps":[{"prompt":"Mitali says: \"You're sweet, but I'm not interested like that.\"","options":[{"text":"\"Is it something I did? I can change it.\"","then":"She shifts. \"It's not about changing. It's just no.\""},{"text":"\"All good. Thanks for being honest.\"","then":"She smiles, relieved. \"Thanks. Still canteen buddies?\"","best":true},{"text":"\"Cool, cool. Wasn't that serious anyway.\"","then":"She raises an eyebrow. \"Oh. Okay then.\""},{"text":"\"Just one coffee? You might change your mind.\"","then":"Her smile fades. \"I said no. Please don't.\""}],"why":"A no is information, not a verdict on you. Taking it lightly keeps your dignity."},{"prompt":"That evening your friend Kunal texts: \"Heard she said no. You okay?\"","options":[{"text":"\"She's clearly into someone richer.\"","then":"\"Yaar, don't go down that road,\" Kunal replies."},{"text":"\"Totally fine. Didn't even care, honestly.\"","then":"\"Sure,\" Kunal replies. You spend the night rereading her texts."},{"text":"\"Stings a bit. I'll live. She was nice about it.\"","then":"\"Respect,\" Kunal replies. \"Chai tomorrow? My treat.\"","best":true},{"text":"\"Tell me how to change her mind. There must be a way.\"","then":"Kunal sends a list of \"moves\" from some reels guy."}],"why":"Admitting it stings, without blaming her, is how you actually get over it."},{"prompt":"A week later Mitali asks in the canteen: \"Hey, no weirdness, right?\"","options":[{"text":"\"Depends. Have you thought about it more?\"","then":"Her face tightens. \"No. I told you already.\""},{"text":"\"None. Pass the chutney?\"","then":"She laughs and passes it. The table feels normal again.","best":true},{"text":"\"Weird? Me? I've forgotten all about it.\"","then":"\"Okay,\" she says, not quite believing you."},{"text":"\"None, as long as you don't date Varun.\"","then":"She stares. \"Who I date isn't up to you.\""}],"why":"Staying easy and friendly shows the no really landed. That's real confidence."}],"relearn":"Taking a no with grace is the confident move; no one owes you a yes."},
  {"id":"cr-928","cat":"real-situations","type":"role-play","persona":"any","source":"naming a limit","hook":"Tonight with Reza is going well, but there's one thing you're not up for.","setup":"He's just suggested something new, grinning.","steps":[{"prompt":"Reza asks: \"So, want to try it?\"","options":[{"text":"\"Maybe some other time?\"","then":"\"Next weekend?\" he asks, grinning."},{"text":"\"Ugh, seriously? Why would you even suggest that?\"","then":"He flushes. \"Sorry. I only asked.\""},{"text":"\"I'm enjoying this. Not that, though.\"","then":"He nods. \"Got it. Thanks for saying so.\"","best":true},{"text":"\"Sorry, I'm kind of boring like that.\"","then":"He laughs. \"You're not boring. So is that a no?\""}],"why":"A clear limit, said kindly, needs no apology and leaves nothing to guess."},{"prompt":"A little later Reza asks: \"Is there anything you do want?\"","options":[{"text":"\"Whatever you like is fine.\"","then":"\"But what do you like?\" he asks, a little puzzled."},{"text":"\"Yes. Slow, and just this. I like this.\"","then":"He smiles. \"That, I can do.\"","best":true},{"text":"\"Why, are you bored already?\"","then":"\"No!\" he says. \"I just want you to enjoy it too.\""},{"text":"\"Let's not talk. Talking makes it awkward.\"","then":"\"Okay,\" he says. He goes quiet and seems to be guessing."}],"why":"Saying what you do want, not only what you don't, is how it gets good."},{"prompt":"The next day your friend Pooja says: \"I never say when I'm not into something. It's easier.\"","options":[{"text":"\"Same. It's not worth the awkwardness.\"","then":"\"Right?\" Pooja says. You both change the subject."},{"text":"\"You can say no to one thing and keep the rest.\"","then":"Pooja thinks. \"Huh. I never tried just saying it.\"","best":true},{"text":"\"Then that's on you if you don't enjoy it.\"","then":"Pooja looks stung. \"Wow. Okay.\""},{"text":"\"Just drop hints. They'll figure it out eventually.\"","then":"\"They never do,\" Pooja sighs."}],"why":"You never have to put up with what you don't want. One limit doesn't end the night."}],"relearn":"You can name a limit plainly; you never have to endure what you don't want."},
  {"id":"cr-929","cat":"real-situations","type":"role-play","persona":"any","source":"online consent","hook":"Nikhil, a guy you matched with, keeps asking you to send an intimate photo.","setup":"It's late, and his messages keep coming.","steps":[{"prompt":"Nikhil texts: \"Just one pic. I'll delete it, promise.\"","options":[{"text":"\"Maybe after we've met in person.\"","then":"\"Deal,\" he replies. \"I'll remind you.\""},{"text":"\"I'm not sending that. Please stop asking.\"","then":"\"Relax. It was a joke,\" he replies. \"Unless?\"","best":true},{"text":"\"Sorry, I'm just shy about that stuff.\"","then":"\"Don't be shy with me,\" he replies. \"I'll send one first.\""},{"text":"\"Haha, you wish. Anyway, what are you up to?\"","then":"\"Thinking about you,\" he replies. \"So, that pic?\""}],"why":"A clear no, with no excuse to argue with, is all you owe him."},{"prompt":"Nikhil texts: \"Everyone sends them. Don't you trust me?\"","options":[{"text":"\"I do trust you. I'm just not ready.\"","then":"\"So when will you be ready?\" he replies."},{"text":"\"Sorry. I know I'm being difficult.\"","then":"\"You are, a bit,\" he replies. \"Make it up to me.\""},{"text":"\"This isn't about trust. The answer is no.\"","then":"\"Wow. Okay,\" he replies. \"Thought you were fun.\"","best":true},{"text":"\"Maybe everyone does. I just feel weird about it.\"","then":"\"Weird is normal at first,\" he replies. \"Just try once.\""}],"why":"Asking again and again is pressure. Trust is never a reason to send."},{"prompt":"Nikhil texts: \"Fine. I'll find someone who isn't so boring.\"","options":[{"text":"\"Maybe I am boring. Everyone else sends them.\"","then":"\"Glad you see it,\" he replies. \"So prove me wrong.\""},{"text":"\"Sorry if I led you on.\"","then":"\"You did,\" he replies. \"Least you could do is one pic.\""},{"text":"\"Go ahead. I'm done with this chat.\"","then":"\"Your loss,\" he replies. Then nothing.","best":true},{"text":"\"Good luck. Nobody will send you anything, creep.\"","then":"\"Creep? Wow,\" he replies, and sends three angry texts."}],"why":"You don't owe him a defence or a fight. Ending the chat protects your peace."},{"prompt":"Later your roommate Aisha asks: \"Who's been blowing up your phone?\"","options":[{"text":"\"No one. It's handled.\"","then":"\"Okay,\" Aisha says, and goes back to her book."},{"text":"\"Just a guy. I kind of brought it on myself.\"","then":"Aisha frowns. \"How is someone pushing you your fault?\""},{"text":"\"A match pushing for pics. Can I show you?\"","then":"Aisha sits beside you. \"Yes. Let's block and report him too.\"","best":true},{"text":"\"Just a guy. Everyone deals with this. It's nothing.\"","then":"\"Hmm,\" Aisha says. \"Doesn't look like nothing.\""}],"why":"It's never your fault when someone pushes. Telling a friend means you're not alone with it."}],"relearn":"Your no covers photos too; a repeated ask is pressure, not persuasion."},
  {"id":"cr-930","cat":"real-situations","type":"role-play","persona":"Meena","source":"off-campus, plain words","hook":"Your flatmate Suresh keeps knocking on your door at night, asking to come in.","setup":"It's past eleven, and he's knocking again.","steps":[{"prompt":"Suresh says through the door: \"Just open for a minute. Why so stiff?\"","options":[{"text":"\"Sorry, I don't mean to be rude. It's just late.\"","then":"\"Not rude, just stiff,\" he says. \"Open up, na.\""},{"text":"\"What will people say if you come in?\"","then":"\"Nobody will know,\" he says, and knocks again."},{"text":"\"No. Don't come into my room. I mean it.\"","then":"A pause. \"Okay, okay. No need to shout,\" he mutters, and walks off.","best":true},{"text":"\"Did I give you the wrong idea somehow?\"","then":"He hears the doubt. \"Then open up and we'll sort it out.\""}],"why":"A plain no, said once, is enough. You never owe him an apology or a reason."},{"prompt":"Next morning Suresh says: \"About last night. Don't make it a big thing, okay?\"","options":[{"text":"\"Sorry. Maybe I did overreact.\"","then":"\"See? Just chill,\" he says, grinning."},{"text":"\"It is a big thing. Stay out of my room.\"","then":"He rolls his eyes. \"Fine. Relax.\" He doesn't sound convinced.","best":true},{"text":"\"I guess guys just act like that sometimes.\"","then":"\"Exactly,\" he says, grinning. You still feel uneasy locking your door."},{"text":"\"Do it again and I'll tell your mother.\"","then":"He laughs. \"She'll say you're making drama.\""}],"why":"Brushing it off doesn't change your no. You don't have to apologise for it."},{"prompt":"Your landlady Mrs. Pillai asks: \"You look tired. Everything okay at the flat?\"","options":[{"text":"\"All fine, aunty. Just work stress.\"","then":"\"Take care of yourself, beta,\" she says, and moves on."},{"text":"\"No. Suresh keeps trying to come into my room.\"","then":"She frowns. \"That's not okay. I'll speak to him. Call me anytime.\"","best":true},{"text":"\"It's nothing. Probably my fault for being friendly.\"","then":"\"Friendly isn't an invitation,\" she says. \"What's he doing?\""},{"text":"\"Just flatmate stuff. I don't want to make drama.\"","then":"\"What kind of stuff?\" she asks. You shrug, and it stays unsaid."}],"why":"Telling someone you trust is strength, not drama. What he does is never your fault."},{"prompt":"On the phone your cousin Lata asks: \"What if he tries again and nobody's around?\"","options":[{"text":"\"I'll manage. Helplines are for serious stuff.\"","then":"\"This is serious,\" Lata says, sounding worried."},{"text":"\"Nothing I can do. There's no warden here.\"","then":"\"You don't need a warden to get help,\" Lata says."},{"text":"\"I'll get my brother to come over and beat him up.\"","then":"\"That could get you both in trouble,\" Lata says."},{"text":"\"I'll lock my door and call 112 if I feel unsafe.\"","then":"\"And save 181 too. It's there day or night,\" Lata says.","best":true}],"why":"Help reaches you anywhere, no warden needed. 112 is there for danger, any hour."}],"relearn":"A plain no is enough anywhere; you don't owe a soft maybe to keep the peace."},
  {"id":"cr-931","cat":"real-situations","type":"role-play","persona":"any","source":"checking before","hook":"You and your new partner Farah are about to take things further for the first time.","setup":"She's smiling, but a little quiet.","steps":[{"prompt":"Farah says softly: \"I'm glad it's you.\"","options":[{"text":"\"Me too. Let's just go with it and see how it feels.\"","then":"\"Okay,\" she says, but her shoulders tense a little."},{"text":"\"You're smiling, so I'll take that as a yes.\"","then":"Her smile slips. \"I mean, I'm still nervous.\""},{"text":"\"Is this something you want? We can stop anytime.\"","then":"She nods. \"Yes. And thank you for saying I can stop.\"","best":true},{"text":"\"Me too. We don't need to talk about it, right?\"","then":"\"Right,\" she says, and looks away."}],"why":"Asking first, and saying she can stop, makes her yes clear and free."},{"prompt":"A few minutes later Farah says: \"Wait. Can we slow down a little?\"","options":[{"text":"\"Sure. Did I do something wrong?\"","then":"\"No, no,\" she says, now soothing you instead."},{"text":"\"Of course. Thanks for telling me.\"","then":"She relaxes. \"Thanks. This feels better.\"","best":true},{"text":"\"Okay. But you said yes earlier.\"","then":"She pulls away. \"I know. I'm saying something different now.\""},{"text":"\"Sure. Just a couple more minutes like this?\"","then":"She hesitates. \"I said slower.\""}],"why":"Slowing down the moment she asks keeps her yes real at every step."},{"prompt":"Later Farah asks: \"Were you annoyed when I asked to slow down?\"","options":[{"text":"\"A bit, honestly. But it's fine.\"","then":"She goes quiet. \"I'll try not to next time.\""},{"text":"\"No. But next time, maybe tell me earlier.\"","then":"\"I didn't know earlier,\" she says slowly."},{"text":"\"Not annoyed. Just surprised, since you seemed into it.\"","then":"\"I was into it,\" she says. \"Then I wasn't.\""},{"text":"\"No. I want you to tell me every time.\"","then":"She smiles. \"Okay. That makes me feel safe with you.\"","best":true}],"why":"Welcoming her no, every time, is what keeps asking honest between you."}],"relearn":"Asking first, and naming that you can stop, keeps it clearly consensual."},
  {"id":"cr-932","cat":"real-situations","type":"role-play","persona":"Zoya","source":"no assumptions","hook":"Your second date with Rhea is going well, but you don't know what she's comfortable with.","setup":"You're walking her home after dinner.","steps":[{"prompt":"At her gate Rhea says: \"I don't want tonight to end yet.\"","options":[{"text":"\"Same. I think we're on the same page anyway.\"","then":"She laughs. \"Which page is that?\" You realise you don't know."},{"text":"\"Same. What would feel good to you?\"","then":"She thinks. \"A walk, and maybe a kiss. Slowly.\"","best":true},{"text":"\"Same. I'll just go with whatever happens.\"","then":"\"Hmm,\" she says. Neither of you knows what the other wants."},{"text":"\"Same. So that's a yes to coming up?\"","then":"She blinks. \"I meant a walk, actually.\""}],"why":"Asking what feels good, instead of assuming, gives her real answer room."},{"prompt":"A little later Rhea says: \"Most people I've dated just assume what I want.\"","options":[{"text":"\"Honestly, I figured we'd both want the same.\"","then":"She tilts her head. \"Not always. I'm pretty slow.\""},{"text":"\"Don't worry. I'm good at reading people.\"","then":"\"Are you, though?\" she asks, half smiling."},{"text":"\"I'd rather ask. It's the only way I'd know.\"","then":"She smiles. \"Then ask me anything. I'll ask too.\"","best":true},{"text":"\"Asking feels awkward, though. Don't you think?\"","then":"She shrugs. \"Less awkward than guessing wrong.\""}],"why":"Assuming shared wants can miss the person in front of you. Asking finds them."},{"prompt":"On your next date Rhea says: \"Tonight I'm less sure. Can we just talk?\"","options":[{"text":"\"But last time you wanted to kiss.\"","then":"She crosses her arms. \"Last time was last time.\""},{"text":"\"Sure. Let me know when you're back in the mood.\"","then":"\"It's not a mood thing,\" she says quietly."},{"text":"\"Sure. Maybe a drink will help you relax?\"","then":"She pulls back. \"I don't need to relax. I need to talk.\""},{"text":"\"Yes. Talking sounds nice.\"","then":"She smiles. \"Thanks. Chai, then?\"","best":true}],"why":"Each time needs its own yes. Honouring today's answer is what matters."}],"relearn":"Consent is the same for everyone; ask rather than assume shared wants."},
  {"id":"cr-933","cat":"real-situations","type":"role-play","persona":"Ananya","source":"the right to stop","hook":"You went back to Varun's room after the party, and mid-moment you realise you want to stop.","setup":"He notices you've pulled away.","steps":[{"prompt":"Varun asks: \"What's wrong? You came up here.\"","options":[{"text":"\"Sorry. I know coming here gave you ideas.\"","then":"\"Well, a bit,\" he says. \"Why else come up?\""},{"text":"\"I've changed my mind. I want to stop now.\"","then":"He sits back. \"Okay. Uh, want me to call you a cab?\"","best":true},{"text":"\"Nothing. Sorry, I'm being so dramatic.\"","then":"\"A little,\" he says, and waits."},{"text":"\"Can you please not make this weird right now?\"","then":"\"I'm not making it weird,\" he says. \"You are.\""}],"why":"Coming to his room was never a yes. You can stop at any point, no reason owed."},{"prompt":"Varun says: \"Honestly, I thought this was where tonight was going.\"","options":[{"text":"\"I know. I'm sorry I messed it up.\"","then":"\"It's fine,\" he sighs. \"You kind of did, though.\""},{"text":"\"It's not you. I'm just not in the mood tonight.\"","then":"\"Maybe you'll get in the mood,\" he says, smiling."},{"text":"\"I get that. I still want to stop.\"","then":"He nods slowly. \"Okay. I'll walk you down.\"","best":true},{"text":"\"That's so typical. Everyone just expects things.\"","then":"\"Everyone?\" he says, stung. \"I'm just saying what I thought.\""}],"why":"His expectation is his to manage. Your no doesn't need his agreement."},{"prompt":"Back at the hostel your friend Kavya asks: \"You left early. All okay?\"","options":[{"text":"\"Fine. I shouldn't have gone to his room.\"","then":"\"Going to his room doesn't mean anything,\" Kavya says. \"What happened?\""},{"text":"\"He pushed when I wanted to stop. Can we talk?\"","then":"Kavya pulls you onto her bed. \"Tell me. I'm listening.\"","best":true},{"text":"\"All okay. Don't tell anyone I went up.\"","then":"\"Of course not,\" Kavya says. \"But are you okay?\""},{"text":"\"Totally fine. Guys are just like that, whatever.\"","then":"Kavya frowns. \"Like what, though?\""}],"why":"Going to someone's place never makes it your fault. Talking to a friend helps."}],"relearn":"Going to someone's place is never a yes; you can stop at any time."},
  {"id":"cr-934","cat":"real-situations","type":"spot","persona":"any","source":"reading the yes","relearn":"A clear, willing yes is consent; a reluctant \"if you want\" or a pressured nod is not.","hook":"Spot the yes that isn't really a yes.","scene":[{"id":"a","text":"\"Yes, I'd love to\"","trick":false},{"id":"b","text":"\"...okay, if you really want\"","trick":true},{"id":"c","text":"\"Absolutely, come here\"","trick":false},{"id":"d","text":"A long silence, then a tiny nod","trick":true},{"id":"e","text":"\"Yes! I've been waiting for this\"","trick":false}],"why":"A clear, willing yes is consent; a reluctant \"if you want\" or a pressured nod is not."},
  {"id":"cr-935","cat":"real-situations","type":"spot","persona":"any","source":"consent online","relearn":"Consent covers messages and images; an unasked pic or resharing a private photo crosses the line.","hook":"Spot the move that ignores consent in a chat.","scene":[{"id":"a","text":"Asking \"can I call you tonight?\"","trick":false},{"id":"b","text":"Sending an explicit pic unasked","trick":true},{"id":"c","text":"Saying \"no rush, reply whenever\"","trick":false},{"id":"d","text":"Saving a private photo to reshare","trick":true},{"id":"e","text":"Checking \"is this too forward?\"","trick":false}],"why":"Consent covers messages and images; an unasked pic or resharing a private photo crosses the line."},
  {"id":"cr-936","cat":"real-situations","type":"spot","persona":"any","source":"freely given","relearn":"A free yes has no pressure behind it; a guilt-trip or a power-play makes a \"yes\" unfree.","hook":"Spot the yes that isn't freely given.","scene":[{"id":"a","text":"A relaxed, unhurried \"yes\"","trick":false},{"id":"b","text":"Yes, after \"everyone does this\"","trick":true},{"id":"c","text":"Yes, with a warm, easy smile","trick":false},{"id":"d","text":"Yes, so the boss stays pleased","trick":true},{"id":"e","text":"Yes, no pressure anywhere near it","trick":false}],"why":"A free yes has no pressure behind it; a guilt-trip or a power-play makes a \"yes\" unfree."},
  {"id":"cr-937","cat":"real-situations","type":"spot","persona":"Ananya","source":"ongoing consent","relearn":"Going still or turning away can be a freeze; pause and check rather than read it as a yes.","hook":"Spot the sign to pause and check.","scene":[{"id":"a","text":"They lean in and pull you closer","trick":false},{"id":"b","text":"They suddenly go still and quiet","trick":true},{"id":"c","text":"They say \"this is great\"","trick":false},{"id":"d","text":"They turn their face away","trick":true},{"id":"e","text":"They guide your hand, smiling","trick":false}],"why":"Going still or turning away can be a freeze; pause and check rather than read it as a yes."},
  {"id":"cr-938","cat":"real-situations","type":"spot","persona":"any","source":"enthusiasm vs politeness","relearn":"Enthusiasm is the bar; a polite \"I guess\" or a yes to avoid awkwardness isn't it.","hook":"Spot the polite yes that isn't enthusiasm.","scene":[{"id":"a","text":"\"Yes, I really want this\"","trick":false},{"id":"b","text":"\"Sure, I guess that's fine\"","trick":true},{"id":"c","text":"\"Yes, you read my mind\"","trick":false},{"id":"d","text":"\"Okay, to not make it weird\"","trick":true},{"id":"e","text":"\"Yes, please, I'm keen\"","trick":false}],"why":"Enthusiasm is the bar; a polite \"I guess\" or a yes to avoid awkwardness isn't it."},
  {"id":"cr-939","cat":"real-situations","type":"spot","persona":"any","source":"every step its own yes","relearn":"Coming over or kissing is never agreement to more; every new step needs its own willing yes.","hook":"Spot the assumption that skips a yes.","scene":[{"id":"a","text":"Asking before moving things on","trick":false},{"id":"b","text":"\"You came over, so obviously...\"","trick":true},{"id":"c","text":"Pausing to check a new step","trick":false},{"id":"d","text":"\"We kissed, so the rest is on\"","trick":true},{"id":"e","text":"\"Want to, or should we slow down?\"","trick":false}],"why":"Coming over or kissing is never agreement to more; every new step needs its own willing yes."},
  {"id":"cr-940","cat":"real-situations","type":"spot","persona":"any","source":"capacity","relearn":"Sober-enough and willing can consent; slurring, barely standing or passed out cannot.","hook":"Spot who cannot give consent right now.","scene":[{"id":"a","text":"Sober and clearly keen","trick":false},{"id":"b","text":"Slurring, can barely stand","trick":true},{"id":"c","text":"One drink, fully with it","trick":false},{"id":"d","text":"Passed out on the sofa","trick":true},{"id":"e","text":"Tipsy but sharp and eager","trick":false}],"why":"Sober-enough and willing can consent; slurring, barely standing or passed out cannot."},
  {"id":"cr-941","cat":"real-situations","type":"sort","persona":"any","source":"consent vs coercion","relearn":"A free yes is willing; a yes to stop sulking, anger or pestering is coercion, not consent.","hook":"Sort: free yes, or coercion?","items":[{"id":"a","text":"\"Yes, I'd love to\""},{"id":"b","text":"\"Fine, if you'll stop sulking\""},{"id":"c","text":"A clear, eager invitation"},{"id":"d","text":"\"Okay, so you won't be angry\""},{"id":"e","text":"\"Yes, I'm really into this\""},{"id":"f","text":"\"I guess, you keep on asking\""}],"bins":[{"id":"free","label":"Free yes","valence":"pos"},{"id":"coerce","label":"Coercion","valence":"neg"}],"key":{"a":"free","b":"coerce","c":"free","d":"coerce","e":"free","f":"coerce"}},
  {"id":"cr-942","cat":"real-situations","type":"sort","persona":"any","source":"can or cannot consent","relearn":"Sober-enough and willing can consent; asleep, blackout or passed out cannot.","hook":"Sort: can give consent now, or cannot?","items":[{"id":"a","text":"Sober and willing"},{"id":"b","text":"Asleep"},{"id":"c","text":"One drink, fully with it"},{"id":"d","text":"Blackout drunk"},{"id":"e","text":"Tipsy but sharp and eager"},{"id":"f","text":"Passed out"}],"bins":[{"id":"can","label":"Can consent","valence":"pos"},{"id":"cannot","label":"Cannot","valence":"neg"}],"key":{"a":"can","b":"cannot","c":"can","d":"cannot","e":"can","f":"cannot"}},
  {"id":"cr-943","cat":"real-situations","type":"sort","persona":"any","source":"builds or erodes","relearn":"Checking in and taking a no well build trust; mocking a boundary or pestering erode it.","hook":"Sort: builds trust, or erodes it?","items":[{"id":"a","text":"Checking \"is this good?\""},{"id":"b","text":"Mocking someone's boundary"},{"id":"c","text":"Taking a no gracefully"},{"id":"d","text":"Pestering after a no"},{"id":"e","text":"Looking out for a drunk friend"},{"id":"f","text":"Treating pressure as normal"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"}},
  {"id":"cr-944","cat":"real-situations","type":"sort","persona":"any","source":"his room myth","relearn":"Only a willing yes is consent; coming over, kissing or staying is never agreement to more.","hook":"Sort: a real yes, or just an assumption?","items":[{"id":"a","text":"\"Yes, I want to\" said clearly"},{"id":"b","text":"\"They came up, so obviously\""},{"id":"c","text":"An eager, spoken invitation"},{"id":"d","text":"\"We kissed, so it's all on\""},{"id":"e","text":"\"Yes\" with a real, keen smile"},{"id":"f","text":"\"They stayed over, so yes\""}],"bins":[{"id":"yes","label":"A real yes","valence":"pos"},{"id":"assume","label":"Just assumed","valence":"neg"}],"key":{"a":"yes","b":"assume","c":"yes","d":"assume","e":"yes","f":"assume"}},
  {"id":"cr-945","cat":"real-situations","type":"sort","persona":"any","source":"persuasion vs pressure","relearn":"One ask that accepts no is fine; repeating, guilt-debts or threats cross into pressure.","hook":"Sort: an ok ask, or crossing into pressure?","items":[{"id":"a","text":"Asking once, then accepting no"},{"id":"b","text":"Asking again and again after no"},{"id":"c","text":"\"No worries if not\""},{"id":"d","text":"\"You owe me after dinner\""},{"id":"e","text":"Suggesting a plan, open to no"},{"id":"f","text":"Threatening to leave if they refuse"}],"bins":[{"id":"ok","label":"An ok ask","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"ok","b":"pressure","c":"ok","d":"pressure","e":"ok","f":"pressure"}},
  {"id":"cr-946","cat":"real-situations","type":"sort","persona":"Rohan","source":"green flag or red flag","relearn":"Welcoming a stop and checking in are green flags; sulking, guilt or pushing past \"wait\" are red.","hook":"Sort: green flag, or red flag?","items":[{"id":"a","text":"\"Tell me if you want to stop\""},{"id":"b","text":"Sulking when told no"},{"id":"c","text":"Checking in as you go"},{"id":"d","text":"\"You're cold for saying no\""},{"id":"e","text":"Cheerfully accepting a pause"},{"id":"f","text":"Pushing past a quiet \"wait\""}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"}},
  {"id":"cr-947","cat":"real-situations","type":"sort","persona":"any","source":"revocable consent","relearn":"Consent is revocable any time; \"too late\" or \"we started\" ignores that, and that's not consent.","hook":"Sort: respects \"you can change your mind,\" or not?","items":[{"id":"a","text":"\"Stop anytime, just say\""},{"id":"b","text":"\"You already agreed, so\""},{"id":"c","text":"Stopping the second they pause"},{"id":"d","text":"\"Too late to back out now\""},{"id":"e","text":"\"Changed your mind? Totally fine\""},{"id":"f","text":"\"We started, so finish it\""}],"bins":[{"id":"respects","label":"Respects it","valence":"pos"},{"id":"ignores","label":"Ignores it","valence":"neg"}],"key":{"a":"respects","b":"ignores","c":"respects","d":"ignores","e":"respects","f":"ignores"}},
  {"id":"cr-948","cat":"real-situations","type":"reflect","persona":"any","source":"your pace","relearn":"Your pace is yours to set; no one is owed a faster one.","hook":"Lensy: your pace is yours to set, fast, slow, or not at all. How does that sit?","prompt":"What do you think?","options":["It's mine","My pace","Good"],"affirm":"Your pace is always yours; no one is owed a faster one, ever."},
  {"id":"cr-949","cat":"real-situations","type":"reflect","persona":"Ananya","source":"right to change your mind","relearn":"You can change your mind any moment; an earlier yes never binds you.","hook":"Lensy: you can change your mind any moment, even halfway, even after going to their place.","prompt":"How does that land?","options":["Reassuring","Any moment","Mine to change"],"affirm":"An earlier yes never binds you; changing your mind is always yours, no reason owed."},
  {"id":"cr-950","cat":"real-situations","type":"reflect","persona":"any","source":"enthusiasm is the core","relearn":"A real, eager yes is the core that makes intimacy good, not just allowed.","hook":"Lensy: a real, eager yes isn't just a rule, it's what makes intimacy actually good.","prompt":"Sit with that?","options":["True","The good part","Eager yes"],"affirm":"Enthusiasm is the warm core; aiming for a real yes makes intimacy better for everyone."},
  {"id":"cr-951","cat":"real-situations","type":"reflect","persona":"Rohan","source":"a no isn't about you","relearn":"A no isn't a verdict on you; respecting it is the dignified move.","hook":"Lensy: a no isn't a verdict on your worth, it's just an answer you get to respect.","prompt":"How's that to hear?","options":["Fair","Not a verdict","I can respect it"],"affirm":"A no never measures your worth; respecting it keeps your dignity intact."},
  {"id":"cr-952","cat":"real-situations","type":"reflect","persona":"any","source":"checking in is good","relearn":"Checking in isn't awkward; it builds trust and makes closeness better.","hook":"Lensy: asking \"is this good?\" isn't awkward, it's part of what makes closeness feel safe.","prompt":"Agree?","options":["Yes","Makes it safer","Not awkward"],"affirm":"Checking in builds trust and makes intimacy better; it's never a buzzkill."},
  {"id":"cr-953","cat":"real-situations","type":"reflect","persona":"Meena","source":"help exists for you","relearn":"Help exists even off-campus; reaching for it is strength, not weakness.","hook":"Lensy: even with no campus or warden, help still exists, and reaching for it is strength.","prompt":"How does that feel?","options":["Good to know","Strength","It's there"],"affirm":"Help reaches you anywhere; using it is the strong, adult move, never weakness."},
  {"id":"cr-954","cat":"real-situations","type":"reflect","persona":"any","source":"every step its own yes","relearn":"Every step needs its own yes; earlier closeness never decides the next.","hook":"Lensy: each step gets its own yes, kissing isn't a yes to more, and that's just how it works.","prompt":"Does that feel right?","options":["Right","Each step","Its own yes"],"affirm":"Every step deserves its own willing yes; earlier closeness never decides the next move."},
  {"id":"cr-955","cat":"real-situations","type":"match","persona":"any","source":"real scene to consent move","relearn":"Each real moment has a consent-first move: pause, stop, ask, hold your no, or see the power gap.","hook":"Match each real moment to the consent-first move.","pairs":[{"left":"They go quiet mid-moment","right":"Pause and check they're okay"},{"left":"You've changed your mind","right":"Say you want to stop, no reason owed"},{"left":"A new partner, first time","right":"Ask as you go what feels good"},{"left":"They asked for a nude, you'd rather not","right":"Hold your no; it covers photos"},{"left":"A senior makes a move","right":"See the power gap; a yes isn't free"}]},
  {"id":"cr-956","cat":"real-situations","type":"match","persona":"any","source":"moment to the words","relearn":"Plain words fit each moment: slow down, name a limit, check in, stop, or give a clear yes.","hook":"Match the moment to the words that fit it.","pairs":[{"left":"Setting a slower pace","right":"\"Can we take this slower?\""},{"left":"Naming a limit","right":"\"Not that tonight, though\""},{"left":"Checking in","right":"\"Is this good for you?\""},{"left":"Stopping","right":"\"I want to stop here\""},{"left":"Inviting clearly","right":"\"Yes, I really want to\""}]},
  {"id":"cr-957","cat":"real-situations","type":"match","persona":"any","source":"myth to truth","relearn":"Every myth has a truth: no silent yes, no assumed yes, no implied yes from coming over, dress or stillness.","hook":"Match each myth to the truth that answers it.","pairs":[{"left":"They didn't say no","right":"Absence of a no isn't a yes"},{"left":"We're together, so it's assumed","right":"Consent is freely given each time"},{"left":"They came back to mine","right":"Coming over is never a yes to more"},{"left":"They were dressed for it","right":"Clothes never imply consent"},{"left":"They didn't resist","right":"Not resisting is never consent"}]},
  {"id":"cr-958","cat":"real-situations","type":"match","persona":"any","source":"cue to read","relearn":"Read the cue: eager is a yes, worn-down isn't free, stillness means pause, passed out can't, tipsy-but-sharp can.","hook":"Match each cue to how to read it.","pairs":[{"left":"An eager, clear \"yes!\"","right":"Enthusiastic consent"},{"left":"A worn-down \"fine, okay\"","right":"Pressured, not a free yes"},{"left":"Going still and silent","right":"Pause and check"},{"left":"Passed out","right":"Cannot consent at all"},{"left":"Tipsy but sharp and keen","right":"Sober-enough to consent"}]},
  {"id":"cr-959","cat":"real-situations","type":"match","persona":"any","source":"step to its own yes","relearn":"Each step needs its own yes; a room, kiss, stay or text is never agreement to the next thing.","hook":"Match each step to what it does, and doesn't, mean.","pairs":[{"left":"Going to their room","right":"Not a yes to anything further"},{"left":"A kiss","right":"Not a yes to what comes next"},{"left":"Agreeing to stay over","right":"Not a yes to intimacy"},{"left":"A clear, eager \"yes\"","right":"Consent for that step"},{"left":"Sending a flirty text","right":"Not a yes to a photo"}]},
  {"id":"cr-960","cat":"real-situations","type":"match","persona":"any","source":"behaviour to flag","relearn":"Welcoming a stop and checking in are green; sulking and pestering are red; bystander care is culture.","hook":"Match each behaviour to the flag it raises.","pairs":[{"left":"Welcoming a \"let's stop\"","right":"Green flag"},{"left":"Sulking at a no","right":"Red flag"},{"left":"Checking in as you go","right":"Builds trust"},{"left":"Pestering after a no","right":"Pressure, not romance"},{"left":"Looking out for a drunk friend","right":"Consent culture"}]},
  {"id":"cr-961","cat":"real-situations","type":"match","persona":"any","source":"need to real route","relearn":"Real routes: 112 for danger, 181 for any violence, the campus ICC, a counsellor, or 1091.","hook":"Match each need to a real route for it.","pairs":[{"left":"Immediate danger","right":"112"},{"left":"Any violence, confidential","right":"181"},{"left":"Campus harassment","right":"Campus Internal Committee (POSH/UGC)"},{"left":"Someone to talk it through","right":"A campus counsellor"},{"left":"Women in distress","right":"1091"}]},
  {"id":"cr-962","cat":"real-situations","type":"match","persona":"any","source":"feeling to the move","relearn":"Your feeling guides the move: unsure means stop, slower means say so, off it means stop, keen means enjoy.","hook":"Match each feeling to the consent-first move it points to.","pairs":[{"left":"\"I'm not sure about this\"","right":"That uncertainty means stop"},{"left":"\"I want to but slower\"","right":"Say so and set the pace"},{"left":"\"I've gone off it now\"","right":"Withdraw your yes anytime"},{"left":"\"I'm fully into this\"","right":"Enjoy it together"},{"left":"\"They seem hesitant\"","right":"Check in for the real answer"}]},
  {"id":"cr-963","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"didn't block me after","relearn":"Staying polite afterwards is not proof it was okay; only a willing yes was.","hook":"The \"they didn't block me after, so it was fine\" myth.","myth":{"un":"They didn't block me afterwards, so it must have been fine.","re":"People often stay polite or in contact to stay safe, not because they agreed.","why":"How someone acts after says nothing about whether they wanted it then."}},
  {"id":"cr-964","cat":"real-situations","type":"strike-rewrite","persona":"Ananya","source":"invited in for chai","relearn":"An invite in is just hospitality, never agreement to anything more.","hook":"The \"they invited me in, so the rest was implied\" myth.","myth":{"un":"They invited me in for chai, so the rest was implied.","re":"Letting you in is hospitality; nothing beyond that is agreed without a clear yes.","why":"An open door is not an open yes; every next step still needs asking."}},
  {"id":"cr-965","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"we live together","relearn":"Sharing a home never banks a standing yes; each time is still asked.","hook":"The \"we live together, so it's a given\" myth.","myth":{"un":"We live together now, so I don't have to ask anymore.","re":"Living together changes the address, not the rule: each time still needs its own yes.","why":"Sharing a roof is not a permanent yes; either person can still say no."}},
  {"id":"cr-966","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"dressed for it","relearn":"Clothes never imply consent; only a willing yes does.","hook":"The \"dressed for it\" myth, struck and rewritten.","myth":{"un":"They were dressed for it.","re":"Clothes never imply consent; only a willing yes does.","why":"What someone wears says nothing about what they agree to."}},
  {"id":"cr-967","cat":"real-situations","type":"strike-rewrite","persona":"Rohan","source":"big enough to fight off","relearn":"Being strong doesn't stop assault; freezing and shock happen to anyone.","hook":"The \"a strong person could've fought it off\" myth.","myth":{"un":"They're big and strong, so they could've fought it off if they wanted.","re":"Strength doesn't prevent assault: shock, fear, and freezing happen to anyone.","why":"The body's freeze response overrides muscle; not fighting is never a yes."}},
  {"id":"cr-968","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"replied to my text","relearn":"Answering a text is never a yes to anything physical; only a willing yes is.","hook":"The \"they texted back, so they were up for it\" myth.","myth":{"un":"They replied to my late text, so they were up for it.","re":"Answering a message is just being friendly, never agreement to anything physical.","why":"A reply says they read you, not that they want to be touched."}},
  {"id":"cr-969","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"they seemed fine after","relearn":"How calm someone looks afterwards never measures the harm done to them.","hook":"The \"they seemed fine after, so it can't have been serious\" myth.","myth":{"un":"They didn't cry, so it can't have been serious.","re":"People hide pain, go numb, or carry on; calmness is not proof nothing happened.","why":"There's no single way harm looks; a steady face can hide a lot."}},
  {"id":"cr-970","cat":"real-situations","type":"strike-rewrite","persona":"any","source":"polite yes is enough","relearn":"A polite yes to please isn't consent; check in for the real, enthusiastic answer.","hook":"A real-life myth about the \"polite yes,\" struck and rewritten.","myth":{"un":"A polite, going-along yes counts as consent.","re":"A yes given to please, not because they want to, isn't enthusiastic consent.","why":"Enthusiasm is the bar; check in for the real answer if it's just polite."}},
  {"id":"cr-1080","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They were quiet, so they were fine with it.\"","myth":{"un":"They stayed quiet, so they were okay with it.","re":"Silence is not a yes; consent is an active, willing yes you can hear.","why":"Quiet often means unsure or frozen, not willing."},"relearn":"Silence is never consent; only a willing yes is.","persona":"any","source":"silence myth"},
  {"id":"cr-1081","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They flirted all night, so they owed me.\"","myth":{"un":"They flirted all night, so they owed me more.","re":"Flirting is not a contract; no one owes you anything beyond a free yes.","why":"Enjoying your company is not agreeing to sex."},"relearn":"Flirting is never an IOU; only a willing yes counts.","persona":"Rohan","source":"flirting myth"},
  {"id":"cr-1082","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They let me pay, so they signed up for the rest.\"","myth":{"un":"I paid for the date, so they owed me the night.","re":"Paying buys dinner, never a person; a yes can't be bought.","why":"Money never stands in for a willing yes."},"relearn":"Paying for a date never buys consent; only a yes does.","persona":"any","source":"who-paid myth"},
  {"id":"cr-1083","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They were drunk and didn't stop me, so it was okay.\"","myth":{"un":"They were drunk and didn't resist, so it was fine.","re":"Not resisting is never consent, especially when someone is drunk or frozen.","why":"Drink and freeze both take away a real yes."},"relearn":"Not resisting is never consent, especially if drunk or frozen.","persona":"any","source":"no-resist myth"},
  {"id":"cr-1084","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"We've been married a year, so it's my right.\"","myth":{"un":"We're married, so consent is automatic.","re":"Marriage never assumes consent; it's freely given each time, by both.","why":"A wedding is not a permanent yes."},"relearn":"Marriage never assumes consent; it's freely given each time.","persona":"Aarti","source":"marriage myth"},
  {"id":"cr-1085","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They didn't push me away, so they wanted it.\"","myth":{"un":"They didn't push me away, so they wanted it.","re":"Not pushing away is not a yes; consent is an active, willing yes.","why":"Many people freeze and can't move under threat."},"relearn":"Not pushing away is never consent; a freeze is not a yes.","persona":"any","source":"freeze myth"},
  {"id":"cr-1086","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"He's a guy, he must have wanted it.\"","myth":{"un":"He's a man, so he must have wanted it.","re":"Anyone of any gender can be harmed, and men deserve the same belief and support.","why":"This myth silences male survivors."},"relearn":"Men can be harmed too and deserve belief and support.","persona":"Rohan","source":"men-want-it myth"},
  {"id":"cr-1087","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"She came to my PG room, so it was settled.\"","myth":{"un":"They came up to my room, so it was settled.","re":"Coming to a room is never agreement to what comes next; each step needs its own yes.","why":"A room is just a place, not a promise."},"relearn":"Coming to a room is never consent to anything further.","persona":"any","source":"room myth"},
  {"id":"cr-1088","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They sent me photos, so the rest was on.\"","myth":{"un":"They sent me a photo, so anything goes now.","re":"A message or photo is never a yes for in-person; consent is asked fresh each time.","why":"Online sharing isn't an offline yes."},"relearn":"A photo or text is never standing consent for what's next.","persona":"any","source":"photos myth"},
  {"id":"cr-1089","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They smiled, so deep down they liked it.\"","myth":{"un":"They smiled through it, so deep down they liked it.","re":"A nervous smile is not a yes; only a clear, willing yes is consent.","why":"People often smile or appease when scared."},"relearn":"A nervous smile is never a yes; only a willing yes is.","persona":"any","source":"smile myth"},
  {"id":"cr-1090","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They never reported it, so it can't have been real.\"","myth":{"un":"They never reported it, so it can't be true.","re":"Delaying or not reporting is a normal trauma response; it doesn't mean it didn't happen.","why":"Fear, shame and freeze keep many people silent."},"relearn":"Not reporting never means it wasn't real.","persona":"Mehta","source":"no-report myth"},
  {"id":"cr-1091","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They said yes last week, so today is covered.\"","myth":{"un":"They said yes last time, so today's covered.","re":"A past yes never covers today; consent is fresh each time.","why":"Yesterday's yes isn't today's."},"relearn":"A past yes never carries over; consent is fresh each time.","persona":"any","source":"past-yes myth"},
  {"id":"cr-1092","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They said yes, then changed their mind. Too late, right?\"","myth":{"un":"They already said yes, so they can't change their mind.","re":"Consent is revocable any time; a new no ends it, no matter how far in.","why":"You can withdraw a yes at any moment."},"relearn":"A yes can be withdrawn any time; a new no means stop.","persona":"any","source":"revoke myth"},
  {"id":"cr-1093","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They're my partner, so a no is just teasing.\"","myth":{"un":"My partner's no is just playing hard to get.","re":"A no is a no, even from a partner; never read it as a game.","why":"Treating no as teasing erases their real answer."},"relearn":"A partner's no is a real no, never a tease.","persona":"any","source":"hard-to-get myth"},
  {"id":"cr-1094","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They were dressed for attention, so they were asking.\"","myth":{"un":"They dressed for attention, so they were asking for it.","re":"Clothes never imply consent; only a willing yes does.","why":"What someone wears says nothing about consent."},"relearn":"Clothes never imply consent; only a willing yes does.","persona":"any","source":"clothes myth"},
  {"id":"cr-1095","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"A real friend would make them go to the police.\"","myth":{"un":"A real friend would force them to report it.","re":"A real friend supports the survivor's own choices, including if and when to report.","why":"The choice to report is theirs alone."},"relearn":"A good friend backs the survivor's choices, never forces reporting.","persona":"Mehta","source":"force-report myth"},
  {"id":"cr-1096","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They stopped saying no, so I had a green light.\"","myth":{"un":"They went quiet and stopped saying no, so it was a green light.","re":"Giving up is not a yes; consent is an active, willing yes, not worn-down silence.","why":"People go silent when worn down or scared."},"relearn":"Going silent under pressure is never a yes.","persona":"any","source":"wear-down myth"},
  {"id":"cr-1097","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"He started it, so he can't say it went too far.\"","myth":{"un":"He started it, so he can't say it went too far.","re":"Starting something is never agreement to all of it; anyone can stop at any point.","why":"A first step is not a yes to every step."},"relearn":"Starting something never means consent to everything after.","persona":"any","source":"who-started myth"},
  {"id":"cr-1098","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They owe me after I helped them so much.\"","myth":{"un":"After all I did for them, they owe me this.","re":"Help is not a debt paid with a body; a yes is never owed.","why":"Favours never buy consent."},"relearn":"No favour ever earns you someone's body; a yes is never owed.","persona":"any","source":"favour-debt myth"},
  {"id":"cr-1099","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"It was just persistent flirting, not pressure.\"","myth":{"un":"Asking over and over is just keen flirting, not pressure.","re":"Asking once is fine; asking again after a no is pressure, not flirting.","why":"Respecting the first no is the line."},"relearn":"Pushing past a no is pressure, not flirting.","persona":"any","source":"persistence myth"},
  {"id":"cr-1100","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They were leading me on, so I couldn't stop.\"","myth":{"un":"They led me on, so I couldn't have stopped.","re":"You can always stop; no one's signals ever cancel your control or their no.","why":"You are responsible for your own actions."},"relearn":"You can always stop; nobody's signals override a no.","persona":"Rohan","source":"led-me-on myth"},
  {"id":"cr-1101","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"A senior asked, so juniors just go along.\"","myth":{"un":"A senior asked, so a junior is meant to go along.","re":"A yes given out of rank or fear isn't free; that's coercion, not consent.","why":"Power imbalance cancels a free yes."},"relearn":"A yes given out of rank or fear is coercion, not consent.","persona":"any","source":"seniority myth"},
  {"id":"cr-1102","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"They only said no to seem decent.\"","myth":{"un":"They said no just to seem decent; they meant yes.","re":"A no means no; never rewrite it into the yes you wanted.","why":"Guessing past a no erases their real answer."},"relearn":"No means no; never reinterpret it as a hidden yes.","persona":"any","source":"token-no myth"},
  {"id":"cr-1103","cat":"spot-the-pressure","type":"strike-rewrite","hook":"\"It can't be assault if they came back to me after.\"","myth":{"un":"They stayed in touch after, so it wasn't assault.","re":"Staying in contact is a common trauma response and never undoes what happened.","why":"Survivors often keep contact out of fear or confusion."},"relearn":"Staying in contact afterwards never means it was okay.","persona":"Mehta","source":"contact-after myth"},
  {"id":"cr-1104","cat":"spot-the-pressure","type":"spot","hook":"Spot the two pressure lines (3 are okay).","scene":[{"id":"a","text":"\"No rush, tell me if you change your mind\"","trick":false},{"id":"b","text":"\"Everyone our age has, why are you so uptight?\"","trick":true},{"id":"c","text":"\"We can just watch the film, that's nice too\"","trick":false},{"id":"d","text":"\"If you really cared you wouldn't make me beg\"","trick":true},{"id":"e","text":"\"Only if you actually want to\"","trick":false}],"why":"Shaming you as 'uptight' or guilting you for 'making them beg' is pressure; the rest leave the choice yours.","relearn":"Shame and guilt-trips are pressure; a real ask leaves the choice yours.","persona":"any","source":"shame and guilt"},
  {"id":"cr-1105","cat":"spot-the-pressure","type":"spot","hook":"Spot the two threats hiding as romance (3 are fine).","scene":[{"id":"a","text":"\"I'll post our chats if you say no\"","trick":true},{"id":"b","text":"\"I had a lovely evening, thank you\"","trick":false},{"id":"c","text":"\"I'll tell everyone what we did unless you agree\"","trick":true},{"id":"d","text":"\"Text me when you reach home safe\"","trick":false},{"id":"e","text":"\"No pressure at all, your call\"","trick":false}],"why":"Threatening to leak chats or out you is blackmail, not romance; the rest respect your choice.","relearn":"Blackmail dressed as romance is still coercion, never consent.","persona":"any","source":"blackmail"},
  {"id":"cr-1106","cat":"spot-the-pressure","type":"spot","hook":"Spot the two power-plays (3 are clean).","scene":[{"id":"a","text":"A classmate asking you out, fine either way","trick":false},{"id":"b","text":"A boss hinting your shifts depend on it","trick":true},{"id":"c","text":"A PG owner hinting your room depends on it","trick":true},{"id":"d","text":"A friend taking your no with a shrug","trick":false},{"id":"e","text":"A date saying 'no worries' when you passed","trick":false}],"why":"Tying your job or your room to sex is coercion through power; the others ask freely and accept a no.","relearn":"Tying your job, room or marks to sex is coercion, not a free ask.","persona":"any","source":"leverage power"},
  {"id":"cr-1107","cat":"spot-the-pressure","type":"spot","hook":"Spot the two coercive moves (3 are respectful).","scene":[{"id":"a","text":"\"Let's slow down, no rush\"","trick":false},{"id":"b","text":"Refilling your glass to 'loosen you up'","trick":true},{"id":"c","text":"\"We can stop any time you like\"","trick":false},{"id":"d","text":"Sulking and going cold until you give in","trick":true},{"id":"e","text":"Checking in: \"still good?\"","trick":false}],"why":"Plying you with drink or sulking you into a yes is coercion; the rest keep the choice freely yours.","relearn":"Getting someone drunk or sulking them into yes is coercion.","persona":"any","source":"ply and sulk"},
  {"id":"cr-1108","cat":"spot-the-pressure","type":"spot","hook":"Spot the two pressured 'yeses' (3 are freely given).","scene":[{"id":"a","text":"\"Yes! I've been wanting to\"","trick":false},{"id":"b","text":"\"Fine, whatever, just stop sulking\"","trick":true},{"id":"c","text":"\"Yes, I'm into this too\"","trick":false},{"id":"d","text":"\"Okay, or you'll make a scene again\"","trick":true},{"id":"e","text":"\"Mmm, yes, this is lovely\"","trick":false}],"why":"A yes to stop sulking or avoid a scene isn't free; the others are willing and eager.","relearn":"A yes to end pressure or avoid a scene isn't a free yes.","persona":"any","source":"pressured yes"},
  {"id":"cr-1109","cat":"spot-the-pressure","type":"spot","hook":"Spot the two manipulations (3 are honest).","scene":[{"id":"a","text":"\"If you loved me, you'd prove it\"","trick":true},{"id":"b","text":"\"I'm happy just being near you\"","trick":false},{"id":"c","text":"\"Everyone else does, don't be a baby\"","trick":true},{"id":"d","text":"\"I really like you, no agenda\"","trick":false},{"id":"e","text":"\"Whatever you're comfortable with\"","trick":false}],"why":"'Prove your love' and 'don't be a baby' weaponise love and shame; the rest don't bargain with your feelings.","relearn":"'Prove your love' and shaming are manipulation, not affection.","persona":"any","source":"love and shame"},
  {"id":"cr-1110","cat":"spot-the-pressure","type":"spot","hook":"Spot the two myths in this chat (3 are true).","scene":[{"id":"a","text":"\"A freeze isn't a yes\"","trick":false},{"id":"b","text":"\"They didn't fight, so it was fine\"","trick":true},{"id":"c","text":"\"Consent can be taken back any time\"","trick":false},{"id":"d","text":"\"We're dating, so it's automatic\"","trick":true},{"id":"e","text":"\"Only a willing yes counts\"","trick":false}],"why":"'Didn't fight = fine' and 'dating = automatic' are myths; the others are the real standard.","relearn":"Not fighting and being a couple never make a yes; only a willing yes does.","persona":"any","source":"myth in chat"},
  {"id":"cr-1111","cat":"spot-the-pressure","type":"spot","hook":"Spot the two pressure tactics by text (3 are okay).","scene":[{"id":"a","text":"\"Sleep well, no pressure to reply\"","trick":false},{"id":"b","text":"\"I'll block you if you keep saying no\"","trick":true},{"id":"c","text":"\"Take your time deciding\"","trick":false},{"id":"d","text":"50 missed calls after one 'not tonight'","trick":true},{"id":"e","text":"\"Happy either way, your call\"","trick":false}],"why":"Threatening to block you or spamming calls after a no is pressure; the rest respect your pace.","relearn":"Threats and spamming after a no are pressure, not keenness.","persona":"any","source":"text pressure"},
  {"id":"cr-1112","cat":"spot-the-pressure","type":"spot","hook":"Spot the two unfree 'yeses' (3 are genuine).","scene":[{"id":"a","text":"\"Yes, let's, I want this\"","trick":false},{"id":"b","text":"A yes given to keep a job","trick":true},{"id":"c","text":"\"Definitely, I'm keen\"","trick":false},{"id":"d","text":"A yes given so they won't out you","trick":true},{"id":"e","text":"\"Yes, this feels right\"","trick":false}],"why":"A yes to keep a job or avoid being outed comes from fear, not freedom; the rest are freely willing.","relearn":"A yes from fear of losing a job or being outed isn't free.","persona":"any","source":"fear-based yes"},
  {"id":"cr-1113","cat":"spot-the-pressure","type":"spot","hook":"Spot the two boundary-stompers (3 respect it).","scene":[{"id":"a","text":"\"Got it, we'll stop\"","trick":false},{"id":"b","text":"\"You said no but I know you meant yes\"","trick":true},{"id":"c","text":"\"Thanks for telling me, no problem\"","trick":false},{"id":"d","text":"Carrying on after you pulled away","trick":true},{"id":"e","text":"\"Want to just talk instead?\"","trick":false}],"why":"Overruling your no or carrying on after you pull away ignores consent; the rest honour your line.","relearn":"Overruling your no or ignoring you pulling away is never consent.","persona":"any","source":"boundary stomp"},
  {"id":"cr-1114","cat":"spot-the-pressure","type":"sort","hook":"Sort each move: respectful, or pressure?","items":[{"id":"a","text":"Asking once and taking the no well"},{"id":"b","text":"Calling them frigid until they cave"},{"id":"c","text":"Saying what you'd like, then dropping it"},{"id":"d","text":"Threatening to dump them if they refuse"},{"id":"e","text":"Checking 'is this okay?' and meaning it"},{"id":"f","text":"Refilling their drink to wear them down"}],"bins":[{"id":"ok","label":"Respectful","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"ok","b":"pressure","c":"ok","d":"pressure","e":"ok","f":"pressure"},"relearn":"Asking once and accepting no is respectful; shaming, threats and plying are pressure.","persona":"any","source":"respect vs pressure"},
  {"id":"cr-1115","cat":"spot-the-pressure","type":"sort","hook":"Sort each yes: freely given, or coerced?","items":[{"id":"a","text":"A relaxed, eager yes between equals"},{"id":"b","text":"A yes bought with a threat"},{"id":"c","text":"A yes after hours of nagging"},{"id":"d","text":"A clear, sober, willing yes"},{"id":"e","text":"A yes to avoid being outed"},{"id":"f","text":"A warm, mutual yes"}],"bins":[{"id":"free","label":"Freely given","valence":"pos"},{"id":"coerced","label":"Coerced","valence":"neg"}],"key":{"a":"free","b":"coerced","c":"coerced","d":"free","e":"coerced","f":"free"},"relearn":"A relaxed, willing yes is free; a yes from threats, nagging or fear is coerced.","persona":"any","source":"free vs coerced"},
  {"id":"cr-1116","cat":"spot-the-pressure","type":"sort","hook":"Sort: does this imply consent, or nothing?","items":[{"id":"a","text":"A clear, spoken 'yes, I want to'"},{"id":"b","text":"What they wore tonight"},{"id":"c","text":"That they came up to the room"},{"id":"d","text":"An enthusiastic 'definitely'"},{"id":"e","text":"That they'd hooked up before"},{"id":"f","text":"That they'd had a drink"}],"bins":[{"id":"yes","label":"Implies consent","valence":"pos"},{"id":"nothing","label":"Implies nothing","valence":"neutral"}],"key":{"a":"yes","b":"nothing","c":"nothing","d":"yes","e":"nothing","f":"nothing"},"relearn":"Only a willing, spoken yes implies consent; clothes, a room, history and a drink imply nothing.","persona":"any","source":"implies what"},
  {"id":"cr-1117","cat":"spot-the-pressure","type":"sort","hook":"Sort: builds a consent culture, or erodes it?","items":[{"id":"a","text":"Taking a no with a graceful 'no worries'"},{"id":"b","text":"Mocking a friend's boundary as drama"},{"id":"c","text":"Checking in mid-way, no awkwardness"},{"id":"d","text":"Joking that 'no means try harder'"},{"id":"e","text":"Backing a friend's stated limit"},{"id":"f","text":"Treating wearing someone down as a win"}],"bins":[{"id":"builds","label":"Builds","valence":"pos"},{"id":"erodes","label":"Erodes","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Taking a no well and checking in build consent culture; mocking limits and wearing people down erode it.","persona":"any","source":"builds vs erodes"},
  {"id":"cr-1118","cat":"spot-the-pressure","type":"sort","hook":"Sort: a free yes, or a power-play?","items":[{"id":"a","text":"A peer asking, fine with either answer"},{"id":"b","text":"A senior tying your marks to it"},{"id":"c","text":"A landlord tying your room to it"},{"id":"d","text":"A date shrugging off your no, fine either way"},{"id":"e","text":"A boss hinting at your promotion"},{"id":"f","text":"A classmate saying 'all good' when you passed"}],"bins":[{"id":"free","label":"Free ask","valence":"pos"},{"id":"power","label":"Power-play","valence":"neg"}],"key":{"a":"free","b":"power","c":"power","d":"free","e":"power","f":"free"},"relearn":"An equal asking freely is fine; leveraging marks, a room or a promotion is a power-play, not consent.","persona":"any","source":"free vs power"},
  {"id":"cr-1119","cat":"spot-the-pressure","type":"sort","hook":"Sort each line: a real ask, or coercion?","items":[{"id":"a","text":"\"Only if you actually want to\""},{"id":"b","text":"\"If you loved me you would\""},{"id":"c","text":"\"No pressure, your call\""},{"id":"d","text":"\"Everyone will know you chickened out\""},{"id":"e","text":"\"We can stop whenever\""},{"id":"f","text":"\"Say yes or I'll find someone else\""}],"bins":[{"id":"ask","label":"Real ask","valence":"pos"},{"id":"coerce","label":"Coercion","valence":"neg"}],"key":{"a":"ask","b":"coerce","c":"ask","d":"coerce","e":"ask","f":"coerce"},"relearn":"A real ask leaves the choice yours; guilt, shame and threats are coercion.","persona":"any","source":"ask vs coerce lines"},
  {"id":"cr-1120","cat":"spot-the-pressure","type":"sort","hook":"Sort: a real yes, or a yes that doesn't count?","items":[{"id":"a","text":"A sober, willing 'yes'"},{"id":"b","text":"A yes from someone slurring, barely awake"},{"id":"c","text":"An eager 'yes, definitely'"},{"id":"d","text":"A yes worn down after an hour of pestering"},{"id":"e","text":"A relaxed mutual 'yes'"},{"id":"f","text":"A yes given out of fear"}],"bins":[{"id":"counts","label":"Real yes","valence":"pos"},{"id":"void","label":"Doesn't count","valence":"neg"}],"key":{"a":"counts","b":"void","c":"counts","d":"void","e":"counts","f":"void"},"relearn":"A sober, willing yes counts; a yes from incapacity, pestering or fear does not.","persona":"any","source":"counts vs void"},
  {"id":"cr-1121","cat":"spot-the-pressure","type":"sort","hook":"Sort: persuasion that's fair, or pressure?","items":[{"id":"a","text":"Sharing why you're keen, once"},{"id":"b","text":"Bringing it up again after a clear no"},{"id":"c","text":"Letting them think and not chasing"},{"id":"d","text":"Guilt-tripping with 'after all I've done'"},{"id":"e","text":"Accepting 'not tonight' easily"},{"id":"f","text":"Going cold to punish a no"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"fair","b":"pressure","c":"fair","d":"pressure","e":"fair","f":"pressure"},"relearn":"Asking once and letting it go is fair; pushing past a no, guilt and punishment are pressure.","persona":"any","source":"persuasion line"},
  {"id":"cr-1122","cat":"spot-the-pressure","type":"sort","hook":"Sort: consent stays, or consent is gone?","items":[{"id":"a","text":"Both still keen, checking in"},{"id":"b","text":"One has passed out"},{"id":"c","text":"A fresh, willing 'yes, carry on'"},{"id":"d","text":"One just said 'stop' and meant it"},{"id":"e","text":"Both relaxed and into it"},{"id":"f","text":"One went silent and pulled away"}],"bins":[{"id":"on","label":"Consent stays","valence":"pos"},{"id":"off","label":"Consent gone","valence":"neg"}],"key":{"a":"on","b":"off","c":"on","d":"off","e":"on","f":"off"},"relearn":"Consent stays while both are willing; passing out, a 'stop', or pulling away ends it at once.","persona":"any","source":"stays vs gone"},
  {"id":"cr-1123","cat":"spot-the-pressure","type":"sort","hook":"Sort: respects a no, or punishes it?","items":[{"id":"a","text":"\"Totally fine, thanks for telling me\""},{"id":"b","text":"Silent treatment for days"},{"id":"c","text":"Suggesting you just hang out instead"},{"id":"d","text":"Telling friends you're 'frigid'"},{"id":"e","text":"\"Glad you said so, no worries\""},{"id":"f","text":"Withholding affection until you cave"}],"bins":[{"id":"respect","label":"Respects no","valence":"pos"},{"id":"punish","label":"Punishes no","valence":"neg"}],"key":{"a":"respect","b":"punish","c":"respect","d":"punish","e":"respect","f":"punish"},"relearn":"Taking a no graciously respects it; sulking, name-calling and withdrawal punish it.","persona":"any","source":"respect vs punish no"},
  {"id":"cr-1124","cat":"spot-the-pressure","type":"branch","persona":"any","source":"party setup","hook":"At a house party, a guy keeps refilling your friend Tara's glass. She's already tipsy.","steps":[{"prompt":"Now he's steering her towards the stairs. What do you do?","options":[{"text":"Assume it's her business and look away","then":"When you look again, Tara is on the stairs with him, unsteady."},{"text":"Text Tara to check she's okay and wait for a reply","then":"The message shows as delivered. She doesn't look at her phone."},{"text":"Go over and say you need Tara for a minute","then":"Tara turns, wobbly, and lets you take her arm. He frowns.","best":true},{"text":"Shout at him in front of everyone","then":"The room goes quiet. He laughs it off and keeps a hand on Tara's back."}],"why":"A quick, calm interruption gets her away from him without a scene."},{"prompt":"Tara is now slurring and can barely stand, and he's still close by. What do you do?","options":[{"text":"Let her lie down in a spare room to sleep it off","then":"You settle her in. As you leave, he's heading up the stairs."},{"text":"Get her water, stay with her, and find a ride home","then":"Tara leans on you and sips the water. He drifts off to the kitchen.","best":true},{"text":"Leave her with him, since he offers to look after her","then":"\"I've got her,\" he says. Something about his smile bothers you."},{"text":"Tell her off for drinking so much","then":"Tara starts crying, and the guy says, \"Let me take her upstairs.\""}],"why":"Someone this drunk can't consent. Staying with her keeps her safe."},{"prompt":"He tells you: \"Relax. She was into me and wanted to go upstairs.\" What do you do?","options":[{"text":"Let it go, since you didn't hear what she said earlier","then":"He steps past you towards Tara, and your stomach drops."},{"text":"Ask Tara, slurring, whether she wants to go with him","then":"Tara nods vaguely at everything, including the wall."},{"text":"Threaten to beat him up if he comes near her","then":"His friends gather. Now there's a standoff, and Tara is still unsteady."},{"text":"Say she's too drunk to agree, and stay put","then":"He shrugs and mutters something, then walks away.","best":true}],"why":"Whatever she said before, she can't consent this drunk. Keeping her with you is safest."},{"prompt":"It's late, and the ride app shows no cars nearby. What do you do?","options":[{"text":"Call a sober friend to help you get her home","then":"Your friend Arjun arrives in twenty minutes, and you get Tara home.","best":true},{"text":"Accept the guy's offer to drop her home","then":"He jingles his keys, a little too eager. Tara can barely stand."},{"text":"Let her crash at the party alone and head home","then":"On the way out you glance back. He's sitting down next to her."},{"text":"Wait it out on the stairs till she sobers up","then":"An hour passes. People leave, and he's still hanging around."}],"why":"Getting her home with someone you trust means she's never left alone with him."},{"prompt":"The next day Tara texts that she barely remembers last night, and asks if she did something stupid. What do you say?","options":[{"text":"Tell her she really embarrassed herself last night","then":"Tara replies with one word, \"Sorry,\" and goes quiet all day."},{"text":"Say nothing happened, so she doesn't worry","then":"\"Okay,\" Tara replies. Later she hears the story from someone else."},{"text":"Say what you saw, and that none of it is on her","then":"Tara reads it twice. \"Thank you for staying with me.\"","best":true},{"text":"Tell her to stop drinking at parties","then":"\"So it's my fault?\" Tara replies."}],"why":"Drinking is never an excuse for him or a fault of hers. Tell her plainly and kindly."}],"debrief":"Getting someone too drunk to think removes their ability to consent, and a friend stepping in is consent culture.","relearn":"Plying someone with drink to wear down a no is coercion."},
  {"id":"cr-1125","cat":"spot-the-pressure","type":"branch","persona":"any","source":"reputation threat","hook":"At Vikram's flat after your date, he says, \"Do it, or I'll tell everyone you're a tease.\"","steps":[{"prompt":"He says it smiling, like it's a joke. What do you do?","options":[{"text":"Decide it's just his humour, and let it pass","then":"He laughs, then says it again, less like a joke."},{"text":"Call it a threat, and leave","then":"\"It was a joke,\" he calls as you go. You're shaking, but out.","best":true},{"text":"Wonder if you did lead him on somehow","then":"You start replaying the evening for your mistake while he waits."},{"text":"Decide a threat like that leaves you no choice","then":"Fear floods in. You get out somehow, but his words ring in your ears all the way home."}],"why":"A yes pulled out by a threat is never free. Leaving is always allowed."},{"prompt":"Later that night he messages, \"Your friends will love hearing about you.\" What do you do?","options":[{"text":"Reply with a long message explaining yourself","then":"He replies, \"Too long, didn't read,\" with a laughing emoji."},{"text":"Keep it secret, since people might believe him","then":"You stay up alone, checking your phone every few minutes."},{"text":"Screenshot it and tell a friend you trust","then":"Your friend Sneha calls straight back. \"I've got you. This is on him.\"","best":true},{"text":"Post first, calling him out publicly by name","then":"The post blows up, and so does he, with angrier messages."}],"why":"Keeping proof and telling someone means you don't face his threat alone."},{"prompt":"The next day a classmate asks if something happened with Vikram. What do you do?","options":[{"text":"Explain every detail to prove you're not a tease","then":"The classmate looks awkward as you go on. More people start listening."},{"text":"Laugh it off and say nothing happened","then":"\"Okay,\" the classmate says, unconvinced. The rumour keeps moving."},{"text":"Ask the classmate what else Vikram said about you","then":"She tells you three new things he's said. You feel sick."},{"text":"Say he made a threat, and the rest is his lie","then":"The classmate nods. \"Figured. He does this.\"","best":true}],"why":"The shame of a threat belongs to him. You don't owe anyone proof."},{"prompt":"The rumours are getting to you, and you can't focus in class. What do you do?","options":[{"text":"Decide it's your fault for going to his flat","then":"The thought sits with you all week and makes it worse."},{"text":"Go to the campus committee or a counsellor","then":"The counsellor listens and explains what the committee can do. You feel steadier.","best":true},{"text":"Ask him nicely to stop, one more time","then":"He reads it and replies, \"Then you know what to do.\""},{"text":"Tell yourself it's just gossip and not worth reporting","then":"The gossip keeps going, and so do his messages."}],"why":"Threats to shame you are coercion, and it's never your fault. Real help exists."}],"debrief":"Threatening your reputation for a yes is a power-play, and the shame belongs to them, not you.","relearn":"A yes given to dodge a threat or gossip is coercion, not consent."},
  {"id":"cr-1126","cat":"spot-the-pressure","type":"branch","persona":"any","source":"internship power","hook":"Rakesh, a senior at your internship, hints that a 'yes' to him would help your review.","steps":[{"prompt":"He says it quietly after a meeting, then smiles. What do you do?","options":[{"text":"Tell yourself you misheard, so it's nothing","then":"The next day he says it again, more clearly."},{"text":"Work extra hard so the review can't be denied","then":"You stay late all week. He comments on your \"dedication\" with a wink."},{"text":"Say no clearly, and write down what he said","then":"His smile tightens. \"Think about it,\" he says, and walks off.","best":true},{"text":"Call him out loudly in front of the team","then":"The room goes still. He laughs it off, and someone whispers \"drama\"."}],"why":"A plain no and a written note put you on firm ground. What he did is his, not yours."},{"prompt":"By Friday he messages, \"Your review is next week. Let's discuss over dinner.\" What do you do?","options":[{"text":"Go, but bring a friend along","then":"He cancels the dinner and says he'll \"remember this.\""},{"text":"Decline and ask to discuss it in the office","then":"He replies, \"Suit yourself,\" and sets the meeting for Monday.","best":true},{"text":"Wonder if your friendliness gave him the idea","then":"You reread your old messages to him, hunting for a mistake that isn't there."},{"text":"Forward his message to the whole team","then":"The team goes silent. Rakesh says you misread a work invite."}],"why":"Keeping it to work spaces limits his power to push you somewhere private."},{"prompt":"On Monday your review is marked \"needs improvement\" with no reason. What do you do?","options":[{"text":"Accept it, since interns can't fight seniors","then":"The unfair mark stays on your record, and Rakesh never has to explain it."},{"text":"Email him to apologise and ask for another chance","then":"He replies, \"Still open to discussing it over dinner.\""},{"text":"Post about him on social media by name","then":"The post spreads fast. HR calls you in about \"unprofessional conduct.\""},{"text":"Take his messages and the review to the committee","then":"A committee member listens and says they'll handle it confidentially.","best":true}],"why":"Tying your review to a yes is harassment. The committee exists for exactly this."},{"prompt":"A friend interning there asks how you're coping. What do you say?","options":[{"text":"That it's been hard, and you'd like to talk it through","then":"She squeezes your hand. \"I'm here. And it's not your fault.\"","best":true},{"text":"That you're fine, and it was your fault for being friendly","then":"\"Being friendly isn't a yes,\" she says. You're not sure you believe it."},{"text":"That she should avoid him, but not ask why","then":"She nods, confused, and doesn't know what to watch for."},{"text":"That nothing ever changes, so why bother reporting","then":"She looks unsure what to say, and the talk drifts elsewhere."}],"why":"It's never your fault when someone misuses power. Support makes it lighter."}],"debrief":"When someone with power over your work ties it to sex, a free yes is impossible, and that's harassment.","relearn":"A yes tied to your job or review by someone with power isn't consent."},
  {"id":"cr-1127","cat":"spot-the-pressure","type":"branch","persona":"any","source":"sulk pressure","hook":"Your partner Zaid sulks and goes cold every time you say \"not tonight\".","steps":[{"prompt":"Tonight you say no, and he turns his back without a word. What do you do?","options":[{"text":"Explain your reasons in detail so he understands","then":"He listens, then says \"So basically still no,\" and turns away."},{"text":"Apologise for being difficult lately","then":"He softens a little. \"It's fine. Just don't make it a habit.\""},{"text":"Tell him a no shouldn't earn you silence","then":"\"I'm not sulking,\" he mutters. The room stays tense.","best":true},{"text":"Decide this is just normal couple stuff","then":"You lie awake, telling yourself it doesn't matter."}],"why":"Sulking at a no is quiet pressure. Naming it keeps your no free."},{"prompt":"The next morning Zaid asks if it's wrong to want you. What do you say?","options":[{"text":"Wanting is fine. Punishing my no isn't.","then":"He looks down. \"I didn't think of it as punishing.\"","best":true},{"text":"Of course not. I'm sorry I keep saying no.","then":"\"It's okay,\" he says, and hugs you like it's settled."},{"text":"You're so childish when you don't get your way.","then":"\"Childish?\" he snaps, and leaves for work without breakfast."},{"text":"Of course not. Let's talk about it some other time.","then":"He nods. The talk never comes, and neither does the warmth."}],"why":"You can honour his feelings and still refuse to be punished for a no."},{"prompt":"A week later he goes cold again after a no. What do you do?","options":[{"text":"Keep it quiet, since couples should sort things alone","then":"The cold spells keep coming, and you start dreading bedtime."},{"text":"Decide you must be a bad partner","then":"You start apologising before you even say no."},{"text":"Ask his best friend to talk sense into him","then":"His friend tells Zaid, who is furious you \"went behind his back.\""},{"text":"Talk it through with a friend you trust","then":"Your friend Leela listens. \"That's a pattern. It's not on you.\"","best":true}],"why":"Sulking after every no is a pattern, never your fault. Saying it to someone helps."},{"prompt":"Zaid asks if you two can just move past this. What do you say?","options":[{"text":"Yes. Let's just pretend none of it ever happened","then":"\"Great,\" he says. A week later, the silence is back."},{"text":"Only if a no can be said without paying for it","then":"He's quiet for a while. \"Okay. I'll work on that.\"","best":true},{"text":"Yes, if we both try harder to meet halfway","then":"\"Deal,\" he says, and you realise only you are bending."},{"text":"No. You always make everything about you","then":"He shuts down. \"Fine. Forget I asked.\""}],"why":"Moving on only works if a no is safe to say. Earning that was never your job."}],"debrief":"Punishing a no with coldness is quiet coercion, and a yes given to end it isn't really given.","relearn":"A yes given to stop sulking or punishment isn't a free yes."},
  {"id":"cr-1128","cat":"spot-the-pressure","type":"branch","persona":"any","source":"history lever","hook":"You meet your ex Harsh for coffee. He wants to hook up and says you've \"done it all before\".","steps":[{"prompt":"When you say no, he laughs and says you're acting brand new. What do you do?","options":[{"text":"Explain that you've changed since the breakup","then":"\"You haven't changed that much,\" he says, grinning."},{"text":"Say a past yes doesn't count for today","then":"He rolls his eyes. \"Okay, okay. Relax.\"","best":true},{"text":"Admit he has a point, but you're just tired","then":"\"Coffee, then my place?\" he says, as if it's agreed."},{"text":"Tell him it was never that great anyway","then":"His face hardens. The coffee ends in an icy silence."}],"why":"Consent is fresh each time. A shared past never books today."},{"prompt":"That night he texts, \"Old times' sake. You know you want to.\" What do you do?","options":[{"text":"Post his text on your story to shame him","then":"Mutual friends see it, and he sends an angry voice note."},{"text":"Reply that you're flattered but busy this week","then":"\"Next week then,\" he replies. \"I'll hold you to it.\""},{"text":"Wonder if refusing an ex is being uptight","then":"You stare at the message, half convinced he's right."},{"text":"Reply: no, and please drop it","then":"\"Your loss,\" he replies, then sends a sulky emoji.","best":true}],"why":"\"You know you want to\" isn't a yes, and his pushing is never your fault."},{"prompt":"A week later Harsh messages again, asking what the big deal is. What do you do?","options":[{"text":"Block him and tell a friend what's going on","then":"\"He's been pushing all week?\" your friend Tanya asks. \"I'm glad you told me.\"","best":true},{"text":"Explain one more time, slowly, why it's no","then":"He replies, \"Blah blah. So Saturday?\""},{"text":"Agree to meet once, just to talk it out","then":"At the café, he starts on \"old times\" within five minutes."},{"text":"Tell yourself you owe him since you dated so long","then":"The thought keeps nagging, and his messages keep coming."}],"why":"Repeated pushing after a no is pressure. Blocking and telling someone keeps you safe."}],"debrief":"\"We've done it before\" is a guilt lever, and every time needs its own willing yes.","relearn":"A shared history never replaces today's free yes."},
  {"id":"cr-1129","cat":"spot-the-pressure","type":"branch","persona":"any","source":"app escalation","hook":"Your dating-app match Yash gets angrier each time you say you're not ready to meet.","steps":[{"prompt":"Now he writes that he's been \"patient enough\" and you're wasting his time. What do you do?","options":[{"text":"Take a friend's advice to give him one more chance","then":"You keep the chat open, and three angrier messages arrive before bed."},{"text":"Unmatch and block him","then":"The chat vanishes. Your phone goes quiet for the first time all day.","best":true},{"text":"Apologise for wasting his time","then":"\"Apology accepted. Prove it,\" he replies."},{"text":"Explain again why you're not ready","then":"He replies with a longer, angrier message picking apart each reason."}],"why":"Anger that grows at a no is a red flag. You owe him no explanation."},{"prompt":"A day later Yash finds your Instagram and messages you there too. What do you do?","options":[{"text":"Reply once to tell him off properly, then stop","then":"He replies within seconds, even angrier, and screenshots it."},{"text":"Take it as a sign of how keen he really is","then":"You don't block him, and two more messages arrive by night."},{"text":"Block and report the account","then":"The report goes in. The account disappears from your requests.","best":true},{"text":"Wonder if you gave him false hope","then":"You scroll back through old chats, hunting for a mistake that isn't there."}],"why":"Blocking and reporting cuts off that route. Chasing you across apps isn't keenness."},{"prompt":"Your roommate Pallavi sees you jump at every buzz and asks what's up. What do you say?","options":[{"text":"Say it's nothing, just work stuff","then":"\"Okay,\" Pallavi says. You jump at the next buzz, alone."},{"text":"Tell her about Yash and how he's chasing you","then":"Pallavi listens. \"This isn't on you. If he writes again, let's save it.\"","best":true},{"text":"Say you probably led him on without meaning to","then":"\"How?\" Pallavi asks. You can't really say."},{"text":"Laugh it off as another funny dating app story","then":"Pallavi laughs, then stops. \"Wait, is he scaring you?\""}],"why":"Telling someone you trust means you're not carrying his anger alone."},{"prompt":"A week later a new account messages, saying it's Yash and he knows your college. What do you do?","options":[{"text":"Keep it to yourself, so nobody says you asked for it","then":"You tell no one, and his next message names the café near your college."},{"text":"Decide it's just talk and let it go","then":"Two days later, he messages again with a photo of your college gate."},{"text":"Save the proof and call 181 or 112 for help","then":"The person on the line listens, and helps you plan how to stay safe.","best":true},{"text":"Threaten to get your friends to sort him out","then":"\"Try it,\" he replies, and the messages get nastier."}],"why":"Escalating contact is serious, and getting help is strength. Call 112, or 181 for women."}],"debrief":"Escalating anger at a no is a control tactic, never your fault, and you owe no explanation.","relearn":"Anger that grows when you say no is a red flag, not keenness."},
  {"id":"cr-1130","cat":"spot-the-pressure","type":"branch","persona":"any","source":"bystander exit","hook":"At a hostel party your friend Simran whispers, \"Help, I want to leave but he won't take no.\"","steps":[{"prompt":"The guy, Nitin, is right behind her. What do you do?","options":[{"text":"Tell her she should just be firmer with him","then":"Simran's face falls. \"I tried,\" she whispers."},{"text":"Say you both need to go, and leave together","then":"Simran grabs her bag. Nitin calls after you, but you're already moving.","best":true},{"text":"Tell Nitin loudly to back off, or else","then":"Nitin squares up. \"Who asked you?\" People turn to stare."},{"text":"Promise to come find her in ten minutes","then":"Ten minutes later you find her by the door, Nitin still beside her."}],"why":"An easy exit gets her out without her having to argue again."},{"prompt":"Nitin says he just wants to talk to Simran alone. What do you do?","options":[{"text":"Ask Simran what she wants, and stay by her side","then":"Simran shakes her head. \"I just want to go.\" Nitin shrugs and backs off.","best":true},{"text":"Let them talk alone, since it's between them","then":"Simran looks at you, pleading, as you step back."},{"text":"Answer for Simran and tell him she's done with him","then":"Nitin gets angry at you, and Simran goes silent between you."},{"text":"Ask Nitin to explain his side first","then":"Nitin starts a long story, and Simran edges towards the stairs."}],"why":"Staying with her and letting her speak keeps the choice hers and her safe."},{"prompt":"Back in her room, Simran says she feels stupid for making a fuss. What do you say?","options":[{"text":"You weren't stupid, just a bit too friendly with him","then":"Simran pulls her knees up. \"So it was my fault.\""},{"text":"Let's forget it and watch something","then":"She nods, but she's quiet all through the episode."},{"text":"It wasn't a fuss. His not listening isn't on you","then":"Simran exhales. \"Thank you. I kept thinking it was me.\"","best":true},{"text":"Next time, don't drink around guys like that","then":"She stiffens. \"I had one drink.\""}],"why":"Saying it's not her fault helps her let go of shame that was never hers."},{"prompt":"The next day Simran says Nitin keeps texting her. What do you do?","options":[{"text":"Take her phone and block him for her","then":"She snatches it back. \"I can do it myself.\""},{"text":"Tell her to report him today, no excuses","then":"Simran shuts down. \"I'm not ready for that.\""},{"text":"Say he's probably just embarrassed, so ignore it","then":"The texts keep coming, and Simran stops going to parties."},{"text":"Ask what she wants, and offer the committee","then":"Simran thinks. \"Maybe the committee. Will you come with me?\"","best":true}],"why":"Offering routes and letting her decide respects her pace and her choices."}],"debrief":"When someone won't take a no, a bystander offering an exit can change everything.","relearn":"Backing a friend whose no isn't heard is real bystander action."},
  {"id":"cr-1131","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: persuasion stops the moment someone says no. After that, it's pressure. Sit with that line?","prompt":"What lands for you?","options":["Asking once is fine","The no is the line","One ask, then let go"],"affirm":"One honest ask is fair; pushing past a no is where pressure begins.","relearn":"Persuasion ends at the first no; after that it's pressure.","persona":"any","source":"the line"},
  {"id":"cr-1132","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: nobody owes you a yes, no matter how nice you've been or how long you've waited.","prompt":"How does that sit?","options":["A yes is never owed","Niceness isn't a debt","My no is mine too"],"affirm":"Kindness is freely given, never an invoice; a yes is only ever a free gift.","relearn":"No one owes you a yes; kindness is never a debt.","persona":"Rohan","source":"never owed"},
  {"id":"cr-1133","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: a yes pulled out of someone by fear, guilt or rank was never really a yes.","prompt":"What do you take from that?","options":["Fear cancels a yes","It has to be free","Only a free yes counts"],"affirm":"A free yes is the only yes; fear, guilt and power empty it out.","relearn":"A yes from fear, guilt or power isn't a free yes at all.","persona":"any","source":"free or nothing"},
  {"id":"cr-1134","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: freezing is the body's reflex, not a yes and never a fault. Many people freeze.","prompt":"What stays with you?","options":["A freeze isn't a yes","It's not their fault","The body reacts on its own"],"affirm":"Freezing is a normal, involuntary response; it is never agreement and never anyone's fault.","relearn":"Freezing is a reflex, not a yes, and never a fault.","persona":"any","source":"freeze is human"},
  {"id":"cr-1135","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: spotting a guilt-trip early is a skill, not paranoia. You're allowed to name it.","prompt":"What feels true?","options":["Naming it is fair","I can trust that read","Guilt isn't love"],"affirm":"You're allowed to notice guilt being used on you and to call it what it is.","relearn":"Naming a guilt-trip isn't paranoia; it's reading pressure clearly.","persona":"any","source":"name it"},
  {"id":"cr-1136","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: your no doesn't need a good enough reason. 'I don't want to' is a whole reason.","prompt":"What lands?","options":["No reason needed","'I don't want to' is enough","My no is complete"],"affirm":"A no is complete on its own; you never owe an argument to justify it.","relearn":"A no needs no justification; 'I don't want to' is a full reason.","persona":"any","source":"no reason needed"},
  {"id":"cr-1137","cat":"spot-the-pressure","type":"reflect","hook":"Lensy: when someone respects your no instantly, that's the green flag worth keeping.","prompt":"What sticks?","options":["A clean 'okay' is gold","That's the keeper","Respecting no is the bar"],"affirm":"Taking your no easily is a sign someone is safe; that's worth holding onto.","relearn":"Taking a no gracefully is a green flag worth keeping.","persona":"any","source":"green flag"},
  {"id":"cr-1138","cat":"spot-the-pressure","type":"match","hook":"Match each pressure tactic to what it really is.","pairs":[{"left":"\"If you loved me, you would\"","right":"Guilt-trip"},{"left":"\"I'll post our chats if you refuse\"","right":"Blackmail"},{"left":"\"Your shifts depend on this\"","right":"Power-play"},{"left":"Keeping your glass full to 'loosen you up'","right":"Plying with drink"},{"left":"Sulking and going cold at a no","right":"Punishing the no"}],"relearn":"Naming the tactic, guilt, blackmail, power-play, plying or punishment, is the first step to refusing it.","persona":"any","source":"name the tactic"},
  {"id":"cr-1139","cat":"spot-the-pressure","type":"match","hook":"Match each myth to the truth that replaces it.","pairs":[{"left":"They didn't say no, so it was consent","right":"The absence of a no is not a yes"},{"left":"We're together, so it's assumed","right":"Each time is freely given"},{"left":"They came back, so they wanted it","right":"Every step needs its own yes"},{"left":"They were dressed for it","right":"Clothes never imply consent"},{"left":"Men can't be assaulted","right":"Anyone of any gender can be harmed"}],"relearn":"Each consent myth has a clear, true replacement; learn the swap and the myth loses its grip.","persona":"any","source":"myth to truth"},
  {"id":"cr-1140","cat":"spot-the-pressure","type":"match","hook":"Match each scene to whether it's a free ask or pressure.","pairs":[{"left":"\"Only if you actually want to\"","right":"A free ask"},{"left":"\"Everyone's done it, don't be a baby\"","right":"Shaming"},{"left":"\"No rush, your call\"","right":"Respecting your pace"},{"left":"50 calls after one 'not tonight'","right":"Hounding"},{"left":"\"Say yes or I'll find someone else\"","right":"A threat"}],"relearn":"Free asks leave the choice yours; shaming, hounding and threats take it away.","persona":"any","source":"ask or pressure"},
  {"id":"cr-1141","cat":"spot-the-pressure","type":"match","hook":"Match each coercive line to the lever it pulls.","pairs":[{"left":"\"After all I've done for you\"","right":"Owes-me guilt"},{"left":"\"Everyone's done it, grow up\"","right":"Peer shame"},{"left":"\"Your marks ride on this\"","right":"Power over you"},{"left":"\"Do it or I'll leave\"","right":"Fear of loss"},{"left":"\"I'll tell people if you don't\"","right":"A threat to expose"}],"relearn":"Coercion pulls a lever, guilt, shame, power, fear or a threat; spotting the lever is how you refuse it.","persona":"any","source":"coercion levers"},
  {"id":"cr-1142","cat":"spot-the-pressure","type":"match","hook":"Match each power gap to where a free yes gets compromised.","pairs":[{"left":"Senior over junior","right":"Fear of grades or status"},{"left":"Boss over worker","right":"Fear for the job"},{"left":"Landlord over tenant","right":"Fear of losing the room"},{"left":"Older partner over much younger","right":"Imbalanced say"},{"left":"Lender over borrower","right":"Money held over them"}],"relearn":"When one side holds power over the other, a yes can come from fear, not freedom.","persona":"any","source":"power gaps"},
  {"id":"cr-1143","cat":"spot-the-pressure","type":"match","hook":"Match each green-flag line to the respect it shows.","pairs":[{"left":"\"We can stop any time\"","right":"Consent stays revocable"},{"left":"\"Still good?\"","right":"Checking in"},{"left":"\"No worries, thanks for saying\"","right":"Taking a no well"},{"left":"\"Only if you want to\"","right":"Keeping it free"},{"left":"\"Your pace, no rush\"","right":"Respecting their pace"}],"relearn":"Green-flag lines keep a yes free, revocable and checked-in; that's what respect sounds like.","persona":"any","source":"green flags named"},
  {"id":"cr-1144","cat":"spot-the-pressure","type":"match","hook":"Match each pressured 'yes' to why it doesn't count.","pairs":[{"left":"\"Fine, just stop asking\"","right":"Worn down"},{"left":"A yes while barely awake","right":"No capacity"},{"left":"\"Okay, or you'll be angry\"","right":"Given out of fear"},{"left":"\"If I must, to keep my job\"","right":"Power held over them"},{"left":"\"Sure, so they won't out me\"","right":"Coerced by a threat"}],"relearn":"A yes that's worn down, incapacitated, scared or coerced isn't a free yes; only a willing one counts.","persona":"any","source":"why it fails"},
  {"id":"cr-1145","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs shame","hook":"You're at Rahul's place after a date, and he wants to go further than you do.","setup":"You've just said you're not feeling it.","steps":[{"prompt":"Rahul laughs: \"Don't be so uptight. Everyone does it.\"","options":[{"text":"\"I'm not uptight. I'm just nervous, I guess.\"","then":"\"Nervous is normal,\" he says. \"You'll relax.\""},{"text":"\"Sorry. I know I'm not much fun.\"","then":"\"You could be,\" he says, with a grin."},{"text":"\"'Everyone' isn't me. I'm not up for this.\"","then":"Rahul sighs. \"Fine. You're really no fun tonight.\"","best":true},{"text":"\"Maybe everyone does. Maybe I'm overthinking it.\"","then":"\"You are,\" he says. \"So stop thinking so much.\""}],"why":"What everyone supposedly does has nothing to do with your no."},{"prompt":"Rahul says: \"Seriously, what's the big deal? It's just fun.\"","options":[{"text":"\"I'll explain why I'm not into it.\"","then":"He listens, then argues with every single reason."},{"text":"\"It's a big deal to me, and it's still no.\"","then":"He throws up his hands. \"Okay, okay. Message received.\"","best":true},{"text":"\"It's not you. I just have issues with this stuff.\"","then":"\"So let me help you get over them,\" he says."},{"text":"\"Why do you even like me, then?\"","then":"\"I do,\" he says. \"That's why I want this.\""}],"why":"Your no doesn't need reasons, a date or his agreement. It stands on its own."},{"prompt":"The next day your friend Ali asks: \"How was the date with Rahul?\"","options":[{"text":"\"Fine. I was a bit uptight, honestly.\"","then":"\"Uptight how?\" Ali asks, and waits."},{"text":"\"Great! Nothing to report.\"","then":"\"Oh nice,\" Ali says, and moves on."},{"text":"\"Bad. I'm putting him on blast online tonight.\"","then":"\"Wait, what happened first?\" Ali asks, alarmed."},{"text":"\"Awful. He called me uptight for saying no.\"","then":"Ali frowns. \"That's not okay. Your no is your no.\"","best":true}],"why":"Being shamed for a no is never your fault. Telling a friend puts it where it belongs."}],"relearn":"Shame is a pressure tactic; your no holds no matter what 'everyone' supposedly does."},
  {"id":"cr-1146","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs guilt","hook":"Ayesha has helped you a lot this month. Tonight she wants more than you do.","setup":"You've just said you'd rather not.","steps":[{"prompt":"Ayesha sighs: \"After everything I do for you, you can't even do this?\"","options":[{"text":"\"Your help isn't a bill I pay with my body.\"","then":"Ayesha blinks. \"That's not what I meant,\" she says quietly.","best":true},{"text":"\"I know couples aren't meant to say no this much.\"","then":"\"Exactly,\" she says, and waits."},{"text":"\"You're right. I'm being unfair to you.\"","then":"\"A bit,\" she says. \"So make it up to me?\""},{"text":"\"Fine, then stop doing things for me.\"","then":"She looks hurt. \"Wow. Okay.\""}],"why":"Favours never buy a body. Naming the guilt-trip keeps your no whole."},{"prompt":"Ayesha says: \"I just feel like you don't love me as much as I love you.\"","options":[{"text":"\"Let's not talk about love right now.\"","then":"Her face falls. \"We never talk about it.\""},{"text":"\"Maybe I don't. I'm just really bad at this.\"","then":"She looks worried. \"Wait, what do you mean?\""},{"text":"\"Don't be so dramatic. You know I love you.\"","then":"Her eyes fill. \"I'm telling you how I feel.\""},{"text":"\"I love you. And a no isn't a lack of love.\"","then":"She's quiet for a moment. \"I've never thought of it like that.\"","best":true}],"why":"Love and a no can live together. Saying both is honest and fair."},{"prompt":"A few days later your sister asks: \"You two okay? You seem tense.\"","options":[{"text":"\"We're fine. Every couple fights about this stuff.\"","then":"\"Sure,\" she says, not quite convinced."},{"text":"\"She guilt-trips me when I say no. Can we talk?\"","then":"Your sister sits down. \"Of course. That's not okay, and it's not on you.\"","best":true},{"text":"\"It's me. I'm a terrible partner lately.\"","then":"\"Since when?\" she asks, frowning."},{"text":"\"Tense? No. Why, did she say something?\"","then":"\"No,\" she says, puzzled. \"You just seem off.\""}],"why":"A guilt-trip is never your fault. Talking it through helps you see it clearly."}],"relearn":"Favours never buy a body; naming a guilt-trip keeps your no intact."},
  {"id":"cr-1147","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs power","hook":"Ritika, a senior at your internship, writes your review and keeps singling you out.","setup":"She stops by your desk after everyone leaves.","steps":[{"prompt":"Ritika says: \"A little friendliness goes a long way around here.\"","options":[{"text":"\"Oh. Have I come across as unfriendly?\"","then":"She smiles. \"Not unfriendly. Just be a bit more open with me.\""},{"text":"\"Let's keep this about my work.\"","then":"Ritika's smile fades. \"Suit yourself. Reviews are next week.\"","best":true},{"text":"\"I guess that's just how internships work here.\"","then":"\"Exactly,\" she says. \"Smart intern.\""},{"text":"\"How dare you? I'll get you fired for this.\"","then":"\"By whom?\" she asks coolly. \"I'm the one writing your review.\""}],"why":"Keeping it about your work refuses the power-play without a fight."},{"prompt":"Next day Ritika messages: \"Drinks at my place tonight? Just us. It'd help you.\"","options":[{"text":"\"Can I bring a friend along?\"","then":"\"Just us,\" she replies. \"That's the point.\""},{"text":"\"Sorry if I gave you the wrong idea yesterday.\"","then":"\"You didn't,\" she replies. \"So, eight?\""},{"text":"\"No thanks. Happy to meet in the office.\"","then":"\"Your call,\" she replies. No emoji this time.","best":true},{"text":"\"Drinks with a senior are just networking, right?\"","then":"\"Now you're getting it,\" she replies. \"Eight, then.\""}],"why":"Keeping meetings to work spaces takes away her private pressure."},{"prompt":"Omkar, a fellow intern, asks: \"Is Ritika being weird with you too?\"","options":[{"text":"\"No, she's fine. Maybe I'm reading too much.\"","then":"\"Oh. Okay,\" Omkar says, and doesn't mention his own story."},{"text":"\"Keep it quiet. Interns who complain get dropped.\"","then":"Omkar nods, worried. Neither of you says a word to anyone."},{"text":"\"Yes. Let's call her out online tonight.\"","then":"Omkar hesitates. \"Won't that make it worse for us?\""},{"text":"\"Yes. Let's take it to the committee together.\"","then":"Omkar lowers his voice. \"Same with me. Okay, together.\"","best":true}],"why":"Going to the committee together means neither of you faces her power alone."},{"prompt":"Ritika says: \"I hope you're not planning to make trouble for me.\"","options":[{"text":"\"It's my word against yours anyway.\"","then":"She smiles. \"Exactly. So, Friday drinks?\""},{"text":"\"Depends. Will my review be fair?\"","then":"\"That depends on you,\" she says, smiling."},{"text":"\"I'll be talking to the committee about this.\"","then":"Ritika goes still. \"No need for that,\" she says, and leaves.","best":true},{"text":"\"You should be scared. Everyone will know soon.\"","then":"Her eyes narrow. \"Careful. I write your review.\""}],"why":"Naming the committee shows you know your rights. Her misuse of power is never your fault."}],"relearn":"A yes tied to your standing isn't free; naming it and signposting the committee is the move."},
  {"id":"cr-1148","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs blackmail","hook":"You've said no to Manav, and now he's using your reputation as leverage.","setup":"His message pops up while you're in the library.","steps":[{"prompt":"Manav texts: \"Say yes or I'll tell everyone you're frigid.\"","options":[{"text":"\"Why would you say that? I thought you liked me.\"","then":"\"I do. So prove you like me,\" he replies."},{"text":"\"Frigid? That's not true. Ask anyone.\"","then":"\"Prove it, then,\" he replies with a wink."},{"text":"\"Tell whoever you like. A threat isn't a yes.\"","then":"\"You'll regret this,\" he replies. Then three more messages.","best":true},{"text":"\"Do it and I'll leak your chats too.\"","then":"\"Go ahead,\" he replies. \"Mine are boring. Yours won't be.\""}],"why":"A yes to dodge a threat is never consent. You don't owe him a defence."},{"prompt":"Manav texts: \"Last chance. I'm posting in the batch group tonight.\"","options":[{"text":"\"Screenshotting this. Stop messaging me.\"","then":"\"Screenshot all you want,\" he replies. You block him.","best":true},{"text":"\"Fine, post it. Nobody will care, loser.\"","then":"\"Watch me,\" he replies, and starts typing in the group."},{"text":"\"Can we meet and talk this out calmly?\"","then":"\"My place, eight,\" he replies at once."},{"text":"\"Okay, maybe I overreacted earlier.\"","then":"\"You did,\" he replies. \"So say yes.\""}],"why":"Keeping proof and ending contact protects you. His threat is his shame."},{"prompt":"Your friend Nandini calls: \"Manav posted something weird about you. Are you okay?\"","options":[{"text":"\"It's fine. It's probably my fault somehow.\"","then":"\"Your fault? How?\" Nandini asks, confused."},{"text":"\"No. He threatened me when I said no. Come over?\"","then":"\"On my way,\" Nandini says. \"This is on him, not you.\"","best":true},{"text":"\"Just ignore it. I'm not getting into it.\"","then":"\"Okay,\" she says. \"But people are talking.\""},{"text":"\"Help me dig up dirt on him to post back tonight.\"","then":"Nandini pauses. \"Let's think before we do anything.\""}],"why":"Telling a friend you trust is how you stop carrying his threat alone."},{"prompt":"Nandini asks: \"Do you want to take this to the campus committee?\"","options":[{"text":"\"No point. Nobody takes this stuff seriously.\"","then":"\"They do,\" she says. \"This is exactly what it's for.\""},{"text":"\"No. It'll only prove what he said about me.\"","then":"\"It proves nothing about you,\" she says gently."},{"text":"\"Let's just deal with him ourselves.\"","then":"\"And risk making it worse?\" she asks, worried."},{"text":"\"Yes, I think so. Will you come with me?\"","then":"\"Of course,\" Nandini says. \"Let's go tomorrow morning.\"","best":true}],"why":"The committee exists for this. Getting help is strength, and it's never your fault."}],"relearn":"A yes given to dodge a threat isn't consent; the shame of blackmail belongs to them."},
  {"id":"cr-1149","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs room","hook":"After a concert, you went back to Nikita's room to hang out. Now she's pushing for more.","setup":"You've already said you're not up for it.","steps":[{"prompt":"Nikita says: \"You came to my room, so what did you expect?\"","options":[{"text":"\"I know. I'm sorry if I gave the wrong idea.\"","then":"\"You kind of did,\" Nikita says. \"So?\""},{"text":"\"I came to hang out. Being here isn't a yes.\"","then":"Nikita rolls her eyes. \"Okay. Mixed signals, but okay.\"","best":true},{"text":"\"I expected to talk. Let me explain what I meant.\"","then":"Nikita interrupts halfway. \"You're overthinking. Relax.\""},{"text":"\"Wow. Do you say that to everyone you invite?\"","then":"Nikita laughs. \"Only the cute ones.\""}],"why":"A room is never a promise. Being somewhere is not agreeing to anything."},{"prompt":"Nikita says: \"Everyone knows what coming over means.\"","options":[{"text":"\"Maybe I should've thought before coming.\"","then":"\"Exactly,\" Nikita says. \"So stay a while.\""},{"text":"\"Fine. Next time we'll hang out in the canteen.\"","then":"\"Or you could just relax here,\" Nikita says."},{"text":"\"Does it? I didn't know. I'm new to this.\"","then":"\"Then let me teach you,\" Nikita says with a smile."},{"text":"\"I don't care what everyone knows. It's no.\"","then":"Nikita sighs. \"Fine. I'll order food then.\"","best":true}],"why":"What 'everyone knows' is a myth. Only your own yes counts."},{"prompt":"Walking back, your friend Rehan calls: \"Where'd you disappear to? All good?\"","options":[{"text":"\"Not really. Nikita kept pushing after my no.\"","then":"Rehan stops walking. \"That's not okay. Want me to meet you?\"","best":true},{"text":"\"All good. My fault for going to her room.\"","then":"\"Going to someone's room isn't a yes,\" Rehan says. \"What happened?\""},{"text":"\"Fine. Just don't tell anyone where I was.\"","then":"\"Okay,\" Rehan says slowly. \"You sure you're fine?\""},{"text":"\"All good. It's not pressure when a girl does it.\"","then":"\"Pressure's pressure,\" Rehan says. \"Who it's from doesn't matter.\""}],"why":"Pressure from anyone is never your fault. Telling a friend helps you carry it."}],"relearn":"A room is never a promise; coming over is never consent to what's next."},
  {"id":"cr-1150","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs revoke","hook":"You said yes to Sameer, but mid-way you've changed your mind.","setup":"You've pulled back and said you want to stop.","steps":[{"prompt":"Sameer says: \"You said yes a minute ago. You can't back out now.\"","options":[{"text":"\"Sorry, I know. I'm being so confusing.\"","then":"\"You are,\" he says. \"So which is it?\""},{"text":"\"Is it really too late to stop now?\"","then":"\"Kind of, yeah,\" he says. \"You started it.\""},{"text":"\"I'm taking it back. Stop.\"","then":"Sameer freezes, then sits back. \"Okay. Okay.\"","best":true},{"text":"\"Can we talk about it first?\"","then":"\"Talk about what? You were into it,\" he says."}],"why":"A yes can be taken back at any moment. A stop is a stop."},{"prompt":"Sameer says: \"That's not fair. You led me on.\"","options":[{"text":"\"I didn't. I changed my mind, and that's allowed.\"","then":"Sameer looks away. \"I guess,\" he mutters.","best":true},{"text":"\"Maybe I did. I'm really sorry.\"","then":"\"You should be,\" he says. \"That was messed up.\""},{"text":"\"Let me explain what happened in my head.\"","then":"He listens, then shrugs. \"So it's just nerves, then.\""},{"text":"\"Next time I won't say yes unless I'm sure.\"","then":"\"Good,\" he says, as if you'd done something wrong."}],"why":"Changing your mind is never leading anyone on. It's your right."},{"prompt":"Back home, your flatmate Nazia asks: \"You're shaking. What happened?\"","options":[{"text":"\"Nothing really. I just feel stupid about it.\"","then":"\"You're not stupid,\" Nazia says. \"Want some tea?\""},{"text":"\"I said stop and he argued. Can I tell you?\"","then":"Nazia sits beside you. \"Of course. Take your time.\"","best":true},{"text":"\"I think I led him on. It's my fault.\"","then":"\"Changing your mind isn't leading anyone on,\" Nazia says gently."},{"text":"\"Just a bad date. I'll sleep it off.\"","then":"\"Okay,\" Nazia says. You lie awake replaying it."}],"why":"What he did is never your fault. A trusted friend helps you feel less alone."},{"prompt":"The next morning Sameer texts: \"Don't tell anyone about last night, okay?\"","options":[{"text":"\"Okay. I guess I owe you that much.\"","then":"\"Good,\" he replies. \"Knew you'd get it.\""},{"text":"\"Only if you promise it won't happen again.\"","then":"\"Sure, promise,\" he replies, too quickly."},{"text":"\"Everyone's going to hear what you did.\"","then":"\"Nobody will believe you,\" he replies."},{"text":"\"I'll talk to whoever I need to.\"","then":"\"Why would you need to talk to anyone?\" he replies.","best":true}],"why":"You never owe anyone secrecy about how you were treated."}],"relearn":"Consent is revocable any moment; a new no ends it, however far in."},
  {"id":"cr-1151","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice as bystander","hook":"At a party, your friend Kriti is being worn down by a guy and looks stuck.","setup":"Music is loud, and nobody else seems to notice.","steps":[{"prompt":"You walk over, and the guy, Deven, says: \"Hey, we're talking here.\"","options":[{"text":"\"Sorry to interrupt. You two okay? I'll leave you to it.\"","then":"Kriti's eyes follow you, pleading, as you walk away."},{"text":"\"Kriti, is he making you uncomfortable? Just say.\"","then":"Kriti glances at Deven. \"No, it's fine. We're just talking.\""},{"text":"\"Kriti, there you are. Our auto's here. Let's go.\"","then":"Kriti grabs her bag. \"Coming!\" Deven shrugs, annoyed.","best":true},{"text":"\"Back off, man. She clearly isn't interested.\"","then":"Deven stands up. \"Who are you to decide?\" People turn."}],"why":"An easy excuse gives her an exit without making her argue in front of him."},{"prompt":"Later, Kriti says quietly: \"I felt so stuck back there.\"","options":[{"text":"\"Why didn't you just walk off?\"","then":"\"I tried,\" Kriti says, and stops talking."},{"text":"\"That wasn't on you. He wasn't listening.\"","then":"Kriti's shoulders drop. \"I kept thinking I was being rude.\"","best":true},{"text":"\"Next time, just don't talk to guys like that.\"","then":"Kriti's face closes. \"Right. My bad.\""},{"text":"\"Want me to go find him and sort it out?\"","then":"\"No! Please don't make it bigger,\" Kriti says."}],"why":"Freezing up is common. Saying it's not her fault helps her shake off the shame."},{"prompt":"Kriti asks: \"Should I have been ruder to him?\"","options":[{"text":"\"Yes. You need to be tougher.\"","then":"Kriti goes quiet. \"I'll try,\" she says."},{"text":"\"Maybe. Guys take politeness as interest, you know.\"","then":"\"So it was my fault for being nice?\" Kriti asks."},{"text":"\"No. That's all on him. And I've got you.\"","then":"Kriti nods slowly. \"Okay. Yeah. That helps.\"","best":true},{"text":"\"Don't think about it anymore. It's over now.\"","then":"\"I guess,\" Kriti says, still turning it over."}],"why":"It's never her job to be rude enough. Not listening was entirely his choice."}],"relearn":"A bystander offering a clear exit can break a pressure situation; give the out and don't ask permission."},
  {"id":"cr-1152","cat":"spot-the-pressure","type":"role-play","persona":"any","source":"voice vs push","hook":"You've been seeing Anjali. Each time you say you're not ready, her messages get angrier.","setup":"Her latest message lands during your study group.","steps":[{"prompt":"Anjali texts: \"How long do I have to wait? This is ridiculous.\"","options":[{"text":"\"Maybe later, okay? Please don't be upset.\"","then":"\"How much later? Give me a date,\" she replies."},{"text":"\"I'm sorry. I know I'm being slow.\"","then":"\"You really are,\" she replies. \"Speed up.\""},{"text":"\"I've said where I'm at. Pushing won't change it.\"","then":"\"Unbelievable,\" she replies. \"Everyone else manages.\"","best":true},{"text":"\"Let me explain why I'm not ready, properly this time.\"","then":"She replies to every point with a counter-point."}],"why":"Pushing harder after a no is a red flag. You owe no timeline and no apology."},{"prompt":"Anjali texts: \"If you cared about me, you wouldn't make me wait.\"","options":[{"text":"\"Maybe you're right. Caring should mean I'm ready.\"","then":"\"Exactly,\" she replies. \"So stop overthinking.\""},{"text":"\"I do care. I'm done discussing this.\"","then":"Three dots appear and vanish. Then: \"Fine.\"","best":true},{"text":"\"Maybe I don't care enough. I'm sorry.\"","then":"\"So I've wasted my time,\" she replies."},{"text":"\"You're being so needy right now.\"","then":"\"Needy? Wow,\" she replies, and sends a long angry message."}],"why":"Caring about someone never means owing them a timeline for intimacy."},{"prompt":"Your study partner Farhan asks: \"You keep wincing at your phone. All okay?\"","options":[{"text":"\"Yeah. It's normal relationship stuff.\"","then":"\"If you say so,\" Farhan says, unconvinced."},{"text":"\"Just me being a bad partner, as usual.\"","then":"\"You? Bad partner?\" Farhan frowns. \"What's going on?\""},{"text":"\"Not really. My partner keeps pushing me.\"","then":"Farhan closes his laptop. \"That's not okay. Want to talk?\"","best":true},{"text":"\"Fine. Let's just focus on the notes.\"","then":"Farhan nods, but your phone buzzes again. And again."}],"why":"Pressure after a no is never your fault. Saying it out loud to a friend helps."}],"relearn":"Pushing harder after a no is a red flag; you owe no negotiation and no apology."},
  {"id":"cr-1153","cat":"spot-the-pressure","type":"match","hook":"Match each excuse to why it never excuses ignoring consent.","pairs":[{"left":"\"They'd been drinking\"","right":"Drink is never an excuse"},{"left":"\"They came to my room\"","right":"A place is never a yes"},{"left":"\"They didn't fight back\"","right":"A freeze is not a yes"},{"left":"\"We're dating\"","right":"Each time is freely given"},{"left":"\"They wore that\"","right":"Clothes say nothing"}],"relearn":"None of these excuse ignoring consent; responsibility lies only with the person ignoring it.","persona":"any","source":"no excuse"},
  {"id":"cr-1350","cat":"tools-and-help","type":"match","hook":"Match each need to the right route in India.","pairs":[{"left":"A woman facing any violence, 24/7","right":"Women Helpline 181"},{"left":"Immediate danger, right now","right":"Emergency 112"},{"left":"A woman in distress, separate line","right":"1091"},{"left":"Harassment by a classmate or staff","right":"The campus Internal Committee"},{"left":"Want to talk it through privately","right":"A campus counsellor"}],"relearn":"181 and 1091 for women, 112 for danger, the campus committee for harassment, a counsellor to talk.","persona":"any","source":"help routes"},
  {"id":"cr-1351","cat":"tools-and-help","type":"match","hook":"Match the consent word to what it means.","pairs":[{"left":"Freely-given","right":"No pressure, fear or power-play behind it"},{"left":"Ongoing","right":"Checked again at each step, not banked"},{"left":"Sober-enough","right":"Awake and clear, not drunk or passed out"},{"left":"Revocable","right":"Can be taken back any time, even mid-way"},{"left":"Enthusiastic","right":"A real, eager yes, not a polite one"}],"relearn":"Freely-given, ongoing, sober-enough, revocable, enthusiastic, that's the whole standard.","persona":"any","source":"the reference"},
  {"id":"cr-1352","cat":"tools-and-help","type":"match","hook":"Mehta: match who you'd point a friend toward.","pairs":[{"left":"Wants to talk, no report yet","right":"A campus counsellor"},{"left":"In danger tonight","right":"Emergency 112"},{"left":"Wants formal campus action","right":"The Internal Committee"},{"left":"Facing violence at home or outside","right":"Women Helpline 181"},{"left":"Just needs to be believed","right":"A trusted person"}],"relearn":"Counsellor to talk, 112 for danger, ICC for action, 181 for violence, a trusted person to be heard.","persona":"Mehta","source":"pointing to help"},
  {"id":"cr-1353","cat":"tools-and-help","type":"match","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"\"They didn't say no\"","right":"Consent is an active, willing yes"},{"left":"\"They were drunk, so it counts\"","right":"Incapacity means no consent"},{"left":"\"We're together, so it's assumed\"","right":"It's freely given each time"},{"left":"\"It was their fault somehow\"","right":"Fault sits only with the one ignoring consent"},{"left":"\"Men can't be assaulted\"","right":"Anyone of any gender can be harmed"}],"relearn":"Active yes; incapacity is no consent; each time; fault sits with the one ignoring it; anyone can be harmed.","persona":"any","source":"myth to truth"},
  {"id":"cr-1354","cat":"tools-and-help","type":"match","hook":"Match each first thing to say to a friend who's just told you.","pairs":[{"left":"To lead with belief","right":"\"I believe you\""},{"left":"To lift the blame off them","right":"\"This wasn't your fault\""},{"left":"To give back control","right":"\"What do you need from me?\""},{"left":"To stay beside them","right":"\"I'm here, on your side\""},{"left":"To respect their choice","right":"\"It's your call whether to report\""}],"relearn":"Believe, un-blame, ask what they need, stay beside them, respect their choice to report.","persona":"any","source":"first words"},
  {"id":"cr-1355","cat":"tools-and-help","type":"match","hook":"Match the capacity state to the line it falls on.","pairs":[{"left":"Sober and clearly willing","right":"Can consent, clearly"},{"left":"One drink, fully with it","right":"Still able to consent"},{"left":"Slurring, can barely stand","right":"Too far gone, cannot"},{"left":"Blacked out","right":"No capacity at all"},{"left":"Asleep or passed out","right":"Definitely cannot consent"}],"relearn":"Sober or mildly tipsy-but-with-it can; slurring, blackout, asleep cannot.","persona":"any","source":"capacity line"},
  {"id":"cr-1356","cat":"tools-and-help","type":"match","hook":"Match the support move to why it matters.","pairs":[{"left":"\"I believe you\"","right":"Belief is what survivors fear losing"},{"left":"\"What do you need?\"","right":"Gives back control they lost"},{"left":"Signposting help","right":"Connects them to real support"},{"left":"Not forcing a report","right":"Respects their autonomy"},{"left":"No blaming questions","right":"Keeps the fault where it belongs"}],"relearn":"Belief, control, signposting, not forcing, no blame, that's why each move matters.","persona":"any","source":"support steps"},
  {"id":"cr-1357","cat":"tools-and-help","type":"match","hook":"Meena: match the route that works even with no warden or counsellor.","pairs":[{"left":"Facing violence, any form","right":"Women Helpline 181"},{"left":"A separate women-in-distress line","right":"1091"},{"left":"Danger needing help fast","right":"Emergency 112"},{"left":"Someone steady to confide in","right":"A trusted person"},{"left":"Not ready to say it aloud","right":"The anonymous in-app route"}],"relearn":"181, 1091, 112, a trusted person, and the anonymous route reach you with no campus at all.","persona":"Meena","source":"offline routes"},
  {"id":"cr-1358","cat":"tools-and-help","type":"match","hook":"Match the situation to the line that fits it.","pairs":[{"left":"They go quiet mid-moment","right":"\"You okay? We can pause\""},{"left":"They changed their mind","right":"\"Of course, we stop\""},{"left":"You want to slow down","right":"\"I'm into you, let's go slower\""},{"left":"You're not sure they mean it","right":"\"Only if you actually want to\""},{"left":"They said no to a plan","right":"\"No worries at all\""}],"relearn":"The right words exist for pausing, stopping, slowing, checking, and taking a no well.","persona":"any","source":"the right words"},
  {"id":"cr-1359","cat":"tools-and-help","type":"match","hook":"Match the campus matter to who handles it.","pairs":[{"left":"Harassment by a student or staff","right":"The campus Internal Committee"},{"left":"You want to talk it through","right":"A campus counsellor"},{"left":"Immediate danger on campus","right":"Emergency 112"},{"left":"You need a confidential first step","right":"The anonymous in-app route"},{"left":"You want a friend simply believed","right":"A trusted person"}],"relearn":"ICC for harassment, counsellor to talk, 112 for danger, anonymous route, a trusted person to be heard.","persona":"any","source":"campus routes"},
  {"id":"cr-1360","cat":"tools-and-help","type":"match","hook":"Match each green-flag behaviour to the value it shows.","pairs":[{"left":"Asks \"is this good?\"","right":"Checking in is care, not a buzzkill"},{"left":"Takes a no without sulking","right":"A no is fully fine"},{"left":"Watches a tipsy friend get home","right":"Looking out for each other"},{"left":"Stops the second you do","right":"Consent is revocable"},{"left":"Welcomes your boundary","right":"Boundaries build trust"}],"relearn":"Checking in, taking a no well, looking out, stopping, welcoming a boundary, all consent culture.","persona":"any","source":"green flags"},
  {"id":"cr-1361","cat":"tools-and-help","type":"match","hook":"Match the worry to the route that answers it.","pairs":[{"left":"\"I don't want to make it official yet\"","right":"A counsellor or trusted person, no report needed"},{"left":"\"It's late and I'm scared right now\"","right":"Emergency 112"},{"left":"\"I want the college to act\"","right":"The Internal Committee"},{"left":"\"I'm facing violence at home\"","right":"Women Helpline 181"},{"left":"\"I just need to be believed\"","right":"A trusted person leading with belief"}],"relearn":"There's a route for talking, for danger, for formal action, for violence, and for being believed.","persona":"Mehta","source":"worry to route"},
  {"id":"cr-1362","cat":"tools-and-help","type":"match","hook":"Match the question to the answer in the one-line reference.","pairs":[{"left":"Was it pressured or scared into?","right":"Then it wasn't freely-given"},{"left":"Did you check at this step too?","right":"Consent is ongoing"},{"left":"Were they clear-headed enough?","right":"It must be sober-enough"},{"left":"Did they change their mind?","right":"Consent is revocable"},{"left":"Was it a real, eager yes?","right":"That's enthusiastic consent"}],"relearn":"Freely-given, ongoing, sober-enough, revocable, enthusiastic, run the situation through each.","persona":"any","source":"reference in action"},
  {"id":"cr-1363","cat":"tools-and-help","type":"match","hook":"Match the friend's situation to the gentle next step.","pairs":[{"left":"Doesn't know help exists","right":"Share the routes, gently"},{"left":"Wants to talk, not report","right":"Point to a counsellor"},{"left":"In danger tonight","right":"Help them reach 112"},{"left":"Blames themselves","right":"Remind them it's not their fault"},{"left":"Wants space","right":"Let them lead, stay reachable"}],"relearn":"Share routes, point to a counsellor, help reach 112, un-blame, and let them lead.","persona":"any","source":"helping a friend"},
  {"id":"cr-1364","cat":"tools-and-help","type":"match","hook":"Match the helpline to what it's for.","pairs":[{"left":"181","right":"Women facing any violence, 24/7"},{"left":"1091","right":"Women in distress"},{"left":"112","right":"Any immediate emergency"},{"left":"Campus ICC","right":"Harassment at college"},{"left":"A counsellor","right":"A confidential talk"}],"relearn":"181 and 1091 for women, 112 for emergencies, ICC for campus, a counsellor to talk.","persona":"any","source":"number to purpose"},
  {"id":"cr-1365","cat":"tools-and-help","type":"match","hook":"Match each option to why it does or doesn't help.","pairs":[{"left":"Women Helpline 181","right":"A real, staffed route"},{"left":"A campus counsellor","right":"Confidential, expert support"},{"left":"Posting in a random group chat","right":"No safety, no privacy"},{"left":"Bottling it up alone","right":"Leaves you carrying it alone"},{"left":"Waiting for it to fix itself","right":"Nothing changes on its own"}],"relearn":"181 and a counsellor are real routes; a random chat, bottling it up, or waiting are not.","persona":"any","source":"route vs dead end"},
  {"id":"cr-1366","cat":"tools-and-help","type":"match","hook":"Match the moment to the consent habit it calls for.","pairs":[{"left":"Things are moving fast","right":"Pause and check in"},{"left":"Drinks are flowing","right":"Watch capacity, yours and theirs"},{"left":"A friend can't look after themselves","right":"Step in as a bystander"},{"left":"Someone tells you their no","right":"Take it gracefully"},{"left":"You want to start something","right":"Look for an eager yes"}],"relearn":"Check in, watch capacity, step in for a friend, take a no well, seek an eager yes.","persona":"any","source":"moment to habit"},
  {"id":"cr-1367","cat":"tools-and-help","type":"match","hook":"Match the false belief to what's actually true.","pairs":[{"left":"\"There's nowhere to turn\"","right":"Real, confidential routes exist"},{"left":"\"Asking for help is weak\"","right":"It's the equipped, adult move"},{"left":"\"Only women can be harmed\"","right":"Anyone of any gender can be"},{"left":"\"A freeze means it was fine\"","right":"Freezing is a normal response, not a yes"},{"left":"\"Reporting is the only option\"","right":"Talking or healing first is valid too"}],"relearn":"Routes exist; help isn't weak; anyone can be harmed; freeze isn't a yes; reporting is one option.","persona":"any","source":"belief vs truth"},
  {"id":"cr-1368","cat":"tools-and-help","type":"match","hook":"Match the blaming question to the better one.","pairs":[{"left":"\"What were you wearing?\"","right":"\"None of that caused this\""},{"left":"\"Why didn't you fight?\"","right":"\"Freezing is normal, it's okay\""},{"left":"\"Why did you go there?\"","right":"\"Where you went doesn't excuse it\""},{"left":"\"Why didn't you report at once?\"","right":"\"You can decide that in your own time\""},{"left":"\"Are you sure it happened?\"","right":"\"I believe you\""}],"relearn":"Swap every blaming question for belief; the fault is never the survivor's.","persona":"any","source":"questions to swap"},
  {"id":"cr-1369","cat":"tools-and-help","type":"match","hook":"Match the channel to when it fits best.","pairs":[{"left":"Anonymous in-app Ask-It","right":"When you're not ready to say it aloud"},{"left":"A campus counsellor","right":"When you want a private, expert talk"},{"left":"The Internal Committee","right":"When you want the college to act"},{"left":"Women Helpline 181","right":"When you're facing violence"},{"left":"Emergency 112","right":"When the danger is right now"}],"relearn":"Anonymous to start, a counsellor to talk, ICC to act, 181 for violence, 112 for danger.","persona":"any","source":"channel to moment"},
  {"id":"cr-1370","cat":"tools-and-help","type":"sort","hook":"Sort: a real support route, or not?","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"Asking a random group chat"},{"id":"c","text":"A campus counsellor"},{"id":"d","text":"Just bottling it up"},{"id":"e","text":"The campus Internal Committee"},{"id":"f","text":"Waiting and hoping it passes"}],"bins":[{"id":"real","label":"Real route","valence":"pos"},{"id":"not","label":"Not a route","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"181, a counsellor and the ICC are real routes; a random chat, bottling it up or waiting aren't.","persona":"any","source":"real routes"},
  {"id":"cr-1371","cat":"tools-and-help","type":"sort","hook":"Sort: does the campus Internal Committee handle this, or not?","items":[{"id":"a","text":"Harassment by a student or staff"},{"id":"b","text":"A lost library book"},{"id":"c","text":"A hostile, unsafe campus environment"},{"id":"d","text":"Your exam timetable"},{"id":"e","text":"Quid-pro-quo pressure from a senior"},{"id":"f","text":"A broken hostel water cooler"}],"bins":[{"id":"icc","label":"ICC handles","valence":"pos"},{"id":"not","label":"Not its remit","valence":"neutral"}],"key":{"a":"icc","b":"not","c":"icc","d":"not","e":"icc","f":"not"},"relearn":"The ICC handles harassment, unsafe environments and quid-pro-quo, not books, timetables or repairs.","persona":"any","source":"campus ICC"},
  {"id":"cr-1372","cat":"tools-and-help","type":"sort","hook":"Sort each into can-consent or cannot.","items":[{"id":"a","text":"Sober and clearly willing"},{"id":"b","text":"Passed out on the sofa"},{"id":"c","text":"One beer, fully with it"},{"id":"d","text":"Slurring, can't stand"},{"id":"e","text":"Asleep"},{"id":"f","text":"Tipsy but talking and clear"}],"bins":[{"id":"can","label":"Can consent","valence":"pos"},{"id":"cannot","label":"Cannot consent","valence":"neg"}],"key":{"a":"can","b":"cannot","c":"can","d":"cannot","e":"cannot","f":"can"},"relearn":"Sober or mildly tipsy-but-with-it can; passed out, slurring or asleep cannot.","persona":"any","source":"capacity sort"},
  {"id":"cr-1373","cat":"tools-and-help","type":"sort","hook":"Sort each move into supports a survivor or harms them.","items":[{"id":"a","text":"\"I believe you\""},{"id":"b","text":"\"What were you wearing?\""},{"id":"c","text":"\"What do you need?\""},{"id":"d","text":"\"You should've reported sooner\""},{"id":"e","text":"\"This wasn't your fault\""},{"id":"f","text":"Forcing them to go to the police"}],"bins":[{"id":"helps","label":"Supports","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Belief, asking what they need and un-blaming support; blame or forcing a report harm.","persona":"any","source":"support vs harm"},
  {"id":"cr-1374","cat":"tools-and-help","type":"sort","hook":"Sort each into the right route for the need.","items":[{"id":"a","text":"Danger right now, late at night"},{"id":"b","text":"Want to talk, no report yet"},{"id":"c","text":"Facing violence, any form"},{"id":"d","text":"Want the college to take action"},{"id":"e","text":"Need someone to simply believe me"},{"id":"f","text":"Not ready to say it out loud"}],"bins":[{"id":"urgent","label":"112 now","valence":"uhoh"},{"id":"talk","label":"Counsellor / person","valence":"pos"},{"id":"act","label":"181 or ICC","valence":"tell"}],"key":{"a":"urgent","b":"talk","c":"act","d":"act","e":"talk","f":"talk"},"relearn":"112 for danger now; a counsellor or trusted person to talk; 181 or the ICC to act.","persona":"any","source":"need to route"},
  {"id":"cr-1375","cat":"tools-and-help","type":"sort","hook":"Sort each into builds a consent culture or erodes it.","items":[{"id":"a","text":"Checking in warmly"},{"id":"b","text":"Mocking someone's boundary"},{"id":"c","text":"Taking a no without sulking"},{"id":"d","text":"Treating pressure as normal"},{"id":"e","text":"Looking out for a tipsy friend"},{"id":"f","text":"Sharing real help routes"}],"bins":[{"id":"builds","label":"Builds it","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"builds"},"relearn":"Checking in, taking a no well, looking out and sharing routes build it; mocking or pressure erode it.","persona":"any","source":"builds vs erodes"},
  {"id":"cr-1376","cat":"tools-and-help","type":"sort","hook":"Sort: which numbers belong to this game's verified set?","items":[{"id":"a","text":"181"},{"id":"b","text":"1091"},{"id":"c","text":"112"},{"id":"d","text":"A number a stranger texted you"},{"id":"e","text":"Campus Internal Committee"},{"id":"f","text":"A number you half-remember"}],"bins":[{"id":"verified","label":"Verified route","valence":"pos"},{"id":"no","label":"Don't use","valence":"neg"}],"key":{"a":"verified","b":"verified","c":"verified","d":"no","e":"verified","f":"no"},"relearn":"181, 1091, 112 and the campus ICC are verified; never use a guessed or stranger's number.","persona":"any","source":"verified set"},
  {"id":"cr-1377","cat":"tools-and-help","type":"sort","hook":"Sort each into a thing consent always is, or never is.","items":[{"id":"a","text":"Freely given"},{"id":"b","text":"Assumed because you're dating"},{"id":"c","text":"Revocable any time"},{"id":"d","text":"Worn out of someone"},{"id":"e","text":"Sober-enough"},{"id":"f","text":"The absence of a no"}],"bins":[{"id":"is","label":"Consent is","valence":"pos"},{"id":"isnt","label":"Consent isn't","valence":"neg"}],"key":{"a":"is","b":"isnt","c":"is","d":"isnt","e":"is","f":"isnt"},"relearn":"Consent is freely-given, revocable, sober-enough; it's never assumed, worn out, or just no-no.","persona":"any","source":"is vs isn't"},
  {"id":"cr-1378","cat":"tools-and-help","type":"sort","hook":"Meena: sort what reaches you even with no campus around.","items":[{"id":"a","text":"Women Helpline 181"},{"id":"b","text":"A campus warden"},{"id":"c","text":"Emergency 112"},{"id":"d","text":"A college counsellor's office"},{"id":"e","text":"A trusted person near you"},{"id":"f","text":"Women-in-distress line 1091"}],"bins":[{"id":"reaches","label":"Reaches you offline","valence":"pos"},{"id":"campus","label":"Needs a campus","valence":"neutral"}],"key":{"a":"reaches","b":"campus","c":"reaches","d":"campus","e":"reaches","f":"reaches"},"relearn":"181, 112, 1091 and a trusted person reach you with no campus; a warden or college office need one.","persona":"Meena","source":"offline reach"},
  {"id":"cr-1379","cat":"tools-and-help","type":"sort","hook":"Sort each into a green flag or a red flag in a partner.","items":[{"id":"a","text":"Asks if you're comfortable"},{"id":"b","text":"Sulks when you say no"},{"id":"c","text":"Stops the moment you do"},{"id":"d","text":"Guilt-trips you into a yes"},{"id":"e","text":"Welcomes your boundary"},{"id":"f","text":"Pushes after you've said stop"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Asking, stopping and welcoming a boundary are green; sulking, guilt-trips and pushing are red.","persona":"any","source":"green vs red"},
  {"id":"cr-1380","cat":"tools-and-help","type":"reflect","hook":"Lensy: a simple line to check yourself mid-moment, \"Are they into this, or just going along?\" Useful?","prompt":"Would you use that check?","options":["I'd pause and ask","Saves a mistake","Worth it"],"affirm":"That one pause, into this or going along, is how a kind person stays a safe one.","relearn":"Mid-moment self-check: are they into this, or just going along? If unsure, pause and ask.","persona":"any","source":"mid-moment check"},
  {"id":"cr-1381","cat":"tools-and-help","type":"reflect","hook":"Lensy: you know the routes now and could share them with a friend who doesn't. Worth carrying?","prompt":"What do you think?","options":["Yes","I'd share them","Good to know"],"affirm":"Knowing where help lives, and passing it on gently, can be a real lifeline for someone.","relearn":"Knowing the routes and sharing them gently can be a lifeline for a friend.","persona":"any","source":"sharing routes"},
  {"id":"cr-1382","cat":"tools-and-help","type":"reflect","hook":"Lensy: asking for help isn't weakness, it's the equipped, adult move. Sit okay with you?","prompt":"What do you think?","options":["Yes","It does","Makes sense"],"affirm":"Knowing where help lives and using it is strength, not weakness.","relearn":"Help-seeking is not weakness; it's the equipped, adult move.","persona":"Deepak","source":"help isn't weakness"},
  {"id":"cr-1383","cat":"tools-and-help","type":"reflect","hook":"Lensy: 181, 1091, 112 and the campus committee, the numbers are small enough to remember. Feel reachable?","prompt":"What do you think?","options":["Yes","Reachable","I've got them"],"affirm":"Help is closer than it feels; those few routes cover a lot of ground.","relearn":"181, 1091, 112 and the campus committee, help is closer than it feels.","persona":"any","source":"reachable"},
  {"id":"cr-1384","cat":"tools-and-help","type":"reflect","hook":"Lensy: there's no deadline on getting support, reaching out a week or a year later is just as valid. Did you know?","prompt":"Did you know that?","options":["I didn't","Good to know it","That helps"],"affirm":"Help has no expiry; reaching out late is still reaching out, and it still counts.","relearn":"There's no deadline on support, reaching out late is just as valid as reaching out at once.","persona":"any","source":"no deadline"},
  {"id":"cr-1385","cat":"tools-and-help","type":"reflect","hook":"Lensy: if a friend ever confides in you, the first thing to say is \"I believe you, it's not your fault.\" Could you?","prompt":"Could you say that to a friend?","options":["I could say it","I'd want to","I'll remember it"],"affirm":"Those two lines, I believe you and it's not your fault, are the most helpful thing a friend can offer.","relearn":"If a friend confides, lead with \"I believe you, it's not your fault\" before anything else.","persona":"any","source":"first words to a friend"},
  {"id":"cr-1386","cat":"tools-and-help","type":"reflect","hook":"Lensy: which habit will you actually try first this week?","prompt":"What's your first step?","options":["Check in out loud","Watch for a freeze","Lead with belief","Share the helplines"],"affirm":"Pick one and start there; a single habit, used for real, is worth more than four you only nod at.","relearn":"Turn it into one habit you'll actually use this week, not four you only agree with.","persona":"any","source":"first step"},
  {"id":"cr-1387","cat":"tools-and-help","type":"reflect","hook":"Lensy: a friend you'd point toward help is lucky to have you. Notice that in yourself?","prompt":"What do you think?","options":["Yes","I'd do it","Maybe"],"affirm":"Being the person a friend can turn to is its own quiet kind of brave.","relearn":"Being someone a friend can turn to is a real, quiet strength.","persona":"any","source":"the one they turn to"},
  {"id":"cr-1388","cat":"tools-and-help","type":"reflect","hook":"Lensy: you can support a survivor without forcing any choice on them. How does that land?","prompt":"What do you think?","options":["Right to me","Reassuring","I get it"],"affirm":"Supporting someone means walking beside their choices, never overriding them.","relearn":"You can support a survivor while leaving every choice fully theirs.","persona":"any","source":"beside their choices"},
  {"id":"cr-1389","cat":"tools-and-help","type":"reflect","hook":"Lensy: checking in warmly made intimacy better, not awkward, in these scenes. Buy it?","prompt":"What do you think?","options":["Yes","I do now","Worth trying"],"affirm":"A warm \"is this good?\" builds trust, that's the green core of all this.","relearn":"Checking in warmly builds trust and makes intimacy better, not awkward.","persona":"any","source":"checking in is hot"},
  {"id":"cr-1390","cat":"tools-and-help","type":"reflect","hook":"Lensy: anyone of any gender can be harmed, and deserves belief. Does that feel like yours too?","prompt":"What do you think?","options":["Yes","It is","Important"],"affirm":"This standard is everyone's, and everyone's enthusiastic yes matters equally.","relearn":"Anyone of any gender can be harmed and deserves belief; this is everyone's.","persona":"any","source":"everyone's"},
  {"id":"cr-1391","cat":"tools-and-help","type":"reflect","hook":"Rohan: a confident, respectful way of dating works better than the old scripts. Sit right with you?","prompt":"What do you think?","options":["Yeah","Makes sense","I'll try it"],"affirm":"Reading a real yes and taking a no well is the version that actually wins.","relearn":"Confident, respectful dating, reading a real yes, works better than the old scripts.","persona":"Rohan","source":"the version that works"},
  {"id":"cr-1392","cat":"tools-and-help","type":"reflect","hook":"Lensy: a no taken gracefully costs you nothing and says a lot. Worth keeping?","prompt":"What do you think?","options":["Yes","Definitely","I'll keep it"],"affirm":"Taking a no with grace, no sulking or pestering, is a quiet superpower.","relearn":"Taking a no gracefully, no sulking or pestering, is a core consent habit.","persona":"any","source":"a graceful no"},
  {"id":"cr-1393","cat":"tools-and-help","type":"reflect","hook":"Lensy: a tipsy friend who can't look after themselves, you'd look out for. Recognise that instinct?","prompt":"What do you think?","options":["Yes","I would","Of course"],"affirm":"Looking out for a friend past looking after themselves is consent culture in action.","relearn":"Looking out for a friend past looking after themselves is consent culture.","persona":"any","source":"bystander instinct"},
  {"id":"cr-1394","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't have to have the perfect words to help, just believe and stay. Relief?","prompt":"What do you think?","options":["Yes","Big relief","Good to know"],"affirm":"\"I believe you, I'm here\" is enough; you don't need a script to be a good friend.","relearn":"You don't need perfect words; believing and staying is enough.","persona":"any","source":"no perfect words"},
  {"id":"cr-1395","cat":"tools-and-help","type":"reflect","hook":"Lensy: the anonymous in-app route exists for when you're not ready to say it aloud. Reassuring?","prompt":"What do you think?","options":["Yes","Reassuring","Good there's that"],"affirm":"You can reach support without having to speak it aloud first; that door stays open.","relearn":"An anonymous route exists for when you're not ready to say it aloud.","persona":"any","source":"anonymous door"},
  {"id":"cr-1396","cat":"tools-and-help","type":"reflect","hook":"Lensy: you can change your mind at any point, and a good partner respects it. Carry that?","prompt":"What do you think?","options":["Yes","Always","Mine to decide"],"affirm":"Your yes is revocable, every time; that's yours to keep, no penalty.","relearn":"You can change your mind any time; consent is revocable, no penalty.","persona":"any","source":"revocable, always"},
  {"id":"cr-1397","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing the difference between persuasion and pressure keeps your own asks honest too. Useful?","prompt":"What do you think?","options":["Yes","Very","Noted"],"affirm":"One honest ask is fine; wearing someone down or leveraging power isn't, on either side.","relearn":"One honest ask is fine; wearing someone down or using power isn't.","persona":"any","source":"honest asks"},
  {"id":"cr-1398","cat":"tools-and-help","type":"reflect","hook":"Lensy: you got through the messy, real version of consent, not a tidy lecture. Feel different?","prompt":"What do you think?","options":["Yes","More real","I think so"],"affirm":"This was the adult, lived version, and you can use it tomorrow, not just remember it.","relearn":"This is the lived version of consent, usable tomorrow, not just a lecture.","persona":"any","source":"the lived version"},
  {"id":"cr-1399","cat":"tools-and-help","type":"reflect","hook":"Lensy: a single line, \"is this okay?\", carries the whole idea. Easy enough to actually say?","prompt":"What do you think?","options":["Yes","I can say it","Easy"],"affirm":"\"Is this okay?\" is the whole standard, shrunk to four words you can actually use.","relearn":"\"Is this okay?\" carries the whole standard in four usable words.","persona":"any","source":"four words"},
  {"id":"cr-1400","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Talking to a counsellor will just make it feel more real and worse.\"","myth":{"un":"Talking to a counsellor will only make it feel worse.","re":"A trained, confidential counsellor helps you carry it, not relive it, at your own pace.","why":"Saying it out loud to someone safe usually lightens the load, not adds to it."},"relearn":"A counsellor helps you carry it at your own pace; it isn't reliving it alone.","persona":"Meena","source":"counsellor helps"},
  {"id":"cr-1401","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Asking for help means I couldn't handle it myself.\"","myth":{"un":"Asking for help means I couldn't handle it myself.","re":"Knowing where help lives and using it is the equipped, adult move, not a failure.","why":"Help-seeking is strength, not weakness."},"relearn":"Help-seeking isn't weakness; it's the equipped, adult move.","persona":"Deepak","source":"help isn't weakness"},
  {"id":"cr-1402","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A real friend would make them go to the police.\"","myth":{"un":"A real friend would make them go to the police.","re":"A real friend supports the survivor's own choices, including whether and when to report.","why":"The choice stays the survivor's; autonomy matters."},"relearn":"A real friend supports a survivor's choices, never forces a report.","persona":"any","source":"don't force reporting"},
  {"id":"cr-1403","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Only women ever need these helplines.\"","myth":{"un":"Only women ever need these helplines.","re":"Anyone of any gender can be harmed and deserves belief and support; routes are for everyone.","why":"Even-handed; male and LGBTQ+ survivors are especially silenced."},"relearn":"Anyone of any gender can be harmed; support routes are for everyone.","persona":"any","source":"routes for everyone"},
  {"id":"cr-1404","cat":"tools-and-help","type":"strike-rewrite","hook":"\"I'll just remember some number I saw somewhere.\"","myth":{"un":"I'll just remember some number I saw somewhere.","re":"Use only the verified routes, 181, 1091, 112, the campus committee, never a half-remembered or guessed number.","why":"A wrong number wastes precious time in a crisis."},"relearn":"Use only verified routes, 181, 1091, 112, the ICC, never a guessed number.","persona":"any","source":"verified only"},
  {"id":"cr-1405","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If I don't want to report, there's no point getting help.\"","myth":{"un":"If I don't want to report, there's no point getting help.","re":"You can reach a counsellor, a helpline or a trusted person without reporting; support isn't all-or-nothing.","why":"Talking and healing are valid help on their own."},"relearn":"You can get help, talk and heal, without reporting; it's not all-or-nothing.","persona":"any","source":"help without reporting"},
  {"id":"cr-1406","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Telling a friend the routes is interfering.\"","myth":{"un":"Telling a friend the routes is interfering.","re":"Gently sharing where help lives, while leaving the choice to them, can be a real lifeline.","why":"Information offered, not imposed, respects their autonomy."},"relearn":"Gently sharing routes, leaving the choice theirs, can be a lifeline, not interfering.","persona":"any","source":"sharing isn't interfering"},
  {"id":"cr-1407","cat":"tools-and-help","type":"spot","hook":"Spot the bad advice for helping a friend who's just disclosed.","scene":[{"id":"a","text":"\"I believe you, and it's not your fault\"","trick":false},{"id":"b","text":"\"Tell me what you need from me\"","trick":false},{"id":"c","text":"\"You have to report this right now\"","trick":true},{"id":"d","text":"\"Here are some routes, if you want them\"","trick":false},{"id":"e","text":"\"Why didn't you just leave?\"","trick":true}],"why":"Forcing a report and blaming questions harm; belief, asking, and offered routes help.","relearn":"Believe and offer routes; never force a report or ask blaming questions.","persona":"any","source":"spot bad advice"},
  {"id":"cr-1408","cat":"tools-and-help","type":"spot","hook":"Spot the wrong route to lean on.","scene":[{"id":"a","text":"Women Helpline 181","trick":false},{"id":"b","text":"A campus counsellor","trick":false},{"id":"c","text":"A number a stranger DM'd you","trick":true},{"id":"d","text":"The campus Internal Committee","trick":false},{"id":"e","text":"Whatever the loudest group chat says","trick":true}],"why":"Use verified routes; a stranger's number or a noisy group chat aren't real support.","relearn":"Lean on verified routes; a stranger's number or a group chat aren't real support.","persona":"any","source":"spot the wrong route"},
  {"id":"cr-1409","cat":"tools-and-help","type":"spot","hook":"Spot what's NOT part of the consent one-liner.","scene":[{"id":"a","text":"Freely-given","trick":false},{"id":"b","text":"Ongoing","trick":false},{"id":"c","text":"Only when you're married","trick":true},{"id":"d","text":"Sober-enough","trick":false},{"id":"e","text":"Assumed after the first time","trick":true}],"why":"The standard is freely-given, ongoing, sober-enough, revocable, never marriage or assumption.","relearn":"Consent is freely-given, ongoing, sober-enough, revocable, never assumed or marriage-bound.","persona":"any","source":"spot the imposter"},
  {"id":"cr-1410","cat":"tools-and-help","type":"spot","hook":"Spot the line that doesn't belong when supporting someone.","scene":[{"id":"a","text":"\"This wasn't your fault\"","trick":false},{"id":"b","text":"\"I'm glad you told me\"","trick":false},{"id":"c","text":"\"What were you wearing, though?\"","trick":true},{"id":"d","text":"\"Take your time deciding\"","trick":false},{"id":"e","text":"\"You probably misread it\"","trick":true}],"why":"Blaming or doubting lines harm; the fault sits only with the one ignoring consent.","relearn":"Drop blaming or doubting lines; the fault sits only with the one ignoring consent.","persona":"any","source":"spot the harm"},
  {"id":"cr-1411","cat":"tools-and-help","type":"spot","hook":"Spot which two can't consent in this list.","scene":[{"id":"a","text":"Sober and clearly into it","trick":false},{"id":"b","text":"Passed out asleep","trick":true},{"id":"c","text":"One drink, fully present","trick":false},{"id":"d","text":"Blacked out, eyes glazed","trick":true},{"id":"e","text":"Tipsy but clear and talking","trick":false}],"why":"Passed out or blacked out means no capacity; sober or mildly tipsy-but-with-it can consent.","relearn":"Passed out or blacked out can't consent; sober or mildly tipsy-but-with-it can.","persona":"any","source":"spot no-capacity"},
  {"id":"cr-1412","cat":"tools-and-help","type":"spot","hook":"Spot the two that aren't real consent-culture habits.","scene":[{"id":"a","text":"Checking in mid-moment","trick":false},{"id":"b","text":"Taking a no gracefully","trick":false},{"id":"c","text":"Sulking until they give in","trick":true},{"id":"d","text":"Looking out for a tipsy friend","trick":false},{"id":"e","text":"Treating pressure as normal","trick":true}],"why":"Checking in, taking a no well and looking out build the culture; sulking and pressure erode it.","relearn":"Checking in, a graceful no and looking out build it; sulking and pressure don't.","persona":"any","source":"spot the non-habit"},
  {"id":"cr-1413","cat":"tools-and-help","type":"spot","hook":"Spot which two numbers aren't part of this game's verified set.","scene":[{"id":"a","text":"181, women facing violence","trick":false},{"id":"b","text":"112, immediate danger","trick":false},{"id":"c","text":"A number a poster promised \"works\"","trick":true},{"id":"d","text":"1091, women in distress","trick":false},{"id":"e","text":"A number a friend half-recalls","trick":true}],"why":"181, 1091 and 112 are verified; a poster's or half-recalled number is not, never guess.","relearn":"181, 1091 and 112 are verified; never trust a poster's or half-recalled number.","persona":"any","source":"spot the fake number"},
  {"id":"cr-1414","cat":"tools-and-help","type":"spot","hook":"Spot the two myths hiding among these statements.","scene":[{"id":"a","text":"Freezing is a normal response","trick":false},{"id":"b","text":"Consent can be withdrawn any time","trick":false},{"id":"c","text":"No struggle means it wasn't assault","trick":true},{"id":"d","text":"Anyone of any gender can be harmed","trick":false},{"id":"e","text":"Going to his room means yes","trick":true}],"why":"Freeze is normal and consent is revocable; \"no struggle\" and \"went to his room\" are myths.","relearn":"Freeze is normal, consent is revocable; \"no struggle\" and \"went to his room\" are myths.","persona":"any","source":"spot the myths"},
  {"id":"cr-1415","cat":"tools-and-help","type":"branch","persona":"any","source":"the 1am message","hook":"Your friend Ira messages at 1am: someone crossed a line tonight, and she's shaken but safe.","steps":[{"prompt":"Her message ends with \"I don't know what to do.\" What do you reply?","options":[{"text":"\"Report it right now. No excuses.\"","then":"Ira types, stops, then sends: \"I can't. Not tonight.\""},{"text":"\"Who was it? I'm going to find him.\"","then":"\"Please don't. That'll make it worse,\" Ira replies."},{"text":"\"I believe you. Come over, or just talk?\"","then":"\"Can you just stay on the phone with me?\" Ira replies.","best":true},{"text":"\"Are you sure? What exactly happened?\"","then":"A long pause. Then: \"Forget it. I'm probably overreacting.\""},{"text":"\"Try to sleep. We'll talk in the morning.\"","then":"\"Okay,\" Ira replies. You see she's still online at 3am."}],"why":"Leading with belief, and letting her choose, tells her she's safe with you."},{"prompt":"The next day Ira says she doesn't want to report it, at least not now. What do you do?","options":[{"text":"Keep pushing, since reporting is the only real way","then":"Ira goes quiet and starts answering in single words."},{"text":"Say it's her call, and you're with her","then":"Ira breathes out. \"Thank you. I thought you'd be angry.\"","best":true},{"text":"Report it yourself without telling her","then":"She hears about it from someone else and feels betrayed."},{"text":"Say okay, and change the subject","then":"Ira goes along with it, but days later she brings it up again."}],"why":"A real friend supports her choices, including if and when to report."},{"prompt":"Ira says she keeps replaying it and wonders if she could have stopped it. What do you say?","options":[{"text":"That maybe she could have left a bit earlier","then":"Ira nods slowly, and you can see her blaming herself."},{"text":"That she should try not to think about it anymore","then":"\"I wish I could,\" Ira says quietly."},{"text":"That being more careful might help her next time","then":"Ira stiffens. \"So it's my fault for not being careful?\""},{"text":"That the fault is only with the one who did it","then":"Ira's eyes fill. \"I needed someone to say that.\"","best":true}],"why":"Responsibility lies only with the person who ignored consent, never with her."},{"prompt":"A week later Ira says she might want to talk to someone, but not the police. What do you do?","options":[{"text":"Mention a counsellor, or 181, and ask what fits","then":"Ira thinks. \"The counsellor. Can you help me find one?\"","best":true},{"text":"Tell her the police are the only option that counts","then":"\"Then I'll just not talk to anyone,\" Ira says."},{"text":"Book her a counsellor appointment without asking","then":"Ira reads the confirmation and feels her choice slip away."},{"text":"Say she's doing fine and doesn't need anyone","then":"Ira nods, though she doesn't look fine."}],"why":"Offering routes and letting her choose keeps her in charge of her own recovery."},{"prompt":"Months later, Ira says she still has bad days. What do you do?","options":[{"text":"Tell her it's time to move on","then":"Ira stops mentioning it to you."},{"text":"Avoid bringing it up in case it upsets her","then":"Ira wonders if you've stopped caring."},{"text":"Keep checking in, and follow her lead","then":"Ira smiles a little. \"It helps knowing you haven't forgotten.\"","best":true},{"text":"Keep asking for details to understand better","then":"Ira tenses every time you ask."}],"why":"Healing has no deadline. Steady, gentle support lets her set the pace."}],"debrief":"Lead with belief and offer, never force, because the survivor sets the pace.","relearn":"Lead with belief and offer help; let the survivor set the pace and never force a report."},
  {"id":"cr-1416","cat":"tools-and-help","type":"branch","persona":"Mehta","source":"talk-not-report","hook":"Your friend Rohit has been carrying something that happened to him last term.","steps":[{"prompt":"He asks where he could go that won't turn into a case. What do you suggest?","options":[{"text":"The police, since that's the only real option","then":"Rohit shakes his head. \"Then I'll just keep quiet.\""},{"text":"Posting anonymously in a group chat for advice","then":"A stranger replies with jokes, and Rohit deletes the post."},{"text":"Someone he trusts, or a counsellor, to listen","then":"Rohit looks relieved. \"I didn't know that was allowed.\"","best":true},{"text":"Keeping it to himself until he's ready to report","then":"Rohit nods, and the weight stays on him."}],"why":"Talking to a counsellor is valid help on its own. No report is needed."},{"prompt":"A few days later Rohit hears the college has a counsellor, but worries they'll judge a guy. What do you say?","options":[{"text":"That anyone can be harmed, and counsellors know that","then":"Rohit exhales. \"Okay. Maybe I can try once.\"","best":true},{"text":"That he's right, so maybe he should just tough it out","then":"Rohit shrugs. \"Yeah. Guys don't talk about this stuff.\""},{"text":"That he could say it happened to a friend instead","then":"Rohit tries it, and ends up answering questions about someone who doesn't exist."},{"text":"That you'll speak to them for him","then":"Rohit tenses. \"I don't want anyone knowing yet.\""}],"why":"Anyone can be harmed, and it's never his fault. Counsellors are there for anyone."},{"prompt":"Rohit asks if talking now means he can't report later. What do you say?","options":[{"text":"That if he doesn't report now, it won't count","then":"Rohit's face falls. \"Then what's the point?\""},{"text":"That he should decide right now, once and for all","then":"Rohit looks overwhelmed. \"I can't decide tonight.\""},{"text":"That you're not sure, so maybe skip the counsellor","then":"Rohit puts it off again, still carrying it alone."},{"text":"That talking now keeps later options open","then":"Rohit nods. \"Then I'll start with talking.\"","best":true}],"why":"Talking first doesn't close the door to reporting, and the choice stays his."}],"debrief":"Talking is valid help on its own, and reporting is one option, not the only one.","relearn":"A counsellor or trusted person fits when someone wants to talk, not report."},
  {"id":"cr-1417","cat":"tools-and-help","type":"branch","persona":"any","source":"spiked drink","hook":"At a party, your classmate Arnav's drink seems to have been spiked. He can barely stand.","steps":[{"prompt":"He's swaying near the balcony and slurring. What do you do?","options":[{"text":"Assume his friends will sort it and walk off","then":"Ten minutes later he's alone on the balcony, head down."},{"text":"Get him somewhere safe and stay with him","then":"You steer him to a sofa inside. He mumbles and closes his eyes.","best":true},{"text":"Give him coffee to sober him up quickly","then":"He spills most of it and gets worse, not better."},{"text":"Let him sleep it off out on the balcony","then":"He slumps near the railing, and nobody else is watching."}],"why":"Staying with someone past coping keeps him safe from harm and from falls."},{"prompt":"Arnav's breathing seems slow, and he won't respond to his name. What do you do?","options":[{"text":"Let him sleep. He'll be fine by morning","then":"His breathing stays shallow, and he doesn't stir."},{"text":"Wait and see if it gets worse first","then":"Minutes pass. His lips look pale."},{"text":"Splash cold water on his face to wake him","then":"He barely flinches, and now he's soaked and shivering."},{"text":"Call 112 and stay with him","then":"The operator talks you through keeping him on his side till help arrives.","best":true}],"why":"Slow breathing and no response is an emergency. 112 is the move."},{"prompt":"The next day Arnav says he remembers nothing and asks what happened. What do you say?","options":[{"text":"What you saw, calmly, and that it's not his fault","then":"Arnav goes quiet, then says, \"Thanks for staying with me.\"","best":true},{"text":"That he should be more careful with his drinks","then":"He looks ashamed. \"Yeah. My fault.\""},{"text":"That it was nothing, so he won't worry","then":"Later he hears the real story from someone else."},{"text":"That guys don't get spiked, so maybe he overdid it","then":"He frowns. \"I had one beer.\""}],"why":"Spiking is on the person who did it. Telling him gently lets him decide what's next."},{"prompt":"Arnav wonders if he should tell anyone. What do you do?","options":[{"text":"Tell him to drop it, since it'll only embarrass him","then":"Arnav drops it, and wonders about it for weeks."},{"text":"Report it for him without asking","then":"Arnav gets a call from the warden and feels ambushed."},{"text":"Offer to go with him to a counsellor, if he wants","then":"Arnav nods. \"Yeah. Maybe tomorrow. Will you come?\"","best":true},{"text":"Post a warning about the party host online","then":"The post blows up, and Arnav's name gets dragged in."}],"why":"Offering help and going with him, if he wants, keeps him supported and in charge."}],"debrief":"Step in for anyone past coping, and reach 112 if there's danger.","relearn":"Step in for anyone past coping, and reach 112 if needed."},
  {"id":"cr-1418","cat":"tools-and-help","type":"branch","persona":"any","source":"quid-pro-quo","hook":"Your junior Pihu tells you a senior keeps pressuring her and dangling a recommendation.","steps":[{"prompt":"She asks you not to make a big deal of it. What do you say?","options":[{"text":"To keep her head down till it passes","then":"Pihu nods, and the messages from the senior keep coming."},{"text":"That seniors are like that, so play along a bit","then":"Pihu looks sick. \"That's what I was afraid of.\""},{"text":"That you'll confront the senior tonight","then":"Pihu panics. \"Please don't. He'll know I told.\""},{"text":"That it's harassment, and not her fault","then":"Pihu blinks. \"I thought I was overreacting.\"","best":true}],"why":"Naming it plainly tells her she's not imagining it, and it's not on her."},{"prompt":"Pihu asks who she could even tell about it. What do you say?","options":[{"text":"The campus ICC, which handles exactly this","then":"Pihu looks up. \"Is it confidential?\"","best":true},{"text":"Only the police can deal with this","then":"Pihu shrinks. \"I can't go that far.\""},{"text":"The senior's friends, so they can talk to him","then":"Pihu imagines it getting back to him and shudders."},{"text":"Nobody, till she has more proof","then":"Pihu starts saving messages, still telling no one."}],"why":"The campus ICC exists for power-play harassment. It's the real route."},{"prompt":"Pihu worries the senior will ruin her recommendation if she speaks up. What do you say?","options":[{"text":"That a recommendation isn't worth the trouble anyway","then":"Pihu frowns. \"It is to me.\""},{"text":"That her fear is fair, and she can just ask the ICC","then":"Pihu nods. \"Asking doesn't commit me to anything?\"","best":true},{"text":"That she should get the letter first, then report","then":"Pihu grits her teeth through another month of hints."},{"text":"That she's probably right, so staying quiet is safer","then":"Pihu stays quiet, and the pressure keeps coming."}],"why":"Her fear is valid. Finding out her options first keeps the choice hers."},{"prompt":"A week later Pihu says she's decided not to report for now. What do you do?","options":[{"text":"Respect it, and keep checking in on her","then":"Pihu smiles faintly. \"Thanks for not pushing.\"","best":true},{"text":"Report it for her, since she's scared","then":"Pihu is called in and feels ambushed and exposed."},{"text":"Tell her she's letting him win","then":"Pihu's eyes fill. \"So now it's on me?\""},{"text":"Drop the subject and never raise it again","then":"Pihu feels you've moved on, and stops updating you."}],"why":"She decides if and when. Staying close is how you keep supporting her."}],"debrief":"Leveraging power for a yes is harassment, and the campus ICC is the route when she's ready.","relearn":"Power-play for a yes is harassment; the campus ICC is the route to act."},
  {"id":"cr-1419","cat":"tools-and-help","type":"branch","persona":"any","source":"offering not imposing","hook":"Your friend Naveen has seemed low since a bad night out, but hasn't asked for any help.","steps":[{"prompt":"You have a list of help routes saved on your phone. What do you do?","options":[{"text":"Forward him ten links and tell him to act now","then":"Naveen leaves them on read and stops replying for a day."},{"text":"Wait until he asks, and say nothing till then","then":"Weeks pass with Naveen getting quieter, and you're not sure he knows help exists."},{"text":"Tell him gently you have them, if he ever wants","then":"Naveen nods. \"Maybe. Not yet. Thanks.\"","best":true},{"text":"Ask him directly what exactly happened that night","then":"Naveen shuts down. \"Nothing happened. Drop it.\""}],"why":"Offering gently leaves the door open and the choice with him."},{"prompt":"Eventually Naveen says he wants to talk to someone, and asks where to start. What do you say?","options":[{"text":"A counsellor or trusted person, just to talk","then":"Naveen nods. \"Just talking. I can do that.\"","best":true},{"text":"The police, since that's the proper way","then":"Naveen hesitates. \"Maybe I'm not ready after all.\""},{"text":"Whatever he picks, as long as he does it tonight","then":"\"Tonight? I don't know,\" Naveen says, backing off."},{"text":"A group chat of friends for advice","then":"Naveen imagines everyone knowing, and changes his mind."}],"why":"Talking is a low-stakes first step. And whatever happened, it isn't on him."},{"prompt":"Naveen asks if you'd keep this between the two of you. What do you say?","options":[{"text":"Yes, completely, no matter what","then":"Naveen relaxes, and you wonder what you'd do if things got worse."},{"text":"Only if he promises to see someone this week","then":"Naveen goes quiet. \"I'll think about it.\""},{"text":"That you'd like to tell a couple of mutual friends","then":"Naveen stiffens. \"No. Please don't.\""},{"text":"Yes, unless he's ever in danger","then":"Naveen nods. \"That's fair. Thank you.\"","best":true}],"why":"Honest confidentiality, with safety as the only limit, is a promise you can keep."}],"debrief":"Offer routes gently and leave the choice with them, because that's a lifeline, not pressure.","relearn":"Offer routes gently and leave the choice theirs; that's a lifeline, not pressure."},
  {"id":"cr-1420","cat":"tools-and-help","type":"branch","persona":"any","source":"the freeze doubt","hook":"Your friend Mansi was harmed at a party two days ago, and she's just told you.","steps":[{"prompt":"She says she froze, and asks if that means it wasn't really assault. What do you say?","options":[{"text":"Ask why she didn't push him off","then":"Mansi goes silent, then says, \"Yeah. I should have.\""},{"text":"Say you're not sure, since you weren't there","then":"Mansi nods slowly, but a day later she comes back to it."},{"text":"Tell her freezing is normal, and it counts","then":"Mansi's voice cracks. \"I thought I was making it up.\"","best":true},{"text":"Say it counts if she reports it quickly","then":"Mansi panics. \"It's been two days. Is it too late?\""}],"why":"Freezing and waiting days to tell are both common. Neither means it didn't happen."},{"prompt":"Mansi says she never said no out loud. What do you say?","options":[{"text":"Next time she should say it clearly","then":"Mansi flinches. \"So it's on me.\""},{"text":"Consent needs a yes. Silence was never one","then":"Mansi stares at her hands. \"No one ever said that to me.\"","best":true},{"text":"Then maybe it was a misunderstanding","then":"Mansi nods, relieved and crushed at the same time."},{"text":"He should have guessed, but it's complicated","then":"\"Complicated how?\" Mansi asks, confused."}],"why":"The absence of a no is not a yes. Responsibility lies with him, not her."},{"prompt":"Mansi asks what she should do now. What do you say?","options":[{"text":"Tell her to report it, or he'll do it again","then":"Mansi shuts down. \"I can't handle that right now.\""},{"text":"Suggest she forget it and focus on exams","then":"Mansi nods, and her grades slip anyway."},{"text":"Offer to confront him with your friends","then":"Mansi panics. \"Please don't. Everyone will know.\""},{"text":"Ask what she needs, and offer to be there","then":"Mansi thinks. \"Someone to talk to, I think. Not police.\"","best":true}],"why":"Asking what she needs keeps her in charge of what happens next."},{"prompt":"Mansi says she wants to talk to someone, maybe tonight. What do you do?","options":[{"text":"Pick a helpline for her and make the call yourself","then":"Mansi takes the phone, flustered, unsure what she wanted to say."},{"text":"Share 181 and the counsellor, and stay with her","then":"Mansi calls 181 with you beside her. Her voice steadies as she talks.","best":true},{"text":"Tell her tonight's too soon, and to wait a week","then":"Mansi nods, and the week feels endless."},{"text":"Search online forums with her for advice","then":"The comments are mixed, and some blame her."}],"why":"Real routes that she chooses, with you beside her, give steady support."}],"debrief":"Freezing is a common, involuntary response, and it never means it didn't happen.","relearn":"Freezing is normal and involuntary; it never means it didn't count."},
  {"id":"cr-1421","cat":"tools-and-help","type":"branch","persona":"Rohan","source":"owning a misstep","hook":"You realise you pushed Aditi a bit hard for a yes last week, and you feel off about it.","steps":[{"prompt":"You see her in the library. What do you do?","options":[{"text":"Tell yourself she didn't say no, so it's fine","then":"She sees you and quickly looks away."},{"text":"Act extra nice so she forgets it","then":"She takes the coffee you bring, but won't meet your eyes."},{"text":"Send her a long text explaining your side","then":"Hours later: \"Okay.\" Nothing else."},{"text":"Ask if you can talk, and apologise plainly","then":"Aditi hesitates, then nods. \"Okay. Outside, for a minute.\"","best":true}],"why":"Owning it directly is what accountability actually looks like."},{"prompt":"Later that week Aditi stops you and says it did feel like pressure at the time. What do you say?","options":[{"text":"That you didn't mean it that way","then":"\"Maybe not,\" Aditi says. \"It still felt that way.\""},{"text":"That she's right, and you're sorry","then":"Aditi exhales. \"Thanks for actually saying it.\"","best":true},{"text":"That she could have just said no","then":"Aditi's face hardens. \"That's exactly the problem.\""},{"text":"That you were drunk and don't remember much","then":"Aditi shakes her head. \"That doesn't make it okay.\""}],"why":"Owning the impact, without excuses, shows you heard her."},{"prompt":"Aditi says she'd rather keep some distance for now. What do you do?","options":[{"text":"Keep messaging to prove you've changed","then":"Aditi mutes your chat after the third message."},{"text":"Ask your mutual friends to vouch for you","then":"Aditi hears about it and feels cornered."},{"text":"Accept it, and give her the space she asked for","then":"Aditi nods. \"Thank you.\" The conversation ends quietly.","best":true},{"text":"Say you understand, but hope she'll get over it soon","then":"Aditi's jaw tightens. \"It's not about getting over it.\""}],"why":"Respecting her distance is part of the apology, not a punishment."},{"prompt":"Weeks later your friend Karan says pushing a bit is just how dating works. What do you say?","options":[{"text":"Laugh along, since it's just banter","then":"The group laughs, and Karan tells another story like it."},{"text":"Say nothing, but feel uneasy","then":"Karan carries on, and the uneasy feeling stays with you."},{"text":"Lecture him about consent in front of everyone","then":"Karan rolls his eyes. \"Okay, professor.\""},{"text":"Say you learnt the hard way it's pressure","then":"Karan pauses. \"Huh. Never thought of it like that.\"","best":true}],"why":"Sharing what you learnt, plainly, shifts things more than any lecture."}],"debrief":"Accountability, not excuses, is part of a consent culture, so own it and grow.","relearn":"Own a misstep plainly; \"they didn't say no\" isn't a yes, and accountability matters."},
  {"id":"cr-1422","cat":"tools-and-help","type":"branch","persona":"Meena","source":"off-campus help","hook":"Your friend Savitri works at a factory in a new city, with no campus or counsellor nearby.","steps":[{"prompt":"A supervisor there keeps harassing her, and she asks where she could even turn. What do you say?","options":[{"text":"Say help is really only for college students","then":"Savitri sighs. \"So there's nothing for people like me.\""},{"text":"Tell her to quit right away and come back home","then":"Savitri goes quiet. \"I need this job.\""},{"text":"Share 181, 112, and a trusted person nearby","then":"Savitri saves the numbers. \"I didn't know I could call without a warden.\"","best":true},{"text":"Say that's normal at work, so she should ignore it","then":"Savitri nods, and the harassment carries on."}],"why":"Help reaches anyone, offline and off-campus. 181 and 112 work anywhere."},{"prompt":"Later Savitri says she's heard of 181, but fears calling means filing a case. What do you say?","options":[{"text":"That calling means the police will turn up at work","then":"Savitri decides not to call at all."},{"text":"That she can just talk, and choose what's next","then":"Savitri relaxes a little. \"Then I'll call tonight.\"","best":true},{"text":"That she should wait till it gets worse","then":"A week later, the supervisor's comments get bolder."},{"text":"That you'll call for her so she's not bothered","then":"Savitri hesitates. \"They'll want to hear from me, no?\""}],"why":"A helpline listens first. She stays in charge of what happens next."},{"prompt":"Savitri asks if she's making too much of it. What do you say?","options":[{"text":"A bit, maybe. He might just be friendly","then":"Savitri doubts herself, and the call waits."},{"text":"Only she can decide that, so you'd rather not say","then":"Savitri feels alone with the question."},{"text":"No. It's not her fault, and help is for this","then":"Savitri's eyes fill. \"I needed to hear that.\"","best":true},{"text":"Yes, unless she has proof","then":"Savitri starts wondering if her word is enough."}],"why":"Harassment is never her fault, and help is for moments exactly like this."}],"debrief":"Help exists offline and off-campus, and 181, 112 and a trusted person reach anyone.","relearn":"181, 112 and a trusted person reach anyone, no campus or counsellor needed."},
  {"id":"cr-1423","cat":"tools-and-help","type":"role-play","persona":"any","source":"first words to a survivor","hook":"Your friend Zara tells you she was assaulted at a party last month.","setup":"You're on the steps outside her hostel.","steps":[{"prompt":"Zara says: \"I haven't told anyone else.\"","options":[{"text":"\"Are you sure? What were you doing there?\"","then":"Zara pulls back and goes quiet, but she doesn't leave."},{"text":"\"I believe you. I'm so glad you told me. This wasn't your fault.\"","then":"Zara's shoulders drop. \"I was so scared you'd doubt me.\"","best":true},{"text":"\"Why did you wait a whole month to tell anyone?\"","then":"Zara looks down. \"I didn't know how.\""},{"text":"\"Oh no. Okay, tell me who it was, and I'll go deal with him myself.\"","then":"\"Please don't,\" Zara says, alarmed. \"That's not what I need.\""}],"why":"Belief first, gratitude, no blame. It's what she needs to hear most."},{"prompt":"After a silence, Zara says: \"I keep thinking I should have left earlier.\"","options":[{"text":"\"Yeah, maybe. Next time, leave when it feels off.\"","then":"Zara's face closes. \"Right. My fault, then.\""},{"text":"\"Don't think about it. It's done now.\"","then":"\"I can't not think about it,\" Zara says quietly."},{"text":"\"When you left doesn't matter. It's on him.\"","then":"Zara wipes her eyes. \"Okay. It's on him.\"","best":true},{"text":"\"Why didn't you, though?\"","then":"Zara stiffens. \"I don't know. I just couldn't.\""}],"why":"Responsibility lies only with the one who ignored consent, never the survivor."},{"prompt":"Zara asks: \"What do I even do now?\"","options":[{"text":"\"You have to report it. Tonight.\"","then":"Zara shrinks. \"I'm not ready for that.\""},{"text":"\"Nothing. Try to put it behind you.\"","then":"Zara nods, but her hands are shaking."},{"text":"\"Let me handle it. I'll tell the warden.\"","then":"\"No!\" Zara says. \"I don't want anyone else knowing.\""},{"text":"\"What would help you most right now?\"","then":"Zara thinks. \"Just someone to talk to. Not the police yet.\"","best":true}],"why":"Asking what she needs, rather than deciding for her, gives her control back."},{"prompt":"Zara asks: \"Is there someone I could talk to who won't judge me?\"","options":[{"text":"\"A counsellor, or 181. I'll sit with you.\"","then":"Zara takes a breath. \"Okay. Tomorrow. With you.\"","best":true},{"text":"\"Just talk to me. You don't need anyone else.\"","then":"Zara nods, and by next week you feel out of your depth."},{"text":"\"Maybe the group chat? They'd have advice.\"","then":"Zara imagines everyone reading it and shakes her head."},{"text":"\"Honestly, everyone judges. Keep it quiet.\"","then":"Zara goes quiet, more alone than before."}],"why":"Real routes, offered gently, with you beside her, make help feel possible."}],"relearn":"Lead with belief and \"this wasn't your fault\", never with doubt or blame."},
  {"id":"cr-1424","cat":"tools-and-help","type":"role-play","persona":"Mehta","source":"offer a soft route","hook":"Your friend Keshav has been struggling since something happened to him last month.","setup":"He's come by your room late at night.","steps":[{"prompt":"Keshav says: \"I need to talk to someone, but I can't do police.\"","options":[{"text":"\"You should go to the police about it, or just forget it.\"","then":"Keshav stands, then sits back down. \"I can't just forget it.\""},{"text":"\"A counsellor can just listen. No report needed.\"","then":"Keshav looks up. \"Really? That's allowed?\"","best":true},{"text":"\"Just talk to me. You don't need anyone else.\"","then":"Keshav nods, but you're not sure what to say next."},{"text":"\"Post it anonymously online. People help.\"","then":"Keshav hesitates. \"People can be cruel online.\""}],"why":"A no-report route like a counsellor lets him get help at his own pace."},{"prompt":"Keshav asks: \"Do counsellors even see guys for this? Wouldn't they judge me?\"","options":[{"text":"\"Maybe. You could just tough it out.\"","then":"Keshav shrugs. \"Yeah. That's what I've been doing.\""},{"text":"\"Just tell them it happened to a friend, not you.\"","then":"Keshav thinks it over, unsure it would help."},{"text":"\"Don't worry. I'll explain it all for you.\"","then":"Keshav tenses. \"I'd rather speak for myself.\""},{"text":"\"Anyone can be harmed. Needing support is human.\"","then":"Keshav breathes out. \"Okay. Maybe.\"","best":true}],"why":"Anyone can be harmed, and it's never his fault. Asking for support is strength."},{"prompt":"Keshav says: \"If I did try a counsellor, I wouldn't know where to start.\"","options":[{"text":"\"I'll book one for you tomorrow morning.\"","then":"Keshav hesitates. \"Tomorrow? I wasn't ready for that.\""},{"text":"\"Then let's look together, and you choose.\"","then":"Keshav pulls his chair closer. \"Okay. Together.\"","best":true},{"text":"\"Try the college website. It's all there somewhere.\"","then":"Keshav scrolls, gets lost, and closes the tab."},{"text":"\"First decide if you're reporting. Then we'll look.\"","then":"Keshav's face falls. \"Then never mind.\""}],"why":"Helping him find one, while he stays in charge, makes the first step doable."}],"relearn":"Offer a no-report route like a counsellor; never make reporting the only option."},
  {"id":"cr-1425","cat":"tools-and-help","type":"role-play","persona":"any","source":"un-blaming a friend","hook":"Your friend Divya keeps blaming herself for what happened at a party.","setup":"She's curled up on your bed with tea.","steps":[{"prompt":"Divya says: \"I shouldn't have had that last drink.\"","options":[{"text":"\"Well, maybe next time just be a bit more careful.\"","then":"Divya nods, eyes down. \"I know.\""},{"text":"\"This isn't on you. It's on the one who did it.\"","then":"Divya looks at you. \"You really think so?\"","best":true},{"text":"\"Drinking was a bit much, but he's worse.\"","then":"Divya flinches at \"a bit much\" and goes quiet."},{"text":"\"Let's not talk about the party.\"","then":"Divya sips her tea in silence. Then she tries again."}],"why":"A drink never causes assault. The fault sits only with the one who did it."},{"prompt":"Divya adds: \"And I went with him willingly at first.\"","options":[{"text":"\"That does make it more complicated.\"","then":"Divya's face crumples. \"So it is my fault.\""},{"text":"\"Then why did you go?\"","then":"Divya pulls the blanket up. \"I don't know.\""},{"text":"\"Going with him wasn't a yes to anything else.\"","then":"Divya is quiet, then says, \"I never thought of it that way.\"","best":true},{"text":"\"Forget him. You deserve way better guys than that.\"","then":"Divya forces a smile. \"Sure.\""}],"why":"Going somewhere with someone is never consent to what comes next."},{"prompt":"Divya asks: \"Do you think anyone else would believe me?\"","options":[{"text":"\"Honestly, people do judge. Keep it quiet.\"","then":"Divya shrinks. \"That's what I was afraid of.\""},{"text":"\"Only if you have proof, like messages or photos.\"","then":"Divya shakes her head. \"I don't have any.\""},{"text":"\"Don't worry about others. Just forget it.\"","then":"\"I can't,\" Divya says quietly."},{"text":"\"I do. And counsellors and 181 are there too.\"","then":"Divya nods slowly. \"Maybe I'll talk to someone.\"","best":true}],"why":"Belief, from you and from real help, can loosen the blame she carries."}],"relearn":"The fault sits only with the one ignoring consent, never the survivor."},
  {"id":"cr-1426","cat":"tools-and-help","type":"role-play","persona":"any","source":"handing over routes","hook":"Your friend Mehek is struggling after a bad night, and you've saved some help routes for her.","setup":"You're walking back from class together.","steps":[{"prompt":"Mehek says: \"I don't even know who I'd call.\"","options":[{"text":"\"Here's 181 and a counsellor. If you want them.\"","then":"Mehek saves them. \"Thanks. I'll keep them for now.\"","best":true},{"text":"\"Call all of these tonight, or you're not serious.\"","then":"Mehek goes quiet. \"Maybe I'm not serious, then.\""},{"text":"\"I'll call for you. Just give me the go-ahead.\"","then":"Mehek hesitates. \"I don't want you telling them things.\""},{"text":"\"Honestly, you'll probably feel better in a week.\"","then":"\"Maybe,\" Mehek says, not believing it."}],"why":"Offering routes with no deadline leaves the choice with her. Whatever happened isn't her fault."},{"prompt":"Mehek asks: \"What if I call and don't know what to say?\"","options":[{"text":"\"Then write a full script first, so you don't mess it up.\"","then":"Mehek spends an hour on it and gives up."},{"text":"\"Then maybe don't call yet.\"","then":"Mehek puts the phone away, relieved and stuck."},{"text":"\"You can just say you're not okay. They'll guide you.\"","then":"Mehek nods. \"Okay. That sounds less scary.\"","best":true},{"text":"\"I'll do the talking for you.\"","then":"\"But it's my story,\" Mehek says."}],"why":"Helplines are there to listen. She doesn't need the right words."},{"prompt":"A week later Mehek says: \"I haven't called yet. Are you annoyed?\"","options":[{"text":"\"A bit. I gave you those numbers for a reason.\"","then":"Mehek looks down. \"Sorry.\""},{"text":"\"No, but you really should call by Friday.\"","then":"Mehek nods, and dreads Friday."},{"text":"\"No. Maybe you don't really need them.\"","then":"Mehek frowns. \"Maybe I do, though.\""},{"text":"\"No. They're there whenever you're ready.\"","then":"Mehek smiles. \"Okay. Knowing that helps.\"","best":true}],"why":"No deadline, no guilt. The routes wait for her, not the other way round."}],"relearn":"Hand over routes as an offer, leaving the timing and choice with them."},
  {"id":"cr-1427","cat":"tools-and-help","type":"role-play","persona":"Deepak","source":"reframe help-seeking","hook":"Your friend Sunil, far from home on a scholarship, has been shaken since a bad night.","setup":"You're sharing dinner at the mess.","steps":[{"prompt":"Sunil says: \"Asking for help feels pathetic.\"","options":[{"text":"\"Yeah, maybe just tough it out.\"","then":"Sunil nods. \"That's what I figured.\""},{"text":"\"It's not pathetic, but it's for serious stuff.\"","then":"\"Maybe mine isn't serious enough,\" Sunil says."},{"text":"\"Reaching out is the strong, grown-up move.\"","then":"Sunil pauses mid-bite. \"Never thought of it like that.\"","best":true},{"text":"\"Help costs money you don't have, though.\"","then":"Sunil sighs. \"Right. Another thing I can't afford.\""}],"why":"Help-seeking is strength, not weakness. Whatever happened, it isn't his fault."},{"prompt":"Sunil says: \"Everyone here seems fine. I don't want to be the one who isn't.\"","options":[{"text":"\"Lots of people struggle quietly. You're not alone.\"","then":"Sunil looks around the mess. \"Huh. Maybe.\"","best":true},{"text":"\"Just fake it till you feel fine.\"","then":"Sunil nods. \"I've been doing that for weeks.\""},{"text":"\"Maybe you're just homesick, and it'll pass on its own.\"","then":"\"It's more than that,\" Sunil says quietly."},{"text":"\"Tell everyone in the group. Get it out.\"","then":"Sunil shakes his head. \"No way.\""}],"why":"Knowing others struggle too makes reaching out feel normal, not shameful."},{"prompt":"Sunil asks: \"Is there anything free? I can't pay for a counsellor.\"","options":[{"text":"\"Not really. Help is for people with money.\"","then":"Sunil sighs. \"Figured.\""},{"text":"\"Just watch some videos on it.\"","then":"Sunil watches two and feels worse."},{"text":"\"Ask your parents to pay. They'd want to help.\"","then":"Sunil flinches. \"They can't know about this.\""},{"text":"\"Campus counselling is usually free. Want company?\"","then":"Sunil nods slowly. \"Okay. If you come with me.\"","best":true}],"why":"Help on campus usually costs nothing. Going with him makes the first step easier."}],"relearn":"Help-seeking is the strong, adult move, never something to be ashamed of."},
  {"id":"cr-1428","cat":"tools-and-help","type":"role-play","persona":"any","source":"how to check in","hook":"Your friend Tushar is getting closer with his new girlfriend and wants your advice.","setup":"You're both on the terrace after dinner.","steps":[{"prompt":"Tushar asks: \"How do I ask without sounding like a robot?\"","options":[{"text":"\"Don't bother asking. It kills the mood.\"","then":"\"Really?\" Tushar asks. \"Then how do I know?\""},{"text":"\"Ask once at the start. After that, you're set.\"","then":"\"Once. Got it,\" Tushar says, filing it away."},{"text":"\"Just ask 'is this good?' It builds trust.\"","then":"Tushar laughs. \"That's it? That's so simple.\"","best":true},{"text":"\"Watch her face. You'll know.\"","then":"\"What if I read it wrong?\" Tushar asks."}],"why":"A warm, simple question builds trust and keeps consent ongoing."},{"prompt":"Tushar asks: \"What if she says 'I don't know'?\"","options":[{"text":"\"Keep going gently. She'll relax.\"","then":"\"Hm. Okay,\" Tushar says, unsure."},{"text":"\"Then pause. Not sure means stop for now.\"","then":"Tushar nods. \"Right. Pause, and check.\"","best":true},{"text":"\"Ask again till she gives a clear answer.\"","then":"\"Like, keep asking?\" Tushar frowns."},{"text":"\"Take it as a yes. She'd say no otherwise.\"","then":"Tushar hesitates. \"Would she, though?\""}],"why":"\"Not sure\" is a stop. You never push for a yes."},{"prompt":"Tushar asks: \"And if she says no, how do I not make it weird?\"","options":[{"text":"\"Ask her what's wrong so you can fix it.\"","then":"\"Is that pushy, though?\" Tushar wonders aloud."},{"text":"\"Go quiet for a bit so she knows you're hurt.\"","then":"Tushar nods. \"Makes sense, I guess.\""},{"text":"\"Joke about it to lighten the mood.\"","then":"\"What kind of joke?\" Tushar asks, looking worried."},{"text":"\"Say 'okay, thanks for saying' and mean it.\"","then":"Tushar smiles. \"Easy. I can do that.\"","best":true}],"why":"Taking a no warmly, with no sulk, makes checking in safe to answer honestly."}],"relearn":"A warm \"is this good?\" builds trust and isn't a mood-killer."},
  {"id":"cr-1429","cat":"tools-and-help","type":"role-play","persona":"any","source":"hand over the line","hook":"Your cousin Asmi leaves for college next week and has questions about consent.","setup":"She's packing, phone propped against a suitcase.","steps":[{"prompt":"Asmi asks: \"So what's the one thing I need to remember?\"","options":[{"text":"\"Honestly, just wing it and hope for the best.\"","then":"Asmi laughs. \"That's not advice.\""},{"text":"\"Freely given, ongoing, sober enough, revocable.\"","then":"Asmi types it into her notes. \"Four things. Okay.\"","best":true},{"text":"\"If nobody says no out loud, then you're totally fine.\"","then":"\"What if someone can't say no?\" Asmi asks."},{"text":"\"Get a yes once, and you're covered.\"","then":"\"Once for the whole night?\" Asmi asks."}],"why":"Freely given, ongoing, sober enough and revocable covers the whole idea."},{"prompt":"Asmi asks: \"What about drinking? How much is too much to say yes?\"","options":[{"text":"\"Zero drinks, always. Otherwise it doesn't count.\"","then":"\"So nobody at a party ever can?\" Asmi asks, doubtful."},{"text":"\"If they started it, drinks don't matter.\"","then":"Asmi frowns. \"Even if they're passed out after?\""},{"text":"\"Tipsy but with it can be okay. Slurring can't.\"","then":"Asmi nods. \"So it's about being with it, not the drink count.\"","best":true},{"text":"\"Whatever feels okay to the person asking.\"","then":"\"But it's the other person who matters,\" Asmi says."}],"why":"The line is capacity. Someone too drunk or asleep can't consent."},{"prompt":"Asmi asks: \"And can I change my mind even halfway?\"","options":[{"text":"\"Yes. Any time, even halfway, no reason needed.\"","then":"Asmi grins. \"Okay. I feel ready.\"","best":true},{"text":"\"Only before things start. After that, it's too late.\"","then":"Asmi stops packing. \"That sounds wrong.\""},{"text":"\"Yes, if you've got a good reason.\"","then":"\"What counts as a good reason?\" Asmi asks."},{"text":"\"Technically, but it's rude to stop midway.\"","then":"Asmi frowns. \"Rude? Even if I'm not okay?\""}],"why":"Consent can be taken back at any moment, and no reason is owed."}],"relearn":"The one-line reference: freely-given, ongoing, sober-enough, revocable."},
  {"id":"cr-1430","cat":"tools-and-help","type":"role-play","persona":"any","source":"believe him too","hook":"Your friend Aarav tells you something happened to him at a party, and doubts it \"counts\".","setup":"He says it quietly, not looking at you.","steps":[{"prompt":"Aarav says: \"Guys aren't supposed to say this stuff, right?\"","options":[{"text":"\"Come on, guys can't really be assaulted.\"","then":"Aarav laughs it off, then goes quiet. \"It still happened, though.\""},{"text":"\"It counts. Anyone can be harmed. I believe you.\"","then":"Aarav lets out a breath. \"I didn't think anyone would say that.\"","best":true},{"text":"\"Wait, was it a girl? Lucky you, then.\"","then":"Aarav's face goes blank. \"It wasn't like that.\""},{"text":"\"I believe you, but are you sure it wasn't a mix-up?\"","then":"Aarav hesitates. \"Maybe it was. I don't know.\""}],"why":"Anyone of any gender can be harmed, and deserves full belief."},{"prompt":"Aarav says: \"I didn't fight back. I just sort of froze.\"","options":[{"text":"\"Why didn't you, though? You're a strong guy.\"","then":"Aarav's jaw tightens. \"I don't know. I couldn't.\""},{"text":"\"Honestly, that's a bit unusual for a guy.\"","then":"Aarav goes quiet, embarrassed."},{"text":"\"If you froze, maybe part of you wanted it?\"","then":"Aarav stands up, then stops. \"See? This is why I told no one.\""},{"text":"\"Freezing is normal. It still counts.\"","then":"Aarav nods. \"I've been telling myself it didn't.\"","best":true}],"why":"Freezing is involuntary. It never means he wanted it, and it's not his fault."},{"prompt":"Aarav asks: \"Who else would even believe a guy?\"","options":[{"text":"\"Honestly, not many. Maybe keep it to yourself.\"","then":"Aarav nods, and doesn't bring it up again."},{"text":"\"I do. A counsellor would too. Want one?\"","then":"Aarav nods slowly. \"Maybe. If you help me look.\"","best":true},{"text":"\"Tell the guys. They'll back you up.\"","then":"Aarav imagines the jokes and shakes his head."},{"text":"\"Only the police count. Go there tomorrow.\"","then":"Aarav stiffens. \"I'm not ready for that.\""}],"why":"Male survivors are often silenced. Belief and a real route break that."}],"relearn":"Anyone of any gender can be harmed and deserves belief; it counts."},
];

